local config = {
  str_homestory_800601001_0_dialog_content = "Carleen...",
  str_homestory_800601001_1_dialog_content = "Hello, PlayerName.",
  str_homestory_800601001_2_dialog_content = "What are you up to, Carleen?",
  str_homestory_800601001_3_dialog_content = "I am murmuring to myself.",
  str_homestory_800601001_4_dialog_content = "You mean \"praying\"?",
  str_homestory_800601001_5_dialog_content = "...",
  str_homestory_800601001_6_dialog_content = "Yes. Please don't laugh at me.",
  str_homestory_800601001_7_dialog_content = "Why would I? It's perfectly normal to pray.",
  str_homestory_800601001_8_dialog_content = "Children who can't hold a blade pray to grown-ups for protection.",
  str_homestory_800601001_9_dialog_content = "A dying patient prays to gods for recovery.",
  str_homestory_800601001_10_dialog_content = "But why would an able person be dependent on \"prayers\"?",
  str_homestory_800601001_11_dialog_content = "(Agree)",
  str_homestory_800601001_12_dialog_content = "That's a bit harsh, but you do have a point...",
  str_homestory_800601001_13_dialog_content = "If one could control their own fate, they'd have no reason to be dependent on anyone else.",
  str_homestory_800601001_14_dialog_content = "However, so many things in this world are beyond our control. Your statement is correct, PlayerName.",
  str_homestory_800601001_15_dialog_content = "Fate.",
  str_homestory_800601001_16_dialog_content = "We consider all things that are irreversible as \"fate\" and it makes us feel better.",
  str_homestory_800601001_17_dialog_content = "But for me, fate can be changed.",
  str_homestory_800601001_18_dialog_content = "(Disagree)",
  str_homestory_800601001_19_dialog_content = "Isn't it common practice in Lumopolis to pray to the God of Light?",
  str_homestory_800601001_20_dialog_content = "I thought everyone did that, including you.",
  str_homestory_800601001_21_dialog_content = "Yes, we often share our thoughts and wishes with the God of Light.",
  str_homestory_800601001_22_dialog_content = "But for me, it's just a way of seeking spiritual comfort and relief.",
  str_homestory_800601001_23_dialog_content = "After prayers are over, the hardships in front of me are still there waiting to be overcome. This never changes.",
  str_homestory_800601001_24_dialog_content = "...",
  str_homestory_800601001_25_dialog_content = "Hmm... When I think about that, I feel quite fortunate.",
  str_homestory_800601001_26_dialog_content = "Fortunate? Why is that?",
  str_homestory_800601001_27_dialog_content = "Because I'm not alone in the face of the enemy.",
  str_homestory_800601001_28_dialog_content = "I'm super grateful to have all these friends.",
  str_homestory_800601001_29_dialog_content = "Can't agree more! It's our fortune to have each other on this journey.",
  str_homestory_800601001_30_dialog_content = "Yes.",
  str_homestory_800601001_31_dialog_content = "You seem a little sentimental today?",
  str_homestory_800601001_32_dialog_content = "I think it's this place... It's perfect for pondering.",
  str_homestory_800601001_33_dialog_content = "No war. No lousy princes and nobles. Everything is so peaceful and tranquil.",
  str_homestory_800601001_34_dialog_content = "I'll leave you to it. Enjoy the solitude.",
  str_homestory_800601001_35_dialog_content = "Thank you, PlayerName.",
  str_homestory_800601001_36_dialog_content = "You're welcome, Carleen.",
  str_homestory_800201001_0_dialog_content = "Greeting, Commander Hiiro.",
  str_homestory_800201001_1_dialog_content = "What brought you here?",
  str_homestory_800201001_2_dialog_content = "Also have a wish to make?",
  str_homestory_800201001_3_dialog_content = "Ah, yes.",
  str_homestory_800201001_4_dialog_content = "I saw you here so I came to say hi.",
  str_homestory_800201001_5_dialog_content = "Good.",
  str_homestory_800201001_6_dialog_content = "You are... Meditating?",
  str_homestory_800201001_7_dialog_content = "I'm praying.<sprite=emo_mojing size=60 />",
  str_homestory_800201001_8_dialog_content = "...!",
  str_homestory_800201001_9_dialog_content = "You seem surprised.",
  str_homestory_800201001_10_option_content = "Admit",
  str_homestory_800201001_11_dialog_content = "I... I didn't think you would pray.",
  str_homestory_800201001_12_option_content = "Deny",
  str_homestory_800201001_13_dialog_content = "It's more of a shock than a surprise...",
  str_homestory_800201001_14_dialog_content = "You are so powerful... I didn't think trivial matters would trouble you.",
  str_homestory_800201001_15_dialog_content = "I'll take it as a compliment.",
  str_homestory_800201001_16_dialog_content = "I'm praying to myself, not to any god.",
  str_homestory_800201001_17_dialog_content = "Praying to yourself?",
  str_homestory_800201001_18_dialog_content = "I'm a little confused...",
  str_homestory_800201001_19_dialog_content = "I heard many people would come here to pray.",
  str_homestory_800201001_20_dialog_content = "I think a prayer might make it clearer to our hearts what we truly want.",
  str_homestory_800201001_21_dialog_content = "In other words, praying here can help us figure out our desires.",
  str_homestory_800201001_22_dialog_content = "Ah... Got it.",
  str_homestory_800201001_23_dialog_content = "It's like to find \"the mission we truly want to complete\"?",
  str_homestory_800201001_24_dialog_content = "Exactly.",
  str_homestory_800201001_25_dialog_content = "So... Have you found it now?",
  str_homestory_800201001_26_dialog_content = "Yes.",
  str_homestory_800201001_27_dialog_content = "The \"prayer\" didn't make it as clear as expected... But I've found my path.",
  str_homestory_800201001_28_dialog_content = "Didn't you know which way to go before?",
  str_homestory_800201001_29_dialog_content = "It has always been clear which way I should go.",
  str_homestory_800201001_30_dialog_content = "But I wasn't quite sure which way my heart wanted to go or wished for.",
  str_homestory_800201001_31_dialog_content = "Now I can totally understand why people are so keen to pray.",
  str_homestory_800201001_32_dialog_content = "Yeah...",
  str_homestory_800201001_33_dialog_content = "For a powerful figure like Commander Hiiro, praying can help you understand the things your heart truly desires...",
  str_homestory_800201001_34_dialog_content = "For those who struggle to make a living, prayers are their devout sustenance.",
  str_homestory_800201001_35_dialog_content = "So, that's why the Fountain of Hope is essential.",
  str_homestory_800201001_36_dialog_content = "You and Vice worked hard for this place.",
  str_homestory_800201001_37_dialog_content = "(The conversation suddenly turned into an admonitory talk to an underling...)",
  str_homestory_800201001_38_dialog_content = "I won't waste more of your precious time. Go and pray, PlayerName.",
  str_homestory_800201001_39_dialog_content = "Bye.",
  str_homestory_800201001_40_dialog_content = "Ah... Yes, Commander Hiiro!",
  str_homestory_802501001_0_dialog_content = "He's reciting a poem?",
  str_homestory_802501001_1_dialog_content = "Not bad...",
  str_homestory_802501001_2_dialog_content = "Not bad?",
  str_homestory_802501001_3_dialog_content = "Hmm. I have to say...",
  str_homestory_802501001_4_dialog_content = "Not bad! This stage is not bad at all!<sprite=emo_yinfu size=60 />",
  str_homestory_802501001_5_dialog_content = "Stage?",
  str_homestory_802501001_6_dialog_content = "Hey, PlayerName. Perfect timing.",
  str_homestory_802501001_7_dialog_content = "Look! A small square outside the Hyacinth Tower...",
  str_homestory_802501001_8_dialog_content = "Isn't this perfect for a moving stage play?",
  str_homestory_802501001_9_dialog_content = "PlayerName, don't waste this light and space.",
  str_homestory_802501001_10_dialog_content = "Please allow me this opportunity to put on a legendary show right here!",
  str_homestory_802501001_11_option_content = "Agree",
  str_homestory_802501001_12_dialog_content = "Sure... Just don't make too much noise...",
  str_homestory_802501001_13_dialog_content = "Not possible!",
  str_homestory_802501001_14_dialog_content = "Trains! Flames! Blood-stained mugs! Heavy metal! Vinyl! And speakers!",
  str_homestory_802501001_15_dialog_content = "I'll make sure my play reaches every corner of the island!",
  str_homestory_802501001_16_dialog_content = "... Wouldn't this disturb the residents?",
  str_homestory_802501001_17_dialog_content = "Disturb the residents? Don't they know how to appreciate art?",
  str_homestory_802501001_18_dialog_content = "Ah-ha-ha! That's not the case!",
  str_homestory_802501001_19_dialog_content = "An indie piece is often appreciated by only a few people with a special interest!",
  str_homestory_802501001_20_dialog_content = "However, I believe your show will be better at the still of the night.",
  str_homestory_802501001_21_dialog_content = "Listen, Charon...",
  str_homestory_802501001_22_option_content = "Reject",
  str_homestory_802501001_23_dialog_content = "What shall I do?",
  str_homestory_802501001_24_dialog_content = "Your cold rejection just sparked new ideas in my head!",
  str_homestory_802501001_25_dialog_content = "The intertwined ideas are shouting and tearing deep in my soul like wild chargers!",
  str_homestory_802501001_26_dialog_content = "What is growling? Art! A performance beyond control...",
  str_homestory_802501001_27_dialog_content = "Now is the time! Let this show echo throughout Eraveil!",
  str_homestory_802501001_28_dialog_content = "(My rejection didn't seem to work at all...)",
  str_homestory_802501001_29_dialog_content = "How about another day?",
  str_homestory_802501001_30_dialog_content = "... Another day?",
  str_homestory_802501001_31_dialog_content = "Ah... A burst of sorrow has suddenly filled my heart.",
  str_homestory_802501001_32_dialog_content = "PlayerName, you have learned to ignore others.",
  str_homestory_802501001_33_dialog_content = "Okay, I'll consider giving you a \"cold and detached role\" in my show.",
  str_homestory_802501001_34_dialog_content = "...",
  str_homestory_810501001_0_dialog_content = "You are so busy, Eve!",
  str_homestory_810501001_1_dialog_content = "Good to see you, Navigator!<sprite=emo_aixin size=60 />",
  str_homestory_810501001_2_dialog_content = "I will be with you shortly. Now I must think about what else I need...",
  str_homestory_810501001_3_dialog_content = "Ah... Don't worry about me!",
  str_homestory_810501001_4_dialog_content = "If you're looking for something, I might be able to help.",
  str_homestory_810501001_5_dialog_content = "Aww... You've prepared so much for us!",
  str_homestory_810501001_6_dialog_content = "I want to make some presents.",
  str_homestory_810501001_7_dialog_content = "I was thinking about which color is better for an embroidered flower or a cup holder.",
  str_homestory_810501001_8_dialog_content = "Embroidered flower? Cup holder?",
  str_homestory_810501001_9_dialog_content = "Yes.",
  str_homestory_810501001_10_dialog_content = "I made a top for Dawn<sprite=emo_qunzi size=60 />. I'd like to add a few dawn flowers on it...",
  str_homestory_810501001_11_dialog_content = "Hmm... The cup holder... You know my brother always carries a bottle of water for me to drink...",
  str_homestory_810501001_12_dialog_content = "A cute cup holder would be a nice gift for him.",
  str_homestory_810501001_13_dialog_content = "Heheh. Navigator, what do you think?",
  str_homestory_810501001_14_dialog_content = "Terrific!",
  str_homestory_810501001_15_dialog_content = "These are very thoughtful gifts. I'm sure Dawn and your brother would be very happy.",
  str_homestory_810501001_16_dialog_content = "Yeah! So glad to hear...",
  str_homestory_810501001_17_dialog_content = "So... Which color should I choose?",
  str_homestory_810501001_18_dialog_content = "Dawn flowers are usually white, but it might be fun to use a different color...",
  str_homestory_810501001_19_dialog_content = "For the cup holder, I can't decide between red and black. Which one would brother like more?",
  str_homestory_810501001_20_dialog_content = "Ahh... It's a hard decision.",
  str_homestory_810501001_21_dialog_content = "Hmm...",
  str_homestory_810501001_22_dialog_content = "What's the color of the top you made for Dawn?",
  str_homestory_810501001_23_dialog_content = "Black!",
  str_homestory_810501001_24_dialog_content = "I think white dawn flowers would look really nice on it.",
  str_homestory_810501001_25_dialog_content = "Try to make the pattern raised above the fabric so Dawn can feel the dawn flowers with her hands.",
  str_homestory_810501001_26_dialog_content = "Raised white dawn flowers...",
  str_homestory_810501001_27_dialog_content = "Ah... That's a fantastic idea!",
  str_homestory_810501001_28_dialog_content = "Glad I could be of help.",
  str_homestory_810501001_29_dialog_content = "How about the cup holder for my brother? Navigator, any thought on it?",
  str_homestory_810501001_30_option_content = "Yes",
  str_homestory_810501001_31_dialog_content = "If you can't decide between the two colors, why not make a black and red checkered one?",
  str_homestory_810501001_32_dialog_content = "However, Eve...",
  str_homestory_810501001_33_option_content = "Not really",
  str_homestory_810501001_34_dialog_content = "To be honest, Eve...",
  str_homestory_810501001_35_dialog_content = "Sinsa will be beside himself with joy for anything you gift him.",
  str_homestory_810501001_36_dialog_content = "Even a random leaf or a handful of sand from you is worth bragging about like the rarest treasures.",
  str_homestory_810501001_37_dialog_content = "Hmm...",
  str_homestory_810501001_38_dialog_content = "Yes, I agree with you...",
  str_homestory_810501001_39_dialog_content = "In this case, I'll pick my favorite color. Heheh.",
  str_homestory_810501001_40_dialog_content = "Hmm... I think it will be just fine.",
  str_homestory_810501001_41_dialog_content = "Eve... You are working so hard for Dawn and Sinsa's gifts. Anything for yourself?",
  str_homestory_810501001_42_dialog_content = "Hmm? Sorry, Navigator. I don't understand...",
  str_homestory_810501001_43_dialog_content = "What should I prepare for myself?",
  str_homestory_810501001_44_dialog_content = "Ah... I mean...",
  str_homestory_810501001_45_dialog_content = "Look. You asked me for nutritive soil and dawn flower seeds a while ago. Those were for Dawn, right?",
  str_homestory_810501001_46_dialog_content = "So she can grow flowers here happily.",
  str_homestory_810501001_47_dialog_content = "And you got some Rediesel Wrench snacks from Vice because you were concerned Sinsa might not have anything to go with his drinks.",
  str_homestory_810501001_48_dialog_content = "Ah... Navigator, you know everything...",
  str_homestory_810501001_49_dialog_content = "You are right.",
  str_homestory_810501001_50_dialog_content = "But...",
  str_homestory_810501001_51_dialog_content = "Why not prepare something for yourself?",
  str_homestory_810501001_52_dialog_content = "Hmm... I prepared these for Dawn and my brother so they could be happier here.",
  str_homestory_810501001_53_dialog_content = "I am already over the moon being around them all the time.",
  str_homestory_810501001_54_dialog_content = "Ah... And you and Vice!",
  str_homestory_810501001_55_dialog_content = "Your presence makes me happy!",
  str_homestory_810501001_56_dialog_content = "I don't need to prepare anything for myself.",
  str_homestory_810501001_57_dialog_content = "Is that so?.",
  str_homestory_810501001_58_dialog_content = "You are so thoughtful and sweet...",
  str_homestory_810501001_59_dialog_content = "So are you, Navigator!",
  str_homestory_810501001_60_dialog_content = "Boo-hoo...",
  str_homestory_810501001_61_dialog_content = "What's the matter?",
  str_homestory_810501001_62_dialog_content = "Navigator, why are you suddenly shedding tears?",
  str_homestory_810501001_63_dialog_content = "*Sob* I wish I had a sister like Eve...<sprite=emo_daku size=60 />",
  str_homestory_811201001_0_dialog_content = "Smokey?",
  str_homestory_811201001_1_dialog_content = "What happened, Smokey?",
  str_homestory_811201001_2_dialog_content = "You look really mad.",
  str_homestory_811201001_3_dialog_content = "Hey, Navigator.",
  str_homestory_811201001_4_dialog_content = "Don't you think this store has too small a selection of products to offer?<sprite=emo_shengqi size=60 />",
  str_homestory_811201001_5_dialog_content = "Ah! Are you mad at this?",
  str_homestory_811201001_6_dialog_content = "Is there something in particular you can't find here? Just let me know.",
  str_homestory_811201001_7_dialog_content = "Are you sure you want to hear?",
  str_homestory_811201001_8_dialog_content = "Yeah. Go ahead.",
  str_homestory_811201001_9_dialog_content = "Then I'll cut to the chase.",
  str_homestory_811201001_10_dialog_content = "First of all, there's no accessory detergent at all.",
  str_homestory_811201001_11_dialog_content = "Then, the buttons available in the store are absolutely terrible!",
  str_homestory_811201001_12_dialog_content = "Trust me. No one would want to put any of these on their clothes.",
  str_homestory_811201001_13_dialog_content = "Pardon me. Those Illumina fellas might like these actually.",
  str_homestory_811201001_14_dialog_content = "Buttons... As long as it does the job...",
  str_homestory_811201001_15_dialog_content = "Can't blame you. After all, most of you don't know much about fashion.",
  str_homestory_811201001_16_dialog_content = "Don't look down upon yourself. You've got me here.",
  str_homestory_811201001_17_dialog_content = "Thanks...",
  str_homestory_811201001_18_dialog_content = "Also, this place is way hotter and sunnier than Umbraton.",
  str_homestory_811201001_19_dialog_content = "I see parasols here but where are the shades and sunscreens? You got none!",
  str_homestory_811201001_20_dialog_content = "Well, you're right...",
  str_homestory_811201001_21_dialog_content = "(Smokey can't be the only Aurorian who struggles to find what she needs here.)",
  str_homestory_811201001_22_dialog_content = "(What shall I do? It will take ages to talk to them one by one...)",
  str_homestory_811201001_23_dialog_content = "Hey, what are you murmuring?",
  str_homestory_811201001_24_dialog_content = "Am I too much for you? Are you troubled that there might be other picky shoppers like me?",
  str_homestory_811201001_25_option_content = "Nod",
  str_homestory_811201001_26_dialog_content = "Good. Honesty is gold.",
  str_homestory_811201001_27_dialog_content = "I'm more worried than troubled...",
  str_homestory_811201001_28_option_content = "Shake the head",
  str_homestory_811201001_29_dialog_content = "No, Smokey, it doesn't trouble me at all...",
  str_homestory_811201001_30_dialog_content = "Actually, trouble or not is not the point here.",
  str_homestory_811201001_31_dialog_content = "There might be others facing a similar problem as you but I'm not sure how to tackle it...",
  str_homestory_811201001_32_dialog_content = "... You need to develop an Eraveil Ordering System.",
  str_homestory_811201001_33_dialog_content = "Everyone can log the products they need into the system regularly. Orders are then placed across Astra accordingly.",
  str_homestory_811201001_34_dialog_content = "Delivery... I bet you can figure out some special technology, right?",
  str_homestory_811201001_35_dialog_content = "The Courier Union<sprite=emo_gezitou size=60 />, Fireflies and such.",
  str_homestory_811201001_36_dialog_content = "Ah... Good idea...",
  str_homestory_811201001_37_dialog_content = "This way you don't need to speak to us one by one. And you won't get another complaint like mine.",
  str_homestory_811201001_38_dialog_content = "You know some Aurorians are quite special.",
  str_homestory_811201001_39_dialog_content = "They could be fond of coffins, painting brushes of all kinds, or bizarre bugs...",
  str_homestory_811201001_40_dialog_content = "And some of them can't live without gin.",
  str_homestory_811201001_41_dialog_content = "Wait... You said gin?",
  str_homestory_811201001_42_dialog_content = "You're talking about... Genevieve?",
  str_homestory_811201001_43_dialog_content = "Is she the only one who loves to have a drink?",
  str_homestory_811201001_44_dialog_content = "... I don't understand how your brain works!",
  str_homestory_811201001_45_dialog_content = "Okay... So you're not talking about her. There's another big fan of gin!",
  str_homestory_811201001_46_dialog_content = "That's right! Many people out there enjoy a drink or two, okay?<sprite=emo_nuhuo size=60 />",
  str_homestory_811201001_47_dialog_content = "Sure... Don't be angry! And don't set anything on fire...",
  str_homestory_811201001_48_dialog_content = "Hmph.",
  str_homestory_811201001_49_dialog_content = "Thank you, Smokey!",
  str_homestory_811201001_50_dialog_content = "Your advise is very helpful!",
  str_homestory_811201001_51_dialog_content = "Gotta go. See you.",
  str_homestory_811201001_52_dialog_content = "See you!",
  str_homestory_807101001_0_dialog_content = "Taki's kite...",
  str_homestory_807101001_1_dialog_content = "Ahem... Taki...",
  str_homestory_807101001_2_dialog_content = "Huh? PlayerName?",
  str_homestory_807101001_3_dialog_content = "Um... I saw your kite...",
  str_homestory_807101001_4_dialog_content = "It was on the ground.",
  str_homestory_807101001_5_dialog_content = "... Oh.",
  str_homestory_807101001_6_dialog_content = "But I picked it up quickly.",
  str_homestory_807101001_7_dialog_content = "...<sprite=emo_yihuo size=60 />",
  str_homestory_807101001_8_dialog_content = "(That's not the point...)",
  str_homestory_807101001_9_dialog_content = "Okay. Based on that, I think your kite flying skill is...",
  str_homestory_807101001_10_option_content = "Quite good!",
  str_homestory_807101001_11_dialog_content = "Kid, trying to give consolation?",
  str_homestory_807101001_12_dialog_content = "Ahem... I just wanted to be supportive...",
  str_homestory_807101001_13_dialog_content = "Understood but fake compliments are the least I need.",
  str_homestory_807101001_14_dialog_content = "I see. As long as you didn't lose your heart...",
  str_homestory_807101001_15_option_content = "Nonexistent!",
  str_homestory_807101001_16_dialog_content = "I'm happy to teach you.",
  str_homestory_807101001_17_dialog_content = "Okay. Teach me then.",
  str_homestory_807101001_18_dialog_content = "Huh? That was easy.",
  str_homestory_807101001_19_dialog_content = "Of course.",
  str_homestory_807101001_20_dialog_content = "It's not a shame to learn from the better.",
  str_homestory_807101001_21_dialog_content = "Admit what we don't understand and communication will be more effective. It's particularly true for any businessman.",
  str_homestory_807101001_22_dialog_content = "The proprietor of Odd Jobs never fails to impress me!",
  str_homestory_807101001_23_dialog_content = "So what's the trick to flying a kite? Tell me.",
  str_homestory_807101001_24_dialog_content = "First, you need to make sure you are facing away from the wind.",
  str_homestory_807101001_25_dialog_content = "The kite will catch the wind this way.",
  str_homestory_807101001_26_dialog_content = "Then you begin to let some line out to help the kite climb higher into the air. If there is not enough wind, you must reel in the line quickly.",
  str_homestory_807101001_27_dialog_content = "Run slowly as you fly the kite. Keep an eye on it always.",
  str_homestory_807101001_28_dialog_content = "If your kite is flying steadily high in the air...",
  str_homestory_807101001_29_dialog_content = "You can tie it to a tree or a signpost and find a comfy spot to watch it fly.",
  str_homestory_807101001_30_dialog_content = "Okay... The direction of the wind... The force of the wind... Slow run... And interaction with the kite...<sprite=emo_wuyu size=60 />",
  str_homestory_807101001_31_dialog_content = "Ah? Are you reciting it?",
  str_homestory_807101001_32_dialog_content = "I can repeat everything I just said if you like...",
  str_homestory_807101001_33_dialog_content = "It's fine. I've memorized everything.",
  str_homestory_807101001_34_dialog_content = "Hmm? Why are you still muttering to yourself then?",
  str_homestory_807101001_35_dialog_content = "Umm... I mean... Why not give it a try?",
  str_homestory_807101001_36_dialog_content = "I'm planning how to print this \"How to Fly a Kite\" book for better sales.",
  str_homestory_807101001_37_dialog_content = "... Huh?",
  str_homestory_807101001_38_dialog_content = "Imagine this. If the Odd Jobs began selling kites and really ramping up the advertisement...",
  str_homestory_807101001_39_dialog_content = "Purchase a kite and get a free coaching session for a limited time only.",
  str_homestory_807101001_40_dialog_content = "What happens if one can't fly a kite after the coaching session? Buy the book \"How to Fly a Kite.\"",
  str_homestory_807101001_41_dialog_content = "We can have all kinds of kites. Maybe even with a headshot of the Shadowlord...",
  str_homestory_807101001_42_dialog_content = "Woah, w-wait a minute!",
  str_homestory_807101001_43_dialog_content = "So you're here flying a kite and learning kite flying skills from me...",
  str_homestory_807101001_44_dialog_content = "To make money?",
  str_homestory_807101001_45_dialog_content = "Yeah.",
  str_homestory_807101001_46_dialog_content = "Kid, I'm a businessman.",
  str_homestory_807101001_47_dialog_content = "Do you have a problem?",
  str_homestory_807101001_48_dialog_content = "No. Not at all...",
  str_homestory_807101001_49_dialog_content = "I admire your strong business sense!",
  str_homestory_807101001_50_dialog_content = "I wouldn't run over the budget every day if I knew how to make money with things around me...",
  str_homestory_807101001_51_dialog_content = "Hmm... You're worried about money.",
  str_homestory_807101001_52_dialog_content = "Listen. Since I got some inspiration from you for this business...",
  str_homestory_807101001_53_dialog_content = "Half of the profit will be yours when it's really happening at the Odd Jobs.",
  str_homestory_807101001_54_dialog_content = "?!",
  str_homestory_807101001_55_dialog_content = "You're being serious?",
  str_homestory_807101001_56_dialog_content = "Yes, but don't get too excited yet.",
  str_homestory_807101001_57_dialog_content = "This business might be a total disaster.",
  str_homestory_807101001_58_dialog_content = "No problem. Taki, I have faith in you!",
  str_homestory_807101001_59_dialog_content = "Okay. I must practice my kite flying skills now.",
  str_homestory_807101001_60_dialog_content = "Kid, you must be busy. Move on with your day.",
  str_homestory_807101001_61_dialog_content = "You got this! Taki!",
  str_homestory_807101001_62_dialog_content = "(... Yes! I've decided!)",
  str_homestory_807101001_63_dialog_content = "(For my half of the profit... I'll make sure Taki practices and improves every day!)<sprite=emo_yaosu size=60 />",
  str_homestory_803301001_0_dialog_content = "Vice?",
  str_homestory_803301001_1_dialog_content = "Inhale... Vice, you can do this!",
  str_homestory_803301001_2_dialog_content = "Breath deeply... Exhale...<sprite=emo_tanqi size=60 />",
  str_homestory_803301001_3_dialog_content = "Exhale?",
  str_homestory_803301001_4_dialog_content = "Vice, you... You're practicing breathing?",
  str_homestory_803301001_5_dialog_content = "Ahh! PlayerName?",
  str_homestory_803301001_6_dialog_content = "... Practice breathing?",
  str_homestory_803301001_7_dialog_content = "I'm not...",
  str_homestory_803301001_8_dialog_content = "What are you doing then?",
  str_homestory_803301001_9_dialog_content = "I'm keeping accounts.",
  str_homestory_803301001_10_dialog_content = "Ah... The expenditure account is giving me a headache.",
  str_homestory_803301001_11_dialog_content = "I wish it was just a breathing exercise...",
  str_homestory_803301001_12_dialog_content = "At least breathing doesn't cost anything.",
  str_homestory_803301001_13_option_content = "Ask Vice",
  str_homestory_803301001_14_dialog_content = "Can I help?",
  str_homestory_803301001_15_dialog_content = "I went through our account book last night.",
  str_homestory_803301001_16_dialog_content = "I'm not very good at bookkeeping but I'm willing to help.",
  str_homestory_803301001_17_option_content = "Keeps silent",
  str_homestory_803301001_18_dialog_content = "Why are you so quiet?",
  str_homestory_803301001_19_dialog_content = "Ahh... I didn't mean to blame you...",
  str_homestory_803301001_20_dialog_content = "I know. I'm just thinking about how I can be of any help.",
  str_homestory_803301001_21_dialog_content = "I went through our account book last night. We did overrun a little...",
  str_homestory_803301001_22_dialog_content = "Ah... Vice... Thank you for everything you've done!",
  str_homestory_803301001_23_dialog_content = "Let me think about what I saw in the account book last night...",
  str_homestory_803301001_24_dialog_content = "\"Just the components for the Fountain of Hope, the plaza, and the rockery will cost a fortune.\"",
  str_homestory_803301001_25_dialog_content = "\"Let alone the materials required for the dorms and the museum\"...",
  str_homestory_803301001_26_dialog_content = "\"We must take into consideration the preference of each and every one of our friends...\"",
  str_homestory_803301001_27_dialog_content = "\"Such as a rocking horse, a hanging chair, and sculptures...\"",
  str_homestory_803301001_28_dialog_content = "\"These things alone are not too expensive but numbers add up quickly.\"",
  str_homestory_803301001_29_dialog_content = "\"There's so much to learn about how to communicate with the craftsmen. Installation can be challenging.\"",
  str_homestory_803301001_30_dialog_content = "\"However... I guess all the efforts of PlayerName and I are not for nothing if our guests can have a comfortable stay.\"",
  str_homestory_803301001_31_dialog_content = "Ah... You saw everything.",
  str_homestory_803301001_32_dialog_content = "Yes... I can't get rid of this old habit of writing my thoughts out... Hahah.",
  str_homestory_803301001_33_dialog_content = "Vice, honestly, you're fabulous!",
  str_homestory_803301001_34_dialog_content = "Navigator, why are you suddenly so generous with your compliments?",
  str_homestory_803301001_35_dialog_content = "I mean it!",
  str_homestory_803301001_36_dialog_content = "Look. You draw construction plans, arrange project schedules and make regional planning...",
  str_homestory_803301001_37_dialog_content = "I'm no help at all. I can't draw. Neither am I good at planning or arranging.",
  str_homestory_803301001_38_dialog_content = "Cloud Gardens owe everything to you.",
  str_homestory_803301001_39_dialog_content = "... Ah... That's true...",
  str_homestory_803301001_40_dialog_content = "But there's no need for thanks!",
  str_homestory_803301001_41_dialog_content = "I just want to cheer you up.",
  str_homestory_803301001_42_dialog_content = "Let's work together to keep us out of the red.",
  str_homestory_803301001_43_dialog_content = "Yes! You're absolutely right!",
  str_homestory_803301001_44_dialog_content = "Ah... Since it's quite hard to buy things in Cloud Gardens...",
  str_homestory_803301001_45_dialog_content = "How about we increase our prices for everything by ten times?<sprite=emo_yaosu size=60 />",
  str_homestory_803301001_46_dialog_content = "... Err... I don't think that's necessary...",
  str_homestory_803301001_47_dialog_content = "Heheh. Navigator, that was a joke!",
  str_homestory_803301001_48_dialog_content = "Seriously, how can we make some money? Let me think...",
  str_homestory_804101001_0_dialog_content = "Ms. Blanc...",
  str_homestory_804101001_1_dialog_content = "Hey, PlayerName.",
  str_homestory_804101001_2_dialog_content = "It's a nice day<sprite=emo_pugongying size=60 />, Ms. Blanc.",
  str_homestory_804101001_3_dialog_content = "Yes.",
  str_homestory_804101001_4_dialog_content = "Are you taking a walk or on your way somewhere?",
  str_homestory_804101001_5_option_content = "Just walking",
  str_homestory_804101001_6_dialog_content = "A good choice.",
  str_homestory_804101001_7_dialog_content = "It's beautiful here, with many recreation facilities...",
  str_homestory_804101001_8_dialog_content = "And a lot of people I've never met before.",
  str_homestory_804101001_9_option_content = "Going fishing",
  str_homestory_804101001_10_dialog_content = "Ah. Are you good at fishing?",
  str_homestory_804101001_11_option_content = "Very good",
  str_homestory_804101001_12_dialog_content = "Really?",
  str_homestory_804101001_13_dialog_content = "I'll come and check.",
  str_homestory_804101001_14_dialog_content = "Welcome!",
  str_homestory_804101001_15_dialog_content = "Heheh. A very confident youth!",
  str_homestory_804101001_16_option_content = "Just so-so...",
  str_homestory_804101001_17_dialog_content = "Fishing takes a lot of patience.",
  str_homestory_804101001_18_dialog_content = "I thought you were a bit too young for this.",
  str_homestory_804101001_19_dialog_content = "Hmm... I find it helpful with my concentration.",
  str_homestory_804101001_20_dialog_content = "Umm...",
  str_homestory_804101001_21_dialog_content = "Only those who \"have trouble focusing\" need to do things that help improve concentration.",
  str_homestory_804101001_22_dialog_content = "But you'll benefit from it over time.",
  str_homestory_804101001_23_dialog_content = "Yes...",
  str_homestory_804101001_24_dialog_content = "Ms. Blanc, why are you standing under this wooden sign?",
  str_homestory_804101001_25_dialog_content = "I'm observing.",
  str_homestory_804101001_26_dialog_content = "Observing?",
  str_homestory_804101001_27_dialog_content = "Can't help with it.",
  str_homestory_804101001_28_dialog_content = "All these new buildings and roads... I want to engrave them all in my head.",
  str_homestory_804101001_29_dialog_content = "I see.",
  str_homestory_804101001_30_dialog_content = "The roads here are not complicated. Maybe Ms. Blanc can relax a little.",
  str_homestory_804101001_31_dialog_content = "Relax?",
  str_homestory_804101001_32_dialog_content = "That's a real luxury...",
  str_homestory_804101001_33_dialog_content = "But I must heed your advise.",
  str_homestory_804101001_34_dialog_content = "PlayerName, have a good rest yourself.",
  str_homestory_804101001_35_dialog_content = "Overwork will speed up aging.<sprite=emo_guilian size=60 />",
  str_homestory_804101001_36_dialog_content = "Okay...",
  str_homestory_804101001_37_dialog_content = "I wish! Ms. Blanc!",
  str_homestory_813801001_0_dialog_content = "Siobhan!",
  str_homestory_813801001_1_dialog_content = "PlayerName?",
  str_homestory_813801001_2_dialog_content = "Ah... Thank goodness you're here...<sprite=emo_tanqi size=60 />",
  str_homestory_813801001_3_dialog_content = "What's up, Siobhan? You look tired.",
  str_homestory_813801001_4_dialog_content = "Because... I stayed up all night to view all the collected items in the museum.",
  str_homestory_813801001_5_dialog_content = "These collectibles are a perfect record of Eraveil's past and all the technologies Caelestites developed...",
  str_homestory_813801001_6_dialog_content = "I have to admit my admiration for your scientific prowess.",
  str_homestory_813801001_7_dialog_content = "Thank you. Illumina is doing very well in science and technology.",
  str_homestory_813801001_8_dialog_content = "I don't know why but I can't shake off this feeling...",
  str_homestory_813801001_9_dialog_content = "Caelestites' technology is nothing like Illumina's.",
  str_homestory_813801001_10_dialog_content = "Illumina's technology is based on elaborate mechanical networks developed with solid knowledge and precision...",
  str_homestory_813801001_11_dialog_content = "But Caelestites'... Everything feels so fresh and different.",
  str_homestory_813801001_12_dialog_content = "Similar to those ancient technologies in some way.",
  str_homestory_813801001_13_dialog_content = "Well, I don't know anything about this...",
  str_homestory_813801001_14_dialog_content = "Ho-hum...",
  str_homestory_813801001_15_dialog_content = "Feeling sleepy all of a sudden...<sprite=emo_xuanyun size=60 />",
  str_homestory_813801001_16_dialog_content = "What are you waiting for? Go back and sleep.",
  str_homestory_813801001_17_dialog_content = "I'm trying to match these collectibles to the documents I read before. Hopefully, there will be intriguing discoveries.",
  str_homestory_813801001_18_dialog_content = "There might be Caelestites somewhere else on this continent way before our time...",
  str_homestory_813801001_19_dialog_content = "People had no idea they were actually Caelestites and thus mistook their technology for ancient ones.",
  str_homestory_813801001_20_dialog_content = "... Hahahah. Never mind.",
  str_homestory_813801001_21_dialog_content = "I'm getting a little unrealistic here. I should probably go to bed.",
  str_homestory_813801001_22_dialog_content = "Siobhan, I'm worried about you.",
  str_homestory_813801001_23_dialog_content = "Why do you have to finish it now?",
  str_homestory_813801001_24_dialog_content = "I don't think you can work well in this state...",
  str_homestory_813801001_25_dialog_content = "Aren't you hosting quite a few citizens of Lumopolis here?",
  str_homestory_813801001_26_dialog_content = "Although a Caelestite like yourself is here, I doubt they'll dare to destroy the museum...",
  str_homestory_813801001_27_dialog_content = "I... I'm just rather worried!",
  str_homestory_813801001_28_dialog_content = "I feel I need to get everything recorded and analyzed as soon as possible.",
  str_homestory_813801001_29_dialog_content = "Who knows how those technology haters really think about this place?",
  str_homestory_813801001_30_dialog_content = "I see...",
  str_homestory_813801001_31_dialog_content = "Don't worry. As far as I know, there are plenty of museums in Lumopolis.",
  str_homestory_813801001_32_dialog_content = "They're my guests here. Whatever you're worried about, it won't happen.",
  str_homestory_813801001_33_dialog_content = "Am I overthinking?",
  str_homestory_813801001_34_dialog_content = "Is overwork making me worry too much?<sprite=emo_sikao size=60 />",
  str_homestory_813801001_35_dialog_content = "I think you're just tired.",
  str_homestory_813801001_36_dialog_content = "How about we take a break and get back to it later?",
  str_homestory_813801001_37_dialog_content = "Alright. That's what I'll do... PlayerName.",
  str_homestory_813801001_38_dialog_content = "I'm going to bed. How about you?",
  str_homestory_813801001_39_dialog_content = "I bet you can use some rest yourself?",
  str_homestory_813801001_40_option_content = "Agree",
  str_homestory_813801001_41_dialog_content = "Yeah, I'm also tired.",
  str_homestory_813801001_42_dialog_content = "But...",
  str_homestory_813801001_43_option_content = "Object",
  str_homestory_813801001_44_dialog_content = "My body might be tired but my spirit feels fulfilled!",
  str_homestory_813801001_45_dialog_content = "I don't mind all this work at all as long as everyone can have a good time here.",
  str_homestory_813801001_46_dialog_content = "You might be young but your sense of leadership is strong.",
  str_homestory_813801001_47_dialog_content = "Thanks...",
  str_homestory_813801001_48_dialog_content = "Don't know why I keep wanting to go to the river, but I'm just too sleepy to do that.",
  str_homestory_813801001_49_dialog_content = "We'll talk more about Caelestite technology after my nap, PlayerName.",
  str_homestory_813801001_50_dialog_content = "Rest well, Siobhan.",
  str_homestory_814501001_0_dialog_content = "What's she looking at?",
  str_homestory_814501001_1_dialog_content = "Amemori?",
  str_homestory_814501001_2_dialog_content = "Hush.<sprite=emo_baiyan size=60 />",
  str_homestory_814501001_3_dialog_content = "?",
  str_homestory_814501001_4_dialog_content = "What are you doing?",
  str_homestory_814501001_5_dialog_content = "Observing.",
  str_homestory_814501001_6_dialog_content = "I'm examining this place very carefully and thoroughly.",
  str_homestory_814501001_7_dialog_content = "Is there anything unusual about it?",
  str_homestory_814501001_8_dialog_content = "Don't you think the design for Cloud Gardens is exquisitely intricate?",
  str_homestory_814501001_9_dialog_content = "I fantasized about building such a place when I was young.",
  str_homestory_814501001_10_dialog_content = "One that is easy to launch an attack from, that's easy to defend, and a great conclave for likeminded individuals.",
  str_homestory_814501001_11_dialog_content = "Oh!",
  str_homestory_814501001_12_dialog_content = "Have you been making such long-term plans since childhood, Amemori?",
  str_homestory_814501001_13_dialog_content = "Well, the dream to me back then was probably just an impetus to \"keep on living.\"",
  str_homestory_814501001_14_dialog_content = "But it's not bad that I can live up here now.",
  str_homestory_814501001_15_dialog_content = "Uh, sorry.",
  str_homestory_814501001_16_dialog_content = "Would you like me to show you around?",
  str_homestory_814501001_17_dialog_content = "That won't be necessary.",
  str_homestory_814501001_18_dialog_content = "I already figured out the lay of the land on my first day.",
  str_homestory_814501001_19_dialog_content = "Wow, how perceptive!",
  str_homestory_814501001_20_dialog_content = "That's what a ninja does.",
  str_homestory_814501001_21_dialog_content = "Actually, I'd like to know who designed this place?",
  str_homestory_814501001_22_dialog_content = "Navigator, do you happen to know?",
  str_homestory_814501001_23_option_content = "Yes",
  str_homestory_814501001_24_dialog_content = "It was Vice who designed it in accordance to suggestions from me and the craftsmen.",
  str_homestory_814501001_25_option_content = "No",
  str_homestory_814501001_26_dialog_content = "I can ask her if you want.",
  str_homestory_814501001_27_dialog_content = "I dabbled in the actual plan, but she knows it the best.",
  str_homestory_814501001_28_dialog_content = "Amemori, why do you want to know so badly?",
  str_homestory_814501001_29_dialog_content = "Are you interested in building another Cloud Gardens on Cloud Island?",
  str_homestory_814501001_30_dialog_content = "That thought did cross my mind.",
  str_homestory_814501001_31_dialog_content = "Imagine, once Cloud Island has dwellings on this level, people would enjoy a much better life.",
  str_homestory_814501001_32_dialog_content = "Of course, that's just the beginning...",
  str_homestory_814501001_33_dialog_content = "If we truly manage to learn this advanced technology, it would be easier for us to defend against enemies.",
  str_homestory_814501001_34_dialog_content = "Caelestite tech with such marvelous planning... It's worth us looking into.",
  str_homestory_814501001_35_dialog_content = "I see.",
  str_homestory_814501001_36_dialog_content = "I'll get the answer for you!",
  str_homestory_814501001_37_dialog_content = "Thank you, Navigator.",
  str_homestory_814601001_0_dialog_content = "Head wagging...",
  str_homestory_814601001_1_dialog_content = "All the Aurorians...",
  str_homestory_814601001_2_dialog_content = "Passing through Cloud Gardens.",
  str_homestory_814601001_3_dialog_content = "?",
  str_homestory_814601001_4_dialog_content = "The arch rises from the flat ground...",
  str_homestory_814601001_5_dialog_content = "With a stuffed bun in the hand!<sprite=emo_yaosu size=60 />",
  str_homestory_814601001_6_dialog_content = "...",
  str_homestory_814601001_7_dialog_content = "Yao, you're reciting a poem?",
  str_homestory_814601001_8_dialog_content = "Hey, Navigator!",
  str_homestory_814601001_9_dialog_content = "I'm not reciting.",
  str_homestory_814601001_10_dialog_content = "But composing! What do you think?",
  str_homestory_814601001_11_option_content = "Good!",
  str_homestory_814601001_12_dialog_content = "Really good!",
  str_homestory_814601001_13_dialog_content = "Yao, you're a gifted poet!",
  str_homestory_814601001_14_option_content = "Not bad",
  str_homestory_814601001_15_dialog_content = "I would say this poem is somewhere between Charon and Vice's works.",
  str_homestory_814601001_16_dialog_content = "Neither too exaggerated nor too realistic, it reveals the Poet's true desire...",
  str_homestory_814601001_17_dialog_content = "Ahem... But what does the arch have to do with stuffed buns?",
  str_homestory_814601001_18_dialog_content = "Just look at this archer. Don't you see my future stuffed bun shop?",
  str_homestory_814601001_19_dialog_content = "Still thinking about opening a stuffed bun shop?",
  str_homestory_814601001_20_dialog_content = "Tired of upholding justice and helping the weak?",
  str_homestory_814601001_21_dialog_content = "I want to do both.",
  str_homestory_814601001_22_dialog_content = "Isn't it nice to retire from the martial life to a stuffed bun shop when I'm grey?",
  str_homestory_814601001_23_dialog_content = "You know. Legendary warriors often choose to retire somewhere in a busy market...",
  str_homestory_814601001_24_dialog_content = "They can continue to hear the legend they left behind!",
  str_homestory_814601001_25_dialog_content = "Don't these warriors have better things to do?",
  str_homestory_814601001_26_dialog_content = "Forget about them. Come and check out my plan!",
  str_homestory_814601001_27_dialog_content = "Go ahead. I'm all ears.",
  str_homestory_814601001_28_dialog_content = "First of all, the stuffed bun shop must have three floors.",
  str_homestory_814601001_29_dialog_content = "Half of the first floor is for Anzu and Momo to sell their tasty food. The other half is for my delicious dishes!",
  str_homestory_814601001_30_dialog_content = "The second floor is more like a tavern so my friends don't have to worry about accommodation when we chat late into the night!",
  str_homestory_814601001_31_dialog_content = "The third floor is where I live!",
  str_homestory_814601001_32_dialog_content = "There will be rooms for me, Amemori, and Rinne. Navigator and Vice as well...",
  str_homestory_814601001_33_dialog_content = "And Kayano. And my friends from the Lin clan, my sworn sister and parents...",
  str_homestory_814601001_34_dialog_content = "Should I keep a room for Taki? He might not like being surrounded by so many girls.<sprite=emo_sikao size=60 />",
  str_homestory_814601001_35_dialog_content = "And Dayna and Robyn?",
  str_homestory_814601001_36_dialog_content = "Wait... Yao, I don't think you can make any money this way...",
  str_homestory_814601001_37_dialog_content = "It will cost you a fortune to prepare all these rooms for your friends.",
  str_homestory_814601001_38_dialog_content = "Some people prefer solitude. This kind of commune life is not for everyone...",
  str_homestory_814601001_39_dialog_content = "Money is not an issue!",
  str_homestory_814601001_40_dialog_content = "Hmm... But personal preference is a problem...",
  str_homestory_814601001_41_dialog_content = "Anyway, they're my friends and I'll prepare their rooms.",
  str_homestory_814601001_42_dialog_content = "But it's completely up to them if they want to come or not.",
  str_homestory_814601001_43_dialog_content = "Heheh. Everyone is happy. No reluctance or compromise.",
  str_homestory_814601001_44_dialog_content = "Yes, you're right...",
  str_homestory_814601001_45_dialog_content = "This is a solution exclusively for the super rich...",
  str_homestory_816301001_0_dialog_content = "Are you drawing?",
  str_homestory_816301001_1_dialog_content = "Whoa! <sprite=emo_wuzui size=60 />The Airship BossPlayerName!",
  str_homestory_816301001_2_dialog_content = "Finally! I've been searching for you everywhere...",
  str_homestory_816301001_3_dialog_content = "Err... How can I help?",
  str_homestory_816301001_4_dialog_content = "I was touring about making arrangements with people for their contributions when I discovered this drawing board...",
  str_homestory_816301001_5_dialog_content = "Miss Vice said you purchased this against all dissenting voices.",
  str_homestory_816301001_6_dialog_content = "May I take it as...",
  str_homestory_816301001_7_dialog_content = "You've finally agreed to create artwork for Al***my St**s?<sprite=emo_yaosu size=60 />",
  str_homestory_816301001_8_option_content = "Confirm",
  str_homestory_816301001_9_dialog_content = "Yes, I've been playing with this idea.",
  str_homestory_816301001_10_dialog_content = "Whoa! Finally you're willing to face your gift!",
  str_homestory_816301001_11_dialog_content = "Err... I need to do something to help with the financial crisis.",
  str_homestory_816301001_12_dialog_content = "My skills are not getting better anytime soon.",
  str_homestory_816301001_13_dialog_content = "I'd rather leave this to someone who actually enjoys drawing, such as you...",
  str_homestory_816301001_14_option_content = "Deny",
  str_homestory_816301001_15_dialog_content = "Ahem... I know my abilities...",
  str_homestory_816301001_16_dialog_content = "This board is for anyone passionate about drawing.",
  str_homestory_816301001_17_dialog_content = "Airship Boss, please put your hand at your chest.",
  str_homestory_816301001_18_dialog_content = "Feel that heart beating with love for drawing.",
  str_homestory_816301001_19_dialog_content = "Speaking of love for drawing, you're second to none.",
  str_homestory_816301001_20_dialog_content = "Mr. Tourdog.",
  str_homestory_816301001_21_dialog_content = "...!",
  str_homestory_816301001_22_dialog_content = "Day and night you approach people for their contributions to your game. When was the last time you had a proper sleep?",
  str_homestory_816301001_23_dialog_content = "For my game, I don't need to sleep or dine.",
  str_homestory_816301001_24_dialog_content = "Then how long haven't you drawn freely?",
  str_homestory_816301001_25_dialog_content = "Whoa...",
  str_homestory_816301001_26_dialog_content = "You really want me to draw on your board?<sprite=emo_yihuo size=60 />",
  str_homestory_816301001_27_dialog_content = "If Mr. Tourdog, the celebrity of Astra, would draw something here...",
  str_homestory_816301001_28_dialog_content = "It'd be perfect!",
  str_homestory_816301001_29_dialog_content = "First, find the target's soft spot and have a pep talk. Then, praise the target before making your request.<sprite=emo_sikao size=60 />",
  str_homestory_816301001_30_dialog_content = "Is this how you play the mind game?",
  str_homestory_816301001_31_dialog_content = "After requesting so many contributions, I almost fell for your trap. Interesting!",
  str_homestory_816301001_32_dialog_content = "The protagonist chosen by the investors is indeed impressive!",
  str_homestory_816301001_33_dialog_content = "The game's plot won't be boring as long as you're still here.",
  str_homestory_816301001_34_option_content = "Ask about the investors",
  str_homestory_816301001_35_dialog_content = "Investors?",
  str_homestory_816301001_36_dialog_content = "A group of able bosses who share a strong faith in you.",
  str_homestory_816301001_37_dialog_content = "You don't need to know who they are.",
  str_homestory_816301001_38_option_content = "Ask about the protagonist",
  str_homestory_816301001_39_dialog_content = "Protagonist?",
  str_homestory_816301001_40_dialog_content = "The central figure of this game, the absolute star loved by everyone.",
  str_homestory_816301001_41_dialog_content = "This position is not for everyone.",
  str_homestory_816301001_42_dialog_content = "You're losing me.",
  str_homestory_816301001_43_dialog_content = "All in all, Airship Boss.",
  str_homestory_816301001_44_dialog_content = "I'll draw you a scroll painting of Cloud Gardens for free!",
  str_homestory_816301001_45_dialog_content = "As my tuition fee for your unique mind game to request contributions.",
  str_homestory_816301001_46_dialog_content = "Look forward to working with you.<sprite=emo_guilian size=60 />",
  str_homestory_816301001_47_dialog_content = "Umm... Likewise...",
  str_homestory_816301001_48_dialog_content = "Excellent. I need to plan the composition of this drawing.",
  str_homestory_816301001_49_dialog_content = "Normally a drawing takes me no more than 3 seconds, but I must give my utmost best for the Airship Boss.",
  str_homestory_816301001_50_dialog_content = "Hmm...",
  str_homestory_816301001_51_dialog_content = "How should I start?",
  str_homestory_816301001_52_dialog_content = "I'll leave you to it...",
  str_homestory_816301001_53_dialog_content = "(I don't think he can hear me.)",
  str_homestory_816301001_54_dialog_content = "(I'm out of here...)",
  str_homestory_814801001_0_dialog_content = "She's here?",
  str_homestory_814801001_1_dialog_content = "Azure...",
  str_homestory_814801001_2_dialog_content = "Huh?",
  str_homestory_814801001_3_dialog_content = "Whose cute face is this? Absolutely adorable.",
  str_homestory_814801001_4_dialog_content = "Come here. Let me feel if it's soft.",
  str_homestory_814801001_5_dialog_content = "Ah<sprite=emo_yundao size=60 />... Wait!",
  str_homestory_814801001_6_dialog_content = "It's me... PlayerName.",
  str_homestory_814801001_7_dialog_content = "PlayerName? Sounds familiar.",
  str_homestory_814801001_8_dialog_content = "Ah! Hahahah. I remember now!",
  str_homestory_814801001_9_dialog_content = "That's my little Caelestite boyfriend!",
  str_homestory_814801001_10_option_content = "Admit",
  str_homestory_814801001_11_dialog_content = "... Yes. It's me.",
  str_homestory_814801001_12_dialog_content = "Wow! You admit it?",
  str_homestory_814801001_13_dialog_content = "Then you better take responsibility.",
  str_homestory_814801001_14_option_content = "Deny",
  str_homestory_814801001_15_dialog_content = "Azure, please don't joke like that...",
  str_homestory_814801001_16_dialog_content = "Other people might misunderstand...",
  str_homestory_814801001_17_dialog_content = "Oh? What are you so afraid of?",
  str_homestory_814801001_18_dialog_content = "You don't want that dragon-tailed Illumina girl to hear?",
  str_homestory_814801001_19_dialog_content = "Or are you thinking about that aloof princess from Lumopolis?",
  str_homestory_814801001_20_dialog_content = "...",
  str_homestory_814801001_21_dialog_content = "Even cuter when you blush. Hahahah.",
  str_homestory_814801001_22_dialog_content = "I... I have to go...<sprite=emo_hanshui size=60 />",
  str_homestory_814801001_23_dialog_content = "There, there. I stop now.",
  str_homestory_814801001_24_dialog_content = "Were you looking for me earlier?",
  str_homestory_814801001_25_dialog_content = "I just want to ask how you are getting along here...",
  str_homestory_814801001_26_dialog_content = "Aww... My little Caelestite is so caring. I'm really touched.",
  str_homestory_814801001_27_dialog_content = "Thanks to you, I'm having a blast here.",
  str_homestory_814801001_28_dialog_content = "Quite different from that scorching and barren desert, this place is so green.",
  str_homestory_814801001_29_dialog_content = "Not hot. Not dry. Even the wind is very gentle.",
  str_homestory_814801001_30_dialog_content = "Much less irritating scum.",
  str_homestory_814801001_31_dialog_content = "A natural beauty salon...",
  str_homestory_814801001_32_dialog_content = "Don't you think I'm more beautiful now?",
  str_homestory_814801001_33_option_content = "Confirm",
  str_homestory_814801001_34_dialog_content = "Yes, your beauty has climaxed...",
  str_homestory_814801001_35_option_content = "Deny",
  str_homestory_814801001_36_dialog_content = "You can't possibly get more beautiful for you are perfect already.",
  str_homestory_814801001_37_dialog_content = "Where did you learn all these sweet words?",
  str_homestory_814801001_38_dialog_content = "I guess I should stay longer to enjoy your warm hospitality?",
  str_homestory_814801001_39_dialog_content = "Little Caelestite, do you want me to stay?",
  str_homestory_814801001_40_option_content = "Confirm",
  str_homestory_814801001_41_dialog_content = "Of course... You're welcome to stay for as long as you like.",
  str_homestory_814801001_42_dialog_content = "The door is always open for you.",
  str_homestory_814801001_43_option_content = "Deny",
  str_homestory_814801001_44_dialog_content = "I... I have no expectation...",
  str_homestory_814801001_45_dialog_content = "You, and everyone else, are free to come and go...",
  str_homestory_814801001_46_dialog_content = "Well, I'll make myself at home then.",
  str_homestory_814801001_47_dialog_content = "Tell your shop to order some decent wine.",
  str_homestory_814801001_48_dialog_content = "I can't wait any longer. Okay?",
  str_homestory_814801001_49_dialog_content = "Yes...",
  str_homestory_814801001_50_dialog_content = "What are you waiting for?<sprite=emo_emo size=60 />",
  str_homestory_814801001_51_dialog_content = "I'm on it!",
  str_homestory_815001001_0_dialog_content = "Completely still...",
  str_homestory_815001001_1_dialog_content = "Hello, PlayerName.<sprite=emo_heimao size=60 />",
  str_homestory_815001001_2_dialog_content = "Lenore's very happy to see you.",
  str_homestory_815001001_3_dialog_content = "Lenore, why are you standing still here like a statue?",
  str_homestory_815001001_4_dialog_content = "Don't you want to take a walk around?",
  str_homestory_815001001_5_dialog_content = "Take a walk around?",
  str_homestory_815001001_6_dialog_content = "Is this a new order from PlayerName?",
  str_homestory_815001001_7_dialog_content = "Where exactly should I go?",
  str_homestory_815001001_8_dialog_content = "Lenore, this is not an order. If you must, take it as a piece of advice.",
  str_homestory_815001001_9_dialog_content = "What's the difference between an order and a piece of advice?",
  str_homestory_815001001_10_dialog_content = "Hmm... Let me think.",
  str_homestory_815001001_11_dialog_content = "An order is something you must do.",
  str_homestory_815001001_12_dialog_content = "A piece of advice is just a suggestion that you don't have to take.",
  str_homestory_815001001_13_dialog_content = "Understood.",
  str_homestory_815001001_14_dialog_content = "PlayerName advised Lenore to take a walk around. It's a piece of advice.",
  str_homestory_815001001_15_dialog_content = "Lenore can choose to walk around or not.",
  str_homestory_815001001_16_dialog_content = "Very smart! You got it completely!",
  str_homestory_815001001_17_dialog_content = "Thanks for the compliment, PlayerName.",
  str_homestory_815001001_18_dialog_content = "You're very welcome.",
  str_homestory_815001001_19_dialog_content = "...",
  str_homestory_815001001_20_dialog_content = "...",
  str_homestory_815001001_21_dialog_content = "...",
  str_homestory_815001001_22_dialog_content = "Err... Lenore?",
  str_homestory_815001001_23_dialog_content = "So you don't want to walk around?",
  str_homestory_815001001_24_dialog_content = "Isn't it just a piece of advice?",
  str_homestory_815001001_25_dialog_content = "Lenore doesn't have to do it.",
  str_homestory_815001001_26_dialog_content = "Ah, well...",
  str_homestory_815001001_27_dialog_content = "I've planted many beautiful flowers and trees. And some new recreation facilities have been installed!",
  str_homestory_815001001_28_dialog_content = "Don't you want to see them?",
  str_homestory_815001001_29_dialog_content = "Should Lenore want to see them?",
  str_homestory_815001001_30_option_content = "Command",
  str_homestory_815001001_31_dialog_content = "Well... There's no other way. Okay. I order Lenore to have a look around.",
  str_homestory_815001001_32_dialog_content = "Yes. Lenore will complete the mission.",
  str_homestory_815001001_33_option_content = "Suggest",
  str_homestory_815001001_34_dialog_content = "I know it sounds like bragging but I really think I did a pretty good job.",
  str_homestory_815001001_35_dialog_content = "So... I think you should check them out.",
  str_homestory_815001001_36_dialog_content = "Since PlayerName said so, Lenore will go.",
  str_homestory_815001001_37_dialog_content = "Yes. Go and enjoy.",
  str_homestory_815001001_38_dialog_content = "But where should Lenore go?",
  str_homestory_815001001_39_dialog_content = "PlayerName, do you have any advice for Lenore?",
  str_homestory_815001001_40_dialog_content = "Ah!",
  str_homestory_815001001_41_dialog_content = "What's the matter, PlayerName?",
  str_homestory_815001001_42_dialog_content = "Nothing...",
  str_homestory_815001001_43_dialog_content = "Lenore has really learned about the word \"advice.\"",
  str_homestory_815001001_44_dialog_content = "I'm a little moved...",
  str_homestory_801901001_0_dialog_content = "Victoria...",
  str_homestory_801901001_1_dialog_content = "Hi, PlayerName.",
  str_homestory_801901001_2_dialog_content = "Victoria, good to see you.",
  str_homestory_801901001_3_dialog_content = "I'm admiring these merry streams. Would you like to join me?",
  str_homestory_801901001_4_dialog_content = "Admiring streams?",
  str_homestory_801901001_5_dialog_content = "Excuse me... What is so special about this stream coming down the rockery?",
  str_homestory_801901001_6_dialog_content = "The water has entered an endless cycle without knowing.",
  str_homestory_801901001_7_dialog_content = "Don't you think it's quite similar to us Aurorians?",
  str_homestory_801901001_8_option_content = "Nod",
  str_homestory_801901001_9_dialog_content = "Yes, it's a bit...",
  str_homestory_801901001_10_dialog_content = "Still, I didn't fully understand your words...",
  str_homestory_801901001_11_option_content = "Shake the head",
  str_homestory_801901001_12_dialog_content = "Sorry, Victoria...",
  str_homestory_801901001_13_dialog_content = "I'm a little lost.",
  str_homestory_801901001_14_dialog_content = "Don't worry about it. Just an insignificant remark.",
  str_homestory_801901001_15_dialog_content = "What is Victoria's thought on this?",
  str_homestory_801901001_16_dialog_content = "The water has no idea it is following a cycle.",
  str_homestory_801901001_17_dialog_content = "Because it flows aimlessly.",
  str_homestory_801901001_18_dialog_content = "It doesn't know why it's flowing, how to escape from this cycle or where the end is.",
  str_homestory_801901001_19_dialog_content = "The majority of us live our lives like this, don't you think?",
  str_homestory_801901001_20_dialog_content = "I'm not criticizing or taking pity in any way.",
  str_homestory_801901001_21_dialog_content = "How one lives his life doesn't make a difference to me.",
  str_homestory_801901001_22_dialog_content = "I'm just trying to think.",
  str_homestory_801901001_23_dialog_content = "... Trying to think?",
  str_homestory_801901001_24_dialog_content = "Yes.",
  str_homestory_801901001_25_dialog_content = "We must respect our thoughts. Anything that drives you to think is beyond your current understanding.",
  str_homestory_801901001_26_dialog_content = "... You mean... we need to respect the unknown?",
  str_homestory_801901001_27_dialog_content = "More or less, dear.",
  str_homestory_801901001_28_dialog_content = "These streams might be having a merry time. They don't need our voice in their flow.",
  str_homestory_801901001_29_dialog_content = "It's a good thing to be happy and content in this cycle.",
  str_homestory_801901001_30_dialog_content = "So... They won't exclaim over matters like this as you did?",
  str_homestory_801901001_31_dialog_content = "Heheh. Who knows?",
  str_homestory_801901001_32_dialog_content = "By the way... The sun is very harsh here<sprite=emo_taiyang size=60 />.",
  str_homestory_801901001_33_dialog_content = "Err... We've got parasols over there. Victoria, would you like to move over?",
  str_homestory_801901001_34_dialog_content = "Thank you for your concern, PlayerName. I think I can use some rest.",
  str_homestory_801901001_35_dialog_content = "May the Truth bless you!",
  str_homestory_800901001_0_dialog_content = "Mr. Faust?",
  str_homestory_800901001_1_dialog_content = "Dear Navigator, good to see you again.",
  str_homestory_800901001_2_dialog_content = "Likewise.",
  str_homestory_800901001_3_dialog_content = "Actually, I didn't expect to see you during the day.",
  str_homestory_800901001_4_dialog_content = "Please don't take me wrong. I personally prefer the night, but I'm not against the energy of the day.",
  str_homestory_800901001_5_dialog_content = "Wispy seems to like it here.",
  str_homestory_800901001_6_dialog_content = "... Wait. Wispy likes here?",
  str_homestory_800901001_7_dialog_content = "Do we have a lot of sadness and despair here?",
  str_homestory_800901001_8_dialog_content = "I still remember how this special case drooled over my helplessness...",
  str_homestory_800901001_9_dialog_content = "Wispy can find comfort in many things.",
  str_homestory_800901001_10_dialog_content = "Sad memories, nightmares, desperate beliefs, or cold water...",
  str_homestory_800901001_11_dialog_content = "Huh?!",
  str_homestory_800901001_12_dialog_content = "(Recalling the time spent looking after Wispy...<sprite=emo_sikao size=60 />)",
  str_homestory_800901001_13_dialog_content = "(So people are sad and having nightmares here?)",
  str_homestory_800901001_14_dialog_content = "Dear Navigator, please don't overthink.",
  str_homestory_800901001_15_dialog_content = "Wispy's comfort...",
  str_homestory_800901001_16_dialog_content = "Might come from Aurorians' past, not their present feelings.",
  str_homestory_800901001_17_dialog_content = "As far as I know, many of us had a bitter, painful past.",
  str_homestory_800901001_18_dialog_content = "If you put it this way...",
  str_homestory_800901001_19_dialog_content = "Yes... Very true.",
  str_homestory_800901001_20_dialog_content = "I hope everyone is happy here.",
  str_homestory_800901001_21_dialog_content = "Sometimes memories and emotions are beyond control, dear Navigator.",
  str_homestory_800901001_22_dialog_content = "It's a good habit to not worry excessively about others.",
  str_homestory_800901001_23_dialog_content = "Let nature take its course.",
  str_homestory_800901001_24_dialog_content = "... Okay.",
  str_homestory_800901001_25_dialog_content = "So you're here for?",
  str_homestory_800901001_26_option_content = "Spreading the truth?",
  str_homestory_800901001_27_dialog_content = "No, my dear Navigator.",
  str_homestory_800901001_28_option_content = "Feeding Wispy?",
  str_homestory_800901001_29_dialog_content = "Yes, my dear Navigator.",
  str_homestory_800901001_30_dialog_content = "This is the perfect spot for feeding Wispy...",
  str_homestory_800901001_31_dialog_content = "Wispy can freely feel the passers-by.",
  str_homestory_800901001_32_dialog_content = "Let Wispy freely feel...",
  str_homestory_800901001_33_dialog_content = "Err... Is there so much unspeakable pain in their hearts?",
  str_homestory_800901001_34_dialog_content = "Your guess is as good as mine, dear Navigator.",
  str_homestory_800901001_35_dialog_content = "However, here's one thing I know for certain.",
  str_homestory_800901001_36_dialog_content = "Yes?",
  str_homestory_800901001_37_dialog_content = "Wispy drank a ton of cold water before we left home.",
  str_homestory_800901001_38_dialog_content = "?",
  str_homestory_800901001_39_dialog_content = "So Wispy's comfort could be a result of all the ice water it just drank?",
  str_homestory_800901001_40_dialog_content = "That means there might not be much sorrow, pain, or other negative feelings after all.",
  str_homestory_800901001_41_dialog_content = "You tricked me!",
  str_homestory_800901001_42_dialog_content = "I'm afraid so, my dear Navigator.",
  str_homestory_800901001_43_dialog_content = "But I did so to distract you from all the work and stress.",
  str_homestory_800901001_44_dialog_content = "Things don't have to be perfect, right?",
  str_homestory_800901001_45_dialog_content = "May the Truth bless you!",
  str_homestory_800901001_46_dialog_content = "Why you...!<sprite=emo_shengqi size=60 />",
  str_homestory_815101001_0_dialog_content = "This nursery rhyme...",
  str_homestory_815101001_1_dialog_content = "There's a black lamb called Isaac. Scary fleece can burn your arm!",
  str_homestory_815101001_2_dialog_content = "Hi, Giles!",
  str_homestory_815101001_3_dialog_content = "Ah. Dear Navigator.",
  str_homestory_815101001_4_dialog_content = "I almost forgot. You've heard this nursery rhyme already.",
  str_homestory_815101001_5_dialog_content = "It's time for something new?",
  str_homestory_815101001_6_dialog_content = "A new, somewhat prophetic work centering on the mysterious Caelestite...<sprite=emo_baimao size=60 />",
  str_homestory_815101001_7_dialog_content = "Err...",
  str_homestory_815101001_8_dialog_content = "You look reluctant, Navigator?",
  str_homestory_815101001_9_dialog_content = "That breaks my heart...",
  str_homestory_815101001_10_dialog_content = "You said my nursery rhymes were your favorite...",
  str_homestory_815101001_11_dialog_content = "(... Did I really?)",
  str_homestory_815101001_12_option_content = "Have you finished creating the work?",
  str_homestory_815101001_13_dialog_content = "It doesn't take long when there's inspiration.",
  str_homestory_815101001_14_dialog_content = "Perfect. The source of inspiration is right in front of me...",
  str_homestory_815101001_15_option_content = "Could you please wait?",
  str_homestory_815101001_16_dialog_content = "You didn't even bother making up some excuse.",
  str_homestory_815101001_17_dialog_content = "This is a clear rejection to me.",
  str_homestory_815101001_18_dialog_content = "Charming and agile, the Caelestite can easily steal your heart...",
  str_homestory_815101001_19_dialog_content = "... Already started?",
  str_homestory_815101001_20_dialog_content = "La la la! La la la! A charming house full of flowers.",
  str_homestory_815101001_21_dialog_content = "Fishes and shrimps also call it home.",
  str_homestory_815101001_22_dialog_content = "She lives here with it. Together they embrace a fearless Caelestite.",
  str_homestory_815101001_23_dialog_content = "Pitpat... Pitpat... The rain of time drizzles.",
  str_homestory_815101001_24_dialog_content = "Build towers high. Strengthen them with bricks and tiles. Search for ways to become stronger.",
  str_homestory_815101001_25_dialog_content = "La la la! La la la! Where is the Caelestite now?",
  str_homestory_815101001_26_dialog_content = "Home is now big and tall. Look at the Caelestite above the clouds, blinking not.",
  str_homestory_815101001_27_dialog_content = "La la la! La la la! A charming house full of flowers...",
  str_homestory_815101001_28_dialog_content = "... This is your prophecy?",
  str_homestory_815101001_29_dialog_content = "Just a simple nursery rhyme, Navigator.",
  str_homestory_815101001_30_dialog_content = "Are you scared? It's just a work of mine...",
  str_homestory_815101001_31_dialog_content = "Yes, I know.",
  str_homestory_815101001_32_dialog_content = "I often find your nursery rhymes simple yet obscure.",
  str_homestory_815101001_33_dialog_content = "A nursery rhyme is nothing more than a nursery rhyme.",
  str_homestory_815101001_34_dialog_content = "Navigator, please don't think too much about it.",
  str_homestory_815101001_35_dialog_content = "Fine. Let's come back to real life...",
  str_homestory_815101001_36_dialog_content = "How are you feeling here?",
  str_homestory_815101001_37_dialog_content = "Isaac and I both love it.",
  str_homestory_815101001_38_dialog_content = "I have a strong desire to write more... Hahah!",
  str_homestory_815101001_39_dialog_content = "Whether it's the random passersby or the Navigator, they're all sources of inspiration for me.<sprite=emo_emo size=60 />",
  str_homestory_815101001_40_dialog_content = "Good to hear...",
  str_homestory_815101001_41_dialog_content = "Baa... Baa...",
  str_homestory_815101001_42_dialog_content = "I need a moment alone with Isaac. Excuse us, Navigator.",
  str_homestory_815101001_43_dialog_content = "See you next time?",
  str_homestory_815101001_44_dialog_content = "Alright... See you.",
  str_homestory_815301001_0_dialog_content = "The Grand Marshal?",
  str_homestory_815301001_1_dialog_content = "You did a great job with the infrastructure.<sprite=emo_dianzan size=60 />",
  str_homestory_815301001_2_dialog_content = "Thank you for your kind words, Grand Marshal!",
  str_homestory_815301001_3_dialog_content = "I'm so used to the neat and uniform squares in Illumina. This one is different and refreshing.",
  str_homestory_815301001_4_dialog_content = "People look down upon Illumina for our poor taste in art and low standard of beauty.",
  str_homestory_815301001_5_dialog_content = "Sadly, many of those places that pursue perfection in the art are struggling to feed their people.",
  str_homestory_815301001_6_dialog_content = "Well-structured things cost less and work more efficiently. This is fairly simple to understand.",
  str_homestory_815301001_7_dialog_content = "But I have to say it's beautiful here.",
  str_homestory_815301001_8_dialog_content = "Pretty and tidy. You and Vice must have worked hard for this.",
  str_homestory_815301001_9_option_content = "Nod",
  str_homestory_815301001_10_dialog_content = "It was mostly Vice... I don't know much about this at all.",
  str_homestory_815301001_11_dialog_content = "Well, it's a merit to own up to your shortcomings.",
  str_homestory_815301001_12_option_content = "Shake the head",
  str_homestory_815301001_13_dialog_content = "Not too bad. Fireflies helped a lot. And our friends from the Courier Union.",
  str_homestory_815301001_14_dialog_content = "It's our pleasure as long as everyone is having a good time here.",
  str_homestory_815301001_15_dialog_content = "Isn't this the most precious quality you two have?",
  str_homestory_815301001_16_dialog_content = "In my opinion, taking pleasure in serving others is a special gift.",
  str_homestory_815301001_17_dialog_content = "As you have thoughtfully arranged...",
  str_homestory_815301001_18_dialog_content = "I'm staying in a room just like Vice's. And we eat the same food every day.",
  str_homestory_815301001_19_dialog_content = "You're treating me way better than most people.",
  str_homestory_815301001_20_dialog_content = "It's hard to treat everyone equally regardless of their status and position.",
  str_homestory_815301001_21_dialog_content = "(Didn't expect the Grand Marshal to see things from this angle...)",
  str_homestory_815301001_22_dialog_content = "(Should I tell the truth?)",
  str_homestory_815301001_23_dialog_content = "(Okay... I'd better be honest...)",
  str_homestory_815301001_24_dialog_content = "Actually, Grand Marshal...",
  str_homestory_815301001_25_dialog_content = "We can't afford any better rooms...",
  str_homestory_815301001_26_dialog_content = "That I know.",
  str_homestory_815301001_27_dialog_content = "It's not about how big your budget is but how you plan to spend the money in the first place.",
  str_homestory_815301001_28_dialog_content = "I think I got it...",
  str_homestory_815301001_29_dialog_content = "That's good.",
  str_homestory_815301001_30_dialog_content = "I'm going to visit my Illumina comrades.",
  str_homestory_815301001_31_dialog_content = "Bye, PlayerName.",
  str_homestory_815301001_32_dialog_content = "It was an honor speaking with you, Grand Marshal!",
  str_homestory_803801001_0_dialog_content = "Playing again?",
  str_homestory_803801001_1_dialog_content = "Hi, PlayerName!",
  str_homestory_803801001_2_dialog_content = "Heheh... Fancy a game?",
  str_homestory_803801001_3_dialog_content = "Ah, no.",
  str_homestory_803801001_4_dialog_content = "I just want to ask how you are settling in here.",
  str_homestory_803801001_5_dialog_content = "Umm...",
  str_homestory_803801001_6_dialog_content = "Not bad. Could use a few more recreation facilities.",
  str_homestory_803801001_7_dialog_content = "Hmm. I got it! The super sweet PlayerName must be here to help relieve boredom. Am I right?",
  str_homestory_803801001_8_dialog_content = "Err... I...",
  str_homestory_803801001_9_dialog_content = "Heheh. Let's play a simple game...",
  str_homestory_803801001_10_dialog_content = "It's really easy. We don't need any device!",
  str_homestory_803801001_11_dialog_content = "You mean... Rock Paper Scissors?",
  str_homestory_803801001_12_dialog_content = "Nope! Quiz!",
  str_homestory_803801001_13_dialog_content = "Ready? The game is about to begin!",
  str_homestory_803801001_14_dialog_content = "Fine... Only because you are so keen on this.",
  str_homestory_803801001_15_dialog_content = "Question 1! Please answer true or false!",
  str_homestory_803801001_16_dialog_content = "Disclosure of Illumina Tech Officer Gronru's mystery origin... She's actually an android!",
  str_homestory_803801001_17_option_content = "True",
  str_homestory_803801001_18_dialog_content = "What the heck? I'm not an android!",
  str_homestory_803801001_19_option_content = "False",
  str_homestory_803801001_20_dialog_content = "Bingo! Correct!<sprite=emo_dianzan size=60 />",
  str_homestory_803801001_21_dialog_content = "Question 2!",
  str_homestory_803801001_22_dialog_content = "Raphael once beat Gronru in the Emperor's Cup!",
  str_homestory_803801001_23_option_content = "True",
  str_homestory_803801001_24_dialog_content = "Hey! No one can beat me, alright?",
  str_homestory_803801001_25_dialog_content = "I even helped her improve those gadgets.",
  str_homestory_803801001_26_option_content = "False",
  str_homestory_803801001_27_dialog_content = "Correct! Good job!",
  str_homestory_803801001_28_dialog_content = "Question 3!",
  str_homestory_803801001_29_dialog_content = "PlayerName will transfer the operating system permissions to this place to Gronru!",
  str_homestory_803801001_30_dialog_content = "True...",
  str_homestory_803801001_31_dialog_content = "Hold on! This question shouldn't be allowed in any quiz!",
  str_homestory_803801001_32_dialog_content = "Ah oh... No?",
  str_homestory_803801001_33_dialog_content = "Err... Of course not, Gronru!",
  str_homestory_803801001_34_dialog_content = "Hmm! You rejected me?",
  str_homestory_803801001_35_dialog_content = "You must be possessed by the final boss!",
  str_homestory_803801001_36_dialog_content = "Possessed? What made you say that?",
  str_homestory_803801001_37_dialog_content = "A true Caelestite can never say no to me!",
  str_homestory_803801001_38_dialog_content = "The super amiable Caelestite never turned down a single request of mine in the past!",
  str_homestory_803801001_39_dialog_content = "Pfft...",
  str_homestory_803801001_40_dialog_content = "I would probably give up anything for you except the permissions to the Colossus and this place, Gronru.",
  str_homestory_803801001_41_dialog_content = "Ahh... That's boring...",
  str_homestory_803801001_42_dialog_content = "However...",
  str_homestory_803801001_43_dialog_content = "Since you have denied my research request, I'll have to do it secretly!",
  str_homestory_803801001_44_dialog_content = "One day... Heheh. One day! I'll figure out how this system is operating!",
  str_homestory_803801001_45_dialog_content = "Alright.",
  str_homestory_803801001_46_dialog_content = "Best of luck.",
  str_homestory_803801001_47_dialog_content = "A new game is on! Very exciting...<sprite=emo_yaosu size=60 />",
  str_homestory_802601001_0_dialog_content = "Uriel...",
  str_homestory_802601001_1_dialog_content = "...",
  str_homestory_802601001_2_dialog_content = "...",
  str_homestory_802601001_3_dialog_content = "Wh-what do you want?",
  str_homestory_802601001_4_dialog_content = "Ah... Nothing. I just wanted to see you.",
  str_homestory_802601001_5_dialog_content = "I'm worried if you are doing okay here. I remember you had many sleepless nights on the Colossus.",
  str_homestory_802601001_6_dialog_content = "There's nothing not okay...",
  str_homestory_802601001_7_dialog_content = "After all, the only two things I truly care about are my Ring of Fire and Phoenix Coat...",
  str_homestory_802601001_8_dialog_content = "Umm... Is there anything I can get for you then?",
  str_homestory_802601001_9_dialog_content = "Food, toys, anything at all?",
  str_homestory_802601001_10_dialog_content = "You can tell me anything!",
  str_homestory_802601001_11_dialog_content = "I don't want anything...",
  str_homestory_802601001_12_dialog_content = "I'll burn<sprite=emo_nuhuo size=60 /> them all to the ground...",
  str_homestory_802601001_13_dialog_content = "No way, Uriel.",
  str_homestory_802601001_14_dialog_content = "I've installed fire prevention facilities here. You don't need to worry about anything!",
  str_homestory_802601001_15_dialog_content = "I see...",
  str_homestory_802601001_16_dialog_content = "Yes!",
  str_homestory_802601001_17_dialog_content = "Anything?",
  str_homestory_802601001_18_dialog_content = "...",
  str_homestory_802601001_19_dialog_content = "... No.",
  str_homestory_802601001_20_dialog_content = "Toys and recreation facilities can't provide lasting joy...",
  str_homestory_802601001_21_dialog_content = "It's brief and cheap...",
  str_homestory_802601001_22_dialog_content = "Actually, such transient joy is often followed by endless pain...",
  str_homestory_802601001_23_dialog_content = "Just think about the torture you will suffer on fire for this momentary happiness...",
  str_homestory_802601001_24_dialog_content = "I'd rather not have any of this...",
  str_homestory_802601001_25_dialog_content = "Besides... There's not always joy after the pain...",
  str_homestory_802601001_26_dialog_content = "Quite the opposite, momentary joy can be misleading, creating an illusion that your suffering always pays off...",
  str_homestory_802601001_27_dialog_content = "But that's not true at all, since suffering is endless and \"joy\" is finite...<sprite=emo_xinsui size=60 />",
  str_homestory_802601001_28_dialog_content = "... Don't you agree, PlayerName?",
  str_homestory_802601001_29_dialog_content = "(Everything sounds reasonable but I can't quite follow her logic...)",
  str_homestory_802601001_30_option_content = "Yes",
  str_homestory_802601001_31_dialog_content = "You're probably right in some sense, Uriel.",
  str_homestory_802601001_32_option_content = "No",
  str_homestory_802601001_33_dialog_content = "I understand where you come from but I can't agree with you...",
  str_homestory_802601001_34_dialog_content = "(The most important thing now is to calm her down...)",
  str_homestory_802601001_35_dialog_content = "Uriel believes the joy after the pain is cheap and momentary...",
  str_homestory_802601001_36_dialog_content = "But many people are living for this transient joy.",
  str_homestory_802601001_37_dialog_content = "Sometimes, this small happiness after suffering is hope.",
  str_homestory_802601001_38_dialog_content = "And this hope keeps us going for the next round of joy...",
  str_homestory_802601001_39_dialog_content = "However short and tiny the joy is every time, it's a moment of comfort.",
  str_homestory_802601001_40_dialog_content = "Happiness is not a reward for the pain you have undergone.",
  str_homestory_802601001_41_dialog_content = "On the contrary, it's the nutrition we desperately need to continue enduring the pain.",
  str_homestory_802601001_42_dialog_content = "...",
  str_homestory_802601001_43_dialog_content = "... Nutrition...",
  str_homestory_802601001_44_dialog_content = "... Maybe...",
  str_homestory_802601001_45_dialog_content = "(I don't think she's convinced...)",
  str_homestory_802601001_46_dialog_content = "Ahh... Anyway, Uriel, please don't treat happiness as a burden!",
  str_homestory_802601001_47_dialog_content = "... Okay...",
  str_homestory_802601001_48_dialog_content = "... I got it, PlayerName...",
  str_homestory_802601001_49_dialog_content = "... Thank you for your concern...",
  str_homestory_802601001_50_dialog_content = "Don't mention it...",
  str_homestory_802601001_51_dialog_content = "Ahh... Speaking of happiness...",
  str_homestory_802601001_52_dialog_content = "(I remember she's quite fond of reading, especially those literary works popular in Umbraton...)",
  str_homestory_802601001_53_dialog_content = "Uriel, how about I borrow a few books for you?",
  str_homestory_802601001_54_dialog_content = "You could read if you feel bored.",
  str_homestory_802601001_55_dialog_content = "Don't worry. So many of us are living here now. I've got a few copies of each book...",
  str_homestory_802601001_56_dialog_content = "... Books...",
  str_homestory_802601001_57_dialog_content = "...",
  str_homestory_802601001_58_dialog_content = "... Sounds good...",
  str_homestory_802601001_59_dialog_content = "I'll read...",
  str_homestory_802601001_60_dialog_content = "Phew... That's wonderful.",
  str_homestory_804401001_0_dialog_content = "Vivian?",
  str_homestory_804401001_1_dialog_content = "The swing is really fun, PlayerName!",
  str_homestory_804401001_2_dialog_content = "Yes! I agree.",
  str_homestory_804401001_3_dialog_content = "The wind gently blows on my face. There's not a worry on my mind...<sprite=emo_pugongying size=60 />",
  str_homestory_804401001_4_dialog_content = "The swing slowly pushes me into the wind's arms...",
  str_homestory_804401001_5_dialog_content = "All my stress is gone like a miracle.",
  str_homestory_804401001_6_dialog_content = "I'm glad you feel so relaxed on the swing.",
  str_homestory_804401001_7_dialog_content = "Hmm... The only drawback of this recreational activity is...",
  str_homestory_804401001_8_dialog_content = "My hair is a bit messy after. Hahah.",
  str_homestory_804401001_9_dialog_content = "That's right!",
  str_homestory_804401001_10_dialog_content = "No wonder Vice insists on fixing her hair every time when she gets off the swing!",
  str_homestory_804401001_11_dialog_content = "So... Who came up with the idea to build a swing, you or Vice?",
  str_homestory_804401001_12_option_content = "It was me.",
  str_homestory_804401001_13_dialog_content = "To be honest, I didn't really play on a swing growing up...",
  str_homestory_804401001_14_dialog_content = "I thought it would be nice to have one here.",
  str_homestory_804401001_15_option_content = "It was Vice.",
  str_homestory_804401001_16_dialog_content = "Vice strongly demanded one here!",
  str_homestory_804401001_17_dialog_content = "I wasn't sure about this at first, but she went ahead confidently with the construction drawing despite my hesitation. I thought...",
  str_homestory_804401001_18_dialog_content = "It wasn't a big deal to put up a swing here. Some of you might like it.",
  str_homestory_804401001_19_dialog_content = "Ahh...",
  str_homestory_804401001_20_dialog_content = "This is a fabulous decision!",
  str_homestory_804401001_21_dialog_content = "Heheh... Thank you for your kind words, Vivian.",
  str_homestory_804401001_22_dialog_content = "Speaking of swings...",
  str_homestory_804401001_23_dialog_content = "There are not many in Illumina.",
  str_homestory_804401001_24_dialog_content = "Hmm... Is that so?",
  str_homestory_804401001_25_dialog_content = "This is probably why Vice and Vivian both love this swing so much.",
  str_homestory_804401001_26_dialog_content = "Yeah. Things seldom seen are more appealing.",
  str_homestory_804401001_27_dialog_content = "Hmm... Right...",
  str_homestory_804401001_28_dialog_content = "Umm? What's on your mind?",
  str_homestory_804401001_29_dialog_content = "Ahh... Nothing.",
  str_homestory_804401001_30_dialog_content = "I was calculating how necessary this expense <sprite=emo_baiyebi size=60 />is.",
  str_homestory_804401001_31_dialog_content = "Expense?",
  str_homestory_804401001_32_dialog_content = "What expense?",
  str_homestory_804401001_33_dialog_content = "I wonder how much it will cost to build a swing...",
  str_homestory_804401001_34_dialog_content = "In every orphanage, school, and base in Illumina.",
  str_homestory_804401001_35_dialog_content = "Ah... I see.",
  str_homestory_804401001_36_dialog_content = "I don't think our budget can afford this project...",
  str_homestory_804401001_37_dialog_content = "Unless other projects of ours could cut some costs.",
  str_homestory_804401001_38_dialog_content = "Hmm... That's tricky.",
  str_homestory_804401001_39_dialog_content = "How about a few swings less?",
  str_homestory_804401001_40_dialog_content = "Fewer swings but at better locations?",
  str_homestory_804401001_41_dialog_content = "Such as...",
  str_homestory_804401001_42_dialog_content = "Somewhere everyone would pass by!",
  str_homestory_804401001_43_dialog_content = "Like the junctions between undercities, and the middle of several orphanages or schools...",
  str_homestory_804401001_44_dialog_content = "You're a genius, little PlayerName!",
  str_homestory_804401001_45_dialog_content = "Happy to help.",
  str_homestory_804401001_46_dialog_content = "However...",
  str_homestory_804401001_47_dialog_content = "Why were you so nervous when I mentioned the budget earlier?",
  str_homestory_804401001_48_dialog_content = "Hah... Ah hah...",
  str_homestory_804401001_49_dialog_content = "You sounded just like Vice when she checks the account book...",
  str_homestory_804401001_50_dialog_content = "It was probably a conditioned response!",
  str_homestory_804401001_51_dialog_content = "Aww... Little Vice and little PlayerName are so close...<sprite=emo_guilian size=60 />",
  str_homestory_808501001_0_dialog_content = "Jane?",
  str_homestory_808501001_1_dialog_content = "Hello, PlayerName.",
  str_homestory_808501001_2_dialog_content = "Ah, Jane!",
  str_homestory_808501001_3_dialog_content = "Are you... Taking notes of Cloud Gardens?",
  str_homestory_808501001_4_dialog_content = "Yes, I'll note down everything that happens here.",
  str_homestory_808501001_5_dialog_content = "But right now I'm not recording. This is a moment to completely let go.<sprite=emo_pugongying size=60 />",
  str_homestory_808501001_6_dialog_content = "Let go?",
  str_homestory_808501001_7_dialog_content = "What happened? Is something troubling you?",
  str_homestory_808501001_8_dialog_content = "Or is there too much pressure?",
  str_homestory_808501001_9_dialog_content = "I guess both.",
  str_homestory_808501001_10_dialog_content = "PlayerName, as a professional Witness, I can't intervene in certain things.",
  str_homestory_808501001_11_dialog_content = "Yeah, I heard about that.",
  str_homestory_808501001_12_dialog_content = "Well...",
  str_homestory_808501001_13_dialog_content = "If you were a Witness, would you help a victim of a gang fight?",
  str_homestory_808501001_14_option_content = "Of course.",
  str_homestory_808501001_15_dialog_content = "Being a witness is just a job...",
  str_homestory_808501001_16_option_content = "No.",
  str_homestory_808501001_17_dialog_content = "To me, it doesn't matter so much to remain absolutely objective...",
  str_homestory_808501001_18_dialog_content = "I might call someone for help right away.",
  str_homestory_808501001_19_dialog_content = "So you'd try to help but not get involved yourself?",
  str_homestory_808501001_20_dialog_content = "Exactly.",
  str_homestory_808501001_21_dialog_content = "What would Jane do?",
  str_homestory_808501001_22_dialog_content = "It was a very specific question you just asked. Are you troubled by something like this in real life?",
  str_homestory_808501001_23_dialog_content = "Yeah. I recently helped a little girl.",
  str_homestory_808501001_24_dialog_content = "I'm still troubled by the decision I made at the time.",
  str_homestory_808501001_25_dialog_content = "What are your worries?",
  str_homestory_808501001_26_dialog_content = "What if my interference changed how things would have unfolded?",
  str_homestory_808501001_27_dialog_content = "When a witness wavers, her testimony is no longer neutral.",
  str_homestory_808501001_28_dialog_content = "It might be that little girl's fate to vanish from this world. And that was supposed to be the consequence of this gang fight.",
  str_homestory_808501001_29_dialog_content = "Now I saved her...",
  str_homestory_808501001_30_dialog_content = "... My biased testimony is pointless.",
  str_homestory_808501001_31_dialog_content = "First of all, you're a real person with feelings. Then, you're a witness who tries her best to remain neutral.",
  str_homestory_808501001_32_dialog_content = "This I understand.",
  str_homestory_808501001_33_dialog_content = "...",
  str_homestory_808501001_34_dialog_content = "... I see.",
  str_homestory_808501001_35_dialog_content = "How about including yourself in this testimony?",
  str_homestory_808501001_36_dialog_content = "Including myself?",
  str_homestory_808501001_37_dialog_content = "Yes, write down the whole story faithfully.",
  str_homestory_808501001_38_dialog_content = "A Witness triggered by the scene intervened in the process after this gang fight... It might have an impact.",
  str_homestory_808501001_39_dialog_content = "... Something like that.",
  str_homestory_808501001_40_dialog_content = "...",
  str_homestory_808501001_41_dialog_content = "You have a point.",
  str_homestory_808501001_42_dialog_content = "I'll try to record the incident in this way.",
  str_homestory_808501001_43_dialog_content = "Thank you.",
  str_homestory_808801001_0_dialog_content = "Maggie!",
  str_homestory_808801001_1_dialog_content = "Navigator... Are you also here for the story?<sprite=emo_wuzui size=60 />",
  str_homestory_808801001_2_dialog_content = "Story? What story?",
  str_homestory_808801001_3_dialog_content = "I thought we could have a chat. Now I'm very interested in this story.",
  str_homestory_808801001_4_dialog_content = "Ah oh... It slipped out...",
  str_homestory_808801001_5_dialog_content = "Hmm? Maggie doesn't want me to know?",
  str_homestory_808801001_6_dialog_content = "Not like that...",
  str_homestory_808801001_7_dialog_content = "Fine... It's no longer a secret anyway...",
  str_homestory_808801001_8_dialog_content = "What is it?",
  str_homestory_808801001_9_dialog_content = "Hmm... A few days ago, I was exploring in the desert...",
  str_homestory_808801001_10_dialog_content = "When I chanced upon a few kids.",
  str_homestory_808801001_11_dialog_content = "They obviously just ran away from home and lost their way in the vast desert...",
  str_homestory_808801001_12_dialog_content = "I saw them going round in circles so I offered to help.",
  str_homestory_808801001_13_dialog_content = "After I escorted them to safety, they asked for my name and wanted to come and thank me one day.",
  str_homestory_808801001_14_dialog_content = "Before I could introduce myself, they saw my tail... They...",
  str_homestory_808801001_15_option_content = "They laughed at you?",
  str_homestory_808801001_16_dialog_content = "No...",
  str_homestory_808801001_17_dialog_content = "They said my tail was very cute!",
  str_homestory_808801001_18_dialog_content = "That's good, isn't it?",
  str_homestory_808801001_19_option_content = "They recognized you?",
  str_homestory_808801001_20_dialog_content = "No...",
  str_homestory_808801001_21_dialog_content = "I'm not popular as Fleur...",
  str_homestory_808801001_22_dialog_content = "But they...",
  str_homestory_808801001_23_dialog_content = "They mistook me for a dragon!",
  str_homestory_808801001_24_dialog_content = "?",
  str_homestory_808801001_25_dialog_content = "I was just as shocked...",
  str_homestory_808801001_26_dialog_content = "I thought it was outrageous!",
  str_homestory_808801001_27_dialog_content = "They told me they had never seen a dragon with a fluffy tail before...",
  str_homestory_808801001_28_dialog_content = "They asked if they could touch my tail...",
  str_homestory_808801001_29_dialog_content = "I got really mad!<sprite=emo_wuyun size=60 />",
  str_homestory_808801001_30_dialog_content = "Why? Couldn't you just explain the situation to them?",
  str_homestory_808801001_31_dialog_content = "I didn't mind they mistook me for something else, but their attitude was irritating!",
  str_homestory_808801001_32_dialog_content = "\"Can we feel your tail?\"",
  str_homestory_808801001_33_dialog_content = "What kind of request is this?",
  str_homestory_808801001_34_dialog_content = "Who would you say such a thing to other than your pet?",
  str_homestory_808801001_35_dialog_content = "I... I'm so mad...",
  str_homestory_808801001_36_dialog_content = "I want to set everything on fire<sprite=emo_nuhuo size=60 />! Right now!",
  str_homestory_808801001_37_dialog_content = "(Not again!)",
  str_homestory_808801001_38_dialog_content = "Calm down, Maggie!",
  str_homestory_808801001_39_dialog_content = "What if they simply found your tail extremely cute?",
  str_homestory_808801001_40_dialog_content = "Th-this is how I feel about it all this time!",
  str_homestory_808801001_41_dialog_content = "... To be honest, I can't imagine how Maggie would be without this lovely tail.",
  str_homestory_808801001_42_dialog_content = "...",
  str_homestory_808801001_43_dialog_content = "... Really?",
  str_homestory_808801001_44_dialog_content = "(Phew... She seems less angry now...)",
  str_homestory_808801001_45_dialog_content = "Yes, Maggie! I swear!",
  str_homestory_808801001_46_dialog_content = "... Okay then...",
  str_homestory_808801001_47_dialog_content = "Ah! By the way...",
  str_homestory_808801001_48_dialog_content = "Earlier you said it was no longer a secret?",
  str_homestory_808801001_49_dialog_content = "I don't think many people are aware of this incident...",
  str_homestory_808801001_50_dialog_content = "Because...",
  str_homestory_808801001_51_dialog_content = "Jomu included this in his latest collection of short stories...",
  str_homestory_808801001_52_dialog_content = "... Hmm... I should have thought of this myself...",
  str_homestory_800801001_0_dialog_content = "Brock?",
  str_homestory_800801001_1_dialog_content = "Hahah! Good to see you.<sprite=emo_yaosu size=60 />",
  str_homestory_800801001_2_dialog_content = "Did you see it? Pretty cool, right?",
  str_homestory_800801001_3_dialog_content = "Err... What are you talking about, Brock?",
  str_homestory_800801001_4_dialog_content = "My punches! Neat! Handsome!",
  str_homestory_800801001_5_dialog_content = "Umm... Not too shabby...",
  str_homestory_800801001_6_dialog_content = "Not too shabby? That's all I got?",
  str_homestory_800801001_7_dialog_content = "Never mind. You know nothing about boxing. I bet you're filled with jealousy right now.",
  str_homestory_800801001_8_dialog_content = "?",
  str_homestory_800801001_9_dialog_content = "Don't worry, PlayerName! Although I'm now the envy of you, I'll still be nice to you!",
  str_homestory_800801001_10_dialog_content = "But I'm not jealous of you...",
  str_homestory_800801001_11_dialog_content = "Shush... I got it.",
  str_homestory_800801001_12_dialog_content = "When I was around your age, I longed to become a real man like who I am now!<sprite=emo_mojing size=60 />",
  str_homestory_800801001_13_dialog_content = "Listen up, PlayerName! Nothing is impossible to a willing heart!",
  str_homestory_800801001_14_dialog_content = "... Fine. Brock.",
  str_homestory_800801001_15_dialog_content = "You're very welcome. It's my bound responsibility to fuel up Cloud Gardens.",
  str_homestory_800801001_16_dialog_content = "When it comes to taking care of the youngsters, no one does it better than me.",
  str_homestory_800801001_17_dialog_content = "Hold on a second... What responsibility? What fuel?",
  str_homestory_800801001_18_dialog_content = "You're not aware of my sacrifice for you?",
  str_homestory_800801001_19_dialog_content = "... Enlighten me.",
  str_homestory_800801001_20_dialog_content = "Well. I visited Odi several days ago to repaint my Brock with rainbow colors.",
  str_homestory_800801001_21_dialog_content = "She looked extremely worried and begged me to do you this favor.",
  str_homestory_800801001_22_dialog_content = "What favor?",
  str_homestory_800801001_23_dialog_content = "Odi told me...",
  str_homestory_800801001_24_dialog_content = "This wobbly dummy of yours has a heat engine installed inside.",
  str_homestory_800801001_25_dialog_content = "?",
  str_homestory_800801001_26_dialog_content = "This engine is the power source of the entire Cloud Gardens!",
  str_homestory_800801001_27_dialog_content = "In short, it's my thousands of punches daily that keep Cloud Gardens running.",
  str_homestory_800801001_28_dialog_content = "Hahah! What's that face for? It's my pleasure!",
  str_homestory_800801001_29_dialog_content = "I'm happy to help!",
  str_homestory_800801001_30_dialog_content = "... Err... Brock... I think...",
  str_homestory_800801001_31_option_content = "You've been bamboozled.",
  str_homestory_800801001_32_dialog_content = "This wobbly dummy has nothing but some stuffing inside...",
  str_homestory_800801001_33_dialog_content = "Basically it has nothing to do with the operation of Cloud Gardens.",
  str_homestory_800801001_34_dialog_content = "However!",
  str_homestory_800801001_35_dialog_content = "Your daily boxing practice is great for your physical and mental health.",
  str_homestory_800801001_36_option_content = "I appreciate!",
  str_homestory_800801001_37_dialog_content = "However...",
  str_homestory_800801001_38_dialog_content = "I don't think Odi is very familiar with the structure of Cloud Gardens.",
  str_homestory_800801001_39_dialog_content = "I mean...",
  str_homestory_800801001_40_dialog_content = "This wobbly dummy has nothing but some stuffing inside...",
  str_homestory_800801001_41_dialog_content = "Oh! Is that so?",
  str_homestory_800801001_42_dialog_content = "Hahah. I guess Odi is not always right!",
  str_homestory_800801001_43_dialog_content = "Hmm... Brock...",
  str_homestory_800801001_44_dialog_content = "You might have been fooled.",
  str_homestory_800801001_45_dialog_content = "I guess so. It wouldn't be the first time.",
  str_homestory_800801001_46_dialog_content = "Aren't you upset?",
  str_homestory_800801001_47_dialog_content = "Why would I be?",
  str_homestory_800801001_48_dialog_content = "They love to play with me because they really like me!",
  str_homestory_800801001_49_dialog_content = "... Hmm... You're probably right.",
  str_homestory_800801001_50_dialog_content = "At the very least...",
  str_homestory_800801001_51_dialog_content = "Teasing me is a way to show their admiration and trust for me.",
  str_homestory_800801001_52_dialog_content = "... Admiration? Are you sure about this?",
  str_homestory_800801001_53_dialog_content = "Why do you think they never make fun of Sinsa?",
  str_homestory_800801001_54_dialog_content = "My common touch is second to none! Hahahahah!<sprite=emo_dianzan size=60 />",
  str_homestory_806501001_0_dialog_content = "Tweety?",
  str_homestory_806501001_1_dialog_content = "Whoa! Navigator! Gwad to see you.",
  str_homestory_806501001_2_dialog_content = "Tweety, what's the matter? Why are you so nervous to see me?",
  str_homestory_806501001_3_dialog_content = "Uh... Me?",
  str_homestory_806501001_4_dialog_content = "Look. You dropped things everywhere.",
  str_homestory_806501001_5_dialog_content = "Ah! Where?",
  str_homestory_806501001_6_dialog_content = "That white fluff next to your feet...",
  str_homestory_806501001_7_dialog_content = "Ahh... Let me wook...",
  str_homestory_806501001_8_dialog_content = "Whoa! They're feathers fwom Tweety!",
  str_homestory_806501001_9_dialog_content = "Boohoo... Should never do bad things.",
  str_homestory_806501001_10_dialog_content = "Bad things?",
  str_homestory_806501001_11_dialog_content = "No wonder your tail is down today.",
  str_homestory_806501001_12_dialog_content = "Hmm...",
  str_homestory_806501001_13_dialog_content = "What happened? Could you tell me?",
  str_homestory_806501001_14_dialog_content = "I better tell Navigator...",
  str_homestory_806501001_15_dialog_content = "Tweety came to dewiver a letter today.",
  str_homestory_806501001_16_dialog_content = "Okay. It's already at the post? I'll go there shortly!",
  str_homestory_806501001_17_dialog_content = "But... Pwease wait!",
  str_homestory_806501001_18_dialog_content = "The letter... I didn't sent to the post.",
  str_homestory_806501001_19_dialog_content = "Tweety noticed Cloud Gardens has changed a wot!",
  str_homestory_806501001_20_dialog_content = "I went here and there and forgot about the letter...",
  str_homestory_806501001_21_dialog_content = "Is this the \"bad thing\" you did?",
  str_homestory_806501001_22_option_content = "Get Angry",
  str_homestory_806501001_23_dialog_content = "Neglecting your duties could be a big deal.",
  str_homestory_806501001_24_dialog_content = "As the owner of Cloud Gardens, should I punish you?",
  str_homestory_806501001_25_dialog_content = "Whoa! Punish me?",
  str_homestory_806501001_26_dialog_content = "More feathers will fall off my tail...",
  str_homestory_806501001_27_dialog_content = "Okay... I'll punish you...",
  str_homestory_806501001_28_option_content = "Comfort",
  str_homestory_806501001_29_dialog_content = "Don't worry. It's not urgent.",
  str_homestory_806501001_30_dialog_content = "I'm very glad you like the changes I've made here.",
  str_homestory_806501001_31_dialog_content = "Thank you, Navigator. You're vewy kind!",
  str_homestory_806501001_32_dialog_content = "So who sent the letter?",
  str_homestory_806501001_33_dialog_content = "Show me.",
  str_homestory_806501001_34_dialog_content = "Okay! The Couwier Union always dewivers!",
  str_homestory_806501001_35_dialog_content = "Whoa! Where is the letter?",
  str_homestory_806501001_36_dialog_content = "Not in my bag...",
  str_homestory_806501001_37_dialog_content = "Not in my hat!",
  str_homestory_806501001_38_dialog_content = "Calm down. Did you drop it somewhere?",
  str_homestory_806501001_39_dialog_content = "Where did you go earlier, Tweety?",
  str_homestory_806501001_40_dialog_content = "Everywhere... I went all over the pwace.",
  str_homestory_806501001_41_dialog_content = "... It will be hard to search then.",
  str_homestory_806501001_42_dialog_content = "Tweety doesn't want to become the next Dove...",
  str_homestory_806501001_43_dialog_content = "Hmm? Something just fell out of your tail...",
  str_homestory_806501001_44_dialog_content = "More feathers fell off my tail? Tweety will be bald in no time!",
  str_homestory_806501001_45_dialog_content = "No, it doesn't look like a feather...",
  str_homestory_806501001_46_dialog_content = "Eh...",
  str_homestory_806501001_47_dialog_content = "Ah! This is the letter!",
  str_homestory_806501001_48_dialog_content = "It was hidden in my tail!",
  str_homestory_805501001_0_dialog_content = "That is...",
  str_homestory_805501001_1_dialog_content = "Pittman?",
  str_homestory_805501001_2_dialog_content = "...!",
  str_homestory_805501001_3_dialog_content = "Pittman?",
  str_homestory_805501001_4_dialog_content = "Ahem... You must be mistaken.",
  str_homestory_805501001_5_dialog_content = "Huh? But this serious suit... and the dark circles on your face!",
  str_homestory_805501001_6_dialog_content = "You're definitely Pittman.",
  str_homestory_805501001_7_dialog_content = "Shh...",
  str_homestory_805501001_8_dialog_content = "Keep it down. Don't let others hear you...",
  str_homestory_805501001_9_option_content = "Make an inquiry",
  str_homestory_805501001_10_dialog_content = "Hmm? The judge from Lumopolis is scared of being recognized?",
  str_homestory_805501001_11_option_content = "Show understanding",
  str_homestory_805501001_12_dialog_content = "Okay.",
  str_homestory_805501001_13_dialog_content = "You don't want to expose your whereabouts!",
  str_homestory_805501001_14_dialog_content = "Are you wanted in Lumopolis?",
  str_homestory_805501001_15_dialog_content = "I'm just and honorable, fair and square, a devout follower of the God of Light and a loyal servant of Lumopolis.",
  str_homestory_805501001_16_dialog_content = "Why would I be wanted?",
  str_homestory_805501001_17_dialog_content = "Maybe...",
  str_homestory_805501001_18_dialog_content = "You rode a rocking horse for fun secretly!",
  str_homestory_805501001_19_dialog_content = "You... you saw it?<sprite=emo_daomei size=60 />",
  str_homestory_805501001_20_dialog_content = "Ah hah! You did ride the rocking horse!",
  str_homestory_805501001_21_dialog_content = "Ahem. I wanted to make sure it was in good condition.",
  str_homestory_805501001_22_dialog_content = "Too many fake ones in the market these days.",
  str_homestory_805501001_23_dialog_content = "We judges must combat these unscrupulous sellers.",
  str_homestory_805501001_24_dialog_content = "But don't worry. Your rocking horse is solid with excellent workmanship. It can bear at least 84 kg.",
  str_homestory_805501001_25_dialog_content = "You can rock it with peace of mind.",
  str_homestory_805501001_26_dialog_content = "Err... Thank you...",
  str_homestory_805501001_27_dialog_content = "I have installed this rocking horse here so everyone can enjoy it.",
  str_homestory_805501001_28_dialog_content = "There's no need to be sneaky about it!",
  str_homestory_805501001_29_dialog_content = "Where is this coming from?",
  str_homestory_805501001_30_dialog_content = "It's all written on your face.",
  str_homestory_805501001_31_dialog_content = "You're not a good liar. Hahahah.",
  str_homestory_805501001_32_dialog_content = "... Okay.",
  str_homestory_805501001_33_dialog_content = "Please keep this between us.",
  str_homestory_805501001_34_dialog_content = "Why? It doesn't have to be a secret...",
  str_homestory_805501001_35_dialog_content = "I love riding it myself.",
  str_homestory_805501001_36_dialog_content = "To uphold justice, judges always want to be persuasive and reassuring.",
  str_homestory_805501001_37_dialog_content = "If people find out this childish side of me...",
  str_homestory_805501001_38_dialog_content = "They won't be able to trust my judgment in court.",
  str_homestory_805501001_39_dialog_content = "Is that right?",
  str_homestory_805501001_40_dialog_content = "So PlayerName, is my secret safe with you?",
  str_homestory_805501001_41_dialog_content = "Fine. Although I still don't see any connection between riding a rocking horse and trying a case...",
  str_homestory_805501001_42_dialog_content = "I promise you I won't tell anyone!",
  str_homestory_805501001_43_dialog_content = "Thank you for your understanding!",
  str_homestory_805501001_44_dialog_content = "One more thing...",
  str_homestory_805501001_45_dialog_content = "If you ever fall victim to fake commodities, I'll uphold justice for you!<sprite=emo_qingsong size=60 />",
  str_homestory_815501001_0_dialog_content = "It sounds like a sword just being sheathed?",
  str_homestory_815501001_1_dialog_content = "Eraveil is truly marvelous, PlayerName!",
  str_homestory_815501001_2_dialog_content = "It's not bad... I guess...",
  str_homestory_815501001_3_dialog_content = "How many more secrets are kept from us by this Caelestite?",
  str_homestory_815501001_4_dialog_content = "... Can't wait to find out.",
  str_homestory_815501001_5_dialog_content = "Hmm... Such a lovely place you have, kiddo.",
  str_homestory_815501001_6_dialog_content = "Very well equipped, strategically situated, and difficult to access.",
  str_homestory_815501001_7_dialog_content = "In times of war, this could make a fine combat base without a problem!",
  str_homestory_815501001_8_dialog_content = "Wow... You're at least ten steps ahead of me, Barton.",
  str_homestory_815501001_9_dialog_content = "Of course!",
  str_homestory_815501001_10_dialog_content = "The constant pursuit of power and the rational planning of what you have are just as important.",
  str_homestory_815501001_11_dialog_content = "(Barton sounds different today...)",
  str_homestory_815501001_12_dialog_content = "Alas... I wish I figured this out earlier...",
  str_homestory_815501001_13_dialog_content = "... Kiddo, what do you think?",
  str_homestory_815501001_14_dialog_content = "Which is more important in your opinion, to grow stronger or to rationally plan your resources?<sprite=emo_sikao size=60 />",
  str_homestory_815501001_15_option_content = "Grow stronger",
  str_homestory_815501001_16_dialog_content = "If 10 Nightium was all I had, there wouldn't be any point in planning...",
  str_homestory_815501001_17_dialog_content = "I must become stronger first. In other words, I need to grow my wealth first.",
  str_homestory_815501001_18_option_content = "Rationally plan",
  str_homestory_815501001_19_dialog_content = "If 10 Nightium was all I had, I must find a way to live before I could think about making more money...",
  str_homestory_815501001_20_dialog_content = "Huh? You can't be serious?",
  str_homestory_815501001_21_dialog_content = "10 Nightium is all you have?",
  str_homestory_815501001_22_dialog_content = "... It was just an example!",
  str_homestory_815501001_23_dialog_content = "Fine.",
  str_homestory_815501001_24_dialog_content = "I was about to offer you a loan if you were that broke.",
  str_homestory_815501001_25_dialog_content = "In this respect, Illumina is pretty good. At least many things don't cost a penny.",
  str_homestory_815501001_26_dialog_content = "?",
  str_homestory_815501001_27_dialog_content = "Sorry. I digress...",
  str_homestory_815501001_28_dialog_content = "I've come to a point that I believe pursuing power and planning resources can be conducted simultaneously.",
  str_homestory_815501001_29_dialog_content = "It doesn't have to be an either-or situation.",
  str_homestory_815501001_30_dialog_content = "I used to give my full attention to the growth of my power. Many important matters were neglected along the way.",
  str_homestory_815501001_31_dialog_content = "Planning what you already have gives you a better idea of the future!",
  str_homestory_815501001_32_dialog_content = "A thorough understanding of yourself allows you to advance smoothly on this journey and to become stronger.",
  str_homestory_815501001_33_dialog_content = "More power gives you a better say.",
  str_homestory_815501001_34_dialog_content = "Hmm... I agree with you to a degree.",
  str_homestory_815501001_35_dialog_content = "So you agree to lend me this place as my combat base?",
  str_homestory_815501001_36_dialog_content = "?!",
  str_homestory_815501001_37_dialog_content = "I never said that!",
  str_homestory_815501001_38_dialog_content = "The concept of a combat base just doesn't sound right for Cloud Gardens!",
  str_homestory_815501001_39_dialog_content = "Hahah. Who knows? No one can guarantee you lasting peace!",
  str_homestory_815501001_40_dialog_content = "Hey! Please don't say that!<sprite=emo_shengqi size=60 />",
  str_homestory_815501001_41_dialog_content = "It doesn't make a difference. We must be prepared for potential risks!",
  str_homestory_815501001_42_dialog_content = "Yes. We need a few more rounds of war games without further due.",
  str_homestory_815501001_43_dialog_content = "And all these ideas in my head... I'll share them with Vivian tomorrow.",
  str_homestory_815501001_44_dialog_content = "Hmm... I don't have the time to look up documents for a written report!",
  str_homestory_815501001_45_dialog_content = "(I decide to take back what I just said...)",
  str_homestory_815501001_46_dialog_content = "(Barton hasn't changed a bit.)",
  str_homestory_801101001_0_dialog_content = "Sharona!",
  str_homestory_801101001_1_dialog_content = "Sir...",
  str_homestory_801101001_2_dialog_content = "Are you practicing new moves?",
  str_homestory_801101001_3_dialog_content = "Yes.",
  str_homestory_801101001_4_dialog_content = "Very diligent<sprite=emo_yaling size=60 />. No wonder Illumina's main combat force, The 1st Legion, is under your command...",
  str_homestory_801101001_5_dialog_content = "I think there's some misunderstanding, PlayerName.",
  str_homestory_801101001_6_dialog_content = "I have no intention to introduce this new set of moves into our military training.",
  str_homestory_801101001_7_dialog_content = "These are actually skills I have recently acquired from a novel.",
  str_homestory_801101001_8_dialog_content = "You... You read a novel?",
  str_homestory_801101001_9_dialog_content = "Wait... You're practicing moves from a novel?",
  str_homestory_801101001_10_dialog_content = "This... This doesn't sound like the Officer Sharona I know!",
  str_homestory_801101001_11_dialog_content = "You're shocked?",
  str_homestory_801101001_12_option_content = "Nod",
  str_homestory_801101001_13_dialog_content = "I thought you were always busy with big deals. Reading novels...",
  str_homestory_801101001_14_dialog_content = "Don't take me wrong. I have nothing against reading!",
  str_homestory_801101001_15_option_content = "Shake the head",
  str_homestory_801101001_16_dialog_content = "On reflection, we shouldn't limit our understanding of a person to the first impression...",
  str_homestory_801101001_17_dialog_content = "To me, Officer Sharona seems busy at all times. I didn't think you would have the leisure to read a novel.",
  str_homestory_801101001_18_dialog_content = "You're right. I'm not a big reader by any measure.",
  str_homestory_801101001_19_dialog_content = "But the name of the book caught my attention: The Millennia Entanglement of Two Rebellious Dragons.",
  str_homestory_801101001_20_dialog_content = "...",
  str_homestory_801101001_21_dialog_content = "Where did you chance upon this book?",
  str_homestory_801101001_22_dialog_content = "Don't tell me you bought it from a certain Aurorian!",
  str_homestory_801101001_23_dialog_content = "Yes, a merchant in Umbraton sold it to me.",
  str_homestory_801101001_24_dialog_content = "You seem calm...",
  str_homestory_801101001_25_dialog_content = "I guess the story is not too out of line.",
  str_homestory_801101001_26_dialog_content = "He told me the gimmick of this book was...",
  str_homestory_801101001_27_dialog_content = "The long-lost secret skills of Dragon and a love story of an ancient bloodline...",
  str_homestory_801101001_28_dialog_content = "What? Aren't you mad?",
  str_homestory_801101001_29_dialog_content = "Not really.",
  str_homestory_801101001_30_dialog_content = "There's not much I can do anyway.",
  str_homestory_801101001_31_dialog_content = "The printing and sales of this book take place in Umbraton, beyond my jurisdiction.",
  str_homestory_801101001_32_dialog_content = "For me, the content of a book matters little.",
  str_homestory_801101001_33_dialog_content = "But for those writers, a book might be the only thing they live on.",
  str_homestory_801101001_34_dialog_content = "... Yes, that's so true...",
  str_homestory_801101001_35_dialog_content = "Sharona... You're an excellent officer!",
  str_homestory_801101001_36_dialog_content = "Well, the secret skills of Dragon mentioned in this book are quite ridiculous...",
  str_homestory_801101001_37_dialog_content = "But it can spice up my exercise routine a bit.",
  str_homestory_801101001_38_dialog_content = "Wanna try?",
  str_homestory_801101001_39_dialog_content = "As recorded in the book, we will start with 200 easy squats before moving on to...",
  str_homestory_801101001_40_dialog_content = "No, no...",
  str_homestory_801101001_41_dialog_content = "I think I really need to focus on the Caelestite abilities, Officer Sharona.",
  str_homestory_801101001_42_dialog_content = "I'll leave you to your exercise... Bye!",
  str_homestory_801101001_43_dialog_content = "Bye.",
  str_homestory_810301001_0_dialog_content = "Is that Eicy?",
  str_homestory_810301001_1_dialog_content = "Eicy, wanna have a look inside?",
  str_homestory_810301001_2_dialog_content = "I remember you love to shop.",
  str_homestory_810301001_3_dialog_content = "PlayerName, since you know my hobby...",
  str_homestory_810301001_4_dialog_content = "How could you be so stingy building one shop only?",
  str_homestory_810301001_5_dialog_content = "Err... I have many reasons...",
  str_homestory_810301001_6_dialog_content = "Go on.",
  str_homestory_810301001_7_dialog_content = "If your memory suddenly fails, I can remove my eye patch...",
  str_homestory_810301001_8_dialog_content = "My Hollow Gaze <sprite=emo_baimao size=60 />will help you.",
  str_homestory_810301001_9_option_content = "Explain",
  str_homestory_810301001_10_dialog_content = "Alright. Give me a minute!",
  str_homestory_810301001_11_dialog_content = "The main reason is our very tight budget...",
  str_homestory_810301001_12_dialog_content = "We have so many things to build. It's not possible to make everything perfect from the beginning.",
  str_homestory_810301001_13_option_content = "Answer vaguely",
  str_homestory_810301001_14_dialog_content = "Interrogation can't make a difference here...",
  str_homestory_810301001_15_dialog_content = "Our budget is very tight. We simply can't afford another shop...",
  str_homestory_810301001_16_dialog_content = "I think... One is better than none!",
  str_homestory_810301001_17_dialog_content = "That's very bold and straightforward of you.",
  str_homestory_810301001_18_dialog_content = "Our one and only store covers all your needs though!",
  str_homestory_810301001_19_dialog_content = "I've been working hard to cooperate with different Guilds in Umbraton...",
  str_homestory_810301001_20_dialog_content = "Supplies are coming on an irregular basis through the Courier Union.",
  str_homestory_810301001_21_dialog_content = "How about you go in and take a look first? Let me know if there's something you want me to order.",
  str_homestory_810301001_22_dialog_content = "That won't be necessary. I've been there already.",
  str_homestory_810301001_23_dialog_content = "Actually, I've cleared your stock to show my support.",
  str_homestory_810301001_24_dialog_content = "Everything?",
  str_homestory_810301001_25_dialog_content = "Yes.",
  str_homestory_810301001_26_dialog_content = "Including the fish we just caught today from the river?",
  str_homestory_810301001_27_dialog_content = "Those colorful ones? Yes, they're adorable.",
  str_homestory_810301001_28_dialog_content = "I couldn't find a tank to keep them so I set them free in a nearby river.",
  str_homestory_810301001_29_dialog_content = "Even that unwanted tattered leather shoe?",
  str_homestory_810301001_30_dialog_content = "Tattered shoe? Yes. Is that not a flowerpot of the latest style?",
  str_homestory_810301001_31_dialog_content = "I have contacted the Courier Union to send it back to the True Order.",
  str_homestory_810301001_32_dialog_content = "How about... my hand-drawn map of Eraveil?",
  str_homestory_810301001_33_dialog_content = "You mean the picture of a crooked maze?",
  str_homestory_810301001_34_dialog_content = "You drew it? I must get it framed and hang it on my wall.",
  str_homestory_810301001_35_dialog_content = "Thank you, Eicy... You're the most generous customer I've ever seen!",
  str_homestory_810301001_36_dialog_content = "Don't mention it. Shopping is all about splashing out!",
  str_homestory_810301001_37_dialog_content = "It irritates me that there's no more store to shop more.",
  str_homestory_810301001_38_dialog_content = "Eicy, you could take a walk around.",
  str_homestory_810301001_39_dialog_content = "We have a museum over there, and the Fountain of Hope...",
  str_homestory_810301001_40_dialog_content = "I can give you my word. You won't be able to see them anywhere else!",
  str_homestory_810301001_41_dialog_content = "Sure. Sounds interesting.",
  str_homestory_810301001_42_dialog_content = "I got an idea. I decide to buy <sprite=emo_baiyebi size=60 />you.",
  str_homestory_810301001_43_dialog_content = "Huh? Buy me?",
  str_homestory_810301001_44_dialog_content = "Just for one day. You can show me around.",
  str_homestory_810301001_45_dialog_content = "You tell me a fair price for your time.",
  str_homestory_810301001_46_dialog_content = "Deal! I'm very happy to serve you!",
  str_homestory_802301001_0_dialog_content = "Connolly...",
  str_homestory_802301001_1_dialog_content = "The soft light...",
  str_homestory_802301001_2_dialog_content = "Connolly, what did you say?",
  str_homestory_802301001_3_dialog_content = "Na-Navigator! <sprite=emo_wuzui size=60 />",
  str_homestory_802301001_4_dialog_content = "I was just murmuring. Please pay no attention to me...",
  str_homestory_802301001_5_dialog_content = "... No, it's not just that!",
  str_homestory_802301001_6_dialog_content = "You can also pay me some attention... I... I'm in the middle of a desensitization training...",
  str_homestory_802301001_7_dialog_content = "Desensitization training?",
  str_homestory_802301001_8_dialog_content = "Yes... Vice told me about this...",
  str_homestory_802301001_9_dialog_content = "I was having a hard time adjusting to the light here...",
  str_homestory_802301001_10_dialog_content = "Vice found me hiding in a corner...",
  str_homestory_802301001_11_dialog_content = "She realized you needed help?",
  str_homestory_802301001_12_dialog_content = "Yes...",
  str_homestory_802301001_13_dialog_content = "She told me to try to do things I like and ignore other people...",
  str_homestory_802301001_14_dialog_content = "Or pretend this is the Holiday Cafe and you're all customers...",
  str_homestory_802301001_15_dialog_content = "I'm really trying...",
  str_homestory_802301001_16_option_content = "How do you feel?",
  str_homestory_802301001_17_dialog_content = "Slightly better...",
  str_homestory_802301001_18_dialog_content = "There were a lot of people on the Colossus as well...",
  str_homestory_802301001_19_option_content = "Don't force yourself.",
  str_homestory_802301001_20_dialog_content = "You're not obliged to go out if staying in your room is more comfortable.",
  str_homestory_802301001_21_dialog_content = "Actually, I have something to tell you, Navigator...",
  str_homestory_802301001_22_dialog_content = "Hmm? What is it?",
  str_homestory_802301001_23_dialog_content = "I heeded Vice's advice and played a song with Anton here<sprite=emo_yinfu size=60 />...",
  str_homestory_802301001_24_dialog_content = "Never expected... a lady dressed in a Lumopolis outfit praised me...",
  str_homestory_802301001_25_dialog_content = "I...",
  str_homestory_802301001_26_dialog_content = "Ah... All of a sudden, this bright place doesn't seem too bad anymore, right?",
  str_homestory_802301001_27_dialog_content = "Sometimes a compliment is very encouraging.",
  str_homestory_802301001_28_dialog_content = "Connolly, I think you're phenomenal!",
  str_homestory_802301001_29_dialog_content = "You make the tastiest coffee and you're a sweet yet powerful fighter...",
  str_homestory_802301001_30_dialog_content = "Thank you for your kind words, Navigator. I... I don't know what to say...",
  str_homestory_802301001_31_dialog_content = "But that lady's compliment... felt different from yours!",
  str_homestory_802301001_32_dialog_content = "Navigator and Vice are good friends of Connolly...",
  str_homestory_802301001_33_dialog_content = "You've always been supportive, comforting me and praising me...",
  str_homestory_802301001_34_dialog_content = "But that lady was a total stranger!",
  str_homestory_802301001_35_dialog_content = "Her approval was pure and more reassuring for Connolly.",
  str_homestory_802301001_36_dialog_content = "Yes... That's exactly how I feel...",
  str_homestory_802301001_37_dialog_content = "Navigator, could you tell Vice I really appreciate her help?",
  str_homestory_802301001_38_dialog_content = "I would most likely be hiding in my room right now if not for her...",
  str_homestory_802301001_39_dialog_content = "Consider it done!",
  str_homestory_802301001_40_dialog_content = "Thank you, Navigator!",
  str_homestory_802301001_41_dialog_content = "I plan to practice that song again with Anton...",
  str_homestory_802301001_42_dialog_content = "You could also try something new.",
  str_homestory_802301001_43_dialog_content = "I'm sure that mystery lady would love to hear.",
  str_homestory_802301001_44_dialog_content = "Ah! You're right...",
  str_homestory_802301001_45_dialog_content = "Okay! Navigator, I'm going to practice!",
  str_homestory_802301001_46_dialog_content = "You got this!",
  str_homestory_803001001_0_dialog_content = "Sinsa...",
  str_homestory_803001001_1_dialog_content = "Hello, Sinsa!",
  str_homestory_803001001_2_dialog_content = "Uh-huh<sprite=emo_yaosu size=60 />! Good to see you, PlayerName, the last Caelestite!",
  str_homestory_803001001_3_dialog_content = "How's everything?",
  str_homestory_803001001_4_dialog_content = "Everything is fine. And you? Getting on alright here?",
  str_homestory_803001001_5_dialog_content = "Not bad.",
  str_homestory_803001001_6_dialog_content = "It didn't take long for you to completely transform this shithole...",
  str_homestory_803001001_7_dialog_content = "You are living up to Sinsa's expectations. Ah hahahah.",
  str_homestory_803001001_8_dialog_content = "So, have you decided?",
  str_homestory_803001001_9_dialog_content = "When will you join the Rediesel Wrench?",
  str_homestory_803001001_10_dialog_content = "Umm... Err...",
  str_homestory_803001001_11_dialog_content = "By the Rediesel Wrench's standard...",
  str_homestory_803001001_12_dialog_content = "This place is in desperate need of an area for fighting and drag racing!",
  str_homestory_803001001_13_option_content = "Reject",
  str_homestory_803001001_14_dialog_content = "I'd rather not have any conflict here...",
  str_homestory_803001001_15_dialog_content = "There's no room for violence.",
  str_homestory_803001001_16_dialog_content = "Alas... I've lost count of your cold rejection.",
  str_homestory_803001001_17_dialog_content = "However, PlayerName, your idea sounds rather childish back there.",
  str_homestory_803001001_18_dialog_content = "Take my word for it. The forbidden are definitely to happen.",
  str_homestory_803001001_19_dialog_content = "Don't ask how I know...",
  str_homestory_803001001_20_dialog_content = "...",
  str_homestory_803001001_21_option_content = "Agree",
  str_homestory_803001001_22_dialog_content = "Hmm... It's not part of our original plan...",
  str_homestory_803001001_23_dialog_content = "But random fighting and drag racing might result in damage to houses I've worked hard for.",
  str_homestory_803001001_24_dialog_content = "It's better to have a special zone...",
  str_homestory_803001001_25_dialog_content = "Hahahah. You've grown, kiddo.",
  str_homestory_803001001_26_dialog_content = "Now you know when to listen!",
  str_homestory_803001001_27_dialog_content = "Could you show me the girls' dorms of Cloud Gardens?",
  str_homestory_803001001_28_dialog_content = "Huh?!",
  str_homestory_803001001_29_dialog_content = "Why is there terror in your eyes?",
  str_homestory_803001001_30_dialog_content = "I guess you go there for a reason?",
  str_homestory_803001001_31_dialog_content = "It's time to pay a visit.",
  str_homestory_803001001_32_dialog_content = "A visit?",
  str_homestory_803001001_33_dialog_content = "Yes<sprite=emo_qingsong size=60 />, I need to make sure if it's good enough for my Eve.",
  str_homestory_803001001_34_dialog_content = "Phew... I see.",
  str_homestory_803001001_35_dialog_content = "I need to check if the mattress is soft enough...",
  str_homestory_803001001_36_dialog_content = "If the bedside lamp is good for the eye...",
  str_homestory_803001001_37_dialog_content = "If the sheet has Eve's favorite pattern...",
  str_homestory_803001001_38_dialog_content = "If there's a suitable wardrobe for Eve's pretty dresses...",
  str_homestory_803001001_39_dialog_content = "Ah! And the most important! If there's a thermos cup in the room!",
  str_homestory_803001001_40_option_content = "Agree",
  str_homestory_803001001_41_dialog_content = "I'll send Vice to double-check everything...",
  str_homestory_803001001_42_dialog_content = "Hahahah! That's my brother!",
  str_homestory_803001001_43_option_content = "Disagree",
  str_homestory_803001001_44_dialog_content = "Sinsa, I think it's time for you to learn to respect Eve's space.",
  str_homestory_803001001_45_dialog_content = "What did you say?",
  str_homestory_803001001_46_dialog_content = "Never mind! I'll send Vice to double-check everything...",
  str_homestory_811601001_0_dialog_content = "These hums and haws!",
  str_homestory_811601001_1_dialog_content = "Navigator, do you have something to repair?",
  str_homestory_811601001_2_dialog_content = "Perfect timing! I haven't received any assignments today!",
  str_homestory_811601001_3_dialog_content = "Repair?",
  str_homestory_811601001_4_dialog_content = "You're taking orders... at the freight depot?",
  str_homestory_811601001_5_dialog_content = "Yes, I get customers here. Then I fix their things in my room.",
  str_homestory_811601001_6_dialog_content = "Ah, don't worry. No money is involved.",
  str_homestory_811601001_7_dialog_content = "Then why do you...",
  str_homestory_811601001_8_dialog_content = "Why do I offer free repair service?",
  str_homestory_811601001_9_dialog_content = "Yes. Normally you're kept busy with your own hobbies...",
  str_homestory_811601001_10_dialog_content = "Research parts and components and such.",
  str_homestory_811601001_11_dialog_content = "Because people here are from all over the place.<sprite=emo_sikao size=60 />",
  str_homestory_811601001_12_dialog_content = "Things they want to fix are so different and fascinating.",
  str_homestory_811601001_13_dialog_content = "Earlier Charon asked me to make his phonograph<sprite=emo_yinfu size=60 /> louder...",
  str_homestory_811601001_14_dialog_content = "I thought it was just a phonograph from Illumina and didn't pay much attention.",
  str_homestory_811601001_15_dialog_content = "You know what? It turned out to be a vintage model of unknown origin!",
  str_homestory_811601001_16_dialog_content = "Hahah. I studied the phonograph in and out again and again!",
  str_homestory_811601001_17_dialog_content = "Err... did you really help Charon make it louder?",
  str_homestory_811601001_18_dialog_content = "Well, just a little bit. It was my payment for this rare opportunity to study a new device...",
  str_homestory_811601001_19_dialog_content = "But! I'm also a victim of his loud music. I swear I only made it slightly louder!",
  str_homestory_811601001_20_dialog_content = "Alright... You seem to enjoy yourself here.",
  str_homestory_811601001_21_dialog_content = "Very much so!",
  str_homestory_811601001_22_dialog_content = "So many different technologies, new parts, and devices to study... This is heaven!<sprite=emo_aixin size=60 />",
  str_homestory_811601001_23_dialog_content = "Okay, as long as you are comfortable here.",
  str_homestory_811601001_24_dialog_content = "Pretty good. Soon I'll be able to make a new mecha!",
  str_homestory_811601001_25_dialog_content = "... Here we go again!",
  str_homestory_811601001_26_dialog_content = "Don't be like that! I care about you very much! I inspected the structure of this freight depot for you just now.",
  str_homestory_811601001_27_dialog_content = "My wrench and screwdriver have proved that this pavilion is very stable and in no need of my service.",
  str_homestory_811601001_28_dialog_content = "It was built with materials from Eraveil.",
  str_homestory_811601001_29_dialog_content = "See? Here I even have access to materials from Eraveil. Fabulous!",
  str_homestory_811601001_30_dialog_content = "Alright then, I guess I'll leave you here... to take orders?",
  str_homestory_811601001_31_dialog_content = "You're not disturbing me at all. Actually, you're welcome to stay and take orders with me.",
  str_homestory_811601001_32_option_content = "Agree",
  str_homestory_811601001_33_dialog_content = "Fine... I'm curious what repair needs are out there.",
  str_homestory_811601001_34_dialog_content = "Excellent!",
  str_homestory_811601001_35_dialog_content = "... I'm having a very slow day today.",
  str_homestory_811601001_36_dialog_content = "... What if no one comes to you for repairs?",
  str_homestory_811601001_37_option_content = "Reject",
  str_homestory_811601001_38_dialog_content = "Not today. Got things to do...",
  str_homestory_811601001_39_dialog_content = "Ah! By the way...",
  str_homestory_811601001_40_dialog_content = "What if no one comes to you for repair?",
  str_homestory_811601001_41_dialog_content = "You'll continue hanging about here?",
  str_homestory_811601001_42_dialog_content = "That's right.",
  str_homestory_811601001_43_dialog_content = "However, Navigator, here's one thing I must correct you.",
  str_homestory_811601001_44_dialog_content = "I'm not hanging about here. An intense mecha war is constantly fighting in my head.",
  str_homestory_811601001_45_dialog_content = "Before you came, I was pondering who would win if Mecha PlayerName and Mecha Odi had a fight.",
  str_homestory_811601001_46_dialog_content = "Mecha PlayerName is known for its swift and light strikes while Mecha Odi is much better equipped...",
  str_homestory_811601001_47_dialog_content = "It was a fierce fight!",
  str_homestory_811601001_48_dialog_content = "Okay... I'm done here...",
  str_homestory_811701001_0_dialog_content = "Gram?",
  str_homestory_811701001_1_dialog_content = "Gram, what are you doing in the store?",
  str_homestory_811701001_2_dialog_content = "Err... Are you pondering?",
  str_homestory_811701001_3_dialog_content = "Or is there something you can't find here?",
  str_homestory_811701001_4_dialog_content = "Kiddo.",
  str_homestory_811701001_5_dialog_content = "I need some ingredients for making skewers with expiring rationed meat.",
  str_homestory_811701001_6_dialog_content = "Expiring meat<sprite=emo_rou size=60 />...",
  str_homestory_811701001_7_dialog_content = "Expiring, not expired. It's perfectly fine.",
  str_homestory_811701001_8_dialog_content = "Besides, how good the dish is solely depends on the chef's skills and has nothing to do with the quality of the ingredients.",
  str_homestory_811701001_9_dialog_content = "Gram, you're correct!",
  str_homestory_811701001_10_dialog_content = "As a matter of fact, I've never tried your skewers...",
  str_homestory_811701001_11_dialog_content = "You will.",
  str_homestory_811701001_12_dialog_content = "Skewers are so easy to make.",
  str_homestory_811701001_13_dialog_content = "... Easy?",
  str_homestory_811701001_14_dialog_content = "I knew it. Gram, you are truly gifted...",
  str_homestory_811701001_15_dialog_content = "A gifted cook? There's no such a thing.",
  str_homestory_811701001_16_dialog_content = "Hmm! The young generation is all about endowments!",
  str_homestory_811701001_17_dialog_content = "Many achievements are reached through hard work and diligent study. Talent alone gets you nowhere!",
  str_homestory_811701001_18_dialog_content = "I cook well because I worked long years in the kitchen.",
  str_homestory_811701001_19_dialog_content = "Cooking as a skill has very little to do with talent.",
  str_homestory_811701001_20_option_content = "I don't quite understand.",
  str_homestory_811701001_21_dialog_content = "I tried to cook and closely followed a recipe...",
  str_homestory_811701001_22_dialog_content = "It didn't turn out well.",
  str_homestory_811701001_23_option_content = "It's starting to make sense",
  str_homestory_811701001_24_dialog_content = "Cooking skills can be improved through practice?",
  str_homestory_811701001_25_dialog_content = "Anything can be improved through enough practice.",
  str_homestory_811701001_26_dialog_content = "To cook a tasty meal, you must feel it in your heart.",
  str_homestory_811701001_27_dialog_content = "Feel it?",
  str_homestory_811701001_28_dialog_content = "So Vice's dishes...",
  str_homestory_811701001_29_dialog_content = "You had no feeling or too much feeling?",
  str_homestory_811701001_30_dialog_content = "Obviously, she lost her feelings to the instructions.",
  str_homestory_811701001_31_dialog_content = "Let's say she's hindered by her personal gains and losses.",
  str_homestory_811701001_32_dialog_content = "Hmm... You can probably say that about me as well.",
  str_homestory_811701001_33_dialog_content = "I'm scared of screwing things up but also very eager to make something amazing. This leaves me confused and stressed...",
  str_homestory_811701001_34_dialog_content = "I'll give you a very simple example.",
  str_homestory_811701001_35_dialog_content = "When I was in the logistics unit, I longed to go to the front but still managed to deliver tasty food every day. There was only one reason.",
  str_homestory_811701001_36_dialog_content = "I wanted all my brothers in arms to eat well so they'd have the strength to fight.",
  str_homestory_811701001_37_dialog_content = "Now I'm cooking here for the same reason.",
  str_homestory_811701001_38_dialog_content = "I want you young folks to eat well so you will have the energy to fight!",
  str_homestory_811701001_39_dialog_content = "Cooking a tasty meal is very easy.",
  str_homestory_811701001_40_dialog_content = "Follow instructions and cast aside all your random thoughts.",
  str_homestory_811701001_41_dialog_content = "The more you think, the more mistakes you will make. Understood?",
  str_homestory_811701001_42_dialog_content = "Yes! This time I got it!",
  str_homestory_811701001_43_dialog_content = "You're absolutely right, Gram!",
  str_homestory_811701001_44_dialog_content = "To be honest, I think you should write a book on cooking techniques.",
  str_homestory_811701001_45_dialog_content = "Even members of the Rediesel Desert are publishing books... You can do this!",
  str_homestory_811701001_46_dialog_content = "I can introduce you to some press in Umbraton.",
  str_homestory_811701001_47_dialog_content = "Not now. I'll think about it.",
  str_homestory_811701001_48_dialog_content = "Are you coming for my skewers when they are ready, kiddo?",
  str_homestory_811701001_49_dialog_content = "Definitely!",
  str_homestory_807701001_0_dialog_content = "Her Majesty?",
  str_homestory_807701001_1_dialog_content = "Your Majesty...",
  str_homestory_807701001_2_dialog_content = "Hi, the one that holds the future.",
  str_homestory_807701001_3_option_content = "Welcome.",
  str_homestory_807701001_4_dialog_content = "It's an honor to have you here.",
  str_homestory_807701001_5_dialog_content = "PlayerName, don't stand on ceremony.",
  str_homestory_807701001_6_dialog_content = "I've been looking at this Hyacinth Tower.",
  str_homestory_807701001_7_option_content = "Am I disturbing?",
  str_homestory_807701001_8_dialog_content = "You look very focused...",
  str_homestory_807701001_9_dialog_content = "Yes, I'm looking at this Hyacinth Tower.",
  str_homestory_807701001_10_dialog_content = "The Hyacinth Tower? What about it?",
  str_homestory_807701001_11_dialog_content = "Hmm... This Hyacinth Tower means a lot to Caelestites.",
  str_homestory_807701001_12_dialog_content = "Yes! This is a massive structure.",
  str_homestory_807701001_13_dialog_content = "You might not be able to see it clearly from here but it's actually very big. Fairly spacious inside as well!",
  str_homestory_807701001_14_dialog_content = "It can produce and repair the Colossus.",
  str_homestory_807701001_15_dialog_content = "According to the information available, many Caelestites were trained here.",
  str_homestory_807701001_16_dialog_content = "It's pretty much a cradle for Navigators.",
  str_homestory_807701001_17_dialog_content = "A cradle?",
  str_homestory_807701001_18_dialog_content = "See how exceptionally bright and radiant it is beneath the sky.",
  str_homestory_807701001_19_dialog_content = "It's more like... a spiritual totem of Caelestites.",
  str_homestory_807701001_20_dialog_content = "PlayerName, do you know how people are bonded together?",
  str_homestory_807701001_21_dialog_content = "Ah, you got me...",
  str_homestory_807701001_22_dialog_content = "I've never thought about this. Sorry.",
  str_homestory_807701001_23_dialog_content = "Don't worry. This question didn't matter to you before.",
  str_homestory_807701001_24_dialog_content = "But things are different now. You need to watch this continent from a new perspective.",
  str_homestory_807701001_25_dialog_content = "Everyone here, tall or short, strong or weak, elderly or young...",
  str_homestory_807701001_26_dialog_content = "As long as they share a common faith and belief...",
  str_homestory_807701001_27_dialog_content = "They are together.",
  str_homestory_807701001_28_dialog_content = "We can't conquer nature single-handedly.",
  str_homestory_807701001_29_dialog_content = "We don't have sharp claws or fangs. Our skins are not hard as rocks and our arms can't take us up to the sky.",
  str_homestory_807701001_30_dialog_content = "But if we fight together as one, our power is beyond imagination...",
  str_homestory_807701001_31_dialog_content = "If you put it this way...",
  str_homestory_807701001_32_dialog_content = "Your Majesty, you're the spiritual totem of us.",
  str_homestory_807701001_33_dialog_content = "...",
  str_homestory_807701001_34_dialog_content = "Hmm... That's right.",
  str_homestory_807701001_35_dialog_content = "Trust, admiration, or the seeking of protection bring them to me.",
  str_homestory_807701001_36_dialog_content = "This is not a bad thing...",
  str_homestory_807701001_37_dialog_content = "A united group is always stronger than a heap of loose sand.",
  str_homestory_807701001_38_dialog_content = "Both Illumina and Lumopolis are maintaining this unity in their own way.",
  str_homestory_807701001_39_dialog_content = "Yes... I've learned about this.",
  str_homestory_807701001_40_dialog_content = "You've grown, the Caelestite that holds the future.",
  str_homestory_807701001_41_dialog_content = "This White Tower, the totem of Caelestites, is like you...",
  str_homestory_807701001_42_dialog_content = "You both have the power of unity.",
  str_homestory_807701001_43_dialog_content = "I have the power to unite people and defend Eraveil...? Oh, Your Majesty, may I be bold enough to ask you a question?",
  str_homestory_807701001_44_dialog_content = "Go ahead.",
  str_homestory_807701001_45_dialog_content = "Did you see today's Eraveil in the future you foresaw?",
  str_homestory_807701001_46_dialog_content = "... Of course. And there are more.",
  str_homestory_804201001_0_dialog_content = "Barton!",
  str_homestory_804201001_1_dialog_content = "Hey, Navigator!",
  str_homestory_804201001_2_dialog_content = "Barton...",
  str_homestory_804201001_3_dialog_content = "Shh... Watch with me.<sprite=emo_mojing size=60 />",
  str_homestory_804201001_4_dialog_content = "... Huh?",
  str_homestory_804201001_5_dialog_content = "What are you watching?",
  str_homestory_804201001_6_dialog_content = "You've got quite a few gifted men here! Navigator!",
  str_homestory_804201001_7_dialog_content = "How did I miss them all on the Colossus?",
  str_homestory_804201001_8_dialog_content = "Hmm... I guess they didn't have enough room to fully spread their wings on the Colossus!",
  str_homestory_804201001_9_dialog_content = "... Gifted men?",
  str_homestory_804201001_10_dialog_content = "You're recruiting for Illumina?",
  str_homestory_804201001_11_dialog_content = "Recruit? No, they don't have to join.",
  str_homestory_804201001_12_dialog_content = "PlayerName, do you know which legion I command?",
  str_homestory_804201001_13_option_content = "The 2nd Legion",
  str_homestory_804201001_14_dialog_content = "That's right!",
  str_homestory_804201001_15_option_content = "The 4th Legion",
  str_homestory_804201001_16_dialog_content = "Seriously? <sprite=emo_shengqi size=60 />Brat, my troops are way larger than that girl's!",
  str_homestory_804201001_17_dialog_content = "Hmm! Wrath's elite reserves can't withstand a single blow from us!",
  str_homestory_804201001_18_dialog_content = "I'm in command of the largest 2nd Legion. Remember this.",
  str_homestory_804201001_19_dialog_content = "Yes...",
  str_homestory_804201001_20_dialog_content = "Do you know my responsibility specially assigned by the Grand Marshal!?",
  str_homestory_804201001_21_option_content = "Rapid support?",
  str_homestory_804201001_22_dialog_content = "... That's for Hiiro and Vice.",
  str_homestory_804201001_23_dialog_content = "Hey! Did you forget your brain at home?",
  str_homestory_804201001_24_dialog_content = "I lead the garrison troops!",
  str_homestory_804201001_25_dialog_content = "... Now you see?",
  str_homestory_804201001_26_dialog_content = "Yes...",
  str_homestory_804201001_27_option_content = "Defense and security.",
  str_homestory_804201001_28_dialog_content = "Correct! You've been learning!",
  str_homestory_804201001_29_dialog_content = "With this knowledge, you should understand what I'm doing here.",
  str_homestory_804201001_30_dialog_content = "You've gathered so many talented ones with unique skills here...",
  str_homestory_804201001_31_dialog_content = "From time to time a fight would break out between them...",
  str_homestory_804201001_32_dialog_content = "Sneak attacks! Hidden weapons! Taijutsu strikes!",
  str_homestory_804201001_33_dialog_content = "Tsk... Splendid.",
  str_homestory_804201001_34_dialog_content = "I don't need them to join Illumina. Do you get it?",
  str_homestory_804201001_35_dialog_content = "Watching their attack and defense is enough.",
  str_homestory_804201001_36_dialog_content = "I'm learning different techniques from different people. After, I'll pass these all on to my soldiers!",
  str_homestory_804201001_37_dialog_content = "This is a valuable lesson!",
  str_homestory_804201001_38_dialog_content = "I see...",
  str_homestory_804201001_39_dialog_content = "Hold on. Why are they fighting?",
  str_homestory_804201001_40_dialog_content = "Isn't it fairly common for Aurorians to not like each other?",
  str_homestory_804201001_41_dialog_content = "I thought you were already used to this on the Colossus.",
  str_homestory_804201001_42_dialog_content = "But...",
  str_homestory_804201001_43_dialog_content = "Just pretend they're sparring with each other!",
  str_homestory_804201001_44_dialog_content = "Now I need to work on the move I saw yesterday...",
  str_homestory_804201001_45_dialog_content = "How did he take that kick of hers?",
  str_homestory_804201001_46_dialog_content = "Hmm... Once I master this, dare Wrath to provoke me again!",
  str_homestory_804201001_47_dialog_content = "Hey! Huh!<sprite=emo_nuhuo size=60 />",
  str_homestory_804201001_48_dialog_content = "... Alright. Good luck, Barton...",
  str_homestory_807601001_0_dialog_content = "Kleken...",
  str_homestory_807601001_1_dialog_content = "Ah! The traveling hero has finally landed.",
  str_homestory_807601001_2_dialog_content = "Hi, Kleken.",
  str_homestory_807601001_3_dialog_content = "Do you really like this Waterfall Rock? I often see you here wandering around...",
  str_homestory_807601001_4_dialog_content = "How precious this stream is!",
  str_homestory_807601001_5_dialog_content = "All these rivers and springs are moving me to tears<sprite=emo_hanshui size=60 />.",
  str_homestory_807601001_6_dialog_content = "Are you being sarcastic?",
  str_homestory_807601001_7_dialog_content = "All we have here are a few ornamental streams...",
  str_homestory_807601001_8_dialog_content = "It's nothing compared to the \"ocean\" and \"drowning\" you like to say.",
  str_homestory_807601001_9_dialog_content = "I want to thank you.",
  str_homestory_807601001_10_dialog_content = "... For what?",
  str_homestory_807601001_11_dialog_content = "Soon you'll witness my Gaze Technique reaching perfection.",
  str_homestory_807601001_12_dialog_content = "I'll be able to tell what your little head has been busy with lately...",
  str_homestory_807601001_13_dialog_content = "One gaze into your beautiful eyes is all it takes to find the answer.",
  str_homestory_807601001_14_dialog_content = "Thank you for being my first witness.",
  str_homestory_807601001_15_dialog_content = "Err...",
  str_homestory_807601001_16_option_content = "Gaze Technique?",
  str_homestory_807601001_17_dialog_content = "You're curious, little one...",
  str_homestory_807601001_18_option_content = "Can I say no?",
  str_homestory_807601001_19_dialog_content = "Sure.",
  str_homestory_807601001_20_dialog_content = "But those swift little creatures behind me won't leave you.",
  str_homestory_807601001_21_dialog_content = "They love to watch you sleep, PlayerName...",
  str_homestory_807601001_22_dialog_content = "(... What the heck?)",
  str_homestory_807601001_23_dialog_content = "Fine... Don't be too long. I got things to do.",
  str_homestory_807601001_24_dialog_content = "So what is this Gaze Technique?",
  str_homestory_807601001_25_dialog_content = "Let me explain, warrior.",
  str_homestory_807601001_26_dialog_content = "I believe you visited Umbraton recently...",
  str_homestory_807601001_27_dialog_content = "Leisurely you were walking down the street when you spotted a pitiful little girl.",
  str_homestory_807601001_28_dialog_content = "She asked you for help to find out the prices of those restaurants on that street...",
  str_homestory_807601001_29_dialog_content = "She had too little to just walk in a random diner.",
  str_homestory_807601001_30_dialog_content = "She couldn't bear the thought of getting dirty looks from waiters if she ordered one slice of bread only...",
  str_homestory_807601001_31_dialog_content = "One restaurant after another you went with her and found out the prices for her.",
  str_homestory_807601001_32_dialog_content = "Every time, she shook her head.",
  str_homestory_807601001_33_dialog_content = "In the end, you decided to buy her a nice meal...",
  str_homestory_807601001_34_dialog_content = "After the meal, she took off after a quick thank you, leaving money on the table enough to cover the bill.",
  str_homestory_807601001_35_dialog_content = "... How do you know?",
  str_homestory_807601001_36_dialog_content = "(How could this Gaze Technique be this magical?)",
  str_homestory_807601001_37_dialog_content = "... Anyway, it was hard for me to process.",
  str_homestory_807601001_38_dialog_content = "If she had the money all along, why didn't she just walk into a restaurant and enjoy the food?",
  str_homestory_807601001_39_dialog_content = "As you said... she checked out the price of each dish in every restaurant in Umbraton!",
  str_homestory_807601001_40_dialog_content = "Hahah... Hahahah<sprite=emo_guilian size=60 />.",
  str_homestory_807601001_41_dialog_content = "Because I asked her to do so.",
  str_homestory_807601001_42_dialog_content = "It was a task assigned by Lord Istvan...",
  str_homestory_807601001_43_dialog_content = "To study food prices in Umbraton.",
  str_homestory_807601001_44_dialog_content = "I've been helping this girl. Giving her this opportunity to do me a small favor could make her feel useful...",
  str_homestory_807601001_45_dialog_content = "Anyway, the Caelestite had no better things to do then. So why not go ahead with it?",
  str_homestory_807601001_46_dialog_content = "Walking is too physical-demanding for me these days.",
  str_homestory_807601001_47_dialog_content = "...",
  str_homestory_807601001_48_dialog_content = "You see. This is the truth of the Gaze Technique, PlayerName.",
  str_homestory_807601001_49_dialog_content = "You seem disappointed... How interesting!",
  str_homestory_804601001_0_dialog_content = "It's him.",
  str_homestory_804601001_1_dialog_content = "Navigator comes and Navigator goes ♪",
  str_homestory_804601001_2_dialog_content = "Navigator smiles at Pierre but Pierre just wants to make trouble.",
  str_homestory_804601001_3_dialog_content = "Are you shopping?",
  str_homestory_804601001_4_dialog_content = "Shopping. Navigator thinks I'm shopping<sprite=emo_yinfu size=60 />",
  str_homestory_804601001_5_dialog_content = "Dian would say no and Kara would say, \"That's right!\" Niel would say, \"Kind of...\" but Pierre would only chuckle.<sprite=emo_muji size=60 />",
  str_homestory_804601001_6_dialog_content = "So what do you think I'm trying to say?",
  str_homestory_804601001_7_dialog_content = "...%^&",
  str_homestory_804601001_8_dialog_content = "Forget it. I'm not in the mood for a riddle.",
  str_homestory_804601001_9_dialog_content = "I wanted to ask how life is treating you here...",
  str_homestory_804601001_10_dialog_content = "It's a relief to see you smart and mischievous as always.",
  str_homestory_804601001_11_dialog_content = "Navigator cares about Keating. Pierre is honored ♪",
  str_homestory_804601001_12_dialog_content = "Navigator, aren't you curious about whom I've met recently?",
  str_homestory_804601001_13_dialog_content = "... I've got a bad feeling...<sprite=emo_tanqi size=60 />",
  str_homestory_804601001_14_dialog_content = "So who have you met?",
  str_homestory_804601001_15_dialog_content = "Your little ones must be more careful here. It's not nice to sneer at others...",
  str_homestory_804601001_16_dialog_content = "You're not in Lumopolis. Some Aurorians are short-tempered!",
  str_homestory_804601001_17_dialog_content = "There are also very sensitive Aurorians. Your mean words would probably bring them to tears...",
  str_homestory_804601001_18_dialog_content = "Navigator is worried about us. Navigator cares about his friends ♪",
  str_homestory_804601001_19_dialog_content = "We met a long-tailed repair guy and he made us a robotic arm to catch chickens.",
  str_homestory_804601001_20_dialog_content = "We met a chubby bird and she gifted us many snowballs.",
  str_homestory_804601001_21_dialog_content = "We met a dog in a suit, upset that no one was interested in his fake paintings.",
  str_homestory_804601001_22_dialog_content = "Pierre met a short and stocky Navigator, standing in front of me worried about his friends.",
  str_homestory_804601001_23_dialog_content = "... Phew... Better than I thought.",
  str_homestory_804601001_24_dialog_content = "To be honest, these are possibly the gentlest words you've ever said.",
  str_homestory_804601001_25_dialog_content = "People become gentle for a reason.",
  str_homestory_804601001_26_dialog_content = "In the bookcase, there are books that Dian likes.",
  str_homestory_804601001_27_dialog_content = "In the room, there's a lens cloth that Niel needs.",
  str_homestory_804601001_28_dialog_content = "In the dining room, there's a hat rack for Kara.",
  str_homestory_804601001_29_dialog_content = "On the grass, there are Gege and Pierre's favorite snacks♪",
  str_homestory_804601001_30_dialog_content = "The thoughtful Navigator is our bosom friend.",
  str_homestory_804601001_31_dialog_content = "The Navigator is the star of tomorrow.",
  str_homestory_804601001_32_dialog_content = "The star that will grow taller♪",
  str_homestory_804601001_33_dialog_content = "... It was all good until the very last line.",
  str_homestory_804601001_34_dialog_content = "Navigator, what's your plan?",
  str_homestory_804601001_35_option_content = "Go back for some rest",
  str_homestory_804601001_36_dialog_content = "I'll take a nap.",
  str_homestory_804601001_37_option_content = "Wander around",
  str_homestory_804601001_38_dialog_content = "I'm going to check out what other people are up to.",
  str_homestory_804601001_39_dialog_content = "Got it. Pierre got it.",
  str_homestory_804601001_40_dialog_content = "Though Pierre doesn't really care. Here is a line for the master.",
  str_homestory_804601001_41_dialog_content = "Gege is fertilizing near the garden. Fertilizing ♪",
  str_homestory_804601001_42_dialog_content = "?!",
  str_homestory_804601001_43_dialog_content = "Fertilizing?",
  str_homestory_804601001_44_dialog_content = "Pierre is very kind. Check it out when you can ♪",
  str_homestory_804601001_45_dialog_content = "... Thank you for your concern!",
  str_homestory_805701001_0_dialog_content = "This is... Cat hair?",
  str_homestory_805701001_1_dialog_content = "Yawn—",
  str_homestory_805701001_2_dialog_content = "Hmm? Philyshy?",
  str_homestory_805701001_3_dialog_content = "Huh... Huh...<sprite=emo_kun size=60 />",
  str_homestory_805701001_4_dialog_content = "... Philyshy?",
  str_homestory_805701001_5_dialog_content = "Phew... Meow!",
  str_homestory_805701001_6_dialog_content = "What the heck! It's PlayerName, meow.",
  str_homestory_805701001_7_dialog_content = "Can't you see I'm sleeping, meow?",
  str_homestory_805701001_8_dialog_content = "Come back after my nap, meow.",
  str_homestory_805701001_9_dialog_content = "I'll have a sweet dream in this comfy haystack, meow...",
  str_homestory_805701001_10_dialog_content = "Wait, Philyshy! I have something to tell you!",
  str_homestory_805701001_11_dialog_content = "Huh... Huh... Meow!",
  str_homestory_805701001_12_dialog_content = "Hmm... What must you tell me, meow?",
  str_homestory_805701001_13_dialog_content = "It better be very important, meow!",
  str_homestory_805701001_14_dialog_content = "Umm... Some Aurorians came to me...",
  str_homestory_805701001_15_dialog_content = "Philyshy, have you been...",
  str_homestory_805701001_16_option_content = "Feeling unwell?",
  str_homestory_805701001_17_dialog_content = "Any itch?",
  str_homestory_805701001_18_dialog_content = "Loss of appetite?",
  str_homestory_805701001_19_dialog_content = "What are you talking about, meow?",
  str_homestory_805701001_20_dialog_content = "Philyshy doesn't understand.",
  str_homestory_805701001_21_option_content = "Shedding season?",
  str_homestory_805701001_22_dialog_content = "Shedding what... meow?",
  str_homestory_805701001_23_dialog_content = "What's that?",
  str_homestory_805701001_24_dialog_content = "(Such bad acting!)",
  str_homestory_805701001_25_dialog_content = "Anyway, Philyshy doesn't feel anything!",
  str_homestory_805701001_26_dialog_content = "(Stroking Philyshy's tail)",
  str_homestory_805701001_27_dialog_content = "Meow!",
  str_homestory_805701001_28_dialog_content = "PlayerName, how could you touch a lady's tail?",
  str_homestory_805701001_29_dialog_content = "It felt kind of nice. No, meow!",
  str_homestory_805701001_30_dialog_content = "Philyshy, so much hair came off when you shook!",
  str_homestory_805701001_31_dialog_content = "Th-that's not true...!",
  str_homestory_805701001_32_dialog_content = "Boohoo... Meow. I can't stop it!",
  str_homestory_805701001_33_dialog_content = "It's the shedding season... No, meow!",
  str_homestory_805701001_34_dialog_content = "My hair is just absorbing enough sunshine for an evolution, meow!",
  str_homestory_805701001_35_dialog_content = "Once it's done... I'll become Super Philyshy, meow!",
  str_homestory_805701001_36_dialog_content = "But... If your hair flies all over the place...",
  str_homestory_805701001_37_dialog_content = "Some Aurorians might suffer from allergies.",
  str_homestory_805701001_38_dialog_content = "Hmm... What shall I do then?",
  str_homestory_805701001_39_dialog_content = "It's not Philyshy's choice.<sprite=emo_tanqi size=60 />",
  str_homestory_805701001_40_dialog_content = "You're right... Let me think...",
  str_homestory_805701001_41_dialog_content = "How about... Let me groom you!",
  str_homestory_805701001_42_dialog_content = "Your hair will be softer and silkier. No more flying about.",
  str_homestory_805701001_43_dialog_content = "Istvan taught me this.",
  str_homestory_805701001_44_dialog_content = "Okay... Only because you prepared this comfy haystack in Eraveil.",
  str_homestory_805701001_45_dialog_content = "Grooming request granted, meow!",
  str_homestory_803601001_0_dialog_content = "Hydrad?",
  str_homestory_803601001_1_dialog_content = "What are you doing?",
  str_homestory_803601001_2_dialog_content = "Can't you see?",
  str_homestory_803601001_3_dialog_content = "I'm standing.",
  str_homestory_803601001_4_dialog_content = "... That I know.",
  str_homestory_803601001_5_dialog_content = "...",
  str_homestory_803601001_6_dialog_content = "...",
  str_homestory_803601001_7_dialog_content = "Hey.",
  str_homestory_803601001_8_dialog_content = "Yes?",
  str_homestory_803601001_9_dialog_content = "I got injured yesterday.",
  str_homestory_803601001_10_dialog_content = "?!",
  str_homestory_803601001_11_option_content = "Are you alright?",
  str_homestory_803601001_12_dialog_content = "Still kicking.",
  str_homestory_803601001_13_option_content = "Where did you go?",
  str_homestory_803601001_14_dialog_content = "I know what you're worried about.",
  str_homestory_803601001_15_dialog_content = "It didn't happen here.",
  str_homestory_803601001_16_dialog_content = "I... I'm just concerned about your health.",
  str_homestory_803601001_17_dialog_content = "How do you feel? Any better?",
  str_homestory_803601001_18_dialog_content = "More or less.",
  str_homestory_803601001_19_dialog_content = "My speedy recovery is all thanks to Shadow Wolves.",
  str_homestory_803601001_20_dialog_content = "Fine. Could you tell me what happened?",
  str_homestory_803601001_21_dialog_content = "Don't tell me you enjoy this.",
  str_homestory_803601001_22_dialog_content = "I was fighting for something.",
  str_homestory_803601001_23_dialog_content = "In the Black Market in Umbraton.",
  str_homestory_803601001_24_dialog_content = "What was so important?",
  str_homestory_803601001_25_dialog_content = "Allegedly an ancient civilization product.",
  str_homestory_803601001_26_dialog_content = "Allegedly?",
  str_homestory_803601001_27_dialog_content = "You're not sure about this?",
  str_homestory_803601001_28_dialog_content = "You'd never know until you try.",
  str_homestory_803601001_29_dialog_content = "... What was it?",
  str_homestory_803601001_30_dialog_content = "Some form of apparatus that can fully materialize Illusion or Shadow magic.",
  str_homestory_803601001_31_dialog_content = "Err... But your Shadow Wolves have always been by your side.",
  str_homestory_803601001_32_dialog_content = "Hum. But I want to pet their fluffy fur every day.",
  str_homestory_803601001_33_dialog_content = "Real fur, growing from their skin, not the scattered hairs that fall off during the molting period.",
  str_homestory_803601001_34_dialog_content = "I see...",
  str_homestory_803601001_35_dialog_content = "(Hydrad... is probably quite lonely?)",
  str_homestory_803601001_36_dialog_content = "I think it's a fake.",
  str_homestory_803601001_37_dialog_content = "The device?",
  str_homestory_803601001_38_dialog_content = "Yes.",
  str_homestory_803601001_39_dialog_content = "I've never heard of anything like that.",
  str_homestory_803601001_40_dialog_content = "(Would he feel better if it was a fake?)",
  str_homestory_803601001_41_dialog_content = "I agree with you.",
  str_homestory_803601001_42_dialog_content = "Something like this would be a priceless heirloom...",
  str_homestory_803601001_43_dialog_content = "It won't end up in the black market.",
  str_homestory_803601001_44_dialog_content = "... That's true.",
  str_homestory_803601001_45_dialog_content = "Since you also think so.",
  str_homestory_803601001_46_dialog_content = "I gotta go.",
  str_homestory_803601001_47_dialog_content = "See you!",
  str_homestory_803601001_48_dialog_content = "(If it was real, what would I do with it?)",
  str_homestory_811401001_0_dialog_content = "This horse...",
  str_homestory_811401001_1_dialog_content = "Ah, dear Navigator.",
  str_homestory_811401001_2_dialog_content = "Is Anna in your way?",
  str_homestory_811401001_3_dialog_content = "Or are you here to see me?",
  str_homestory_811401001_4_dialog_content = "Sorry for staying here for so long. These flowers are so fragrant...",
  str_homestory_811401001_5_dialog_content = "Don't worry about it. Enjoy the flowers.",
  str_homestory_811401001_6_dialog_content = "That was fast. These flowers...",
  str_homestory_811401001_7_dialog_content = "A lot more flowers than I imagined.",
  str_homestory_811401001_8_dialog_content = "Hmm? What was that, Navigator?",
  str_homestory_811401001_9_dialog_content = "Ah... I was murmuring about these flowers.",
  str_homestory_811401001_10_dialog_content = "I just ordered through the Courier Union<sprite=emo_gezitou size=60 /> a few days ago.",
  str_homestory_811401001_11_dialog_content = "Some people suggested that we should add some flowers to all the rocks and trees.",
  str_homestory_811401001_12_dialog_content = "Oh? I thought about the same thing!",
  str_homestory_811401001_13_dialog_content = "I just told Anna the other day that we needed more flowers here.",
  str_homestory_811401001_14_dialog_content = "Yes. That's why I reached out to the Courier Union.",
  str_homestory_811401001_15_dialog_content = "However, it's a bit more than I expected...",
  str_homestory_811401001_16_dialog_content = "I also just bought some after my last quest.",
  str_homestory_811401001_17_dialog_content = "That explains everything...",
  str_homestory_811401001_18_dialog_content = "Navigator, you've got a nice place.",
  str_homestory_811401001_19_dialog_content = "I checked out the store and found my favorite gin...",
  str_homestory_811401001_20_dialog_content = "Also those essential herbs, syrups, and spices for a lovely cocktail.",
  str_homestory_811401001_21_dialog_content = "Hahah. I'm nicely surprised!",
  str_homestory_811401001_22_dialog_content = "You've become more thoughtful.",
  str_homestory_811401001_23_dialog_content = "Thoughtful...",
  str_homestory_811401001_24_dialog_content = "What experiences turned that ignorant kid this sweet and considerable?",
  str_homestory_811401001_25_dialog_content = "Genevieve is still talking about stocking gin in the shop?",
  str_homestory_811401001_26_dialog_content = "Not just that. You've also ordered flowers for the ladies.",
  str_homestory_811401001_27_dialog_content = "Well... Actually...",
  str_homestory_811401001_28_dialog_content = "The person who told me to stock some gin and order flowers is...",
  str_homestory_811401001_29_dialog_content = "... Smokey.",
  str_homestory_811401001_30_dialog_content = "... Oh?",
  str_homestory_811401001_31_dialog_content = "She had a lot more requests, so I don't think she did it for you...",
  str_homestory_811401001_32_dialog_content = "Now you mentioned it... That day when I was talking with Anna, I did feel some hot air around me.",
  str_homestory_811401001_33_dialog_content = "I didn't even think about her, considering the sheer number of people here that use fire<sprite=emo_nuhuo size=60 />.",
  str_homestory_811401001_34_dialog_content = "... This guy...",
  str_homestory_811401001_35_dialog_content = "She probably doesn't want me to find out about this.",
  str_homestory_811401001_36_dialog_content = "Umm... I think...",
  str_homestory_811401001_37_option_content = "She hopes so.",
  str_homestory_811401001_38_dialog_content = "Otherwise, she could easily get some gin and flowers herself...",
  str_homestory_811401001_39_dialog_content = "I mean... She didn't really need me to get these.",
  str_homestory_811401001_40_option_content = "She hopes not.",
  str_homestory_811401001_41_dialog_content = "I actually asked if the gin was for you. And she denied...",
  str_homestory_811401001_42_dialog_content = "Is that so?",
  str_homestory_811401001_43_dialog_content = "That's a bit awkward.",
  str_homestory_811401001_44_dialog_content = "Anyway, Navigator, please keep today's conversation between us.",
  str_homestory_811401001_45_dialog_content = "Although I've learned about her kindness, nobody wants this exposed to her face...",
  str_homestory_811401001_46_dialog_content = "To conceal her embarrassment, she would either set fire or make a scene.",
  str_homestory_811401001_47_dialog_content = "Understood...",
  str_homestory_811401001_48_dialog_content = "You know her well!",
  str_homestory_811401001_49_dialog_content = "You think so? I don't know about that.",
  str_homestory_801801001_0_dialog_content = "This wild aura...",
  str_homestory_801801001_1_dialog_content = "Don't care!",
  str_homestory_801801001_2_dialog_content = "And... no waste of breath!",
  str_homestory_801801001_3_dialog_content = "Too many fools in this world! Flame! Scorch!<sprite=emo_nuhuo size=60 />",
  str_homestory_801801001_4_dialog_content = "(She's completely beside herself!)",
  str_homestory_801801001_5_dialog_content = "Hey, Regina!",
  str_homestory_801801001_6_dialog_content = "Navigator, what do you think about my new demo?",
  str_homestory_801801001_7_dialog_content = "I thought you were cursing...",
  str_homestory_801801001_8_dialog_content = "You heard it?",
  str_homestory_801801001_9_dialog_content = "Yes!",
  str_homestory_801801001_10_dialog_content = "Oh... I've tried myself to be implicit!",
  str_homestory_801801001_11_dialog_content = "But you could still hear it?",
  str_homestory_801801001_12_dialog_content = "You've learned from the bad kids!",
  str_homestory_801801001_13_dialog_content = "?",
  str_homestory_801801001_14_dialog_content = "Ahem... Never...",
  str_homestory_801801001_15_dialog_content = "Whatever. Who cares!",
  str_homestory_801801001_16_dialog_content = "My new song is not yet complete. Any thought? Hit me!",
  str_homestory_801801001_17_dialog_content = "Theme? Lyrics? Melody?",
  str_homestory_801801001_18_dialog_content = "I suck at music.",
  str_homestory_801801001_19_dialog_content = "So what? I hate no one more than those old fogeys who insist on setting thresholds for music!",
  str_homestory_801801001_20_dialog_content = "Just say something, anything!",
  str_homestory_801801001_21_dialog_content = "...",
  str_homestory_801801001_22_option_content = "Barbara is the best",
  str_homestory_801801001_23_dialog_content = "Huh? What the heck did you say?",
  str_homestory_801801001_24_dialog_content = "I got it. Sarcasm.",
  str_homestory_801801001_25_option_content = "Metal forever!",
  str_homestory_801801001_26_dialog_content = "That's right!",
  str_homestory_801801001_27_dialog_content = "I'll write it down!",
  str_homestory_801801001_28_dialog_content = "Hah! A new song composed with the Caelestite's help will be awesome!",
  str_homestory_801801001_29_dialog_content = "Ah. You're competing with Barbara in all fields, as well as with your metal peers?",
  str_homestory_801801001_30_dialog_content = "Come on. Which musician genuinely respects another?<sprite=emo_shengqi size=60 />",
  str_homestory_801801001_31_dialog_content = "Especially those in my genre. Most of them are ignorant and fake!",
  str_homestory_801801001_32_dialog_content = "Feeling themselves the very last one that understands rock and has considerable seniority... In reality, they probably never write a song on their own!",
  str_homestory_801801001_33_dialog_content = "Hmm! If it's up to me, I'd set them all on fire...",
  str_homestory_801801001_34_dialog_content = "Talking with them about metal is worse than listening to Barbara's new single!",
  str_homestory_801801001_35_dialog_content = "... I thought you strongly dislike Barbara?",
  str_homestory_801801001_36_dialog_content = "Two seconds.",
  str_homestory_801801001_37_dialog_content = "?",
  str_homestory_801801001_38_dialog_content = "I can stand Barbara's new song for 2 seconds.",
  str_homestory_801801001_39_dialog_content = "Ahh...",
  str_homestory_809201001_0_dialog_content = "That is...",
  str_homestory_809201001_1_dialog_content = "Hey, Pact.",
  str_homestory_809201001_2_dialog_content = "Who else could it be?<sprite=emo_baiyan size=60 />",
  str_homestory_809201001_3_dialog_content = "Ahem. This swing is quite popular...",
  str_homestory_809201001_4_dialog_content = "So... You like to play on the swing?",
  str_homestory_809201001_5_dialog_content = "Your question is not very well-structured.",
  str_homestory_809201001_6_dialog_content = "First, what's your definition of \"like\"?",
  str_homestory_809201001_7_option_content = "Define",
  str_homestory_809201001_8_dialog_content = "I think if you like something, you'd want to do it often.",
  str_homestory_809201001_9_dialog_content = "Then what's the measure of \"often\"? This is not clear.",
  str_homestory_809201001_10_dialog_content = "Like constantly?",
  str_homestory_809201001_11_dialog_content = "Or only when I have time?",
  str_homestory_809201001_12_dialog_content = "Or maybe I don't think about it frequently, but when I do, I'll go ahead and take action?",
  str_homestory_809201001_13_dialog_content = "(Dear heaven! I'm just trying to have a casual conversation with Pact...)",
  str_homestory_809201001_14_dialog_content = "I guess the measure of \"often\" is to do it when you have time.",
  str_homestory_809201001_15_option_content = "Refuse to define",
  str_homestory_809201001_16_dialog_content = "Who needs a definition of \"like\"?",
  str_homestory_809201001_17_dialog_content = "When I have time, I like to walk around.",
  str_homestory_809201001_18_dialog_content = "Something that I want to do when I have time?",
  str_homestory_809201001_19_dialog_content = "Understood.",
  str_homestory_809201001_20_dialog_content = "In this case, I do like to sit on this swing.",
  str_homestory_809201001_21_dialog_content = "This kind of hanging chair offers a very subtle sense of zero gravity...",
  str_homestory_809201001_22_dialog_content = "It gives me a joy that can't be put in words.",
  str_homestory_809201001_23_dialog_content = "Really? That's great!",
  str_homestory_809201001_24_dialog_content = "At first, I wasn't sure if a swing was a good idea.",
  str_homestory_809201001_25_dialog_content = "I'm so glad that you are enjoying it!",
  str_homestory_809201001_26_dialog_content = "However, there's also trouble.",
  str_homestory_809201001_27_dialog_content = "Hunting Stone has a hard time finding the right amount of strength to push me.",
  str_homestory_809201001_28_dialog_content = "I actually fell off once!",
  str_homestory_809201001_29_dialog_content = "Hahahah...",
  str_homestory_809201001_30_dialog_content = "Did you just laugh at me?<sprite=emo_shengqi size=60 />",
  str_homestory_809201001_31_option_content = "Deny",
  str_homestory_809201001_32_dialog_content = "Never...",
  str_homestory_809201001_33_dialog_content = "Are you sure? Why did the corners of your lips go up then?",
  str_homestory_809201001_34_option_content = "Admit",
  str_homestory_809201001_35_dialog_content = "I'm sorry...",
  str_homestory_809201001_36_dialog_content = "I could almost see it in my head...",
  str_homestory_809201001_37_dialog_content = "Ahem... Were you injured?",
  str_homestory_809201001_38_dialog_content = "Do you think I'm that vulnerable?",
  str_homestory_809201001_39_dialog_content = "That's a relief! Since you love the swing so much...",
  str_homestory_809201001_40_dialog_content = "May I give you a push?",
  str_homestory_809201001_41_dialog_content = "Hmm? Do you mind?",
  str_homestory_809201001_42_dialog_content = "Well, if you don't mind. My strength is nothing compared to Hunting Stone's.",
  str_homestory_809201001_43_dialog_content = "That depends on how you define \"mind.\"",
  str_homestory_809201001_44_dialog_content = "Err...",
  str_homestory_809201001_45_dialog_content = "Come on. It's swing time!",
  str_homestory_809201001_46_dialog_content = "Okay... Since you're this sincere... Let's go.",
  str_homestory_809901001_0_dialog_content = "Areia...",
  str_homestory_809901001_1_dialog_content = "Ah, PlayerName...",
  str_homestory_809901001_2_dialog_content = "Thank you for inviting me here. I'm very happy!",
  str_homestory_809901001_3_dialog_content = "You're very welcome!",
  str_homestory_809901001_4_dialog_content = "I guess you're not yet familiar with this area. Do you need a tour guide?",
  str_homestory_809901001_5_dialog_content = "PlayerName, do you really have time for this?",
  str_homestory_809901001_6_dialog_content = "Of course. No one knows this place better than I.",
  str_homestory_809901001_7_dialog_content = "But...",
  str_homestory_809901001_8_dialog_content = "I... I'd rather go back to my room.",
  str_homestory_809901001_9_dialog_content = "Huh? Areia, you don't like the scenery outside?",
  str_homestory_809901001_10_dialog_content = "Quite the opposite. I love the scenery here!",
  str_homestory_809901001_11_dialog_content = "I was never at a secluded and comfortable place like this before.",
  str_homestory_809901001_12_option_content = "Show gratitude",
  str_homestory_809901001_13_dialog_content = "I'm really glad you like it here!",
  str_homestory_809901001_14_dialog_content = "We've got peace and seclusion as well as hilarity and jubilation here.",
  str_homestory_809901001_15_dialog_content = "I'll show you around.",
  str_homestory_809901001_16_dialog_content = "But I'm scared...",
  str_homestory_809901001_17_option_content = "Make an inquiry",
  str_homestory_809901001_18_dialog_content = "What's the rush going back to the room?",
  str_homestory_809901001_19_dialog_content = "I'm scared...",
  str_homestory_809901001_20_dialog_content = "What if the curse and dark thorns on me ruined the beauty?",
  str_homestory_809901001_21_dialog_content = "It would cause so much trouble for PlayerName...",
  str_homestory_809901001_22_dialog_content = "Areia, that's very considerate of you.",
  str_homestory_809901001_23_dialog_content = "But I don't think you would ruin the beauty here.",
  str_homestory_809901001_24_dialog_content = "Hmm?",
  str_homestory_809901001_25_dialog_content = "We've known each other for some time. Your curse doesn't affect me at all.",
  str_homestory_809901001_26_dialog_content = "But my dark thorns...",
  str_homestory_809901001_27_dialog_content = "Aren't they your friends who protect your body from the curse?",
  str_homestory_809901001_28_dialog_content = "Yes...",
  str_homestory_809901001_29_dialog_content = "Areia's friends are my friends!",
  str_homestory_809901001_30_dialog_content = "Besides...",
  str_homestory_809901001_31_dialog_content = "I remember you've been looking for ways to remove the curse.",
  str_homestory_809901001_32_dialog_content = "Have a walk around and you might find something.",
  str_homestory_809901001_33_dialog_content = "Huh... I find it very hard to believe even if it came out of PlayerName.",
  str_homestory_809901001_34_dialog_content = "So many years have passed. What's the chance to just find a solution here?",
  str_homestory_809901001_35_dialog_content = "I guess you don't go out much at all other than for work?",
  str_homestory_809901001_36_dialog_content = "Yes...",
  str_homestory_809901001_37_dialog_content = "When you spend time in nature, your mood will improve.",
  str_homestory_809901001_38_dialog_content = "You never know. A good mood might weaken the curse!",
  str_homestory_809901001_39_dialog_content = "...",
  str_homestory_809901001_40_dialog_content = "Hahahah...",
  str_homestory_809901001_41_dialog_content = "Thank you. I'm feeling pretty good now.<sprite=emo_aixin size=60 />",
  str_homestory_809901001_42_dialog_content = "Well, then... may I visit the mine?",
  str_homestory_809901001_43_dialog_content = "Hmm?",
  str_homestory_801601001_0_dialog_content = "Kafka?",
  str_homestory_801601001_1_dialog_content = "Wait, Kafka... What is this water stain<sprite=emo_hanshui size=60 /> on the ground?",
  str_homestory_801601001_2_dialog_content = "Ah... I'm so sorry. Franz<sprite=emo_goutou size=60 /> drooled. I just wiped it clean.",
  str_homestory_801601001_3_dialog_content = "He seems to drool a lot when he feels happy. I've worked hard to address this new problem.",
  str_homestory_801601001_4_dialog_content = "Err... At least he doesn't wet my bed as often.",
  str_homestory_801601001_5_dialog_content = "That's worth a treat... Franz has always been a good boy, right?",
  str_homestory_801601001_6_dialog_content = "Your compliment will make him go wild with joy.",
  str_homestory_801601001_7_dialog_content = "I know he's very happy here.",
  str_homestory_801601001_8_dialog_content = "Hmm? Because he has more room here than on the Colossus?",
  str_homestory_801601001_9_dialog_content = "Or because he keeps running into strange people...",
  str_homestory_801601001_10_dialog_content = "As you know, he loves strange things.",
  str_homestory_801601001_11_dialog_content = "Like what?",
  str_homestory_801601001_12_dialog_content = "I should say \"strange creatures.\"",
  str_homestory_801601001_13_dialog_content = "Strange creatures...",
  str_homestory_801601001_14_dialog_content = "Got it! You must be talking about... Him...",
  str_homestory_801601001_15_option_content = "Tourdog?",
  str_homestory_801601001_16_dialog_content = "Hmm... That sounds about right. I never talked to him much.",
  str_homestory_801601001_17_dialog_content = "But Franz's tail wags like crazy when he sees Tourdog. He even tried to bite Tourdog's ear once.",
  str_homestory_801601001_18_dialog_content = "Ah? What did Tourdog do?",
  str_homestory_801601001_19_dialog_content = "Nothing much. He stared at Franz for a while, holding a pan in his hand. I felt he had something to say.",
  str_homestory_801601001_20_dialog_content = "(... He might ask Franz to draw him some pictures!)",
  str_homestory_801601001_21_dialog_content = "At last, he glanced at Franz's paws and walked away shaking his head.",
  str_homestory_801601001_22_dialog_content = "Phew... That's a relief...",
  str_homestory_801601001_23_dialog_content = "By the way, his ears look very soft.",
  str_homestory_801601001_24_dialog_content = "I should just touch them next time...",
  str_homestory_801601001_25_option_content = "Hachi and Gin?",
  str_homestory_801601001_26_dialog_content = "Two fluffy brats who try to appear mature.",
  str_homestory_801601001_27_dialog_content = "Every time they see Franz, they yell, \"Wow! A real doggie!\"",
  str_homestory_801601001_28_dialog_content = "Franz seems to like them as well and keeps rushing upon their tails.",
  str_homestory_801601001_29_dialog_content = "That sounds weird...",
  str_homestory_801601001_30_dialog_content = "I don't know why but I really want to see it for myself...",
  str_homestory_801601001_31_dialog_content = "All in all, Franz is living a good life here.",
  str_homestory_801601001_32_dialog_content = "However... have you been spending a lot of time with Franz lately?",
  str_homestory_801601001_33_dialog_content = "Hmm? I can't recall that.",
  str_homestory_801601001_34_dialog_content = "But I can smell you on Franz!",
  str_homestory_801601001_35_dialog_content = "He might have sneaked into your room.",
  str_homestory_801601001_36_dialog_content = "Hmm... It isn't entirely impossible.",
  str_homestory_801601001_37_dialog_content = "Wait...",
  str_homestory_801601001_38_dialog_content = "What did you say to me?",
  str_homestory_801601001_39_dialog_content = "Franz doesn't wet your bed<sprite=emo_hanshui size=60 /> as often?",
  str_homestory_801601001_40_dialog_content = "Err... Don't tell me...",
  str_homestory_801601001_41_dialog_content = "... No wonder my beddings have been damp recently!",
  str_homestory_801601001_42_dialog_content = "That explains a lot...",
  str_homestory_801601001_43_dialog_content = "I guess Franz really likes you.",
  str_homestory_801601001_44_dialog_content = "... Should I feel happy right now?",
  str_homestory_801601001_45_dialog_content = "Are you seeking advice from me?",
  str_homestory_801601001_46_dialog_content = "Well... If I were you, I would rush home to wash the sheets right now.",
  str_homestory_804501001_0_dialog_content = "What's that sound?",
  str_homestory_804501001_1_dialog_content = "Nails?",
  str_homestory_804501001_2_dialog_content = "Shush... Please wait...",
  str_homestory_804501001_3_dialog_content = "Ah! Your face is bright and clean like a porcelain plate, reflecting the filthy body of mine...",
  str_homestory_804501001_4_dialog_content = "Your eyes are deep like the night sky, piercing right through the unbearable part of my heart...",
  str_homestory_804501001_5_dialog_content = "Please forgive me for my sin...",
  str_homestory_804501001_6_dialog_content = "Or would forgiving me be your disgrace?",
  str_homestory_804501001_7_dialog_content = "...",
  str_homestory_804501001_8_dialog_content = "Sorry about the wait, PlayerName!",
  str_homestory_804501001_9_dialog_content = "Did I disturb you?",
  str_homestory_804501001_10_dialog_content = "My most sincere apologies! My voice is intolerable to any ear, filled with sins...",
  str_homestory_804501001_11_dialog_content = "Please don't be so harsh on yourself. I'm not disturbed at all!",
  str_homestory_804501001_12_dialog_content = "But I'm really curious... Who were you speaking to?",
  str_homestory_804501001_13_dialog_content = "There must be some misunderstanding... There was no one. I was confessing my sins.",
  str_homestory_804501001_14_dialog_content = "It's all thanks to you!",
  str_homestory_804501001_15_dialog_content = "Thank you for providing this perfect place for my confession.",
  str_homestory_804501001_16_dialog_content = "Finally, I'm able to confess without disturbing Lady Victoria.",
  str_homestory_804501001_17_option_content = "Deny",
  str_homestory_804501001_18_dialog_content = "I can't remember building a place for confession...",
  str_homestory_804501001_19_dialog_content = "So very humble. I'm sure this magnificent fountain took you a lot of time and effort.",
  str_homestory_804501001_20_dialog_content = "But this is the Fountain of Hope.",
  str_homestory_804501001_21_option_content = "Admit",
  str_homestory_804501001_22_dialog_content = "You're most welcome. Glad you like it...",
  str_homestory_804501001_23_dialog_content = "Wait... You said confession?",
  str_homestory_804501001_24_dialog_content = "You're not talking about this Fountain of Hope, are you?",
  str_homestory_804501001_25_dialog_content = "The Fountain of Hope. What a gentle name!",
  str_homestory_804501001_26_dialog_content = "I saw people here putting their palms together devoutly and confessing. Now I know its name!",
  str_homestory_804501001_27_dialog_content = "I'm guilty. I must confess...",
  str_homestory_804501001_28_dialog_content = "I guess that's one way of looking at it... I believe people are here praying.",
  str_homestory_804501001_29_dialog_content = "I must also confess on PlayerName's behalf...",
  str_homestory_804501001_30_dialog_content = "Huh?!",
  str_homestory_804501001_31_dialog_content = "A confession should never be interrupted...",
  str_homestory_804501001_32_dialog_content = "PlayerName, please forgive me for not explaining this before.",
  str_homestory_804501001_33_dialog_content = "O Truth dwelling in the Fountain of Hope...",
  str_homestory_804501001_34_dialog_content = "Please forgive Nails for disturbing you once again!",
  str_homestory_804501001_35_dialog_content = "I'm guilty. I'm here to confess. Please punish me...",
  str_homestory_804501001_36_option_content = "Punish",
  str_homestory_804501001_37_dialog_content = "Gosh! I felt the Fountain of Hope's response!",
  str_homestory_804501001_38_dialog_content = "Response? Truth is finally here!",
  str_homestory_804501001_39_dialog_content = "Ahem, the Fountain of Hope said...",
  str_homestory_804501001_40_option_content = "Comfort",
  str_homestory_804501001_41_dialog_content = "Nails, I really don't think you need to confess to such matters.",
  str_homestory_804501001_42_dialog_content = "Instead of confessing here, why not make plans for the future?",
  str_homestory_804501001_43_dialog_content = "!",
  str_homestory_804501001_44_dialog_content = "How could I not think of this until now?",
  str_homestory_804501001_45_dialog_content = "I knew it... I'm a sinful man...",
  str_homestory_804501001_46_dialog_content = "Err...",
  str_homestory_808601001_0_dialog_content = "This familiar white blossom...",
  str_homestory_808601001_1_dialog_content = "Navigator PlayerName.",
  str_homestory_808601001_2_dialog_content = "I didn't expect Eraveil to be this beautiful.",
  str_homestory_808601001_3_dialog_content = "This endless prairie... You can't find it in Lumopolis.",
  str_homestory_808601001_4_dialog_content = "Even these white blossoms<sprite=emo_huaduo size=60 /> like Eraveil...",
  str_homestory_808601001_5_dialog_content = "Yeah. I'm just as amazed.",
  str_homestory_808601001_6_dialog_content = "Hmm? Aren't you one of them in Eraveil?",
  str_homestory_808601001_7_dialog_content = "Ah... Right...",
  str_homestory_808601001_8_dialog_content = "I remember now... You were forced to leave Eraveil at an early age.",
  str_homestory_808601001_9_dialog_content = "That's correct. I learned about Eraveil from Soroz...",
  str_homestory_808601001_10_dialog_content = "But I was amazed by its beauty when I first came to Eraveil.<sprite=emo_pugongying size=60 />",
  str_homestory_808601001_11_dialog_content = "And this amazement doesn't fade over time.",
  str_homestory_808601001_12_dialog_content = "This is probably the feeling of being home. I know Eraveil is connected with me.",
  str_homestory_808601001_13_dialog_content = "Yeah... Everything here is full of spiritual intelligence. The Caelestite architecture coexists perfectly with nature.",
  str_homestory_808601001_14_dialog_content = "I often deal with the dead. I can feel it...",
  str_homestory_808601001_15_dialog_content = "This place has the beauty of the source of life.",
  str_homestory_808601001_16_dialog_content = "Anything alive and anyone that sings the praises of life will fall in love with Eraveil.",
  str_homestory_808601001_17_dialog_content = "PlayerName's home is truly beautiful.",
  str_homestory_808601001_18_dialog_content = "I'm so glad this is where you choose to settle.",
  str_homestory_808601001_19_dialog_content = "Thank you, Uriah.",
  str_homestory_808601001_20_dialog_content = "I'm thrilled by your high appraisal of Eraveil.",
  str_homestory_808601001_21_option_content = "Ask for a favor",
  str_homestory_808601001_22_dialog_content = "Actually... I have a favor to ask of you, if you don't mind.",
  str_homestory_808601001_23_dialog_content = "Heheh... PlayerName, don't be a stranger.",
  str_homestory_808601001_24_dialog_content = "It feels quite serious yet somewhat romantic...",
  str_homestory_808601001_25_dialog_content = "Is it more than a date? Are you proposing?",
  str_homestory_808601001_26_dialog_content = "Wh... What?!",
  str_homestory_808601001_27_dialog_content = "Not that!",
  str_homestory_808601001_28_dialog_content = "Heheheh... Adorable!",
  str_homestory_808601001_29_dialog_content = "Please don't make fun of me!",
  str_homestory_808601001_30_option_content = "Extend your welcome",
  str_homestory_808601001_31_dialog_content = "You're welcome to Eraveil anytime, Miss Uriah. I hope to see you more often.",
  str_homestory_808601001_32_dialog_content = "Sure.",
  str_homestory_808601001_33_dialog_content = "The beautiful scenery here is fascinating. Plus, this is your home.",
  str_homestory_808601001_34_dialog_content = "PlayerName, I look forward to its bright future under your leadership.",
  str_homestory_808601001_35_dialog_content = "Thank you... Uriah, you're a nun in charge of the prayer for the deceased so they can rest in peace, right?",
  str_homestory_808601001_36_dialog_content = "Yes, that is my responsibility in Lumopolis.",
  str_homestory_808601001_37_dialog_content = "... I think I know what you need.",
  str_homestory_808601001_38_dialog_content = "Yes. I want to pray for my deceased clansmen so they can rest easy.",
  str_homestory_808601001_39_dialog_content = "I figured...",
  str_homestory_808601001_40_dialog_content = "I'm impressed by how mature you've become. Now you're able to accept both life and death.",
  str_homestory_808601001_41_dialog_content = "I, Funeral Prayer, Uriah the nun, will pray for the spirits of Eraveil.",
  str_homestory_808601001_42_dialog_content = "May their souls rest in peace! May white blossoms carpet Eraveil.",
  str_homestory_808601001_43_dialog_content = "Thank you.",
  str_homestory_810201001_0_dialog_content = "This electric current...",
  str_homestory_810201001_1_dialog_content = "Tessa?",
  str_homestory_810201001_2_dialog_content = "If you're tired, get some rest in Cloud Gardens dorms.",
  str_homestory_810201001_3_dialog_content = "*Yawn*<sprite=emo_kun size=60 />",
  str_homestory_810201001_4_dialog_content = "Say what? Hey, you!",
  str_homestory_810201001_5_dialog_content = "Excuse me?",
  str_homestory_810201001_6_dialog_content = "Sigh... Do I have to take out this lollipop to make you understand?",
  str_homestory_810201001_7_dialog_content = "Hmm... I just don't want you to catch a cold sleeping outside.",
  str_homestory_810201001_8_dialog_content = "Is it a rule here to sleep inside?",
  str_homestory_810201001_9_dialog_content = "It's not mandatory...",
  str_homestory_810201001_10_dialog_content = "I don't really care even if it is.",
  str_homestory_810201001_11_dialog_content = "I sleep wherever I want.",
  str_homestory_810201001_12_option_content = "Agree",
  str_homestory_810201001_13_dialog_content = "Of course!",
  str_homestory_810201001_14_dialog_content = "I'm jealous of your lifestyle.",
  str_homestory_810201001_15_dialog_content = "I just need some peace. There's nothing to be jealous of.",
  str_homestory_810201001_16_option_content = "Unable to agree",
  str_homestory_810201001_17_dialog_content = "I understand where Tessa is from but...",
  str_homestory_810201001_18_dialog_content = "I just need some peace. Understanding is not needed.",
  str_homestory_810201001_19_dialog_content = "Fine...",
  str_homestory_810201001_20_dialog_content = "There are parasols and tents in the store. Let me know whenever you need one.",
  str_homestory_810201001_21_dialog_content = "I'm pretty good in the shade.",
  str_homestory_810201001_22_dialog_content = "By the way, does this shop carry lollipops?",
  str_homestory_810201001_23_dialog_content = "I'm running out.",
  str_homestory_810201001_24_dialog_content = "We do, but...",
  str_homestory_810201001_25_dialog_content = "Have you been inside a Cloud Gardens dorm?",
  str_homestory_810201001_26_dialog_content = "As I said, I'm not interested in staying indoors.",
  str_homestory_810201001_27_dialog_content = "What does this have to do with lollipops?",
  str_homestory_810201001_28_dialog_content = "To welcome Tessa...",
  str_homestory_810201001_29_dialog_content = "I've prepared a lot of lollipops in the dorm...",
  str_homestory_810201001_30_dialog_content = "Lollipops?",
  str_homestory_810201001_31_dialog_content = "I just checked. There's nothing left.",
  str_homestory_810201001_32_dialog_content = "I thought it was Tessa... I guess someone got it before you.",
  str_homestory_810201001_33_dialog_content = "Seriously? Why didn't you tell me earlier?",
  str_homestory_810201001_34_dialog_content = "I thought everyone would go to Cloud Gardens dorms for a rest first...",
  str_homestory_810201001_35_dialog_content = "Hmph! Whatever.",
  str_homestory_810201001_36_dialog_content = "I'll buy some more.",
  str_homestory_810201001_37_dialog_content = "(Tessa's surprisingly reasonable...)",
  str_homestory_810201001_38_dialog_content = "Is there any paid job available here?",
  str_homestory_810201001_39_dialog_content = "Hmm? I thought you were on a break... How come you are looking for a job now?",
  str_homestory_810201001_40_dialog_content = "I wanted to shop but I've got no money left.",
  str_homestory_810201001_41_dialog_content = "I'll have to buy on credit if there's nothing available.",
  str_homestory_810201001_42_dialog_content = "...",
  str_homestory_810201001_43_dialog_content = "Could you please inspect the electric circuit of Cloud Gardens dorms?",
  str_homestory_810201001_44_dialog_content = "Alright!",
  str_homestory_801501001_0_dialog_content = "That's a first...",
  str_homestory_801501001_1_dialog_content = "I've never seen you without Gin before.",
  str_homestory_801501001_2_dialog_content = "Ah! PlayerName, can you smell it?",
  str_homestory_801501001_3_dialog_content = "The fragrance of Nightium<sprite=emo_baiyebi size=60 />! It's everywhere!",
  str_homestory_801501001_4_option_content = "Express your doubts",
  str_homestory_801501001_5_dialog_content = "How come I can't smell it?",
  str_homestory_801501001_6_dialog_content = "What's the fragrance of Nightium anyway?",
  str_homestory_801501001_7_dialog_content = "PlayerName, this is an art of speech. The point is...",
  str_homestory_801501001_8_dialog_content = "I have a few projects to discuss with you. Any one of these is worth over 9 digits!",
  str_homestory_801501001_9_dialog_content = "9 digits?",
  str_homestory_801501001_10_option_content = "Ask about the smell",
  str_homestory_801501001_11_dialog_content = "How does Nightium smell like?",
  str_homestory_801501001_12_dialog_content = "30% rusty sweetness mixed with 40% salty sweat...",
  str_homestory_801501001_13_dialog_content = "Plus 50%... *Sniff*",
  str_homestory_801501001_14_dialog_content = "50% pure fragrance of fruit trees!",
  str_homestory_801501001_15_dialog_content = "That's 120%.",
  str_homestory_801501001_16_dialog_content = "Just as much as my sincerity to do business with PlayerName.",
  str_homestory_801501001_17_dialog_content = "Just to be clear. It's 120% not 12%.",
  str_homestory_801501001_18_dialog_content = "What have you got this time?",
  str_homestory_801501001_19_dialog_content = "Listen. My drawings are not for sale. And you can't borrow to make a copy...",
  str_homestory_801501001_20_dialog_content = "PlayerName, take a longer perspective.",
  str_homestory_801501001_21_dialog_content = "Now you have a natural exhibition hall. Don't be too attached to a few drawings.",
  str_homestory_801501001_22_dialog_content = "Exhibition hall?",
  str_homestory_801501001_23_dialog_content = "A perfect example of combining an open natural space with cultural ecology.",
  str_homestory_801501001_24_dialog_content = "This is an excellent natural Exhibition Hall.",
  str_homestory_801501001_25_dialog_content = "PlayerName, we love<sprite=emo_aixin size=60 /> this place so much.",
  str_homestory_801501001_26_dialog_content = "I've just made a difficult decision!",
  str_homestory_801501001_27_dialog_content = "I decide...",
  str_homestory_801501001_28_dialog_content = "I'll become an exhibition planner!",
  str_homestory_801501001_29_dialog_content = "What exactly does an exhibition planner do?",
  str_homestory_801501001_30_dialog_content = "Cough... In short, I'm responsible for evaluating, studying, preserving, and displaying all kinds of works of art...",
  str_homestory_801501001_31_dialog_content = "I'll be a professional manager who plans and organizes art exhibitions at specific venues.",
  str_homestory_801501001_32_dialog_content = "I'm lost but it sounds legit.",
  str_homestory_801501001_33_dialog_content = "So you agree?",
  str_homestory_801501001_34_dialog_content = "You don't need my permission to change your career.",
  str_homestory_801501001_35_dialog_content = "As long as you don't destroy our environment... I've worked hard to build this.",
  str_homestory_801501001_36_dialog_content = "Understood.",
  str_homestory_801501001_37_dialog_content = "PlayerName doesn't want me to change the architecture and plants here.",
  str_homestory_801501001_38_dialog_content = "That's right.",
  str_homestory_801501001_39_dialog_content = "PlayerName doesn't want me to design or organize artistic exhibitions and festivals.",
  str_homestory_801501001_40_dialog_content = "Correct.",
  str_homestory_801501001_41_dialog_content = "PlayerName also doesn't want my exhibitions and art festivals to attract any tourists.",
  str_homestory_801501001_42_dialog_content = "Yes...",
  str_homestory_801501001_43_dialog_content = "Neither is PlayerName interested in the significant revenue ensued.",
  str_homestory_801501001_44_dialog_content = "Hmm...",
  str_homestory_801501001_45_dialog_content = "PlayerName has no desire to improve his terrible financial standing.",
  str_homestory_801501001_46_dialog_content = "Ahem... Hang on a minute.",
  str_homestory_801501001_47_dialog_content = "I need to think about this more.",
  str_homestory_801501001_48_dialog_content = "Hahah. PlayerName finally smelt the fragrance of Nightium!",
  str_homestory_815401001_0_dialog_content = "Again?",
  str_homestory_815401001_1_dialog_content = "Vice, you've been spending a lot of time in the museum lately.",
  str_homestory_815401001_2_dialog_content = "Is there a way to make money there?",
  str_homestory_815401001_3_dialog_content = "Alas...",
  str_homestory_815401001_4_dialog_content = "Our financial position is not good but I thought we've reached an agreement?",
  str_homestory_815401001_5_dialog_content = "This museum is a public service site dedicated to showing the history of Eraveil and the technology of Caelestites.",
  str_homestory_815401001_6_dialog_content = "Free admission and non-profit...",
  str_homestory_815401001_7_option_content = "Apologize",
  str_homestory_815401001_8_dialog_content = "I'm sorry, Vice.",
  str_homestory_815401001_9_dialog_content = "I've been thinking about it these days. I guess I'm obsessed now.",
  str_homestory_815401001_10_dialog_content = "Hahahah. It's okay! I was once there myself.",
  str_homestory_815401001_11_dialog_content = "I think you need a break!",
  str_homestory_815401001_12_dialog_content = "Vice, tell that to yourself.",
  str_homestory_815401001_13_dialog_content = "You have almost moved to the museum these days. You look anxious and worried...",
  str_homestory_815401001_14_dialog_content = "How long haven't you rested properly?",
  str_homestory_815401001_15_option_content = "Concern",
  str_homestory_815401001_16_dialog_content = "Don't worry. I'll never change my stand on this!",
  str_homestory_815401001_17_dialog_content = "As the last Caelestite, I can't let our civilization end in my hands.",
  str_homestory_815401001_18_dialog_content = "But...",
  str_homestory_815401001_19_dialog_content = "What are you doing so thoughtfully in the museum?",
  str_homestory_815401001_20_dialog_content = "Alas... I can't hide anything from PlayerName.<sprite=emo_wuzui size=60 />",
  str_homestory_815401001_21_dialog_content = "Recently, I've been investigating the items on display in the museum.",
  str_homestory_815401001_22_dialog_content = "Investigate? A new quest assigned by Illumina?",
  str_homestory_815401001_23_dialog_content = "No, it's for myself.",
  str_homestory_815401001_24_dialog_content = "Maybe I shouldn't call it an investigation.",
  str_homestory_815401001_25_dialog_content = "I'm looking for inspiration.",
  str_homestory_815401001_26_dialog_content = "You know... After what happened to my body...",
  str_homestory_815401001_27_dialog_content = "I've recalled many fragments of memory.",
  str_homestory_815401001_28_dialog_content = "But it's completely blank when it comes to my origin...",
  str_homestory_815401001_29_dialog_content = "So... You are looking for leads to your background?",
  str_homestory_815401001_30_dialog_content = "Heheheh. Weird, right?",
  str_homestory_815401001_31_dialog_content = "I know. How could I find anything in a Caelestite museum?",
  str_homestory_815401001_32_dialog_content = "You never know.",
  str_homestory_815401001_33_dialog_content = "The world is big but coincidences occur every day.",
  str_homestory_815401001_34_dialog_content = "Hahahahah. You're so much more optimistic now.",
  str_homestory_815401001_35_dialog_content = "Shall we have another tour of the museum?",
  str_homestory_815401001_36_dialog_content = "We might find something this time, like a family letter or such?",
  str_homestory_815401001_37_dialog_content = "Sure!",
  str_homestory_815401001_38_dialog_content = "But what if I'm your elder sister...<sprite=emo_sikao size=60 />",
  str_homestory_815401001_39_dialog_content = "What would you do?",
  str_homestory_815401001_40_dialog_content = "My elder sister? No way!",
  str_homestory_815401001_41_dialog_content = "It's possible I'm your elder brother though!",
  str_homestory_815401001_42_dialog_content = "PlayerName...",
  str_homestory_815401001_43_dialog_content = "Hmm... I really can't see that.",
  str_homestory_815401001_44_dialog_content = "Ahem... I hope this is not the case!",
  str_homestory_805702001_0_dialog_content = "Is it raining?",
  str_homestory_805702001_1_dialog_content = "Meow...",
  str_homestory_805702001_2_dialog_content = "It's raining, Philyshy. We should get out of the rain.",
  str_homestory_805702001_3_dialog_content = "No, it was actually me shaking the water off myself.",
  str_homestory_805702001_4_dialog_content = "Sorry for getting it on you, PlayerName...",
  str_homestory_805702001_5_dialog_content = "I see. No wonder you were shaking your head every direction...",
  str_homestory_805702001_6_dialog_content = "Stop making fun of me, PlayerName...",
  str_homestory_805702001_7_dialog_content = "But if it didn't rain, how did you get wet?",
  str_homestory_805702001_8_dialog_content = "Meow... I blame it on the shiny dried fish in the river!<sprite=emo_shengqi size=60 />",
  str_homestory_805702001_9_option_content = "Shiny?",
  str_homestory_805702001_10_dialog_content = "How is that possible?",
  str_homestory_805702001_11_dialog_content = "I want to know, too. That's why I tried to catch it, meow.",
  str_homestory_805702001_12_option_content = "Shiny dried fish?",
  str_homestory_805702001_13_dialog_content = "Hold on, how can dried fish be in the river?",
  str_homestory_805702001_14_dialog_content = "It will be after I catch it and sun-dry it!",
  str_homestory_805702001_15_dialog_content = "Try as I may, I couldn't catch it and fell into the river.",
  str_homestory_805702001_16_dialog_content = "Achoo! The river is too cold, meow...",
  str_homestory_805702001_17_dialog_content = "You should get back to the house and get warm before you catch a cold.",
  str_homestory_805702001_18_dialog_content = "But...",
  str_homestory_805702001_19_dialog_content = "Hey, since you're the owner here, PlayerName...",
  str_homestory_805702001_20_dialog_content = "Catch that shiny dried fish for me!",
  str_homestory_805702001_21_dialog_content = "Huh?",
  str_homestory_805702001_22_dialog_content = "And remember... Sun-dry it... Zzz...<sprite=emo_kun size=60 />",
  str_homestory_805702001_23_dialog_content = "You're going to catch a cold sleeping out here... Philyshy?",
  str_homestory_805702001_24_dialog_content = "Zzz... Zzz... <sprite=emo_kun size=60 />Dried fish...",
  str_homestory_814101001_0_dialog_content = "How exciting...",
  str_homestory_814101001_1_dialog_content = "Hi, PlayerName, out exploring too?",
  str_homestory_814101001_2_option_content = "Yep.",
  str_homestory_814101001_3_dialog_content = "There are a lot of places to explore in my curated Cloud Gardens.",
  str_homestory_814101001_4_option_content = "No.",
  str_homestory_814101001_5_dialog_content = "I'm just getting some fresh air.",
  str_homestory_814101001_6_dialog_content = "It was through great effort that Cloud Gardens has become what it is today, so I like to hang out here when I can.",
  str_homestory_814101001_7_dialog_content = "You're absolutely right!",
  str_homestory_814101001_8_dialog_content = "This island you built is so thrilling. I love it!",
  str_homestory_814101001_9_dialog_content = "I was just poking around that river a while ago.",
  str_homestory_814101001_10_dialog_content = "Yeah? Found anything exciting?",
  str_homestory_814101001_11_dialog_content = "Haha! I knew you'd ask me that!",
  str_homestory_814101001_12_dialog_content = "As soon as I saw the river, I leaped right in!",
  str_homestory_814101001_13_dialog_content = "I parted the reeds and found a coin I'd never seen before at the bottom<sprite=emo_baiyebi size=60 />...",
  str_homestory_814101001_14_dialog_content = "Then I caught a big Betta Fish...",
  str_homestory_814101001_15_dialog_content = "A few strokes later, I saw a strange relic!",
  str_homestory_814101001_16_dialog_content = "So I just grabbed it and brought it to shore. Guess what it was!",
  str_homestory_814101001_17_dialog_content = "W-what was it?",
  str_homestory_814101001_18_dialog_content = "An old tattered shoe full of reeds!",
  str_homestory_814101001_19_dialog_content = "I tried to sell it to the store but it wouldn't even fetch one Nightium! I was so amused!",
  str_homestory_814101001_20_dialog_content = "What about the fish and the coin you found?",
  str_homestory_814101001_21_dialog_content = "Oh yeah... I recall putting them in my pocket...",
  str_homestory_814101001_22_dialog_content = "Hmm, they probably fell out when I reached for the shoe.",
  str_homestory_814101001_23_dialog_content = "We can go find it if you're interested!",
  str_homestory_814101001_24_dialog_content = "Though the fish has swum away by now, for sure.",
  str_homestory_814101001_25_dialog_content = "Ruby, such an eternal optimist.",
  str_homestory_814101001_26_dialog_content = "Oh, don't tell Rouge about it!",
  str_homestory_814101001_27_dialog_content = "Or she'll force some bitter fever medicine down my throat!",
  str_homestory_801001001_0_dialog_content = "Still asleep?",
  str_homestory_801001001_1_dialog_content = "Are you okay, Louise? You look sleepy.",
  str_homestory_801001001_2_dialog_content = "Oh, it's you, PlayerName.",
  str_homestory_801001001_3_dialog_content = "I thought my wait was finally over...",
  str_homestory_801001001_4_dialog_content = "You're waiting for someone?",
  str_homestory_801001001_5_dialog_content = "I'm waiting for the fae in the river.",
  str_homestory_801001001_6_dialog_content = "Fae?",
  str_homestory_801001001_7_dialog_content = "Haven't you heard of that very famous fairy tale, PlayerName?",
  str_homestory_801001001_8_dialog_content = "In a remote river lived a very beautiful fae.",
  str_homestory_801001001_9_dialog_content = "The fae would fly out when someone accidentally dropped something in the water.",
  str_homestory_801001001_10_dialog_content = "And those who answered the fae's question honestly would be rewarded!",
  str_homestory_801001001_11_option_content = "A remote river...",
  str_homestory_801001001_12_dialog_content = "You think there's a fae in this river, Louise?",
  str_homestory_801001001_13_dialog_content = "Uh, isn't there a fae in every river?",
  str_homestory_801001001_14_dialog_content = "In the river of Northland lived a Northland fae, so in the river of Eraveil would live an Eraveil fae...",
  str_homestory_801001001_15_option_content = "Fairy tale, you said...",
  str_homestory_801001001_16_dialog_content = "You know, I think I've heard something similar.",
  str_homestory_801001001_17_dialog_content = "Someone lost a steel axe but got greedy and claimed it was a gold axe.",
  str_homestory_801001001_18_dialog_content = "But the point here is...",
  str_homestory_801001001_19_dialog_content = "Did you lose something in the river?",
  str_homestory_801001001_20_dialog_content = "Yeah! But it's not mine.",
  str_homestory_801001001_21_dialog_content = "It's a coin I picked up by the bank with very intricate patterns.",
  str_homestory_801001001_22_dialog_content = "But it rolled into the water before I could get a good look.",
  str_homestory_801001001_23_dialog_content = "I've been waiting for a really long time but there is still no fae.",
  str_homestory_801001001_24_dialog_content = "I guess your river has no fae, PlayerName...<sprite=emo_sikao size=60 />",
  str_homestory_801001001_25_dialog_content = "Let me see if I can scoop it out.",
  str_homestory_801001001_26_dialog_content = "So you're the fae, PlayerName?!",
  str_homestory_804102001_0_dialog_content = "You're so earnest...",
  str_homestory_804102001_1_dialog_content = "Hi, Ms. Blanc.",
  str_homestory_804102001_2_dialog_content = "Hello, dear PlayerName.",
  str_homestory_804102001_3_dialog_content = "Are you still inspecting the roads and buildings in Cloud Gardens?",
  str_homestory_804102001_4_dialog_content = "I'm glad you still remember my usual routine.",
  str_homestory_804102001_5_option_content = "I think it's very professional.",
  str_homestory_804102001_6_dialog_content = "But...",
  str_homestory_804102001_7_option_content = "Sorry!",
  str_homestory_804102001_8_dialog_content = "Why did you apologise?",
  str_homestory_804102001_9_dialog_content = "I've been expanding Cloud Gardens, adding structures and roads.",
  str_homestory_804102001_10_dialog_content = "That won't make your job easier, will it?",
  str_homestory_804102001_11_dialog_content = "Never underestimate the abilities of a professional, PlayerName.",
  str_homestory_804102001_12_dialog_content = "As long as I can get the locations of the main buildings and roads in my head...",
  str_homestory_804102001_13_dialog_content = "I'll have no problem memorizing more.",
  str_homestory_804102001_14_dialog_content = "Such an incredible memory!",
  str_homestory_804102001_15_dialog_content = "But I saw you frowning. Is there a problem?",
  str_homestory_804102001_16_dialog_content = "Oops, you saw that, PlayerName?",
  str_homestory_804102001_17_dialog_content = "Well, something is indeed bothering me. I guess it's okay to tell you.",
  str_homestory_804102001_18_dialog_content = "I was writing the guide to Cloud Gardens...",
  str_homestory_804102001_19_dialog_content = "But when I got to the river here.",
  str_homestory_804102001_20_dialog_content = "On top of a variety of fish, I noticed something shiny.",
  str_homestory_804102001_21_dialog_content = "To ensure the accuracy of my description, I'd very much like to know what that is...",
  str_homestory_804102001_22_dialog_content = "Shiny object, you said...",
  str_homestory_804102001_23_dialog_content = "Since you're the owner of Cloud Gardens, would you mind looking into it?",
  str_homestory_804102001_24_dialog_content = "Sure, no problem!",
  str_homestory_801502001_0_dialog_content = "Sniffing around again?",
  str_homestory_801502001_1_dialog_content = "Ahem, what are you up to right now, Hachi?",
  str_homestory_801502001_2_dialog_content = "Hey, isn't it our dearest PlayerName!<sprite=emo_yaosu size=60 />",
  str_homestory_801502001_3_dialog_content = "So, have you made your decision?",
  str_homestory_801502001_4_dialog_content = "What decision?",
  str_homestory_801502001_5_dialog_content = "Oh, I understand. You got a lot of things on your plate!",
  str_homestory_801502001_6_dialog_content = "I'm referring to... remodeling Cloud Gardens into a natural exhibit.",
  str_homestory_801502001_7_option_content = "It's under consideration.",
  str_homestory_801502001_8_dialog_content = "Well, uh, I'm still thinking about it...",
  str_homestory_801502001_9_option_content = "Forget it.",
  str_homestory_801502001_10_dialog_content = "An admirable goal, but I like Cloud Gardens the way it is now, neat and quiet.",
  str_homestory_801502001_11_dialog_content = "Uh. All right.",
  str_homestory_801502001_12_dialog_content = "But you should reconsider. Opportunities wait for no one!",
  str_homestory_801502001_13_dialog_content = "Hmm...",
  str_homestory_801502001_14_dialog_content = "*Sniff sniff*",
  str_homestory_801502001_15_dialog_content = "What are you sniffing for?",
  str_homestory_801502001_16_dialog_content = "You can't smell it? It smells like a coin.",
  str_homestory_801502001_17_dialog_content = "Nightium <sprite=emo_baiyebi size=60 />again?",
  str_homestory_801502001_18_dialog_content = "No, totally different!",
  str_homestory_801502001_19_dialog_content = "It's brand new and indescribably unique... *Sniff*",
  str_homestory_801502001_20_dialog_content = "It's more gamy and humid than Nightium, more ancient too...",
  str_homestory_801502001_21_dialog_content = "And the patterns are more intricate.",
  str_homestory_801502001_22_dialog_content = "You can smell the patterns too?!",
  str_homestory_801502001_23_dialog_content = "Never underestimate the canine nose.",
  str_homestory_801502001_24_dialog_content = "Whether it's a business trend or the scent of a coin, I can point you in the right direction.",
  str_homestory_801502001_25_dialog_content = "This time, I'll allow you the chance to find the coin, dear PlayerName.",
  str_homestory_801502001_26_dialog_content = "Huh?",
  str_homestory_801502001_27_dialog_content = "Hope you'll think over our collaboration!",
  str_homestory_805602001_0_dialog_content = "Constantine?",
  str_homestory_805602001_1_dialog_content = "Hello, PlayerName.",
  str_homestory_805602001_2_dialog_content = "Where did you go this time, Constantine?",
  str_homestory_805602001_3_dialog_content = "I just got back from fishing.",
  str_homestory_805602001_4_dialog_content = "Ah, I see you've been doing that the last few days.",
  str_homestory_805602001_5_dialog_content = "You're a pro, so you probably caught a lot of fish, right?",
  str_homestory_805602001_6_dialog_content = "Not even one.",
  str_homestory_805602001_7_dialog_content = "What? But you're an expert hunter!",
  str_homestory_805602001_8_dialog_content = "You might consider fishing the same as hunting, but there's a big difference between the two.<sprite=emo_sikao size=60 />",
  str_homestory_805602001_9_dialog_content = "You actively subdue the prey when hunting.",
  str_homestory_805602001_10_dialog_content = "Whereas you take minimal initiative and instead make them come to you when fishing.",
  str_homestory_805602001_11_option_content = "Got it.",
  str_homestory_805602001_12_dialog_content = "When fishing, nobody has any idea what they'll catch.",
  str_homestory_805602001_13_dialog_content = "But when hunting, they find the target first, then act.",
  str_homestory_805602001_14_option_content = "No.",
  str_homestory_805602001_15_dialog_content = "But you said hunting requires patience. That's also necessary for fishing.",
  str_homestory_805602001_16_dialog_content = "Nobody has any idea when a fish will bite.",
  str_homestory_805602001_17_dialog_content = "Yes, you are correct.",
  str_homestory_805602001_18_dialog_content = "Frankly, I was against the rules at first...",
  str_homestory_805602001_19_dialog_content = "I'd always lock on a target first, then try to catch it, but that never worked out.",
  str_homestory_805602001_20_dialog_content = "To remind myself of the lesson learned, I flattened out the hook.",
  str_homestory_805602001_21_dialog_content = "What? You can catch fish like that?",
  str_homestory_805602001_22_dialog_content = "Don't know, don't care. I just want to hone my patience.",
  str_homestory_805602001_23_dialog_content = "Will you continue to fish like that?",
  str_homestory_805602001_24_dialog_content = "I've set a deadline for myself.",
  str_homestory_805602001_25_dialog_content = "When the coin by the bank is mired in mud or washed away... or someone scoops it up.",
  str_homestory_805602001_26_dialog_content = "Until then, I'll stick with the straight hook.",
  str_homestory_805602001_27_dialog_content = "(Coin...?)",
  str_homestory_805602001_28_dialog_content = "(I ought to see if I can fish that out.)",
  str_homestory_808502001_0_dialog_content = "Whoa, so fast...",
  str_homestory_808502001_1_dialog_content = "Are you recording in your journal, Jane?",
  str_homestory_808502001_2_dialog_content = "Yes, I'm recording everything I see in Cloud Gardens.",
  str_homestory_808502001_3_dialog_content = "If I hadn't known your occupation, I would've thought you were drawing.",
  str_homestory_808502001_4_dialog_content = "But I was drawing.",
  str_homestory_808502001_5_dialog_content = "Huh...?<sprite=emo_wuzui size=60 />",
  str_homestory_808502001_6_dialog_content = "You need more than text for descriptions. Illustrations are necessary too.",
  str_homestory_808502001_7_dialog_content = "When are illustrations necessary?",
  str_homestory_808502001_8_dialog_content = "It's quite straightforward. When words aren't enough to describe something, you use illustrations.",
  str_homestory_808502001_9_dialog_content = "For example, I was just describing everything I saw in the river.",
  str_homestory_808502001_10_dialog_content = "I could use words to describe the Redfin Perch, but the readers would just picture a vague image in their minds.",
  str_homestory_808502001_11_dialog_content = "But if I actually illustrate the shape and their color...",
  str_homestory_808502001_12_dialog_content = "They'll immediately get what the fish looks like.",
  str_homestory_808502001_13_dialog_content = "So that's it...",
  str_homestory_808502001_14_dialog_content = "Another example, when I wrote that \"A coin is still lying at the bottom of the river\"...",
  str_homestory_808502001_15_dialog_content = "Readers can only picture coins they've used before.",
  str_homestory_808502001_16_dialog_content = "So I'd have to draw the patterns of that coin that no one's seen before.",
  str_homestory_808502001_17_dialog_content = "It lets them know clearly what kind of coin was lying at the bottom of the river in Cloud Gardens.",
  str_homestory_808502001_18_dialog_content = "So, where is the coin now?",
  str_homestory_808502001_19_dialog_content = "Still in the river.",
  str_homestory_808502001_20_dialog_content = "What? Why didn't you scoop it out?",
  str_homestory_808502001_21_dialog_content = "I just record. I don't interfere.",
  str_homestory_808502001_22_dialog_content = "That also means I won't stop you from getting the coin yourself.",
  str_homestory_808502001_23_dialog_content = "But I will record it as it happens.",
  str_homestory_805502001_0_dialog_content = "In a bad mood?",
  str_homestory_805502001_1_dialog_content = "What happened, Pittman? You seem angry.",
  str_homestory_805502001_2_dialog_content = "Just in time, PlayerName. I was going to look for you!",
  str_homestory_805502001_3_dialog_content = "Uh, does it have anything to do with me?",
  str_homestory_805502001_4_dialog_content = "I'm not sure yet, but...",
  str_homestory_805502001_5_dialog_content = "White Night up high! As a Judge of Lumopolis, I hereby would like to open an inquiry...",
  str_homestory_805502001_6_dialog_content = "Are you minting Nightium here in Cloud Gardens?",
  str_homestory_805502001_7_option_content = "No!",
  str_homestory_805502001_8_dialog_content = "It's true I do need Nightium, but I'm not that desperate!",
  str_homestory_805502001_9_option_content = "I would like to.",
  str_homestory_805502001_10_dialog_content = "But it's expensive to mint Nightium. I would need a bunch of money to make money.",
  str_homestory_805502001_11_dialog_content = "You know I don't have that much!",
  str_homestory_805502001_12_dialog_content = "Do you swear?",
  str_homestory_805502001_13_dialog_content = "I, PlayerName, have never minted Nightium, ever.",
  str_homestory_805502001_14_dialog_content = "Or... you can do with me as you will!",
  str_homestory_805502001_15_dialog_content = "Then, have you noticed any suspects or signs related to such in Cloud Gardens?",
  str_homestory_805502001_16_dialog_content = "Particularly those from Umbraton and the desert?",
  str_homestory_805502001_17_dialog_content = "They're all my friends, so I really don't want to doubt them...",
  str_homestory_805502001_18_dialog_content = "Everyone is equal before the law, regardless of whom.",
  str_homestory_805502001_19_dialog_content = "But why do you suspect them?",
  str_homestory_805502001_20_dialog_content = "Since you swore your oath, I can divulge my secret.",
  str_homestory_805502001_21_dialog_content = "I found a coin by the river that resembled Nightium in make!",
  str_homestory_805502001_22_dialog_content = "Mind if I see it?",
  str_homestory_805502001_23_dialog_content = "I got so angry, I lost my grip on it and it fell into the river.",
  str_homestory_805502001_24_dialog_content = "It's just a guess... but I think that probably belonged to us Caelestites.",
  str_homestory_805502001_25_dialog_content = "Ah... R-really?",
  str_homestory_805502001_26_dialog_content = "Well, I didn't get a good look, after all...",
  str_homestory_805502001_27_dialog_content = "If that is indeed the truth, I must apologize for my rudeness.",
  str_homestory_805502001_28_dialog_content = "Sorry!",
  str_homestory_805502001_29_dialog_content = "It's okay, I'm not sure what exactly the origins of that coin are, either.",
  str_homestory_805502001_30_dialog_content = "I'll show it to you when I find it.",
  str_homestory_805502001_31_dialog_content = "Thank you very much, PlayerName!",
  str_homestory_815701001_0_dialog_content = "Sanae...",
  str_homestory_815701001_1_dialog_content = "Ahhhhhhhhhhh! Mr. Navigator...",
  str_homestory_815701001_2_dialog_content = "I was just admiring the flowers<sprite=emo_huaduo size=60 />!",
  str_homestory_815701001_3_dialog_content = "I definitely did not just fall nearby and ended up resting here...",
  str_homestory_815701001_4_dialog_content = "You fell? Are you hurt?",
  str_homestory_815701001_5_dialog_content = "I'm used to it... Ah, did I give myself away?",
  str_homestory_815701001_6_dialog_content = "Sanae... You're really easy to read.",
  str_homestory_815701001_7_dialog_content = "Please don't fire me for my clumsiness...",
  str_homestory_815701001_8_dialog_content = "That won't happen, but... what was on your mind?",
  str_homestory_815701001_9_dialog_content = "If you have any ideas regarding Cloud Gardens' development, please let me know!",
  str_homestory_815701001_10_dialog_content = "I don't... really...",
  str_homestory_815701001_11_dialog_content = "I wasn't wondering at all why you decided to grow flowers in this precise location!",
  str_homestory_815701001_12_dialog_content = "Well, that's not suspicious at all...",
  str_homestory_815701001_13_dialog_content = "Huh?",
  str_homestory_815701001_14_dialog_content = "Burying your longing here in the form of flowers in memory of your beloved...",
  str_homestory_815701001_15_dialog_content = "Oh, I wouldn't know anything about it...",
  str_homestory_815701001_16_option_content = "Beloved?",
  str_homestory_815701001_17_dialog_content = "Yes! Someone who met you by coincidence...",
  str_homestory_815701001_18_dialog_content = "Someone who broke through all worldly constraints and came to your side...",
  str_homestory_815701001_19_dialog_content = "Someone who offered advice on your journey on Astra...",
  str_homestory_815701001_20_dialog_content = "Oh, she must have been a very fine girl!",
  str_homestory_815701001_21_dialog_content = "The flowers in this garden must be her favorite, right?",
  str_homestory_815701001_22_option_content = "Burying my longing?",
  str_homestory_815701001_23_dialog_content = "Someone who left everything behind to come to you...",
  str_homestory_815701001_24_dialog_content = "Someone who looked over your shoulders on the journey...",
  str_homestory_815701001_25_dialog_content = "But now it is impossible for the two of you to reunite because of some worldly constraints.",
  str_homestory_815701001_26_dialog_content = "So, to show how much you miss her...",
  str_homestory_815701001_27_dialog_content = "You planted her favorite flowers in the garden!",
  str_homestory_815701001_28_dialog_content = "I have no idea what you're talking about...",
  str_homestory_815701001_29_dialog_content = "Is that so...<sprite=emo_sikao size=60 />!",
  str_homestory_815701001_30_dialog_content = "I should have known. This information cannot be easily disclosed to an outsider like me...",
  str_homestory_815701001_31_dialog_content = "If you're wondering why there are flowerbeds here...",
  str_homestory_815701001_32_dialog_content = "My answer would be that they are there as part of the landscape design.",
  str_homestory_815701001_33_dialog_content = "Landscape design? What a complicated term...",
  str_homestory_815701001_34_dialog_content = "Vice is very knowledgeable about engineering drawing, so she gave me a lot of advice when we designed Cloud Gardens.",
  str_homestory_815701001_35_dialog_content = "Gabriel, Nikinis, and Jola know a lot about plants...",
  str_homestory_815701001_36_dialog_content = "I've asked them for advice on what plants look good in gardens.",
  str_homestory_815701001_37_dialog_content = "It's a joint effort that Cloud Gardens looks the way it is today.",
  str_homestory_815701001_38_dialog_content = "Joint effort...",
  str_homestory_815701001_39_dialog_content = "Exactly! Also, don't consider yourself an \"outsider,\" Sanae.",
  str_homestory_815701001_40_dialog_content = "You've become one of us since the moment you arrived here!",
  str_homestory_815701001_41_dialog_content = "Aww... Aww...",
  str_homestory_815701001_42_dialog_content = "Ahh, please don't cry. I didn't mean to blame you...",
  str_homestory_815701001_43_dialog_content = "You're really a nice person, Mr. Navigator...",
  str_homestory_815701001_44_dialog_content = "I will also... make my contributions.",
  str_homestory_815701001_45_dialog_content = "Got an idea! Let me take care of this \"Flowerbed of Love<sprite=emo_aixin size=60 />\" from now on!",
  str_homestory_815601001_0_dialog_content = "I can't believe my eyes!",
  str_homestory_815601001_1_dialog_content = "Did Nina just ride a rocking horse?",
  str_homestory_815601001_2_dialog_content = "A rocking horse?",
  str_homestory_815601001_3_dialog_content = "I thought you hated those toys.",
  str_homestory_815601001_4_dialog_content = "I-I didn't say I liked it either...",
  str_homestory_815601001_5_dialog_content = "I was just tired of walking, and I needed a place to rest.",
  str_homestory_815601001_6_dialog_content = "I would never be interested in such a thing.",
  str_homestory_815601001_7_dialog_content = "Good point...",
  str_homestory_815601001_8_dialog_content = "Isn't the point supposed to be \"I was tired of walking and had no place to rest\"?",
  str_homestory_815601001_9_option_content = "Apologize",
  str_homestory_815601001_10_dialog_content = "Oh... I'm so sorry!",
  str_homestory_815601001_11_dialog_content = "Should I put a few more stone benches nearby?",
  str_homestory_815601001_12_dialog_content = "Stone bench? Hahaha, you must be joking, right?",
  str_homestory_815601001_13_dialog_content = "No one will really sit on something that hard, right?",
  str_homestory_815601001_14_dialog_content = "If it fancies you...",
  str_homestory_815601001_15_dialog_content = "Yours truly can design some beautiful and comfortable visitor seats for you.",
  str_homestory_815601001_16_dialog_content = "As long as you tell me what's so fun about that wooden stuff...",
  str_homestory_815601001_17_option_content = "Ask about her mood",
  str_homestory_815601001_18_dialog_content = "Looks like you've been to a lot of places today, Nina.",
  str_homestory_815601001_19_dialog_content = "I wonder if my place serves you all right, miss?",
  str_homestory_815601001_20_dialog_content = "Now that you asked, don't blame me for being harsh.",
  str_homestory_815601001_21_dialog_content = "This place is in the middle of nowhere!",
  str_homestory_815601001_22_dialog_content = "Can't argue with that...",
  str_homestory_815601001_23_dialog_content = "But the scenery here is really nice. I can add it to my vacation wishlist.",
  str_homestory_815601001_24_dialog_content = "You must know that my comments can influence a lot of people if they are ever published in the Umbraton newspaper.",
  str_homestory_815601001_25_dialog_content = "Provided that... you explain to me what's so interesting about that wooden stuff...",
  str_homestory_815601001_26_dialog_content = "I thought you are not interested in rocking horses.",
  str_homestory_815601001_27_dialog_content = "... I changed my mind.",
  str_homestory_815601001_28_dialog_content = "Knowing what everyone is into is part of my job.",
  str_homestory_815601001_29_dialog_content = "These unstable blocks of wood will obviously wobble when you try to sit on them.",
  str_homestory_815601001_30_dialog_content = "So you've never ridden a rocking horse?",
  str_homestory_815601001_31_dialog_content = "How is that possible?",
  str_homestory_815601001_32_dialog_content = "But... the whole experience of riding a rocking horse is this rocking sensation.",
  str_homestory_815601001_33_dialog_content = "Oh, I see... Don't get it wrong! I already knew that!",
  str_homestory_815601001_34_dialog_content = "It was just, just a test for you.",
  str_homestory_815601001_35_option_content = "Believe her",
  str_homestory_815601001_36_dialog_content = "Then I must have passed it...",
  str_homestory_815601001_37_dialog_content = "Yes! You are smarter than you look, PlayerName. Haha.",
  str_homestory_815601001_38_option_content = "Don't believe her",
  str_homestory_815601001_39_dialog_content = "I don't buy it.",
  str_homestory_815601001_40_dialog_content = "PlayerName is such a fool! Humph.",
  str_homestory_815601001_41_dialog_content = "...",
  str_homestory_815601001_42_dialog_content = "But...",
  str_homestory_815601001_43_dialog_content = "Why would anyone ride wooden horses instead of real ones?",
  str_homestory_815601001_44_dialog_content = "I don't know for sure...",
  str_homestory_815601001_45_dialog_content = "But rocking horses offer the fun of their own, and they are much safer...",
  str_homestory_815601001_46_dialog_content = "And I'm guessing not everyone gets to ride real horses.",
  str_homestory_815601001_47_dialog_content = "You mean... They can't afford the real ones?<sprite=emo_wuzui size=60 />",
  str_homestory_815601001_48_dialog_content = "I'm afraid some people can't even afford a rocking horse.",
  str_homestory_815601001_49_dialog_content = "...",
  str_homestory_815601001_50_dialog_content = "... I've made my decision!",
  str_homestory_815601001_51_dialog_content = "On what?",
  str_homestory_815601001_52_dialog_content = "I want to learn carpentry design and make more interesting rocking horses...",
  str_homestory_815601001_53_dialog_content = "And send them to children who need them!",
  str_homestory_810401001_0_dialog_content = "Dawn?",
  str_homestory_810401001_1_dialog_content = "These footsteps...",
  str_homestory_810401001_2_dialog_content = "Could it be PlayerName?",
  str_homestory_810401001_3_dialog_content = "Ah! You can recognize my footsteps?",
  str_homestory_810401001_4_dialog_content = "Yup!<sprite=emo_yaosu size=60 />",
  str_homestory_810401001_5_dialog_content = "There are so many more different sounds here than on the Colossus...",
  str_homestory_810401001_6_dialog_content = "But I can still pick out those made by familiar people.",
  str_homestory_810401001_7_dialog_content = "Like PlayerName and Eve. You guys have a special way of walking.",
  str_homestory_810401001_8_dialog_content = "A special way of walking...",
  str_homestory_810401001_9_option_content = "Ask about mine",
  str_homestory_810401001_10_dialog_content = "You're always in a rush but then become cautious when approaching me.",
  str_homestory_810401001_11_dialog_content = "I may not make it clear to you...",
  str_homestory_810401001_12_dialog_content = "Anyway, I just know this is you!",
  str_homestory_810401001_13_dialog_content = "Ah! One more thing...",
  str_homestory_810401001_14_dialog_content = "When you get close, I feel happy.",
  str_homestory_810401001_15_dialog_content = "This happy feeling also tells me that PlayerName is coming.",
  str_homestory_810401001_16_option_content = "Ask about Eve's",
  str_homestory_810401001_17_dialog_content = "Eve has very cute footsteps!",
  str_homestory_810401001_18_dialog_content = "... Cute... footsteps?",
  str_homestory_810401001_19_dialog_content = "Yes! Everything about Eve is cute<sprite=emo_aixin size=60 />.",
  str_homestory_810401001_20_dialog_content = "Err...",
  str_homestory_810401001_21_dialog_content = "Well, let me put it this way. Eve's physique is quite special...",
  str_homestory_810401001_22_dialog_content = "She barely makes any sound when she walks.",
  str_homestory_810401001_23_dialog_content = "But when Eve gets close, I feel happy.",
  str_homestory_810401001_24_dialog_content = "This happy feeling tells me that Eve is coming.",
  str_homestory_810401001_25_dialog_content = "So that's it...",
  str_homestory_810401001_26_dialog_content = "You're amazing!",
  str_homestory_810401001_27_dialog_content = "I guess because I can't see, my hearing has become very sharp.",
  str_homestory_810401001_28_dialog_content = "Ah! By the way...",
  str_homestory_810401001_29_dialog_content = "How about Sinsa?",
  str_homestory_810401001_30_dialog_content = "I believe you're familiar with him. What do Sinsa's footsteps sound like?",
  str_homestory_810401001_31_dialog_content = "Well, I have an easier way to recognize him.",
  str_homestory_810401001_32_dialog_content = "What is it?",
  str_homestory_810401001_33_dialog_content = "He's stinky.",
  str_homestory_810401001_34_dialog_content = "...?",
  str_homestory_810401001_35_dialog_content = "He's constantly moving... I think he sweats a lot.",
  str_homestory_810401001_36_dialog_content = "I see...",
  str_homestory_810401001_37_dialog_content = "He's definitely not the most smelly man in Rediesel Wrench...",
  str_homestory_810401001_38_dialog_content = "But he's certainly stinkier than you and Eve.",
  str_homestory_810401001_39_dialog_content = "I'm glad that you don't smell like him, Navigator.",
  str_homestory_810401001_40_dialog_content = "Err... Thanks...",
  str_homestory_810401001_41_dialog_content = "But why... Why can't I notice Sinsa's smell?",
  str_homestory_810401001_42_dialog_content = "Can't you?",
  str_homestory_810401001_43_dialog_content = "Am I so upset about Eve spending too much time with him...<sprite=emo_sikao size=60 />",
  str_homestory_810401001_44_dialog_content = "... that I've made up that odor?",
  str_homestory_810401001_45_dialog_content = "... That must be it!",
  str_homestory_810401001_46_dialog_content = "... Whatever! I'm positive he's very stinky.",
  str_homestory_810401001_47_dialog_content = "Stinky, stinky Sinsa<sprite=emo_kulou size=60 />!",
  str_homestory_809001001_0_dialog_content = "Barbara?",
  str_homestory_809001001_1_dialog_content = "Is love just a beautiful lie? ♪",
  str_homestory_809001001_2_dialog_content = "<sprite=emo_aixin size=60 />True love only emerges when the fuel burns off. ♪",
  str_homestory_809001001_3_dialog_content = "Whoa, whoa. The one and only love. ♪",
  str_homestory_809001001_4_dialog_content = "Are you practicing your new single?",
  str_homestory_809001001_5_dialog_content = "Heheh, new single? No!",
  str_homestory_809001001_6_dialog_content = "I'm getting ready for a new album!",
  str_homestory_809001001_7_option_content = "An album?",
  str_homestory_809001001_8_dialog_content = "Is an album a disc with many songs included?",
  str_homestory_809001001_9_dialog_content = "That's right.",
  str_homestory_809001001_10_option_content = "Better than Regina's?",
  str_homestory_809001001_11_dialog_content = "Uh-huh! Of course!",
  str_homestory_809001001_12_dialog_content = "I got to give it my absolute best for this album's sales!",
  str_homestory_809001001_13_dialog_content = "You're really hardworking.",
  str_homestory_809001001_14_dialog_content = "Certainly. After all, new music genres are popping up everywhere...",
  str_homestory_809001001_15_dialog_content = "I can't fall behind!",
  str_homestory_809001001_16_dialog_content = "Are you worried about losing popularity and support?",
  str_homestory_809001001_17_dialog_content = "Losing popularity and support? Never!",
  str_homestory_809001001_18_dialog_content = "I love to see different types of music and musicians bloom together.",
  str_homestory_809001001_19_dialog_content = "Then what do you mean by \"can't fall behind\"?",
  str_homestory_809001001_20_dialog_content = "That just means I must work harder<sprite=emo_yinfu size=60 />.",
  str_homestory_809001001_21_dialog_content = "I need to make progress together with new artists and bring more awesome music to everyone!",
  str_homestory_809001001_22_dialog_content = "I hate to fall behind!",
  str_homestory_809001001_23_dialog_content = "That's inspiring!",
  str_homestory_809001001_24_dialog_content = "Hmm... I'm not too worried about my popularity.",
  str_homestory_809001001_25_dialog_content = "But if the fans I know well left me for other singers...",
  str_homestory_809001001_26_dialog_content = "I would still feel a bit frustrated!",
  str_homestory_809001001_27_dialog_content = "Other singers... Are you talking about Regina?",
  str_homestory_809001001_28_dialog_content = "PlayerName... That's very blunt of you!",
  str_homestory_809001001_29_dialog_content = "You do care about Regina's music, don't you?",
  str_homestory_809001001_30_dialog_content = "How should I put it?",
  str_homestory_809001001_31_dialog_content = "It would be a lie if I say I don't care at all<sprite=emo_tanqi size=60 />...",
  str_homestory_809001001_32_dialog_content = "Er... It's safe to say that...",
  str_homestory_809001001_33_dialog_content = "I'm listening to her music to promote diversity.",
  str_homestory_809001001_34_dialog_content = "Hmm... She might not have as many fans as me, but her supporters are very loyal.",
  str_homestory_809001001_35_dialog_content = "Musicians speak with the quality of their songs, but I'm quite curious...",
  str_homestory_809001001_36_dialog_content = "How is she keeping her fans around?",
  str_homestory_809001001_37_dialog_content = "Why not just ask Regina if you really want to know?",
  str_homestory_809001001_38_dialog_content = "Hmm...",
  str_homestory_809001001_39_dialog_content = "I guess I will heed your advise, PlayerName...",
  str_homestory_809001001_40_dialog_content = "Asking her a question is no big deal!",
  str_homestory_809001001_41_dialog_content = "Hmm... In at least 20 years<sprite=emo_emo size=60 />!",
  str_homestory_809001001_42_dialog_content = "... Better just say you will never ask her!",
  str_homestory_807001001_0_dialog_content = "Leona...",
  str_homestory_807001001_1_dialog_content = "Hey, kiddo.",
  str_homestory_807001001_2_dialog_content = "What's up?",
  str_homestory_807001001_3_dialog_content = "Sorry, I don't really have time right now.",
  str_homestory_807001001_4_dialog_content = "As you can see, I'm busy relieving my negative emotions.",
  str_homestory_807001001_5_dialog_content = "Ah! I didn't know punching sandbags is something that can help.",
  str_homestory_807001001_6_dialog_content = "Very effectively<sprite=emo_baiyan size=60 />.",
  str_homestory_807001001_7_dialog_content = "You never heard?",
  str_homestory_807001001_8_dialog_content = "Exercising is a good way to combat negative emotions.",
  str_homestory_807001001_9_dialog_content = "I did hear that before.",
  str_homestory_807001001_10_dialog_content = "Speaking of your negative emotions...",
  str_homestory_807001001_11_option_content = "What is the cause?",
  str_homestory_807001001_12_dialog_content = "No specific cause.",
  str_homestory_807001001_13_option_content = "Do you feel better now?",
  str_homestory_807001001_14_dialog_content = "Yeah, more or less.",
  str_homestory_807001001_15_dialog_content = "You can see negative emotions as a knot inside your body.",
  str_homestory_807001001_16_dialog_content = "A knot? Like a knot on a rope?",
  str_homestory_807001001_17_dialog_content = "Kind of.",
  str_homestory_807001001_18_dialog_content = "Once you notice you're in a bad mood...",
  str_homestory_807001001_19_dialog_content = "You need to do something you like to get yourself out of it.",
  str_homestory_807001001_20_dialog_content = "Anything that relaxes you would do.",
  str_homestory_807001001_21_dialog_content = "For me, this is the best way to relax. It makes me feel like I'm in a battle.",
  str_homestory_807001001_22_dialog_content = "When negative feelings take root in your heart, this knot gets more and more difficult to untie.",
  str_homestory_807001001_23_dialog_content = "It can even become a threat to your health.",
  str_homestory_807001001_24_dialog_content = "It took me a long time to learn this.",
  str_homestory_807001001_25_dialog_content = "When your heart is blinded by hatred...",
  str_homestory_807001001_26_dialog_content = "... Sorry. I digress...",
  str_homestory_807001001_27_dialog_content = "Huh... you are absolutely right.",
  str_homestory_807001001_28_dialog_content = "Give it a try next time.",
  str_homestory_807001001_29_dialog_content = "No problem!",
  str_homestory_807001001_30_dialog_content = "Maybe Sharona was here punching sandbags for the same reason last time.",
  str_homestory_807001001_31_dialog_content = "You mean Sharona?",
  str_homestory_807001001_32_dialog_content = "Sharona had punched this sandbag?",
  str_homestory_807001001_33_dialog_content = "Ah? Just kidding!",
  str_homestory_807001001_34_dialog_content = "(Ah oh... I probably should not have said that...)",
  str_homestory_807001001_35_dialog_content = "...",
  str_homestory_807001001_36_dialog_content = "Leona, what's the matter?",
  str_homestory_807001001_37_dialog_content = "Heheh. I'm doing the same thing as my dear sister again.",
  str_homestory_807001001_38_dialog_content = "To not burn this place <sprite=emo_nuhuo size=60 />down...",
  str_homestory_807001001_39_dialog_content = "I should probably leave for Umbraton right away.",
  str_homestory_807001001_40_dialog_content = "Bye, kiddo.",
  str_homestory_807001001_41_dialog_content = "U-Um...",
  str_homestory_807001001_42_dialog_content = "See you soon...",
  str_homestory_811501001_0_dialog_content = "Naroxel!",
  str_homestory_811501001_1_dialog_content = "Dear PlayerName.",
  str_homestory_811501001_2_dialog_content = "It must be the force of nature that has guided us here once again.",
  str_homestory_811501001_3_dialog_content = "Are you having a conversation with Olive and Palm?",
  str_homestory_811501001_4_dialog_content = "Yea!",
  str_homestory_811501001_5_dialog_content = "I'm amazed that you still remember their names.",
  str_homestory_811501001_6_dialog_content = "They're very happy.",
  str_homestory_811501001_7_dialog_content = "It's nothing...",
  str_homestory_811501001_8_dialog_content = "I'm filled with emotions watching the Eraveil rise again<sprite=emo_pugongying size=60 />.",
  str_homestory_811501001_9_dialog_content = "Cloud Gardens is really prosperous and beautiful now.",
  str_homestory_811501001_10_dialog_content = "Thanks to nature's blessing and your hard work, PlayerName.",
  str_homestory_811501001_11_dialog_content = "However... I'm a little concerned about you.",
  str_homestory_811501001_12_dialog_content = "Are you okay after what has happened lately?",
  str_homestory_811501001_13_option_content = "Nod",
  str_homestory_811501001_14_dialog_content = "I'm happy to share this place with all of you.",
  str_homestory_811501001_15_dialog_content = "But sometimes I feel stressed because of high expectations.",
  str_homestory_811501001_16_option_content = "Shake the head",
  str_homestory_811501001_17_dialog_content = "I'm not in a bad mood...",
  str_homestory_811501001_18_dialog_content = "But I do feel anxious and stressed.",
  str_homestory_811501001_19_dialog_content = "Understood.",
  str_homestory_811501001_20_dialog_content = "Would you like to relax a little with me?",
  str_homestory_811501001_21_dialog_content = "Okay.",
  str_homestory_811501001_22_dialog_content = "Let's try this breathing exercise.",
  str_homestory_811501001_23_dialog_content = "Breathing exercise?",
  str_homestory_811501001_24_dialog_content = "Yes.",
  str_homestory_811501001_25_dialog_content = "This will help you balance the energy inside your body.",
  str_homestory_811501001_26_dialog_content = "To put it simple...",
  str_homestory_811501001_27_dialog_content = "It keeps our inner energy flowing.",
  str_homestory_811501001_28_dialog_content = "Understood! Shall we begin?",
  str_homestory_811501001_29_dialog_content = "Sure.",
  str_homestory_811501001_30_dialog_content = "Relax your shoulders. Take a deep breath.",
  str_homestory_811501001_31_dialog_content = "Very good. Now... hold your nose.",
  str_homestory_811501001_32_dialog_content = "(Hold the nose... Hmm...)",
  str_homestory_811501001_33_dialog_content = "Press the right wing of the nose and inhale through the left nostril.",
  str_homestory_811501001_34_dialog_content = "Then press the left wing of the nose and exhale through the right nostril...",
  str_homestory_811501001_35_dialog_content = "(Inhale... Exhale...)",
  str_homestory_811501001_36_dialog_content = "Just like that. Slowly adjust your breathing.",
  str_homestory_811501001_37_dialog_content = "Inhale and exhale in balance...",
  str_homestory_811501001_38_dialog_content = "Soon we will feel our body and mind relaxed through this breathing exercise.",
  str_homestory_811501001_39_dialog_content = "Yes... I feel very calm now.",
  str_homestory_811501001_40_dialog_content = "I'm actually a little sleepy<sprite=emo_kun size=60 />...",
  str_homestory_811501001_41_dialog_content = "Heheh.",
  str_homestory_811501001_42_dialog_content = "This breathing exercise can bring us a release and a good sleep.",
  str_homestory_811501001_43_dialog_content = "Feel free to try it again before bed.",
  str_homestory_811501001_44_dialog_content = "You might feel even better if your eyes are closed during this exercise.",
  str_homestory_811501001_45_dialog_content = "Hmm. I'll try to remember that.",
  str_homestory_811501001_46_dialog_content = "Thank you, Naroxel!",
  str_homestory_803302001_0_dialog_content = "Hello, Vice.",
  str_homestory_803302001_1_dialog_content = "PlayerName! Are you free at the moment?",
  str_homestory_803302001_2_dialog_content = "Sure. What do you need?",
  str_homestory_803302001_3_dialog_content = "As I was walking along the riverbank, I noticed something in the water.",
  str_homestory_803302001_4_dialog_content = "I tried to grab it, but failed. It looked like some sort of blueprint.",
  str_homestory_803302001_5_dialog_content = "If you want, you can go check it out.",
  str_homestory_803302001_6_dialog_content = "Sure, no problem.",
  str_homestory_803303001_0_dialog_content = "What are you doing?",
  str_homestory_803303001_1_dialog_content = "I'm thinking about how I can fish that thing out of there...",
  str_homestory_803303001_2_dialog_content = "What is it?",
  str_homestory_803303001_3_dialog_content = "There's something peculiar in the river that piqued my curiosity<sprite=emo_sikao size=60 />.",
  str_homestory_803303001_4_dialog_content = "But I can't get it no matter how I try... and my hands are sore now.",
  str_homestory_803303001_5_dialog_content = "Can you help me out? It's over there.",
  str_homestory_803303001_6_dialog_content = "Okay, I'll give it a go.",
  str_homestory_803304001_0_dialog_content = "Looking for me?",
  str_homestory_803304001_1_dialog_content = "Hey, how did you know I was looking for you?",
  str_homestory_803304001_2_dialog_content = "I found something interesting!<sprite=emo_yaosu size=60 />",
  str_homestory_803304001_3_dialog_content = "Not another giant spider or dancing cricket, right?",
  str_homestory_803304001_4_dialog_content = "No, it's a blueprint for new furniture!",
  str_homestory_803304001_5_dialog_content = "But it's underwater and hard to dredge up.",
  str_homestory_803304001_6_dialog_content = "Well, leave it to me. I'm good at stuff like that.",
  str_homestory_803304001_7_dialog_content = "It's over there! Let me show you!",
  str_homestory_809301001_0_dialog_content = "That look in your eyes...",
  str_homestory_809301001_1_dialog_content = "Can I, uh, help you?",
  str_homestory_809301001_2_dialog_content = "You've grown since we last met. You knew I wanted something from you.",
  str_homestory_809301001_3_dialog_content = "I just felt the hair stand up on my back like I'm being watched...",
  str_homestory_809301001_4_dialog_content = "I looked up and found you staring at me.",
  str_homestory_809301001_5_dialog_content = "\"Looked up\"? I guess you haven't grown as much as I'd thought.",
  str_homestory_809301001_6_option_content = "I grew taller!",
  str_homestory_809301001_7_dialog_content = "Yeah? How come I couldn't tell? Want to go to my lab?",
  str_homestory_809301001_8_dialog_content = "I can cut you open to see if your bones grew.",
  str_homestory_809301001_9_option_content = "Right...",
  str_homestory_809301001_10_dialog_content = "Give up already? I should help you. Want to go to my lab?",
  str_homestory_809301001_11_dialog_content = "I can open you up and see if your bones can still grow.",
  str_homestory_809301001_12_dialog_content = "U-Um, that won't be necessary...",
  str_homestory_809301001_13_dialog_content = "Don't worry. After my dissection, I will make you a plan to grow taller.",
  str_homestory_809301001_14_dialog_content = "It's okay. Let's just leave it to nature for now.",
  str_homestory_809301001_15_dialog_content = "Nature? Are you kidding?",
  str_homestory_809301001_16_dialog_content = "I can tell many of the trees in Cloud Gardens have been genetically modified.",
  str_homestory_809301001_17_dialog_content = "And this was accomplished by...",
  str_homestory_809301001_18_dialog_content = "Splicing the seeds of different plants into new, unique varieties.",
  str_homestory_809301001_19_dialog_content = "You could tell that just by looking?",
  str_homestory_809301001_20_dialog_content = "Have you forgotten I'm a Tech Officer from Illumina who specializes in biotech?",
  str_homestory_809301001_21_dialog_content = "I've done more bioengineering experiments like this than I can count.",
  str_homestory_809301001_22_dialog_content = "But I didn't expect you to have a knack for this kind of tech.",
  str_homestory_809301001_23_dialog_content = "I was just messing around, so it's nothing special.",
  str_homestory_809301001_24_dialog_content = "Yeah, I can tell.",
  str_homestory_809301001_25_dialog_content = "...",
  str_homestory_809301001_26_dialog_content = "You can't experience success without failing 99 times.",
  str_homestory_809301001_27_dialog_content = "That's what I realized from all my hard work. As for you...",
  str_homestory_809301001_28_dialog_content = "To get an ultra-rare seed, you need to do this-and-that.",
  str_homestory_809301001_29_dialog_content = "\"This-and-that\"? What do you mean?",
  str_homestory_809301001_30_dialog_content = "I doubt you can understand when you lack a scientific background. We'll talk about it some other time.",
  str_homestory_809301001_31_dialog_content = "Well, we can do it now.",
  str_homestory_809301001_32_dialog_content = "Now? Let me grab some shut-eye first.",
  str_homestory_809301001_33_dialog_content = "...",
  str_homestory_809301001_34_dialog_content = "Oh, wait, I almost forgot what I wanted to ask you.",
  str_homestory_809301001_35_dialog_content = "Can you switch my room to a dorm with more pretty girls?",
  str_homestory_809301001_36_option_content = "Agree",
  str_homestory_809301001_37_dialog_content = "I can, but you should discuss it with everyone first.",
  str_homestory_809301001_38_option_content = "Reject",
  str_homestory_809301001_39_dialog_content = "I don't get involved in living arrangements here.",
  str_homestory_809301001_40_dialog_content = "But it's fine if you can work it out with everyone yourself.",
  str_homestory_809301001_41_dialog_content = "That sounds complicated.",
  str_homestory_809301001_42_dialog_content = "Though it's worth a try. If not, 100 tries.",
  str_homestory_809301001_43_dialog_content = "(She's sticking with that attitude for this, too?)",
  str_homestory_815702001_0_dialog_content = "What are you looking at?",
  str_homestory_815702001_1_dialog_content = "Ahhhhhhhhhhh!",
  str_homestory_815702001_2_dialog_content = "Sorry, did I startle you again?",
  str_homestory_815702001_3_dialog_content = "(But why did I say, \"again\"?)",
  str_homestory_815702001_4_dialog_content = "No, I was just lost in thought...",
  str_homestory_815702001_5_dialog_content = "So I didn't see you here.",
  str_homestory_815702001_6_dialog_content = "I should be the one apologizing.",
  str_homestory_815702001_7_dialog_content = "Everything's fine, so don't sweat it.",
  str_homestory_815702001_8_dialog_content = "You just came from the river, right? Were you thinking about...",
  str_homestory_815702001_9_option_content = "Fishing?",
  str_homestory_815702001_10_dialog_content = "Fishing... must require lots of expensive gear, right?",
  str_homestory_815702001_11_dialog_content = "I-I would never be so impudent...",
  str_homestory_815702001_12_option_content = "Swimming?",
  str_homestory_815702001_13_dialog_content = "Swimming... Don't you have to wear a skintight suit for that?",
  str_homestory_815702001_14_dialog_content = "I-I'm too shy for that.",
  str_homestory_815702001_15_dialog_content = "Actually, I was pondering...",
  str_homestory_815702001_16_dialog_content = "Did the farmers of past in Eraveil labor as hard as those in Cloud Island?",
  str_homestory_815702001_17_dialog_content = "I'm not sure, either, but I think that regardless of region...",
  str_homestory_815702001_18_dialog_content = "All farmers are ecstatic when there's a bountiful harvest.",
  str_homestory_815702001_19_dialog_content = "So, what brought that up?",
  str_homestory_815702001_20_dialog_content = "Well, I just found a shiny object at the riverside that looked like a coin<sprite=emo_baiyebi size=60 />.",
  str_homestory_815702001_21_dialog_content = "Coins mean trade, trade means food, and where there's food... there's farmers!",
  str_homestory_815702001_22_dialog_content = "That's... an interesting thought process...",
  str_homestory_815702001_23_dialog_content = "Oh, please don't be upset!",
  str_homestory_815702001_24_dialog_content = "I never intended to keep the coin for myself.",
  str_homestory_815702001_25_dialog_content = "I'll give it to you right now...",
  str_homestory_815702001_26_dialog_content = "It's okay, take it easy.",
  str_homestory_815702001_27_dialog_content = "Where did I put it again?",
  str_homestory_815702001_28_dialog_content = "It's gone...",
  str_homestory_815702001_29_dialog_content = "Ah!",
  str_homestory_815702001_30_dialog_content = "What's is it?",
  str_homestory_815702001_31_dialog_content = "I remember hearing a splash when I left the riverbank earlier.",
  str_homestory_815702001_32_dialog_content = "I must've accidentally dropped it into the water!",
  str_homestory_815702001_33_dialog_content = "It's all right. I'll fish it up.",
  str_homestory_815702001_34_dialog_content = "Oh, will you? R-Really? Thank you!",
  str_homestory_815602001_0_dialog_content = "What are you looking for?",
  str_homestory_815602001_1_dialog_content = "Hey, get over here!",
  str_homestory_815602001_2_dialog_content = "Nina?",
  str_homestory_815602001_3_dialog_content = "If I'm not wrong, you were looking for something.",
  str_homestory_815602001_4_dialog_content = "Yep.",
  str_homestory_815602001_5_dialog_content = "Have you seen a round little thing?",
  str_homestory_815602001_6_dialog_content = "Can you be more precise?",
  str_homestory_815602001_7_dialog_content = "Well... Here's the thing.",
  str_homestory_815602001_8_dialog_content = "I'd never seen something with a pattern like that...",
  str_homestory_815602001_9_dialog_content = "That's why I clenched it tightly in my hand!",
  str_homestory_815602001_10_dialog_content = "But... it slipped out of my hand and into the water when I loosened my grip...",
  str_homestory_815602001_11_dialog_content = "Wait, why do I feel like you're talking about—",
  str_homestory_815602001_12_dialog_content = "Hold on, let me finish.",
  str_homestory_815602001_13_dialog_content = "Then I discovered a strange pattern on the palm of my hand!",
  str_homestory_815602001_14_option_content = "Mutated Lumina?!",
  str_homestory_815602001_15_dialog_content = "Have you been reading too many fantasy novels?",
  str_homestory_815602001_16_option_content = "Are you gonna transform?!",
  str_homestory_815602001_17_dialog_content = "What in the world are you talking about?",
  str_homestory_815602001_18_dialog_content = "It's because that object had a unique shape and pattern!",
  str_homestory_815602001_19_dialog_content = "When I held it in my palm, it got imprinted onto my skin.",
  str_homestory_815602001_20_dialog_content = "This pattern is somewhat aesthetically pleasing...",
  str_homestory_815602001_21_dialog_content = "Think about it, if I were to design a piece of clothing based on this pattern...",
  str_homestory_815602001_22_dialog_content = "I need to find that coin!",
  str_homestory_815602001_23_dialog_content = "I knew it was a coin!",
  str_homestory_815602001_24_dialog_content = "I'll help.",
  str_homestory_815602001_25_dialog_content = "T-Thanks—Hey, wait!<sprite=emo_wuzui size=60 />",
  str_homestory_815602001_26_dialog_content = "Since I found the coin in Cloud Gardens... it technically belongs to you, right?",
  str_homestory_815602001_27_dialog_content = "So, if I were to borrow it from you and study it...",
  str_homestory_815602001_28_dialog_content = "Not a problem. But we'll need to find it first.",
  str_homestory_815602001_29_dialog_content = "I'm surprised you agreed to it so quickly.",
  str_homestory_815602001_30_dialog_content = "Ahem... It's not like I really WANT to study it...",
  str_homestory_815602001_31_dialog_content = "It's just an inspiration for clothing design, you know!",
  str_homestory_815602001_32_dialog_content = "You do know, right?",
  str_homestory_815602001_33_dialog_content = "I know.",
  str_homestory_815602001_34_dialog_content = "Tsk, that's good.",
  str_homestory_812601001_0_dialog_content = "What are you thinking about?",
  str_homestory_812601001_1_dialog_content = "Bethel?",
  str_homestory_812601001_2_dialog_content = "You look like you're thinking hard about something...",
  str_homestory_812601001_3_dialog_content = "Hush...<sprite=emo_chidai size=60 />",
  str_homestory_812601001_4_dialog_content = "I just dealt with all those Guild statements. I'm in the middle of doing some pondering.",
  str_homestory_812601001_5_dialog_content = "About what?",
  str_homestory_812601001_6_dialog_content = "My latest work of fiction!",
  str_homestory_812601001_7_dialog_content = "Maybe I should run it through with you.",
  str_homestory_812601001_8_dialog_content = "Sure, if I can be of help.",
  str_homestory_812601001_9_dialog_content = "Alright... Listen up. This is how the story goes...",
  str_homestory_812601001_10_dialog_content = "The male and female leads come to a river...",
  str_homestory_812601001_11_dialog_content = "And suddenly, the female lead's handkerchief falls into the water!",
  str_homestory_812601001_12_dialog_content = "So here's the question: Should the female lead retrieve it, or should the male lead?",
  str_homestory_812601001_13_option_content = "The female lead",
  str_homestory_812601001_14_dialog_content = "Hmm...",
  str_homestory_812601001_15_dialog_content = "Sure, that'll show her to be a very independent and capable woman.",
  str_homestory_812601001_16_option_content = "The male lead",
  str_homestory_812601001_17_dialog_content = "Hmm...",
  str_homestory_812601001_18_dialog_content = "That'll really drive the story forward, and they can start talking about the handkerchief!",
  str_homestory_812601001_19_dialog_content = "Alright. I got it!",
  str_homestory_812601001_20_dialog_content = "That's how I'm gonna write it!<sprite=emo_yaosu size=60 />",
  str_homestory_812601001_21_dialog_content = "What made you conceive a plot like that?",
  str_homestory_812601001_22_dialog_content = "Because I saw something fall into the water just now.",
  str_homestory_812601001_23_dialog_content = "It got me thinking that it be a good premise...",
  str_homestory_812601001_24_dialog_content = "Wait, what? What fell into the water?",
  str_homestory_812601001_25_dialog_content = "I didn't catch a good look. It was something small and round.<sprite=emo_sikao size=60 />",
  str_homestory_812601001_26_dialog_content = "Small and round...",
  str_homestory_812601001_27_dialog_content = "I know what that is.",
  str_homestory_816401001_0_dialog_content = "Carleen?",
  str_homestory_816401001_1_dialog_content = "PlayerName?",
  str_homestory_816401001_2_dialog_content = "What are you up to, Carleen?",
  str_homestory_816401001_3_dialog_content = "I'm... thinking.",
  str_homestory_816401001_4_dialog_content = "Is everything alright? You look kind of... down.",
  str_homestory_816401001_5_dialog_content = "Down? Well...",
  str_homestory_816401001_6_dialog_content = "Because Lumopolis was hit by several natural disasters recently.",
  str_homestory_816401001_7_dialog_content = "I'm sorry to hear that...",
  str_homestory_816401001_8_dialog_content = "How is the city now? Is there anything I can do to help?",
  str_homestory_816401001_9_dialog_content = "Thank you for asking, PlayerName.",
  str_homestory_816401001_10_dialog_content = "The casualty count and the asset losses are being handled officially.",
  str_homestory_816401001_11_dialog_content = "Other than returning the bodies of the dead to their families...",
  str_homestory_816401001_12_dialog_content = "I don't really know what else we can do to ease their pain.",
  str_homestory_816401001_13_dialog_content = "I know how you must feel, Carleen.",
  str_homestory_816401001_14_dialog_content = "Phew... <sprite=emo_tanqi size=60 />",
  str_homestory_816401001_15_dialog_content = "My mind feels a lot clearer now that I've told you what was bothering me.",
  str_homestory_816401001_16_dialog_content = "Are you thinking about how to avoid these disasters going forward?",
  str_homestory_816401001_17_dialog_content = "No.",
  str_homestory_816401001_18_dialog_content = "In the face of natural disasters, we are but ants.",
  str_homestory_816401001_19_dialog_content = "I'm just praying on my own, and to reaffirm something to myself...",
  str_homestory_816401001_20_option_content = "Your faith?",
  str_homestory_816401001_21_dialog_content = "Well...",
  str_homestory_816401001_22_option_content = "The effectiveness of prayers?",
  str_homestory_816401001_23_dialog_content = "How should I put this?",
  str_homestory_816401001_24_dialog_content = "I just want to confirm that prayers are still able to provide the solace that I desperately need.",
  str_homestory_816401001_25_dialog_content = "I see...",
  str_homestory_816401001_26_dialog_content = "We often fear the unpredictable things we can't control.",
  str_homestory_816401001_27_dialog_content = "But there is nothing we can do other than to watch them unfold.",
  str_homestory_816401001_28_dialog_content = "And that's why you feel helpless, right?",
  str_homestory_816401001_29_dialog_content = "Correct.",
  str_homestory_816401001_30_dialog_content = "I pray whenever I feel defeated.",
  str_homestory_816401001_31_dialog_content = "And I also wonder what it is that prayers actually give me.",
  str_homestory_816401001_32_dialog_content = "And after lots of thinking, I've concluded that it's spiritual support, and...",
  str_homestory_816401001_33_dialog_content = "The motivation to keep going.",
  str_homestory_816401001_34_dialog_content = "Indeed.",
  str_homestory_816401001_35_dialog_content = "I'm sure your prayers will help you through these rough times.",
  str_homestory_816401001_36_dialog_content = "And I finally understood something.",
  str_homestory_816401001_37_dialog_content = "Why do we have a tendency to make deities out of so much of nature's elements?",
  str_homestory_816401001_38_dialog_content = "Because we have too many questions about this world and too few answers.",
  str_homestory_816401001_39_dialog_content = "Prayers are actually a compromise. <sprite=emo_sikao size=60 />",
  str_homestory_816401001_40_dialog_content = "They don't solve any problems or provide any answers.",
  str_homestory_816401001_41_dialog_content = "But they do bring you inner peace, and help you get back on your feet.",
  str_homestory_816401001_42_dialog_content = "True... they do provide a lot of support.",
  str_homestory_816401001_43_dialog_content = "Maybe I should try this prayer thing next time.",
  str_homestory_816401001_44_dialog_content = "I look forward to talking to you about it.",
  str_homestory_811101001_0_dialog_content = "Beryl...",
  str_homestory_811101001_1_dialog_content = "...",
  str_homestory_811101001_2_dialog_content = "Beryl!",
  str_homestory_811101001_3_dialog_content = "Hm? What's up?",
  str_homestory_811101001_4_dialog_content = "You're zoning out, staring at the river. Is something wrong?",
  str_homestory_811101001_5_dialog_content = "Oh, were you worried about me?",
  str_homestory_811101001_6_option_content = "Yep.",
  str_homestory_811101001_7_dialog_content = "So you think I'm unhappy because I've been standing by the river? <sprite=emo_wuzui size=60 />",
  str_homestory_811101001_8_dialog_content = "Um, well, that's not really it...",
  str_homestory_811101001_9_dialog_content = "I was just taking a walk by the river. I mean, the weather is nice today, right?",
  str_homestory_811101001_10_dialog_content = "The look on your face is a strange one.",
  str_homestory_811101001_11_option_content = "Not really.",
  str_homestory_811101001_12_dialog_content = "I just didn't know what you were doing, because you've been standing here for a long time.",
  str_homestory_811101001_13_dialog_content = "When I come down to the river, I usually walk or fish, but I don't stand still.",
  str_homestory_811101001_14_dialog_content = "So... what were you doing?",
  str_homestory_811101001_15_dialog_content = "I was thinking about my crystals and Cloud Gardens.",
  str_homestory_811101001_16_dialog_content = "Your crystals...",
  str_homestory_811101001_17_dialog_content = "Yes, Vice said you've been stressing over Cloud Gardens' development.",
  str_homestory_811101001_18_dialog_content = "And about how you don't have a lot of money <sprite=emo_baiyebi size=60 />, so I was thinking about how to make you rich.",
  str_homestory_811101001_19_dialog_content = "And I started thinking about my power, the crystals.",
  str_homestory_811101001_20_dialog_content = "If I turn the stones in Cloud Gardens into crystals, then sell them to the jewelers in Umbration...",
  str_homestory_811101001_21_dialog_content = "You can do that?",
  str_homestory_811101001_22_dialog_content = "Yes, I heard that you can shatter them and sell the crystal fragments for a handsome sum.",
  str_homestory_811101001_23_dialog_content = "R-Really?",
  str_homestory_811101001_24_dialog_content = "No, not really.",
  str_homestory_811101001_25_dialog_content = "Wow! I see you've learned how to make jokes!",
  str_homestory_811101001_26_dialog_content = "Maybe I changed after coming here. After all, it's a very relaxing place.",
  str_homestory_811101001_27_dialog_content = "Especially when I gaze at the fish in the river.",
  str_homestory_811101001_28_dialog_content = "If you want to look at fish, why not just go to the Fountain of Hope?",
  str_homestory_811101001_29_dialog_content = "There should be plenty in there, and some are really pretty, too.",
  str_homestory_811101001_30_dialog_content = "Here... I can only see really small ones.",
  str_homestory_811101001_31_dialog_content = "Those are the ones I've been looking at.",
  str_homestory_811101001_32_dialog_content = "Especially the way they roam through the algae, or the way they rest by the rocks.",
  str_homestory_811101001_33_dialog_content = "It's very relaxing how they blend in with the environment.",
  str_homestory_811101001_34_dialog_content = "Your attention to detail is really something...",
  str_homestory_811101001_35_dialog_content = "I can't believe your eyes are able to follow them as they dart through the water.",
  str_homestory_811101001_36_dialog_content = "They're not swimming all the time. In fact, they spend a good deal of time resting at the bottom of the river.",
  str_homestory_811101001_37_dialog_content = "Some even go into the gaps among the rocks and only stick their heads out.",
  str_homestory_811101001_38_dialog_content = "Some follow the algae when they sway in the water. It just feels so... liberating.",
  str_homestory_811101001_39_dialog_content = "I see. You're not looking at the fish, Beryl. You're really looking at how they live.",
  str_homestory_811101001_40_dialog_content = "How they live?",
  str_homestory_811101001_41_dialog_content = "How they're not tied down by anything and live carefree lives.",
  str_homestory_811101001_42_dialog_content = "Yes, I've never felt this anywhere else.",
  str_homestory_811101001_43_dialog_content = "It only occurred to me after I arrived at Cloud Gardens and saw them in the river.",
  str_homestory_811101001_44_dialog_content = "Is this because of the charm of this place?",
  str_homestory_811101001_45_dialog_content = "Not the charm, but the way it relaxes you.",
  str_homestory_811101001_46_dialog_content = "Yes, relaxed <sprite=emo_pugongying size=60 />...",
  str_homestory_816501001_0_dialog_content = "Ciel...",
  str_homestory_816501001_1_dialog_content = "Hey there! Got any jobs for me?",
  str_homestory_816501001_2_option_content = "I do.",
  str_homestory_816501001_3_dialog_content = "What are they? How's the pay?",
  str_homestory_816501001_4_dialog_content = "I'm not sure if they're right for you... They're building decorating tasks...",
  str_homestory_816501001_5_dialog_content = "Which would be a waste of your talents.",
  str_homestory_816501001_6_option_content = "No.",
  str_homestory_816501001_7_dialog_content = "You really don't have anything?",
  str_homestory_816501001_8_dialog_content = "Cloud Gardens doesn't have a lot of jobs to begin with, and the Chubbs do most of them.",
  str_homestory_816501001_9_dialog_content = "Anything on a larger scale then? Like tunneling or digging through mountains.",
  str_homestory_816501001_10_dialog_content = "My mecha is made for those things, you know. <sprite=emo_dianzan size=60 />",
  str_homestory_816501001_11_dialog_content = "Don't think I got anything right now. Why are you suddenly looking for jobs, by the way? Don't you want to enjoy your break to its fullest?",
  str_homestory_816501001_12_dialog_content = "I can't take any breaks because I need money.",
  str_homestory_816501001_13_dialog_content = "Money? I heard Illumina rations it. Is there something you want to buy?",
  str_homestory_816501001_14_dialog_content = "I... I want a mechanical calculator. I saw one once in the Research Lab.",
  str_homestory_816501001_15_dialog_content = "Why don't you build one? You have the time to while you're here.",
  str_homestory_816501001_16_dialog_content = "No, because they have a lot of non-standard parts, and it's too complicated.",
  str_homestory_816501001_17_dialog_content = "It would take a long time if I had to make the parts myself.",
  str_homestory_816501001_18_dialog_content = "And it would cost a lot of money to get them made.",
  str_homestory_816501001_19_dialog_content = "But I really want one, so I'm looking for any side jobs I can take on.",
  str_homestory_816501001_20_dialog_content = "Speaking of, what suddenly prompted you to want to get one?",
  str_homestory_816501001_21_dialog_content = "Because I think there's something wrong with the blueprint. There's one place where the calculations don't match, even after several attempts.",
  str_homestory_816501001_22_dialog_content = "The calculation is really complicated and I've done my best, but a machine would never be wrong.",
  str_homestory_816501001_23_dialog_content = "So you want to verify the numbers.",
  str_homestory_816501001_24_dialog_content = "Yes! I recently built a dynamic mecha according to this blueprint...",
  str_homestory_816501001_25_dialog_content = "But because of an error, the mecha broke down and almost burned the blueprint.",
  str_homestory_816501001_26_dialog_content = "I saved it from the burning building, but...",
  str_homestory_816501001_27_dialog_content = "This just isn't working, and I think it's because I might be missing a part of the blueprint. <sprite=emo_daomei size=60 />",
  str_homestory_816501001_28_dialog_content = "Some parts of the dynamic mecha built according the current plans aren't working as intended.",
  str_homestory_816501001_29_dialog_content = "Logically, if the blueprint is missing a part, you shouldn't be able to build the mecha at all, right?",
  str_homestory_816501001_30_dialog_content = "Generally speaking, yes.",
  str_homestory_816501001_31_dialog_content = "So could it be a perspective problem?",
  str_homestory_816501001_32_dialog_content = "For example, I thought one of the connections on the Colossus didn't look right, but I couldn't fix it even after trying for a long time.",
  str_homestory_816501001_33_dialog_content = "Then a Firefly came and immediately saw the problem.",
  str_homestory_816501001_34_dialog_content = "Perspective...",
  str_homestory_816501001_35_dialog_content = "I got it! It's just like the <sprite=emo_baiyebi size=60 /> coin!",
  str_homestory_816501001_36_dialog_content = "What coin?",
  str_homestory_816501001_37_dialog_content = "I saw a coin by the river yesterday. Well, it could have been a bottle cap or just a piece of metal.",
  str_homestory_816501001_38_dialog_content = "Anyway, that's not important. What's important was that it was bouncing on the river on its own!",
  str_homestory_816501001_39_dialog_content = "Come to think of it, the surface was calm, but maybe there was a water current underneath...",
  str_homestory_816501001_40_dialog_content = "Ah, I see. Maybe the formulae were just suggesting the direction that the design should take.",
  str_homestory_816501001_41_dialog_content = "Wait, you said you saw a coin by the river?",
  str_homestory_816501001_42_dialog_content = "Hm? Right, yes. Anyway, I'm off to design the mecha again. See you!",
  str_homestory_816501001_43_dialog_content = "Okay...",
  str_homestory_810001001_0_dialog_content = "What's on your mind?",
  str_homestory_810001001_1_dialog_content = "Sikare?",
  str_homestory_810001001_2_dialog_content = "Oh, hi Snowball. Just who I was looking for.",
  str_homestory_810001001_3_dialog_content = "What's up?",
  str_homestory_810001001_4_dialog_content = "What do you think of Cloud Gardens?",
  str_homestory_810001001_5_dialog_content = "Huh? That's my line. Now that you're asking me, I need a moment...",
  str_homestory_810001001_6_option_content = "A home.",
  str_homestory_810001001_7_dialog_content = "This is, of course, my home.",
  str_homestory_810001001_8_option_content = "A place for resting.",
  str_homestory_810001001_9_dialog_content = "A great place for taking a break.",
  str_homestory_810001001_10_dialog_content = "I see...",
  str_homestory_810001001_11_dialog_content = "Don't you think it's like a prison, too?",
  str_homestory_810001001_12_dialog_content = "Like the Starry Crypt that I guard.",
  str_homestory_810001001_13_dialog_content = "I'm not following you.",
  str_homestory_810001001_14_dialog_content = "It's too comfortable here. It's so comfortable that it makes you not want to think about other things.",
  str_homestory_810001001_15_dialog_content = "I feel like others have said this to me as well.",
  str_homestory_810001001_16_dialog_content = "It's a kind of comfort that is related to the Astra saying that everyone knows:",
  str_homestory_810001001_17_dialog_content = "The most menacing blade is a comfortable bed, where many heroes have faded.",
  str_homestory_810001001_18_dialog_content = "People forget their duties when they're comfortable, especially blockheads that only see what's in front of them <sprite=emo_wuyu size=60 />.",
  str_homestory_810001001_19_dialog_content = "What made you think of this anyway?",
  str_homestory_810001001_20_dialog_content = "I was by the river yesterday, and saw some weeds floating in the water.",
  str_homestory_810001001_21_dialog_content = "And there might have been a piece of metal that was bouncing on the water's surface with the weeds.",
  str_homestory_810001001_22_dialog_content = "I think I see your point now.",
  str_homestory_810001001_23_dialog_content = "If you can think of an analogy like this, then it's very obvious you're not that piece of metal.",
  str_homestory_810001001_24_dialog_content = "After all, we control what actions we take individually, don't we?",
  str_homestory_810001001_25_dialog_content = "I knew I wasn't wrong about you, Snowball. You're different from those other blockheads.",
  str_homestory_816601001_0_dialog_content = "Not bad...",
  str_homestory_816601001_1_dialog_content = "You look like you're in a good mood today.",
  str_homestory_816601001_2_dialog_content = "I take it you've finally settled down here?",
  str_homestory_816601001_3_dialog_content = "Don't try to guess what an extrozoologist is thinking!",
  str_homestory_816601001_4_dialog_content = "I haven't even said anything... <sprite=emo_shengqi size=60 />",
  str_homestory_816601001_5_dialog_content = "But your actions have demonstrated that you're in a good mood.",
  str_homestory_816601001_6_dialog_content = "Huh?",
  str_homestory_816601001_7_dialog_content = "I don't think so.",
  str_homestory_816601001_8_dialog_content = "Well... alright. I happen to have some questions for you.",
  str_homestory_816601001_9_dialog_content = "Questions?",
  str_homestory_816601001_10_dialog_content = "Do ask, and I'll see if I can answer.",
  str_homestory_816601001_11_dialog_content = "What do dogs <sprite=emo_goutou size=60 /> do when they're happy?",
  str_homestory_816601001_12_dialog_content = "You don't even know that?",
  str_homestory_816601001_13_dialog_content = "When they're happy, which is very often, they wag their tails. It's obvious, too.",
  str_homestory_816601001_14_dialog_content = "How about cats <sprite=emo_baimao size=60 />?",
  str_homestory_816601001_15_dialog_content = "That's easy, too.",
  str_homestory_816601001_16_dialog_content = "They're very cautious, but if you can make them happy...",
  str_homestory_816601001_17_dialog_content = "They will approach you and start purring.",
  str_homestory_816601001_18_dialog_content = "How about a wondrous beast like Kyllo?",
  str_homestory_816601001_19_dialog_content = "It's actually really obvious when Kyllo is happy.",
  str_homestory_816601001_20_dialog_content = "I can tell how Kyllo is feeling with my eyes closed, actually!",
  str_homestory_816601001_21_dialog_content = "Well, wondrous beasts or not...",
  str_homestory_816601001_22_dialog_content = "I guess animals do show it when they're happy.",
  str_homestory_816601001_23_dialog_content = "... Why do I have a feeling that you have other intentions with these questions?",
  str_homestory_816601001_24_dialog_content = "Not at all!",
  str_homestory_816601001_25_dialog_content = "I just wanted to see if my observations of you were correct.",
  str_homestory_816601001_26_dialog_content = "Of... me?",
  str_homestory_816601001_27_dialog_content = "I'm an extrozoologist, and I'm usually the one observing...",
  str_homestory_816601001_28_dialog_content = "So why are you observing me?",
  str_homestory_816601001_29_dialog_content = "Maybe...",
  str_homestory_816601001_30_option_content = "Out of curiosity.",
  str_homestory_816601001_31_dialog_content = "You show a lot more emotions than me, so I'm very intrigued.",
  str_homestory_816601001_32_option_content = "Boredom",
  str_homestory_816601001_33_dialog_content = "You're a very interesting child, so I felt like observing your behavior.",
  str_homestory_816601001_34_dialog_content = "And based on what I've seen...",
  str_homestory_816601001_35_dialog_content = "Your bunny ears perk up when you're happy.",
  str_homestory_816601001_36_dialog_content = "Ahhhhh! <sprite=emo_hanshui size=60 /> N-No, please don't look at my ears...",
  str_homestory_816601001_37_dialog_content = "...",
  str_homestory_816601001_38_dialog_content = "Hold on!",
  str_homestory_816601001_39_dialog_content = "My ears are always standing up!",
  str_homestory_816601001_40_dialog_content = "By covering them just now, you've admitted that you're in a good mood.",
  str_homestory_816601001_41_dialog_content = "So you tricked me, PlayerName!",
  str_homestory_816601001_42_dialog_content = "I'm sorry.",
  str_homestory_816601001_43_dialog_content = "To show that I'm apologetic, I'll go down the slides with you.",
  str_homestory_816601001_44_dialog_content = "That sounds good.",
  str_homestory_816701001_0_dialog_content = "Are you asleep?",
  str_homestory_816701001_1_dialog_content = "A good question.",
  str_homestory_816701001_2_dialog_content = "If the wind is how the world breathes...",
  str_homestory_816701001_3_dialog_content = "Then the world is probably drifting towards dreamland right now <sprite=emo_kun size=60 />.",
  str_homestory_816701001_4_dialog_content = "Ah, so you're awake.",
  str_homestory_816701001_5_dialog_content = "I thought you fell asleep on the lounge chair.",
  str_homestory_816701001_6_dialog_content = "The ocean is like a tyrant that never wakes up.",
  str_homestory_816701001_7_dialog_content = "If you have the pleasure of feeling the gusts, like blades, brushing past your face on the ocean...",
  str_homestory_816701001_8_dialog_content = "Jeno?",
  str_homestory_816701001_9_dialog_content = "Yes, divination seeker?",
  str_homestory_816701001_10_dialog_content = "I'm not sure I understand what you just said.",
  str_homestory_816701001_11_dialog_content = "Actually, I know I didn't understand at all.",
  str_homestory_816701001_12_dialog_content = "Words no longer belong to the throat that formed them once they leave the mouth.",
  str_homestory_816701001_13_dialog_content = "And then they are interpreted by the brain receiving them as soon as they enter someone else's ears.",
  str_homestory_816701001_14_dialog_content = "This world is a huge festival of fantasies.",
  str_homestory_816701001_15_dialog_content = "At least that's what I've always thought.",
  str_homestory_816701001_16_option_content = "(Not understanding this at all)",
  str_homestory_816701001_17_dialog_content = "That's... deep. I really don't know what you're talking about.",
  str_homestory_816701001_18_option_content = "(Understood)",
  str_homestory_816701001_19_dialog_content = "You think that people will never truly understand one another.",
  str_homestory_816701001_20_dialog_content = "My dear listener.",
  str_homestory_816701001_21_dialog_content = "It doesn't matter, for we only need to enjoy.",
  str_homestory_816701001_22_dialog_content = "Ahem. I somehow think...",
  str_homestory_816701001_23_dialog_content = "That sometimes you don't even know what you're talking about.",
  str_homestory_816701001_24_dialog_content = "Perhaps sometimes I don't have the right words.",
  str_homestory_816701001_25_dialog_content = "But my magic will never let anyone down <sprite=emo_mojing size=60 />.",
  str_homestory_816701001_26_dialog_content = "That's true.",
  str_homestory_816701001_27_dialog_content = "Hm? Wait!",
  str_homestory_816701001_28_dialog_content = "You didn't create an illusion to fool me, did you?",
  str_homestory_816701001_29_dialog_content = "In fact, you've been sleeping on the lounge chair the entire time!",
  str_homestory_816701001_30_dialog_content = "Ah, have you caught me?",
  str_homestory_816701001_31_dialog_content = "I knew it!",
  str_homestory_816701001_32_dialog_content = "Hold on, I'm not finished.",
  str_homestory_816701001_33_dialog_content = "You're right about one thing: there is someone sleeping on the lounge chair.",
  str_homestory_816701001_34_dialog_content = "But...",
  str_homestory_816701001_35_dialog_content = "How do you know it's not... you?",
  str_homestory_816701001_36_dialog_content = "It can't be!",
  str_homestory_816701001_37_dialog_content = "Because I saw you sleeping on it from afar!",
  str_homestory_816701001_38_dialog_content = "Do you remember what was happening before that, then?",
  str_homestory_816701001_39_dialog_content = "I was...",
  str_homestory_816701001_40_dialog_content = "Wait, what was I doing?",
  str_homestory_816701001_41_dialog_content = "Hahahah.",
  str_homestory_816701001_42_dialog_content = "Did you hypnotize me without me knowing?",
  str_homestory_816701001_43_dialog_content = "Please wake me up... <sprite=emo_tanqi size=60 />",
  str_homestory_816701001_44_dialog_content = "That's easy. Just take a nap on the lounge chair.",
  str_homestory_816701001_45_dialog_content = "Okay...",
  str_homestory_816801001_0_dialog_content = "What are you doing?",
  str_homestory_816801001_1_dialog_content = "Here you are, PlayerName.",
  str_homestory_816801001_2_dialog_content = "This place looks pretty cool! Especially that thing over there...",
  str_homestory_816801001_3_dialog_content = "It plays music when you touch it <sprite=emo_yinfu size=60 />!",
  str_homestory_816801001_4_dialog_content = "Oh yeah? I'm glad to hear that.",
  str_homestory_816801001_5_dialog_content = "I thought it might take up too much space...",
  str_homestory_816801001_6_dialog_content = "And that no one would like it.",
  str_homestory_816801001_7_dialog_content = "I like it!",
  str_homestory_816801001_8_dialog_content = "No, I love it!",
  str_homestory_816801001_9_dialog_content = "Will you show me how to use it?",
  str_homestory_816801001_10_dialog_content = "I'm not too familiar with it, either.",
  str_homestory_816801001_11_dialog_content = "Is there manual or something?",
  str_homestory_816801001_12_dialog_content = "Not sure...",
  str_homestory_816801001_13_dialog_content = "So we'll just have to figure it out on our own?",
  str_homestory_816801001_14_dialog_content = "It feels more fun that way, though.",
  str_homestory_816801001_15_dialog_content = "I didn't know you were so into music.",
  str_homestory_816801001_16_dialog_content = "I love beautiful things. And...",
  str_homestory_816801001_17_dialog_content = "If I could learn how to use it, then implement it in my performances...",
  str_homestory_816801001_18_dialog_content = "It'd make our opening act more enjoyable!",
  str_homestory_816801001_19_dialog_content = "You're always thinking about the circus.",
  str_homestory_816801001_20_dialog_content = "You must really love what you do.",
  str_homestory_816801001_21_dialog_content = "Honestly, I've never really given it much thought <sprite=emo_wuzui size=60 />.",
  str_homestory_816801001_22_dialog_content = "I just always believed that I was born to protect the Emerald.",
  str_homestory_816801001_23_dialog_content = "I do that by repairing and maintaining it when it's docked...",
  str_homestory_816801001_24_dialog_content = "And shooting anyone onboard with nefarious intentions with my Aqua Blaster.",
  str_homestory_816801001_25_dialog_content = "Performing with the circus so that more will know about the Emerald...",
  str_homestory_816801001_26_dialog_content = "is another way to protect it.",
  str_homestory_816801001_27_dialog_content = "So that's it...",
  str_homestory_816801001_28_dialog_content = "Protection comes in many shapes and forms.",
  str_homestory_816801001_29_dialog_content = "For example, you do a great job at protecting Cloud Gardens.",
  str_homestory_816801001_30_dialog_content = "But you might want to clear out the bottom of the river soon.",
  str_homestory_816801001_31_dialog_content = "When I was filling up the blaster with water just now...",
  str_homestory_816801001_32_dialog_content = "I found something shiny at the bottom of the river.",
  str_homestory_816801001_33_dialog_content = "Something shiny...?",
  str_homestory_816801001_34_dialog_content = "Speaking of the river, you wanna cool down?",
  str_homestory_816801001_35_option_content = "I'd love to!",
  str_homestory_816801001_36_dialog_content = "I was working, and it was really hot.",
  str_homestory_816801001_37_dialog_content = "That's easy.",
  str_homestory_816801001_38_dialog_content = "Take this!",
  str_homestory_816801001_39_dialog_content = "What?!",
  str_homestory_816801001_40_option_content = "Not really...",
  str_homestory_816801001_41_dialog_content = "You're not going to blast me with the water pistol, are you?",
  str_homestory_816801001_42_dialog_content = "What else?",
  str_homestory_816801001_43_dialog_content = "I'm fine, really.",
  str_homestory_816801001_44_dialog_content = "I'll just be by the river <sprite=emo_pugongying size=60 />!",
  str_homestory_801602001_0_dialog_content = "Kafka?",
  str_homestory_801602001_1_dialog_content = "Ah!",
  str_homestory_801602001_2_dialog_content = "You scared me, PlayerName.",
  str_homestory_801602001_3_dialog_content = "Sorry about that.",
  str_homestory_801602001_4_dialog_content = "What's up?",
  str_homestory_801602001_5_option_content = "Well...",
  str_homestory_801602001_6_dialog_content = "I just noticed that you've been standing here for a while.",
  str_homestory_801602001_7_dialog_content = "And I was afraid you'd get a heat stroke.",
  str_homestory_801602001_8_dialog_content = "Don't worry, I'm just guarding something.",
  str_homestory_801602001_9_option_content = "I'm fine.",
  str_homestory_801602001_10_dialog_content = "I just noticed that you've been standing here for a while.",
  str_homestory_801602001_11_dialog_content = "So I was curious what you're up to.",
  str_homestory_801602001_12_dialog_content = "Clearly, I'm guarding something.",
  str_homestory_801602001_13_dialog_content = "Guarding something?",
  str_homestory_801602001_14_dialog_content = "Thank you, but Cloud Gardens is very safe...",
  str_homestory_801602001_15_dialog_content = "You don't need to be so alarmed.",
  str_homestory_801602001_16_dialog_content = "I'm not doing this for Cloud Gardens. It's for...",
  str_homestory_801602001_17_dialog_content = "A group of bunnies.",
  str_homestory_801602001_18_dialog_content = "Bunnies? Where are they?",
  str_homestory_801602001_19_dialog_content = "They're back in their burrows",
  str_homestory_801602001_20_dialog_content = "Don't worry, you'll never find them.",
  str_homestory_801602001_21_dialog_content = "I'm not their enemy...",
  str_homestory_801602001_22_dialog_content = "You really like critters, don't you?",
  str_homestory_801602001_23_dialog_content = "D-Do I?",
  str_homestory_801602001_24_dialog_content = "I just don't want them to go somewhere they're not supposed to.",
  str_homestory_801602001_25_dialog_content = "You're almost like a... shepherd.",
  str_homestory_801602001_26_dialog_content = "With your big dog <sprite=emo_goutou size=60 />, ushering animals to a safe place...",
  str_homestory_801602001_27_dialog_content = "Shepherd? No, definitely not.",
  str_homestory_801602001_28_dialog_content = "By the way, I saw something shiny at the bottom of the river.",
  str_homestory_801602001_29_dialog_content = "Will you find out what it is?",
  str_homestory_801602001_30_dialog_content = "Don't let it scare the critters in the area.",
  str_homestory_801602001_31_dialog_content = "Okay!",
  str_homestory_817001001_0_dialog_content = "What a rare occasion...",
  str_homestory_817001001_1_dialog_content = "Who's there?!",
  str_homestory_817001001_2_dialog_content = "It's me, PlayerName...",
  str_homestory_817001001_3_dialog_content = "Apologies, I get jumpy when I hear footsteps stopping suddenly.",
  str_homestory_817001001_4_dialog_content = "Relax, it's very safe in Cloud Gardens.",
  str_homestory_817001001_5_dialog_content = "Yes, I'd heard a while back",
  str_homestory_817001001_6_dialog_content = "that the Caelestite that appeared out of nowhere built an exquisite hideaway in Eraveil.",
  str_homestory_817001001_7_dialog_content = "I wouldn't have believed it if I hadn't seen it for myself.",
  str_homestory_817001001_8_dialog_content = "I didn't expect such management skills from someone as young as you.",
  str_homestory_817001001_9_option_content = "Acknowledge",
  str_homestory_817001001_10_dialog_content = "Thanks for the compliment.",
  str_homestory_817001001_11_dialog_content = "Not humble, I see.",
  str_homestory_817001001_12_dialog_content = "Still, I like the spunk in you.",
  str_homestory_817001001_13_option_content = "Deny",
  str_homestory_817001001_14_dialog_content = "Actually, my friends helped me a lot.",
  str_homestory_817001001_15_dialog_content = "Is that so?",
  str_homestory_817001001_16_dialog_content = "It's rare to see young ones with such humility.",
  str_homestory_817001001_17_dialog_content = "No wonder Cloud Gardens is able to maintain its serenity and peace.",
  str_homestory_817001001_18_dialog_content = "No harassment from Eclipsites, no gang wars.",
  str_homestory_817001001_19_dialog_content = "When I think about it, I haven't had the chance to enjoy the warm sunshine on my skin",
  str_homestory_817001001_20_dialog_content = "in what feels like a lifetime.",
  str_homestory_817001001_21_dialog_content = "That's why you should try to relax.",
  str_homestory_817001001_22_dialog_content = "Relax?",
  str_homestory_817001001_23_dialog_content = "You know, I'm just now realizing that",
  str_homestory_817001001_24_dialog_content = "staying alert has become second nature to me.",
  str_homestory_817001001_25_dialog_content = "Even though I've left Euphoria...",
  str_homestory_817001001_26_dialog_content = "my old habits have stayed with me.",
  str_homestory_817001001_27_dialog_content = "Is gazing down at all those nearby from a vantage point...",
  str_homestory_817001001_28_dialog_content = "a habit you've kept from your time in Euphoria too?",
  str_homestory_817001001_29_dialog_content = "I see, keeping tabs on your guests must be one of your duties as leader of this place.",
  str_homestory_817001001_30_dialog_content = "I guess I can't underestimate you at all.",
  str_homestory_817001001_31_dialog_content = "No, that's not what I meant.",
  str_homestory_817001001_32_dialog_content = "I just happened to see you on the watchtower.",
  str_homestory_817001001_33_dialog_content = "Relax, I'm not trying to start anything.",
  str_homestory_817001001_34_dialog_content = "I used to enjoy standing up high, watching all of Euphoria's happenings unfold before me.",
  str_homestory_817001001_35_dialog_content = "Normally, you would see...",
  str_homestory_817001001_36_dialog_content = "a myriad of greed and desire accumulating beneath the dense rain clouds.",
  str_homestory_817001001_37_dialog_content = "But not here.",
  str_homestory_817001001_38_dialog_content = "It's tranquil as far as my eyes can see.",
  str_homestory_817001001_39_dialog_content = "I do have a request, PlayerName.",
  str_homestory_817001001_40_dialog_content = "Just let me know what you need.",
  str_homestory_817001001_41_dialog_content = "Can I bring the children from the church with me next time?",
  str_homestory_817001001_42_dialog_content = "Sure!",
  str_homestory_817001001_43_dialog_content = "Oh, and another thing...",
  str_homestory_817001001_44_dialog_content = "I saw something by the river that might interest you.",
  str_homestory_817001001_45_dialog_content = "It should still be there if you go now.",
  str_homestory_817001001_46_dialog_content = "Really? I'll take a look!",
  str_homestory_817101001_0_dialog_content = "Casta?",
  str_homestory_817101001_1_dialog_content = "Hey, it's you.",
  str_homestory_817101001_2_dialog_content = "How are you settling in Cloud Gardens?",
  str_homestory_817101001_3_dialog_content = "Not well.",
  str_homestory_817101001_4_dialog_content = "Oh? What seems to be the problem?",
  str_homestory_817101001_5_dialog_content = "I'll rectify it!",
  str_homestory_817101001_6_dialog_content = "For one, the fog here...",
  str_homestory_817101001_7_dialog_content = "always seems to dissipate.",
  str_homestory_817101001_8_dialog_content = "The incessant sunlight makes my eyes feel dry.",
  str_homestory_817101001_9_dialog_content = "And there are no thugs or hooligans looking for trouble.",
  str_homestory_817101001_10_dialog_content = "I'm not getting any decent workout in this peaceful place.",
  str_homestory_817101001_11_dialog_content = "If this keeps up, my accuracy's gonna deteriorate<sprite=emo_daomei size=60 />.",
  str_homestory_817101001_12_option_content = "Apologize",
  str_homestory_817101001_13_dialog_content = "Sorry about that!",
  str_homestory_817101001_14_dialog_content = "Life must be boring for you here.",
  str_homestory_817101001_15_option_content = "Sigh in resignation",
  str_homestory_817101001_16_dialog_content = "But...",
  str_homestory_817101001_17_dialog_content = "I can't do anything about that...",
  str_homestory_817101001_18_dialog_content = "Can't you tell I'm trying to compliment you?",
  str_homestory_817101001_19_dialog_content = "Huh?",
  str_homestory_817101001_20_dialog_content = "I've gotten so used to life in the slums...",
  str_homestory_817101001_21_dialog_content = "that I don't know what to do in a place that's actually safe and comfortable.",
  str_homestory_817101001_22_dialog_content = "Which is kinda amusing, honestly.",
  str_homestory_817101001_23_dialog_content = "Well, there are actually lots of interesting things to do here!",
  str_homestory_817101001_24_dialog_content = "Yeah, I've been discovering that lately.",
  str_homestory_817101001_25_dialog_content = "This billboard is intriguing with how the colors and images come together...",
  str_homestory_817101001_26_dialog_content = "Must be a casino ad, right?",
  str_homestory_817101001_27_dialog_content = "...",
  str_homestory_817101001_28_dialog_content = "What's with your expression<sprite=emo_baiyan size=60 />?",
  str_homestory_817101001_29_dialog_content = "I just want to win some souvenirs for the church kids.",
  str_homestory_817101001_30_dialog_content = "I'm not gonna break your bank or anything.",
  str_homestory_817101001_31_dialog_content = "Uh, this is just for show.",
  str_homestory_817101001_32_dialog_content = "We don't have casinos here...",
  str_homestory_817101001_33_dialog_content = "What?",
  str_homestory_817101001_34_dialog_content = "How about fishing instead?",
  str_homestory_817101001_35_dialog_content = "Fishing?",
  str_homestory_817101001_36_dialog_content = "You know, casting bait and waiting for fish to bite.",
  str_homestory_817101001_37_dialog_content = "It's a good test of one's luck!",
  str_homestory_817101001_38_dialog_content = "Well, any test of luck is something I can't pass up!",
  str_homestory_817101001_39_dialog_content = "Oh, almost forgot...",
  str_homestory_817101001_40_dialog_content = "You're blessed by Lady Luck<sprite=emo_dianzan size=60 />!",
  str_homestory_817101001_41_dialog_content = "I see today is a bad day for fish...",
  str_homestory_813001001_0_dialog_content = "Looks nice, doesn't it?",
  str_homestory_813001001_1_dialog_content = "Huh?",
  str_homestory_813001001_2_dialog_content = "Ahem...",
  str_homestory_813001001_3_dialog_content = "Oh, it's you.",
  str_homestory_813001001_4_dialog_content = "Don't be so loud next time. Are you trying to scare me to death?",
  str_homestory_813001001_5_dialog_content = "Don't say I never warned you!",
  str_homestory_813001001_6_dialog_content = "If you give someone a heart attack...",
  str_homestory_813001001_7_dialog_content = "That could be a life sentence!",
  str_homestory_813001001_8_dialog_content = "Thanks for the warning...",
  str_homestory_813001001_9_dialog_content = "Now that you know, did you need me for anything?",
  str_homestory_813001001_10_dialog_content = "Does Cloud Gardens have need of my judging skills?",
  str_homestory_813001001_11_dialog_content = "Uh, no, not at all.",
  str_homestory_813001001_12_dialog_content = "I saw you pondering and gesturing before this statue...",
  str_homestory_813001001_13_dialog_content = "So I was just curious.",
  str_homestory_813001001_14_dialog_content = "Gesturing? Who was gesturing?",
  str_homestory_813001001_15_dialog_content = "Rumormongering is against the law.",
  str_homestory_813001001_16_dialog_content = "According to the Lumopolis Reputation Code, those who slander others...",
  str_homestory_813001001_17_dialog_content = "shall be sentenced to 100 days in jail or fined one million Nightium.",
  str_homestory_813001001_18_dialog_content = "What?",
  str_homestory_813001001_19_option_content = "Refute",
  str_homestory_813001001_20_dialog_content = "But we're in Cloud Gardens, not Lumopolis!",
  str_homestory_813001001_21_dialog_content = "P-P-Preposterous!",
  str_homestory_813001001_22_dialog_content = "How can you tolerate not having any sort of laws in Cloud Gardens?",
  str_homestory_813001001_23_option_content = "Comply",
  str_homestory_813001001_24_dialog_content = "I guess I was mistaken then...",
  str_homestory_813001001_25_dialog_content = "You have to be more careful, PlayerName.",
  str_homestory_813001001_26_dialog_content = "Or you'll be surrounded by sordidness.",
  str_homestory_813001001_27_dialog_content = "That'd be the downfall of your dominion!",
  str_homestory_813001001_28_dialog_content = "Right...",
  str_homestory_813001001_29_dialog_content = "Say...",
  str_homestory_813001001_30_dialog_content = "How about you give me the statue?",
  str_homestory_813001001_31_dialog_content = "And we'll forget about the whole thing.",
  str_homestory_813001001_32_dialog_content = "What? But...",
  str_homestory_813001001_33_dialog_content = "The statue is very important to me.",
  str_homestory_813001001_34_dialog_content = "It represents a certain Caelestite forebearer.",
  str_homestory_813001001_35_dialog_content = "Lawless lands truly are incomprehensible.",
  str_homestory_813001001_36_dialog_content = "If you really like the statue...",
  str_homestory_813001001_37_dialog_content = "I can make a replica for you out of mud.",
  str_homestory_813001001_38_dialog_content = "Well...",
  str_homestory_813001001_39_dialog_content = "That is a solution<sprite=emo_woshou size=60 />.",
  str_homestory_813001001_40_dialog_content = "Just don't keep me waiting.",
  str_homestory_812101001_0_dialog_content = "Paloma?",
  str_homestory_812101001_1_dialog_content = "Oh, it's you.",
  str_homestory_812101001_2_dialog_content = "Pardon me...",
  str_homestory_812101001_3_dialog_content = "Did I wake you up?",
  str_homestory_812101001_4_dialog_content = "You know better than to pretend that you care when talking to me.",
  str_homestory_812101001_5_dialog_content = "Just spit it out.",
  str_homestory_812101001_6_dialog_content = "You want to know how I like Cloud Gardens so far, right?",
  str_homestory_812101001_7_option_content = "Deny",
  str_homestory_812101001_8_dialog_content = "Not really...",
  str_homestory_812101001_9_dialog_content = "Just wanted to say hello.",
  str_homestory_812101001_10_option_content = "Admit",
  str_homestory_812101001_11_dialog_content = "You're right...",
  str_homestory_812101001_12_dialog_content = "I do care about your opinion.",
  str_homestory_812101001_13_dialog_content = "Whether you admit it or not, I'll say this...",
  str_homestory_812101001_14_dialog_content = "...",
  str_homestory_812101001_15_dialog_content = "I don't hate the place.",
  str_homestory_812101001_16_dialog_content = "That's great!",
  str_homestory_812101001_17_dialog_content = "I thought you were going to pick it apart...",
  str_homestory_812101001_18_dialog_content = "What did you say?",
  str_homestory_812101001_19_dialog_content = "Oh, I mean...",
  str_homestory_812101001_20_dialog_content = "I was expecting constructive criticism from you!",
  str_homestory_812101001_21_dialog_content = "It's not that I don't have anything to say.",
  str_homestory_812101001_22_dialog_content = "But since you're good with development, construction, and management...",
  str_homestory_812101001_23_dialog_content = "Are you interested in kicking the nobles out of Lumopolis and taking over Azurite?",
  str_homestory_812101001_24_dialog_content = "What?!",
  str_homestory_812101001_25_dialog_content = "I've never even considered anything like that.",
  str_homestory_812101001_26_dialog_content = "I've met many who said one thing and did the opposite...",
  str_homestory_812101001_27_dialog_content = "One too many times.",
  str_homestory_812101001_28_dialog_content = "I... I'm just trying to protect my own home.",
  str_homestory_812101001_29_dialog_content = "I'd presume those in Lumopolis feel the same about their home, too.",
  str_homestory_812101001_30_dialog_content = "Home?",
  str_homestory_812101001_31_dialog_content = "I'm someone who got kicked out of their home.",
  str_homestory_812101001_32_dialog_content = "\"Home\" has long become a meaningless word to me.",
  str_homestory_812101001_33_dialog_content = "Remember Paloma, you've still got Cloud Gardens.",
  str_homestory_812101001_34_dialog_content = "If you'd like...",
  str_homestory_812101001_35_dialog_content = "you can treat Cloud Gardens as your home!",
  str_homestory_812101001_36_dialog_content = "So you don't think anyone else is going to try and take it from you?",
  str_homestory_812101001_37_dialog_content = "It only got to where it is today thanks to all my friends.",
  str_homestory_812101001_38_dialog_content = "That's why I want Cloud Gardens to be a safe haven for everyone.",
  str_homestory_812101001_39_dialog_content = "Oh, Caelestite, you sure are unbelievably naive.<sprite=emo_baiyan size=60 />",
  str_homestory_812101001_40_dialog_content = "Maybe...",
  str_homestory_812101001_41_dialog_content = "I can add a definition to \"home\" in my dictionary.",
  str_homestory_812101001_42_dialog_content = "Which would be...",
  str_homestory_812101001_43_dialog_content = "Cloud Gardens.",
  str_homestory_812001001_0_dialog_content = "There you are, Hedy.",
  str_homestory_812001001_1_dialog_content = "Argh...",
  str_homestory_812001001_2_dialog_content = "What's wrong, Hedy?",
  str_homestory_812001001_3_dialog_content = "White Night up high...",
  str_homestory_812001001_4_dialog_content = "That machine keeps growling evilly at me!",
  str_homestory_812001001_5_dialog_content = "Tell me, is it an evil relic from the Old Era, PlayerName?",
  str_homestory_812001001_6_dialog_content = "If this continues...",
  str_homestory_812001001_7_dialog_content = "I'll have to summon the Knight of Light to destroy it<sprite=emo_shengqi size=60 />.",
  str_homestory_812001001_8_option_content = "Console",
  str_homestory_812001001_9_dialog_content = "Don't worry, Hedy.",
  str_homestory_812001001_10_dialog_content = "It's just an ice cream machine.",
  str_homestory_812001001_11_option_content = "Apologize",
  str_homestory_812001001_12_dialog_content = "Sorry, I forgot to tell you.",
  str_homestory_812001001_13_dialog_content = "This is an ice cream machine!",
  str_homestory_812001001_14_dialog_content = "An... ice cream machine?<sprite=emo_wuzui size=60 />",
  str_homestory_812001001_15_dialog_content = "Yeah. Just put a cup on top and press the button.",
  str_homestory_812001001_16_dialog_content = "Then the machine will make you yummy ice cream.",
  str_homestory_812001001_17_dialog_content = "Actually, I, uh already guessed it was an ice cream machine from the snowflakes on it.",
  str_homestory_812001001_18_dialog_content = "But no ice cream came out...",
  str_homestory_812001001_19_dialog_content = "So I thought it could be a diabolical creation masquerading as an ice cream machine.",
  str_homestory_812001001_20_dialog_content = "Did it run out of ice cream again?",
  str_homestory_812001001_21_dialog_content = "\"Again\"?",
  str_homestory_812001001_22_dialog_content = "Well, the ice cream it makes is so good...",
  str_homestory_812001001_23_dialog_content = "If you don't get here early enough, you won't get any.",
  str_homestory_812001001_24_dialog_content = "It's been so much cooler the past few days, I thought less people would be using it.",
  str_homestory_812001001_25_dialog_content = "But I guess it's still very popular.",
  str_homestory_812001001_26_dialog_content = "What flavor do you like, Hedy?",
  str_homestory_812001001_27_dialog_content = "I'll go get the ingredients for it.",
  str_homestory_812001001_28_dialog_content = "My favorite ice cream flavor...",
  str_homestory_812001001_29_dialog_content = "Yeah, what do you like?",
  str_homestory_812001001_30_dialog_content = "Vanilla, chocolate, matcha, orange, red bean...",
  str_homestory_812001001_31_dialog_content = "I love them all!",
  str_homestory_812001001_32_dialog_content = "So many flavors, I see...",
  str_homestory_812001001_33_dialog_content = "Have you never had ice cream before? These are all basic flavors...",
  str_homestory_812001001_34_dialog_content = "W-What do you mean?",
  str_homestory_812001001_35_dialog_content = "Of course I've had ice cream before!",
  str_homestory_812001001_36_dialog_content = "I just think all the flavors you mentioned were too plain.",
  str_homestory_812001001_37_dialog_content = "I've only had \"ancient tome\"-flavored ice cream before.",
  str_homestory_812001001_38_dialog_content = "But I don't think the machine can make that.<sprite=emo_emo size=60 />",
  str_homestory_812001001_39_dialog_content = "\"Ancient tomes\"-flavored?!",
  str_homestory_812001001_40_dialog_content = "Can't say I've had that, ever.",
  str_homestory_812001001_41_dialog_content = "But I'll try to find the recipe!",
  str_homestory_812001001_42_dialog_content = "Oh, that's quite all right...",
  str_homestory_812001001_43_dialog_content = "How come?",
  str_homestory_812001001_44_dialog_content = "I'd like to find out how...",
  str_homestory_812001001_45_dialog_content = "vanilla, chocolate, matcha, orange, and red bean ice cream taste.",
  str_homestory_806801001_0_dialog_content = "Wendy?",
  str_homestory_806801001_1_dialog_content = "What are you up to?",
  str_homestory_806801001_2_dialog_content = "Oh, it's you, PlayerName.",
  str_homestory_806801001_3_dialog_content = "I'm looking for a place to practice vertical flight.",
  str_homestory_806801001_4_dialog_content = "Vertical flight?",
  str_homestory_806801001_5_dialog_content = "Yeah, flying straight up and straight down.",
  str_homestory_806801001_6_dialog_content = "It's the ultimate test of flying skills.",
  str_homestory_806801001_7_dialog_content = "You know, I always get scared that you'll fall from flying so high up.",
  str_homestory_806801001_8_dialog_content = "Seriously?",
  str_homestory_806801001_9_dialog_content = "Relax, it's a piece of cake for me.",
  str_homestory_806801001_10_dialog_content = "Or have you forgotten that I'm the desert hurricane missile<sprite=emo_mojing size=60 />?",
  str_homestory_806801001_11_option_content = "Forgot",
  str_homestory_806801001_12_dialog_content = "Then I shall reiterate!",
  str_homestory_806801001_13_option_content = "Didn't forget",
  str_homestory_806801001_14_dialog_content = "How could I forget such an impressive moniker?",
  str_homestory_806801001_15_dialog_content = "I'll reiterate everything, just in case!",
  str_homestory_806801001_16_dialog_content = "I'm Wendy, the desert hurricane missile!",
  str_homestory_806801001_17_dialog_content = "Speed is my trademark, and boldness is my middle name!",
  str_homestory_806801001_18_dialog_content = "Okay, okay, I got it.",
  str_homestory_806801001_19_dialog_content = "That said, why practice vertical flight?",
  str_homestory_806801001_20_dialog_content = "For delivery purposes, of course!",
  str_homestory_806801001_21_dialog_content = "Delivering a letter?",
  str_homestory_806801001_22_dialog_content = "Have you seen the thing with the long tentacles, PlayerName?",
  str_homestory_806801001_23_dialog_content = "You mean the jellyfish balloon?",
  str_homestory_806801001_24_dialog_content = "I don't care what it is.",
  str_homestory_806801001_25_dialog_content = "If a client wants a letter delivered, they'll get it 100% guaranteed.",
  str_homestory_806801001_26_dialog_content = "So you know the balloon, PlayerName?",
  str_homestory_806801001_27_dialog_content = "I mean I know the furnishing... so I guess?",
  str_homestory_806801001_28_dialog_content = "Is the balloon's name Kleken?",
  str_homestory_806801001_29_dialog_content = "Well, if the mail is addressed to Kleken...",
  str_homestory_806801001_30_dialog_content = "There must be a mix-up, because Kleken is not a balloon.",
  str_homestory_806801001_31_dialog_content = "What?! Really?",
  str_homestory_806801001_32_dialog_content = "The sender said Kleken has a lot of long, smooth tentacles.",
  str_homestory_806801001_33_dialog_content = "And he often wears a black top hat.",
  str_homestory_806801001_34_dialog_content = "Is there a hat on the balloon?",
  str_homestory_806801001_35_dialog_content = "Well, in any case, jellyfish balloons aren't the recipient you're looking for.",
  str_homestory_806801001_36_dialog_content = "Oh no, I'm going to set a new personal record for the longest delivery time.",
  str_homestory_806801001_37_dialog_content = "Gotta run.",
  str_homestory_806801001_38_dialog_content = "Even though I saw something shiny by the river and wanted to check it out...",
  str_homestory_806801001_39_dialog_content = "I've got a delivery to make!<sprite=emo_dianzan size=60 />",
  str_homestory_817201001_0_dialog_content = "Hey, Lilica...",
  str_homestory_817201001_1_dialog_content = "Come check it out, PlayerName!",
  str_homestory_817201001_2_dialog_content = "What's up?",
  str_homestory_817201001_3_dialog_content = "Look, this toy is so much fun!",
  str_homestory_817201001_4_dialog_content = "So, all you have to do is hit it with a bat until it explodes with a burst of confetti!<sprite=emo_caitiao size=60 />",
  str_homestory_817201001_5_dialog_content = "Sometimes, candy may appear too!",
  str_homestory_817201001_6_dialog_content = "I don't think I've ever seen a toy like this before.",
  str_homestory_817201001_7_dialog_content = "Well, that makes sense since Windelion Dolls are traditional ornaments unique to Eraveil.",
  str_homestory_817201001_8_dialog_content = "You definitely won't find them anywhere else.",
  str_homestory_817201001_9_dialog_content = "Windelion Dolls? Traditional ornaments from Eraveil...",
  str_homestory_817201001_10_dialog_content = "Now that you mention it, I think I vaguely remember that!",
  str_homestory_817201001_11_dialog_content = "Don't they have a festival where they'd fill a clay pot with seeds beforehand...",
  str_homestory_817201001_12_dialog_content = "and shatter it on the day itself?",
  str_homestory_817201001_13_dialog_content = "Only then can they receive the nature's blessing for a bountiful harvest that year!",
  str_homestory_817201001_14_dialog_content = "Am I right?",
  str_homestory_817201001_15_dialog_content = "Wow, Lilica! I've no idea you know Eraveil's traditions so well!",
  str_homestory_817201001_16_dialog_content = "Hehe, I wouldn't go THAT far, you know?",
  str_homestory_817201001_17_dialog_content = "I once played the role of a history teacher in a movie.",
  str_homestory_817201001_18_dialog_content = "It wasn't a special role or anything—I didn't even get a close-up! But I needed to keep lecturing in the background.",
  str_homestory_817201001_19_dialog_content = "I remember the script I was given touched on Eraveil and its traditions!",
  str_homestory_817201001_20_dialog_content = "Oh, wow! Turns out there are films like that out there?",
  str_homestory_817201001_21_dialog_content = "What's the name of the movie?",
  str_homestory_817201001_22_dialog_content = "*Clears throat* Anyway, my lines were just part of the background noise, nothing more.",
  str_homestory_817201001_23_dialog_content = "I doubt you can even make out what I was saying in the movie...",
  str_homestory_817201001_24_option_content = "(Feel disappointed)",
  str_homestory_817201001_25_dialog_content = "Alright, then...",
  str_homestory_817201001_26_dialog_content = "For a second, I thought I'd be able to watch a film about Eraveil.",
  str_homestory_817201001_27_dialog_content = "Come on, don't look so defeated, PlayerName! Have you already forgotten who I am?",
  str_homestory_817201001_28_option_content = "(Feel excited)",
  str_homestory_817201001_29_dialog_content = "Even if it was just background noise, for Eraveil to get mentioned in a movie...",
  str_homestory_817201001_30_dialog_content = "Just knowing that much makes me incredibly happy!",
  str_homestory_817201001_31_dialog_content = "It really isn't that big of a deal, PlayerName... Besides, have you already forgotten who I am?",
  str_homestory_817201001_32_dialog_content = "I'm the brightest up-and-coming film director of our time! Remember?",
  str_homestory_817201001_33_dialog_content = "Why don't I...",
  str_homestory_817201001_34_dialog_content = "shoot a film dedicated entirely to Eraveil?",
  str_homestory_817201001_35_dialog_content = "Eh? Is that okay?",
  str_homestory_817201001_36_dialog_content = "Of course, you can count on me!",
  str_homestory_817201001_37_dialog_content = "That'd be amazing! Do you already have something in mind, Lilica?",
  str_homestory_817201001_38_dialog_content = "Hmm... Let's see...<sprite=emo_sikao size=60 />",
  str_homestory_817201001_39_dialog_content = "Aha! I've got it!",
  str_homestory_817201001_40_dialog_content = "What about a dance movie that takes place in Eraveil... with me as the star!",
  str_homestory_817201001_41_dialog_content = "Huh?",
  str_homestory_817201001_42_dialog_content = "Will that still be a movie about Eraveil?",
  str_homestory_817201001_43_dialog_content = "Why wouldn't it?",
  str_homestory_817201001_44_dialog_content = "Ugh, this sure is a headache...",
  str_homestory_817201001_45_dialog_content = "Alright, what if instead of me... YOU star in the dance movie that takes place in Eraveil! Eh? Eh??",
  str_homestory_817201001_46_dialog_content = "I... don't think anyone would want to watch that...",
  str_homestory_817301001_0_dialog_content = "Minos...",
  str_homestory_817301001_1_dialog_content = "Good morning, Navigator<sprite=emo_mojing size=60 />.",
  str_homestory_817301001_2_dialog_content = "Hello, Minos.",
  str_homestory_817301001_3_dialog_content = "Is there anything I can do for you today, Navigator?",
  str_homestory_817301001_4_option_content = "(Confirm)",
  str_homestory_817301001_5_dialog_content = "Er... Well, there's actually something I've been meaning to ask you, Minos.",
  str_homestory_817301001_6_dialog_content = "By all means, sir.",
  str_homestory_817301001_7_dialog_content = "I hope you can loosen up a little when you're here in Cloud Gardens...",
  str_homestory_817301001_8_dialog_content = "There's no need for you to be so courteous and reverent, you know?",
  str_homestory_817301001_9_option_content = "(Deny)",
  str_homestory_817301001_10_dialog_content = "N-Not really, no...",
  str_homestory_817301001_11_dialog_content = "I always feel so at ease whenever you're here in Cloud Gardens, Minos.",
  str_homestory_817301001_12_dialog_content = "But I really hope you can loosen up a little while you're here...",
  str_homestory_817301001_13_dialog_content = "After all, I invited you to be my guest in Cloud Gardens.",
  str_homestory_817301001_14_dialog_content = "You do have a point, yes.",
  str_homestory_817301001_15_dialog_content = "As your guest, it is certainly rude of me to deprive you of the pleasure of hosting guests.",
  str_homestory_817301001_16_dialog_content = "I have taken note of your request, sir.",
  str_homestory_817301001_17_dialog_content = "Now then, please allow me a few moments to mold myself into the perfect guest.",
  str_homestory_817301001_18_dialog_content = "You don't have to go out of your way to be perfect, you know?",
  str_homestory_817301001_19_dialog_content = "An imperfect guest, then?",
  str_homestory_817301001_20_dialog_content = "That sounds like a challenge.",
  str_homestory_817301001_21_dialog_content = "Hehehe... You are overthinking it, Minos. Anyway...",
  str_homestory_817301001_22_dialog_content = "I just saw these candles lit up as soon as you raise your hand.",
  str_homestory_817301001_23_dialog_content = "That's simply incredible! How did you do that, Minos?",
  str_homestory_817301001_24_dialog_content = "You have such keen observation skills, sir.",
  str_homestory_817301001_25_dialog_content = "I was just finishing up their training when you arrived.",
  str_homestory_817301001_26_dialog_content = "You were... training candles?",
  str_homestory_817301001_27_dialog_content = "Indeed. It's a technique known only to veteran butlers who have dedicated years to providing service...",
  str_homestory_817301001_28_dialog_content = "No matter how expensive a piece of furniture may be, or how delicate an ornament may seem...",
  str_homestory_817301001_29_dialog_content = "With the right technique, they can all be trained to better serve others within their respective spaces.",
  str_homestory_817301001_30_dialog_content = "Take these candles, for instance.",
  str_homestory_817301001_31_dialog_content = "They have a mechanism that allows them to light up and extinguish automatically.",
  str_homestory_817301001_32_dialog_content = "Left unchecked, these candles will simply activate and deactivate randomly, without the slightest semblance of order.",
  str_homestory_817301001_33_dialog_content = "But not to worry. By approaching them in the proper order...",
  str_homestory_817301001_34_dialog_content = "They will now happily light up in your presence.",
  str_homestory_817301001_35_dialog_content = "Th-That's amazing...",
  str_homestory_817301001_36_dialog_content = "Ah! My apologies...",
  str_homestory_817301001_37_dialog_content = "As your guest, I shouldn't be doing things like training your furniture...",
  str_homestory_817301001_38_dialog_content = "No worries.",
  str_homestory_817301001_39_dialog_content = "If it weren't for you, I never would have known I could do this with these candles!",
  str_homestory_817301001_40_dialog_content = "Thank you for overlooking my misdemeanor.",
  str_homestory_817301001_41_dialog_content = "Though I cannot help but feel grateful for my mistake...",
  str_homestory_817301001_42_dialog_content = "Because of it, I have perfectly assumed the role of an imperfect guest.",
  str_homestory_817301001_43_dialog_content = "But I only hope my performance<sprite=emo_baimao size=60 /> has been to your satisfaction, Navigator.",
  str_homestory_815901001_0_dialog_content = "Hey, Sadie!",
  str_homestory_815901001_1_dialog_content = "Oh, it's you. Don't tell me someone had you to look for me?",
  str_homestory_815901001_2_dialog_content = "Nah, I was drawn by the music<sprite=emo_yinfu size=60 /> earlier.",
  str_homestory_815901001_3_dialog_content = "That catchy rhythm and exhilarating beats...",
  str_homestory_815901001_4_dialog_content = "I just can't help dancing to the music!",
  str_homestory_815901001_5_dialog_content = "Looks like you've fallen for the irresistible charm of hip-hop!",
  str_homestory_815901001_6_dialog_content = "But it's perfectly normal since who doesn't love hip-hop?",
  str_homestory_815901001_7_dialog_content = "So this is hip-hop...?",
  str_homestory_815901001_8_dialog_content = "Don't tell me you've never heard of it before, PlayerName?",
  str_homestory_815901001_9_option_content = "(Confirm)",
  str_homestory_815901001_10_dialog_content = "I don't really listen to much hip-hop, so I can't say I understand it very well.",
  str_homestory_815901001_11_option_content = "(Deny)",
  str_homestory_815901001_12_dialog_content = "No way, I love all kinds of music!",
  str_homestory_815901001_13_dialog_content = "But the only hip-hop songs I've heard are your rapping...",
  str_homestory_815901001_14_dialog_content = "That's why I don't understand much about the genre.",
  str_homestory_815901001_15_dialog_content = "It's also why I couldn't tell it was hip-hop right away.",
  str_homestory_815901001_16_dialog_content = "That's a real shame. No wonder I thought something was missing when I first got here.",
  str_homestory_815901001_17_dialog_content = "As soon as I saw this drum earlier, it hit me suddenly that this place is in need of some hip-hop!",
  str_homestory_815901001_18_dialog_content = "I never knew that a single drum can make such moving beats...",
  str_homestory_815901001_19_dialog_content = "It looks like you're completely mesmerized by it, PlayerName.",
  str_homestory_815901001_20_dialog_content = "I guess a swashbuckler like me has no choice but to lend you a hand.",
  str_homestory_815901001_21_dialog_content = "Lend me a hand?",
  str_homestory_815901001_22_dialog_content = "That's right! I'm gonna teach you how to play this drum the right way!",
  str_homestory_815901001_23_dialog_content = "That way, you can listen to sweet hip-hop beats whenever you want!",
  str_homestory_815901001_24_dialog_content = "Eh? Hold on, if I teach you how to do that...",
  str_homestory_815901001_25_dialog_content = "Won't that mean that everyone in Cloud Gardens will get to hear the hip-hop beats you make?!",
  str_homestory_815901001_26_dialog_content = "I can't believe that I'll be starting the hip-hop trend in Astra!",
  str_homestory_815901001_27_dialog_content = "S-Sorry to interrupt, Sadie...",
  str_homestory_815901001_28_dialog_content = "But I'm just a beginner when it comes to hip-hop or drums.",
  str_homestory_815901001_29_dialog_content = "I don't think teaching me will be an easy feat.",
  str_homestory_815901001_30_dialog_content = "Oh, don't you worry about that! After all, the best student is one who is eager to learn<sprite=emo_dianzan size=60 />!",
  str_homestory_815901001_31_dialog_content = "Now, the two most important aspects of hip-hop are rhythm and beat.",
  str_homestory_815901001_32_dialog_content = "The rhythm will come naturally as long as you're playing on the beat.",
  str_homestory_815901001_33_dialog_content = "Now, picture yourself as the drumstick and bring out the rhythm within your heart.",
  str_homestory_815901001_34_dialog_content = "After all, the best hip-hop always comes straight from the heart!",
  str_homestory_815901001_35_dialog_content = "So you're saying I'll be able to perform just like you if I follow my heart?",
  str_homestory_815901001_36_dialog_content = "Absolutely! Why don't you give it a try?",
  str_homestory_815901001_37_dialog_content = "Just stay on the beat and keep drumming away. The music will flow out on its own!",
  str_homestory_815901001_38_dialog_content = "J-Just keep drumming, huh...",
  str_homestory_815901001_39_dialog_content = "Don't you wanna help more people realize how amazing hip-hop is?",
  str_homestory_815901001_40_dialog_content = "Of course I do, but I'm really worn out now.",
  str_homestory_815901001_41_dialog_content = "I guess you still have a long way to go before becoming a hip-hop superstar, PlayerName.",
  str_homestory_815901001_42_dialog_content = "Let's just call it for today, yeah?",
  str_homestory_815901001_43_dialog_content = "Th-Thank you...",
  str_homestory_807901001_0_dialog_content = "Michenny...",
  str_homestory_807901001_1_dialog_content = "Michenny?",
  str_homestory_807901001_2_dialog_content = "Hello, PlayerName.",
  str_homestory_807901001_3_dialog_content = "Heheh... Are you here to appreciate the decor too?",
  str_homestory_807901001_4_dialog_content = "As a logically-minded Tax Collector, the word \"appreciate\" is too sentimental.",
  str_homestory_807901001_5_dialog_content = "I'm simply here to assess the value of this item, nothing more.",
  str_homestory_807901001_6_dialog_content = "Ah... This isn't Lumopolis, you know? I think even you can afford to relax every once in a while, Michenny<sprite=emo_sikao size=60 />.",
  str_homestory_807901001_7_dialog_content = "Exercising rational thought is no trifling matter.",
  str_homestory_807901001_8_dialog_content = "Especially when one's goal is to become a top scholar in the field of tax laws.",
  str_homestory_807901001_9_dialog_content = "I have no intention of squandering years of academic experience just to slack off, even for a moment.",
  str_homestory_807901001_10_dialog_content = "That isn't to say I don't have any free time, however. If you need, I can help you with Cloud Gardens' taxes in my spare time.",
  str_homestory_807901001_11_dialog_content = "I don't think we have tax issues in Cloud Gardens for now...",
  str_homestory_807901001_12_dialog_content = "Your tone is soft, and you sound uncertain. That's about a tax of 10 Nightium<sprite=emo_baiyebi size=60 /> away from determined.",
  str_homestory_807901001_13_dialog_content = "It seems you have rejected my service entirely.",
  str_homestory_807901001_14_option_content = "Agree",
  str_homestory_807901001_15_dialog_content = "It's not that I want to turn you down, Michenny. It's just that... Cloud Gardens can't really afford a tax collector like you.",
  str_homestory_807901001_16_dialog_content = "Ah, short of Nightium as ever, I see.",
  str_homestory_807901001_17_dialog_content = "You don't need to worry about that. I can provide you with expert tax advice, free of charge.",
  str_homestory_807901001_18_dialog_content = "After all, properly assessing the value of Cloud Gardens will provide me with a measure of emotional value as well.",
  str_homestory_807901001_19_option_content = "Deny",
  str_homestory_807901001_20_dialog_content = "N-Not at all!",
  str_homestory_807901001_21_dialog_content = "If Cloud Gardens ever needs a tax collector, you'll be the first person I call, Michenny!",
  str_homestory_807901001_22_dialog_content = "Taxes must exist wherever land is managed and transactions take place.",
  str_homestory_807901001_23_dialog_content = "Since you have placed so much trust in me, I'll continue assessing Cloud Gardens' value.",
  str_homestory_807901001_24_dialog_content = "S-Sure...",
  str_homestory_807901001_25_dialog_content = "Going back to the subject at hand, tell me... How much do you know about this piece of decor?",
  str_homestory_807901001_26_dialog_content = "I require more information to make a fair assessment of it.",
  str_homestory_807901001_27_dialog_content = "It's called a Windelion Nest.",
  str_homestory_807901001_28_dialog_content = "Even though these giant eggshells are just decorations for us, plenty of animals<sprite=emo_gezitou size=60 /> like to use them to lay eggs.",
  str_homestory_807901001_29_dialog_content = "Hmm. They don't generate any direct economic value, and they take up space.",
  str_homestory_807901001_30_dialog_content = "In addition, the creatures that they nurture will eventually begin to consume Cloud Gardens' food resources.",
  str_homestory_807901001_31_dialog_content = "My conclusion is that this object and the small creatures residing in them have no value whatsoever.",
  str_homestory_807901001_32_dialog_content = "On the contrary, they are an economic burden on Cloud Gardens.",
  str_homestory_807901001_33_dialog_content = "B-But inside the eggs are living creatures!",
  str_homestory_807901001_34_dialog_content = "How could you possibly assess the value of their lives using logic?",
  str_homestory_807901001_35_dialog_content = "If you ask me, their lives are priceless.",
  str_homestory_807901001_36_dialog_content = "Priceless, you say?",
  str_homestory_807901001_37_dialog_content = "Wait... I've got it!",
  str_homestory_807901001_38_dialog_content = "How would you like to take care of this Windelion Nest, Michenny?",
  str_homestory_807901001_39_dialog_content = "Very well. What do I need to do?",
  str_homestory_807901001_40_dialog_content = "Just wait here until these little guys hatch, and watch over them until they grow up!",
  str_homestory_807901001_41_dialog_content = "I can lend you a book that teaches you all about caring for animals.",
  str_homestory_807901001_42_dialog_content = "A textbook would be most helpful, yes.",
  str_homestory_807901001_43_dialog_content = "Leave it to me. I promise I won't disappoint you.",
  str_homestory_817601001_0_dialog_content = "Beretta!",
  str_homestory_817601001_1_dialog_content = "What are you doing, Beretta?",
  str_homestory_817601001_2_dialog_content = "Oh, hi PlayerName!",
  str_homestory_817601001_3_dialog_content = "I'm exercising.",
  str_homestory_817601001_4_dialog_content = "When I ran by here, I thought I saw Lady Raphael.",
  str_homestory_817601001_5_dialog_content = "So I stopped for another look...",
  str_homestory_817601001_6_dialog_content = "and noticed her photo on this card!",
  str_homestory_817601001_7_dialog_content = "Ah, that's the postcard everyone sent to me before!",
  str_homestory_817601001_8_dialog_content = "Some of the others are souvenirs I brought back from new places.",
  str_homestory_817601001_9_dialog_content = "I think this one was taken when Raphael dragged Michael on a long trip.",
  str_homestory_817601001_10_dialog_content = "I was wondering why Michael looked so bummed out!<sprite=emo_wuzui size=60 />",
  str_homestory_817601001_11_dialog_content = "You seem pretty popular.",
  str_homestory_817601001_12_dialog_content = "You have a lot here... I even saw one with Lady Hedy's signature on it.",
  str_homestory_817601001_13_dialog_content = "Hey, is this a landscape photo of the Rediesel Desert?",
  str_homestory_817601001_14_dialog_content = "It is.",
  str_homestory_817601001_15_dialog_content = "This one is a souvenir from visiting the Rediesel Wrench.",
  str_homestory_817601001_16_option_content = "And this one is from Northland...",
  str_homestory_817601001_17_dialog_content = "Wow, desert and snow... Spectacular!",
  str_homestory_817601001_18_option_content = "And this one is from the beach...",
  str_homestory_817601001_19_dialog_content = "Wow, desert and beach... Spectacular!",
  str_homestory_817601001_20_dialog_content = "I'm so jealous that you've been to so many places, PlayerName!",
  str_homestory_817601001_21_dialog_content = "Don't you travel, Beretta?",
  str_homestory_817601001_22_dialog_content = "No, because my work, I'm never able to fully relax even when I'm off work.",
  str_homestory_817601001_23_dialog_content = "After all, patients don't stop getting sick or hurt just because you're on vacation.",
  str_homestory_817601001_24_dialog_content = "Even when I do get to travel, it's for providing medical assistance.",
  str_homestory_817601001_25_dialog_content = "It really is tough being a doctor...",
  str_homestory_817601001_26_dialog_content = "It is tough.",
  str_homestory_817601001_27_dialog_content = "But when I think about how I can alleviate someone's pain or even save a life...",
  str_homestory_817601001_28_dialog_content = "It's not tough anymore!",
  str_homestory_817601001_29_dialog_content = "Not to mention I have to put in more work to get better.",
  str_homestory_817601001_30_dialog_content = "That way, I can build my own traveling medical team to treat patients all over the continent.",
  str_homestory_817601001_31_dialog_content = "Then, not only will I get to help more people, but I'll also get to see scenery I've never seen before!",
  str_homestory_817601001_32_dialog_content = "Two birds with one stone!<sprite=emo_guilian size=60 />",
  str_homestory_817601001_33_dialog_content = "I'm impressed, Beretta!",
  str_homestory_817601001_34_dialog_content = "You have a certain glow about you when you speak of your work!",
  str_homestory_817601001_35_dialog_content = "Hahaha, but I've still got a long way to go!",
  str_homestory_817601001_36_dialog_content = "My goal is to be a great doctor like Lady Raphael or Mr. John.",
  str_homestory_817601001_37_dialog_content = "But I still have a lot to learn.",
  str_homestory_817601001_38_dialog_content = "Not just in medicine but in physical and mental stamina too.",
  str_homestory_817601001_39_dialog_content = "When Dr. John operated on me, he stood by the operation table for three whole days!",
  str_homestory_817601001_40_dialog_content = "That's impossible for me to do right now.",
  str_homestory_817601001_41_dialog_content = "Ah, I better quit talking and resume my training!",
  str_homestory_817601001_42_dialog_content = "Bye, PlayerName.",
  str_homestory_817601001_43_dialog_content = "I'll send you postcards when I start going around treating people!",
  str_homestory_817601001_44_dialog_content = "Heh, still in a hurry as usual.",
  str_homestory_817601001_45_dialog_content = "I look forward to that day. You can do it, Beretta.",
  str_homestory_817501001_0_dialog_content = "Axelia?",
  str_homestory_817501001_1_dialog_content = "Hi, Axelia.",
  str_homestory_817501001_2_dialog_content = "Hello, PlayerName.",
  str_homestory_817501001_3_dialog_content = "Feeling better lately?",
  str_homestory_817501001_4_dialog_content = "I see you quite often in Cloud Gardens.",
  str_homestory_817501001_5_dialog_content = "Yes<sprite=emo_chidai size=60 />... once I'm done exploring Cloud Gardens however, I must return to the stasis chamber.",
  str_homestory_817501001_6_dialog_content = "But there are many things here that I find fascinating.",
  str_homestory_817501001_7_dialog_content = "Such as this drum that you frequently visit?",
  str_homestory_817501001_8_dialog_content = "*Coughs*",
  str_homestory_817501001_9_dialog_content = "Have you been watching me, PlayerName?",
  str_homestory_817501001_10_option_content = "Of course!",
  str_homestory_817501001_11_dialog_content = "The Cubes are always with you, so no mishaps should ever occur.",
  str_homestory_817501001_12_dialog_content = "But I feel I should be mindful of your condition.",
  str_homestory_817501001_13_dialog_content = "Thank you for caring.",
  str_homestory_817501001_14_option_content = "Nope",
  str_homestory_817501001_15_dialog_content = "It's just that every time I see you, you're always hanging around the drum.",
  str_homestory_817501001_16_dialog_content = "Hmm...",
  str_homestory_817501001_17_dialog_content = "I have a certain curiosity about such drums.",
  str_homestory_817501001_18_dialog_content = "Right, I remember you had an interest in music.",
  str_homestory_817501001_19_dialog_content = "But is there a reason that you like techno?",
  str_homestory_817501001_20_dialog_content = "Reason...",
  str_homestory_817501001_21_dialog_content = "Maybe it's because music like that has no lyrics. <sprite=emo_sikao size=60 />",
  str_homestory_817501001_22_dialog_content = "Lyrics?",
  str_homestory_817501001_23_dialog_content = "Yes.",
  str_homestory_817501001_24_dialog_content = "With no lyrics, listeners have more room for imagination.",
  str_homestory_817501001_25_dialog_content = "They can simply indulge themselves in the rhythm of the music without needing to invest too much of their emotions into some sort of story.",
  str_homestory_817501001_26_dialog_content = "That's a very Axelia-like answer indeed.",
  str_homestory_817501001_27_dialog_content = "Even though Father would scoff at the thought, I think that compared to other music...",
  str_homestory_817501001_28_dialog_content = "Techno epitomizes the rational fusion of creativity and straightforward musical notes.",
  str_homestory_817501001_29_dialog_content = "You know, it does make sense when you put it that way.",
  str_homestory_817501001_30_dialog_content = "This kind of music doesn't seem to evoke any strong emotions in me...",
  str_homestory_817501001_31_dialog_content = "Yes.",
  str_homestory_817501001_32_dialog_content = "So...",
  str_homestory_817501001_33_dialog_content = "Do you hang around the drum because techno music usually has drum beats?",
  str_homestory_817501001_34_dialog_content = "Or are you trying to incorporate drum sounds into the rhythm?",
  str_homestory_817501001_35_dialog_content = "I just want to listen to their sounds more.",
  str_homestory_817501001_36_dialog_content = "But you've given me an idea.",
  str_homestory_817501001_37_dialog_content = "I shall continue to visit in the future.",
  str_homestory_817501001_38_dialog_content = "Sure! Let me know if there's anything else you need.",
  str_homestory_817501001_39_dialog_content = "Thank you, PlayerName.",
  str_homestory_805401001_0_dialog_content = "Nadine?",
  str_homestory_805401001_1_dialog_content = "PlayerName!",
  str_homestory_805401001_2_dialog_content = "Why are you standing here all by yourself?",
  str_homestory_805401001_3_dialog_content = "Why aren't you inside the dorms with the others, or fishing somewhere nearby?",
  str_homestory_805401001_4_dialog_content = "Because I have to finish my job!",
  str_homestory_805401001_5_dialog_content = "Your job?",
  str_homestory_805401001_6_dialog_content = "That's right. As Cloud Gardens' first Nightwatch...",
  str_homestory_805401001_7_dialog_content = "it's my duty to be vigilant during every shift!",
  str_homestory_805401001_8_dialog_content = "Hey, wait a minute—",
  str_homestory_805401001_9_dialog_content = "I don't recall asking you to be the Nightwatch for Cloud Gardens <sprite=emo_yueliang size=60 />.",
  str_homestory_805401001_10_dialog_content = "You invited me to hang out in Cloud Gardens.",
  str_homestory_805401001_11_dialog_content = "You provided lodging, food, and so many fun things...",
  str_homestory_805401001_12_dialog_content = "I'm incredibly happy!",
  str_homestory_805401001_13_dialog_content = "I've never thought I would get to be the close friend of a celebrity like you.",
  str_homestory_805401001_14_dialog_content = "Much less leaving Lumopolis for somewhere as remote as Cloud Gardens.",
  str_homestory_805401001_15_dialog_content = "But I don't have money or special skills... I don't know how to repay you.",
  str_homestory_805401001_16_dialog_content = "It seems all I know is to be a Nightwatch.",
  str_homestory_805401001_17_dialog_content = "So I decided that this is how I'll show my gratitude to you, PlayerName!",
  str_homestory_805401001_18_option_content = "Thank her",
  str_homestory_805401001_19_dialog_content = "Thank you, Nadine. It touches me to hear you say that.",
  str_homestory_805401001_20_dialog_content = "But I can't have my guests working here for me.",
  str_homestory_805401001_21_option_content = "Comfort her",
  str_homestory_805401001_22_dialog_content = "Your happiness is the best payback for me!",
  str_homestory_805401001_23_dialog_content = "You really don't have to push yourself so much.",
  str_homestory_805401001_24_dialog_content = "No worries, I'm used to it. It's not hard for me.",
  str_homestory_805401001_25_dialog_content = "Besides...",
  str_homestory_805401001_26_dialog_content = "Cloud Gardens is gorgeous!",
  str_homestory_805401001_27_dialog_content = "And you always get furniture that suits our preferences…",
  str_homestory_805401001_28_dialog_content = "I've gradually come to feel at home here.",
  str_homestory_805401001_29_dialog_content = "Since this is home, you don't need to be so formal with me.",
  str_homestory_805401001_30_dialog_content = "Don't get hung up on your unpaid debts.",
  str_homestory_805401001_31_dialog_content = "Well, I feel a sense of duty here because I think of it as a home.",
  str_homestory_805401001_32_dialog_content = "I want to protect Cloud Gardens, our home, from all harm!",
  str_homestory_805401001_33_dialog_content = "To me, this is not just a job.",
  str_homestory_805401001_34_dialog_content = "It's an instinct and a duty!",
  str_homestory_805401001_35_dialog_content = "Oh, Nadine...",
  str_homestory_805401001_36_dialog_content = "Thank you, I suppose.",
  str_homestory_805401001_37_dialog_content = "I'll try to compensate you for this in some way.",
  str_homestory_805401001_38_dialog_content = "What?!",
  str_homestory_817801001_0_dialog_content = "Hey there, Vic.",
  str_homestory_817801001_1_dialog_content = "It's not every day we get to see you venturing outdoors!",
  str_homestory_817801001_2_dialog_content = "Not in the mood for lying in bed drinking today?<sprite=emo_kun size=60 />",
  str_homestory_817801001_3_dialog_content = "Wow, is that really what you think of me?",
  str_homestory_817801001_4_dialog_content = "That hurts... I'm a master extrozoologist, you know...",
  str_homestory_817801001_5_dialog_content = "Whenever I'm in my room, I'm usually sorting through materials or working on my new book.",
  str_homestory_817801001_6_dialog_content = "I always have my mind on important matters—it's just that drinking helps to expand my mind!",
  str_homestory_817801001_7_dialog_content = "Oh, yeah? So, how's your new book going?",
  str_homestory_817801001_8_dialog_content = "Ahem... I do say, the environment here really is improving day by day.",
  str_homestory_817801001_9_dialog_content = "Well, that's one way to change the subject.",
  str_homestory_817801001_10_dialog_content = "No, no—do you know what I've been doing here?",
  str_homestory_817801001_11_dialog_content = "Hmm... Apart from walking around in a daze?",
  str_homestory_817801001_12_dialog_content = "...",
  str_homestory_817801001_13_dialog_content = "I'm investigating the species and quantities of lifeforms in your forest.",
  str_homestory_817801001_14_dialog_content = "What are you doing that for?",
  str_homestory_817801001_15_dialog_content = "Don't underestimate the significance of this information!",
  str_homestory_817801001_16_dialog_content = "It may reveal phenomena of great importance.",
  str_homestory_817801001_17_dialog_content = "For example, it will tell us which kinds of lifeforms are suited to the environment here,",
  str_homestory_817801001_18_dialog_content = "the symbiotic interactions between the animals and plants here, and so on.",
  str_homestory_817801001_19_dialog_content = "You know what, it only just occurred to me<sprite=emo_wuzui size=60 />—",
  str_homestory_817801001_20_dialog_content = "This place is perfect for investigation and research!",
  str_homestory_817801001_21_dialog_content = "I plan to introduce some wondrous beasts here.",
  str_homestory_817801001_22_dialog_content = "That way, my book will have more...",
  str_homestory_817801001_23_dialog_content = "Wait... You wanna do what?",
  str_homestory_817801001_24_dialog_content = "Huh? Gather information and write it in my book...?",
  str_homestory_817801001_25_dialog_content = "No, I mean the other thing.",
  str_homestory_817801001_26_dialog_content = "You want to raise wondrous beasts in the forest?",
  str_homestory_817801001_27_dialog_content = "I gave you so many rooms to yourself already, that's not enough!?",
  str_homestory_817801001_28_dialog_content = "How's that anywhere remotely near the same thing?",
  str_homestory_817801001_29_dialog_content = "Artificial indoor scenery cannot compare to the real environments of the outside world.",
  str_homestory_817801001_30_dialog_content = "Animal behavior can only be observed in its truest state when the subject is in its natural habitat.",
  str_homestory_817801001_31_dialog_content = "That's not my point!",
  str_homestory_817801001_32_dialog_content = "You brought so many wondrous beasts onto the Colossus already; I've received a lot of complaints from the others, you know!",
  str_homestory_817801001_33_dialog_content = "Not to mention, you haven't found me a solution for the constant wondrous beast shrieks waking everyone up early in the morning.",
  str_homestory_817801001_34_dialog_content = "And you never get around to cleaning up all the scat and hair they leave all over the place.",
  str_homestory_817801001_35_dialog_content = "Now you want to make even more trouble for me!?",
  str_homestory_817801001_36_dialog_content = "You're so cold, PlayerName.",
  str_homestory_817801001_37_dialog_content = "How could you think this troublesome?",
  str_homestory_817801001_38_dialog_content = "Think about the contribution this will make to wondrous beast organizations across the continent!",
  str_homestory_817801001_39_dialog_content = "You're being ridiculous!<sprite=emo_shengqi size=60 />",
  str_homestory_817801001_40_dialog_content = "You're not allowed to bring your extrozoological havoc to this forest, and that's the end of it.",
  str_homestory_817801001_41_dialog_content = "The grasslands, valleys, and rivers are all off-limits, too!",
  str_homestory_817801001_42_dialog_content = "Sigh... Fine.",
  str_homestory_817801001_43_dialog_content = "Really, young people nowadays have no patience for their elders.",
  str_homestory_817701001_0_dialog_content = "Goldie!",
  str_homestory_817701001_1_dialog_content = "Ah, I finally found you, Goldie! <sprite=emo_yaosu size=60 />",
  str_homestory_817701001_2_dialog_content = "PlayerName, I just sang my new song on stage.",
  str_homestory_817701001_3_dialog_content = "Oh, I'm so nervous. I wonder if everyone liked it...",
  str_homestory_817701001_4_dialog_content = "What did you think of it?",
  str_homestory_817701001_5_dialog_content = "It sounded amazing!",
  str_homestory_817701001_6_dialog_content = "I'm certain everyone loved it!",
  str_homestory_817701001_7_dialog_content = "Heehee... Thanks. I guess I can rest easy now.",
  str_homestory_817701001_8_dialog_content = "To be honest, there's something on my mind right now.",
  str_homestory_817701001_9_dialog_content = "I was hoping you could give me some advice.",
  str_homestory_817701001_10_dialog_content = "What's up? I rarely see you conflicted.",
  str_homestory_817701001_11_dialog_content = "It's about the lead single in my new album...",
  str_homestory_817701001_12_dialog_content = "There's a song written in my usual style, full of sunshine <sprite=emo_taiyang size=60 /> and positivity.",
  str_homestory_817701001_13_dialog_content = "Then there's this other cooler-sounding <sprite=emo_mojing size=60 /> song I'm thinking of replacing it with, in an attempt to try something new.",
  str_homestory_817701001_14_dialog_content = "Do you think I need to replace it, PlayerName?",
  str_homestory_817701001_15_option_content = "You should do it.",
  str_homestory_817701001_16_dialog_content = "It's good to try a new style once in a while!",
  str_homestory_817701001_17_option_content = "There's no need to replace it.",
  str_homestory_817701001_18_dialog_content = "Right, I can handle my familiar style much more confidently!",
  str_homestory_817701001_19_dialog_content = "However, it all depends on the theme of the album as a whole, right?",
  str_homestory_817701001_20_dialog_content = "Right! The theme of the new album is \"Growing Pains.\"",
  str_homestory_817701001_21_dialog_content = "The company spent a fortune to publish this album!",
  str_homestory_817701001_22_dialog_content = "What does your agent think?",
  str_homestory_817701001_23_dialog_content = "My agent says I don't need to change a thing.",
  str_homestory_817701001_24_dialog_content = "Because some of my fans might not be receptive to a new style...",
  str_homestory_817701001_25_dialog_content = "It's a somewhat conservative suggestion.",
  str_homestory_817701001_26_dialog_content = "But I think your fans prefer you to be true to yourself.",
  str_homestory_817701001_27_dialog_content = "Whether you change or not, your fans will support you like they always have!",
  str_homestory_817701001_28_dialog_content = "So, you might as well just follow your heart.",
  str_homestory_817701001_29_dialog_content = "Choose a style that you really like.",
  str_homestory_817701001_30_dialog_content = "Alright!",
  str_homestory_817701001_31_dialog_content = "That settles it! I'll choose—",
  str_homestory_817701001_32_dialog_content = "You're going to choose—",
  str_homestory_817701001_33_dialog_content = "My positive sunshine song!",
  str_homestory_817701001_34_dialog_content = "Eh?",
  str_homestory_817701001_35_dialog_content = "Because that's who I really am!",
  str_homestory_817701001_36_dialog_content = "That's what suits me best!",
  str_homestory_817701001_37_dialog_content = "I guess your agent does know you, after all...",
  str_homestory_818001001_0_dialog_content = "Brandy?",
  str_homestory_818001001_1_dialog_content = "Hmm...? Should I put this light stick here? Is that strange?",
  str_homestory_818001001_2_dialog_content = "What are you doing?",
  str_homestory_818001001_3_dialog_content = "Hey! You're just in time!",
  str_homestory_818001001_4_dialog_content = "Help me take a look. Should I put this light stick on the left or the right?",
  str_homestory_818001001_5_option_content = "The left.",
  str_homestory_818001001_6_dialog_content = "It would look better on the right.",
  str_homestory_818001001_7_option_content = "It's all the same.",
  str_homestory_818001001_8_dialog_content = "You're right. I'll just put it on the right.",
  str_homestory_818001001_9_dialog_content = "...",
  str_homestory_818001001_10_dialog_content = "What are you doing this for?",
  str_homestory_818001001_11_dialog_content = "I'm taking pictures for my \"Goldie Takes Cloud Gardens By Storm\" article.",
  str_homestory_818001001_12_dialog_content = "Right now, I'm taking shots of Goldie's fan merchandise.",
  str_homestory_818001001_13_dialog_content = "There are light sticks, neon signs, stickers, mini portrait cards...",
  str_homestory_818001001_14_dialog_content = "There's even a T-shirt with Goldie's face on it. It's so cute!",
  str_homestory_818001001_15_dialog_content = "Come to think of it. I feel like I'm still lacking a life-size Goldie standee.",
  str_homestory_818001001_16_dialog_content = "I just need to get my hands on one and sneak it back to my room... <sprite=emo_sikao size=60 />",
  str_homestory_818001001_17_dialog_content = "Oh no! Shouldn't there be a life-size Goldie standee around here somewhere!?",
  str_homestory_818001001_18_dialog_content = "Could it have been snatched away by some filthy-minded fan?",
  str_homestory_818001001_19_dialog_content = "Drat! How could anyone do such a thing?",
  str_homestory_818001001_20_dialog_content = "You just said that was exactly what you wanted to do...",
  str_homestory_818001001_21_dialog_content = "Forget it. I'll just take these pictures first.",
  str_homestory_818001001_22_dialog_content = "She's standing right next to you, why do you need to take photos of merch?",
  str_homestory_818001001_23_dialog_content = "I don't think you're going about this the right way.",
  str_homestory_818001001_24_dialog_content = "You don't understand—this is a way of adding a degree of contrast. It can fully express...",
  str_homestory_818001001_25_dialog_content = "Eh? Wait a second!",
  str_homestory_818001001_26_dialog_content = "What's wrong?",
  str_homestory_818001001_27_dialog_content = "That clump of shadows from the trees is hitting the neon sign in just the right spot.",
  str_homestory_818001001_28_dialog_content = "Light and shadows dancing across the board, livening up the scene with the silhouette of the trees.",
  str_homestory_818001001_29_dialog_content = "This is the perfect time to take some pictures!",
  str_homestory_818001001_30_dialog_content = "What a shot! I've never seen such a perfect photo before!",
  str_homestory_818001001_31_dialog_content = "This is just the photo my news article needs!",
  str_homestory_818001001_32_dialog_content = "I think your news article needs a photo of the actual Goldie...",
  str_homestory_818001001_33_dialog_content = "I'm done! I'm gonna head back and develop these photos.",
  str_homestory_818001001_34_dialog_content = "By the way, I remember seeing something in the water on the way here. You should go take a look.",
  str_homestory_818001001_35_dialog_content = "You're not listening to me at all, are you...",
  str_homestory_818101001_0_dialog_content = "Zhong Xu?",
  str_homestory_818101001_1_dialog_content = "What are you looking at?",
  str_homestory_818101001_2_dialog_content = "Check out the shelf.",
  str_homestory_818101001_3_dialog_content = "What's so special about it? <sprite=emo_sikao size=60 />",
  str_homestory_818101001_4_dialog_content = "Wait, I see Yixin!",
  str_homestory_818101001_5_dialog_content = "He crawled onto the shelf while I wasn't paying attention.",
  str_homestory_818101001_6_dialog_content = "What a mischievous cat!",
  str_homestory_818101001_7_dialog_content = "Yimeng and Yinuo are on there too.",
  str_homestory_818101001_8_dialog_content = "They like the shelf that much?",
  str_homestory_818101001_9_dialog_content = "Probably because they like dark and narrow places.",
  str_homestory_818101001_10_dialog_content = "That makes sense. The shelf is layered, and very dark inside.",
  str_homestory_818101001_11_dialog_content = "This could serve as a new type of cat tower, maybe?",
  str_homestory_818101001_12_dialog_content = "Sounds logical.",
  str_homestory_818101001_13_dialog_content = "I shall get a craftsman to model one after this.",
  str_homestory_818101001_14_dialog_content = "Absolutely, you're welcome any time!",
  str_homestory_818101001_15_dialog_content = "I never thought the shelf could be used this way.",
  str_homestory_818101001_16_dialog_content = "Thank you.",
  str_homestory_818101001_17_dialog_content = "Will this inconvenience you?",
  str_homestory_818101001_18_option_content = "Not at all!",
  str_homestory_818101001_19_option_content = "A little.",
  str_homestory_818101001_20_dialog_content = "I'm sorry, I'll make sure to talk to them about it.",
  str_homestory_818101001_21_dialog_content = "Now the question is... how do we get them out?",
  str_homestory_818101001_22_dialog_content = "They're sleeping so soundly.",
  str_homestory_818101001_23_dialog_content = "Usually they come over when I call their names, but they're not very responsive today.",
  str_homestory_818101001_24_dialog_content = "Maybe it's because they know you too well.",
  str_homestory_818101001_25_dialog_content = "What do you mean? <sprite=emo_wuzui size=60 />",
  str_homestory_818101001_26_dialog_content = "Usually you call their names when you need them to do something.",
  str_homestory_818101001_27_dialog_content = "Today, you're just trying to get them off the shelf.",
  str_homestory_818101001_28_dialog_content = "So they chose to ignore you.",
  str_homestory_818101001_29_dialog_content = "These cats are very smart!",
  str_homestory_818101001_30_dialog_content = "... This shelf appears to have far more potent power than I imagined.",
  str_homestory_818101001_31_dialog_content = "I must prepare a replica for them.",
  str_homestory_818101001_32_dialog_content = "What are you going to do about the cats?",
  str_homestory_818101001_33_dialog_content = "I'll wait for them to wake up, I suppose.",
  str_homestory_818101001_34_dialog_content = "A resounding victory for the cats!",
  str_homestory_818101001_35_dialog_content = "What a wonderful view, though.",
  str_homestory_818101001_36_dialog_content = "Those who don't know what's going on probably think Zhong Xu is pondering over something philosophical again...",
  str_homestory_818301001_0_dialog_content = "Liqing?",
  str_homestory_818301001_1_dialog_content = "Where did it go...?",
  str_homestory_818301001_2_dialog_content = "What are you up to?",
  str_homestory_818301001_3_dialog_content = "H-Hello, PlayerName.",
  str_homestory_818301001_4_dialog_content = "I'm looking for Tinytail. Have you seen him?",
  str_homestory_818301001_5_dialog_content = "No, what's going on?",
  str_homestory_818301001_6_dialog_content = "He's slacking off again, that's what's going on! <sprite=emo_shengqi size=60 />",
  str_homestory_818301001_7_dialog_content = "I took him into the garden to pick some herbs.",
  str_homestory_818301001_8_dialog_content = "And then he was gone, just like that!",
  str_homestory_818301001_9_dialog_content = "There are herbs in Cloud Gardens?",
  str_homestory_818301001_10_dialog_content = "Of course.",
  str_homestory_818301001_11_dialog_content = "Good herbs are usually found where you least expect them.",
  str_homestory_818301001_12_dialog_content = "You just need a pair of good eyes. <sprite=emo_mojing size=60 />",
  str_homestory_818301001_13_dialog_content = "That totally sounds like something you'd say.",
  str_homestory_818301001_14_dialog_content = "By the way...",
  str_homestory_818301001_15_option_content = "How long have you been looking for him?",
  str_homestory_818301001_16_dialog_content = "Um, well, about thirty minutes...",
  str_homestory_818301001_17_dialog_content = "That's a long time.",
  str_homestory_818301001_18_dialog_content = "Actually, maybe... just ten minutes?",
  str_homestory_818301001_19_option_content = "What herbs were you picking?",
  str_homestory_818301001_20_dialog_content = "Um, j-just... herbs?",
  str_homestory_818301001_21_dialog_content = "Why do you keep stammering?",
  str_homestory_818301001_22_dialog_content = "I'm not!",
  str_homestory_818301001_23_dialog_content = "Could it be that...",
  str_homestory_818301001_24_dialog_content = "You were slacking off too?",
  str_homestory_818301001_25_dialog_content = "N-N-Nope. Not possible. Not a chance.",
  str_homestory_818301001_26_dialog_content = "I came with Tinytail to pick herbs!",
  str_homestory_818301001_27_dialog_content = "But...",
  str_homestory_818301001_28_dialog_content = "But...?",
  str_homestory_818301001_29_dialog_content = "It's too comfortable here...",
  str_homestory_818301001_30_dialog_content = "I... might have <sprite=emo_kun size=60 /> taken a nap. Just for a moment!",
  str_homestory_818301001_31_dialog_content = "And Tinytail was gone when I woke up.",
  str_homestory_818301001_32_dialog_content = "Haha, so both of you are slackers, I see.",
  str_homestory_818301001_33_dialog_content = "No, I'm not!",
  str_homestory_818201001_0_dialog_content = "What are you doing?",
  str_homestory_818201001_1_dialog_content = "I'm reveling in the feeling of the water breathing.",
  str_homestory_818201001_2_dialog_content = "I don't really get it, but... sounds cool.",
  str_homestory_818201001_3_dialog_content = "Have you felt water breathing before?",
  str_homestory_818201001_4_option_content = "Yes.",
  str_homestory_818201001_5_dialog_content = "Really? What does it feel like?",
  str_homestory_818201001_6_dialog_content = "Cold, refreshing, thirst-quenching.",
  str_homestory_818201001_7_dialog_content = "That's the flavor, not its breath.",
  str_homestory_818201001_8_option_content = "No.",
  str_homestory_818201001_9_dialog_content = "If you want to learn, I can teach you.",
  str_homestory_818201001_10_dialog_content = "Okay.",
  str_homestory_818201001_11_dialog_content = "Let's start now.",
  str_homestory_818201001_12_dialog_content = "Now? I don't have my swimming trunks...",
  str_homestory_818201001_13_dialog_content = "We can practice the basic movements onshore first.",
  str_homestory_818201001_14_dialog_content = "Stand straight, take a deep breath and feel the water flowing.",
  str_homestory_818201001_15_dialog_content = "That's not too hard. I think I can do that.",
  str_homestory_818201001_16_dialog_content = "*Inhale*",
  str_homestory_818201001_17_dialog_content = "*Exhale*",
  str_homestory_818201001_18_dialog_content = "How long do I have to stand like this?",
  str_homestory_818201001_19_dialog_content = "10,000 hours.",
  str_homestory_818201001_20_dialog_content = "10,000 hours?!",
  str_homestory_818201001_21_dialog_content = "It takes 10,000 hours to become extraordinary at something.",
  str_homestory_818201001_22_dialog_content = "I know, but this is a bit monotonous... <sprite=emo_xinsui size=60 />",
  str_homestory_818201001_23_dialog_content = "You can give up now if you want to.",
  str_homestory_818201001_24_dialog_content = "There are plenty of fun things, but the road to success is generally not a fun one.",
  str_homestory_818201001_25_dialog_content = "Sorry, I'll work harder.",
  str_homestory_818201001_26_dialog_content = "Did you undergo similar training to become so good in the water?",
  str_homestory_818201001_27_dialog_content = "No, I was born with the ability.",
  str_homestory_818201001_28_dialog_content = "???",
  str_homestory_818201001_29_dialog_content = "So are you just trying to trick me into standing here for 10,000 hours?",
  str_homestory_818201001_30_dialog_content = "No, a Lin elder taught me this when I was first learning to swim.",
  str_homestory_818201001_31_dialog_content = "But I was born with the ability to resonate with water, so I didn't have to practice.",
  str_homestory_818201001_32_dialog_content = "Well, if a Lin elder said it, it's probably true.",
  str_homestory_818201001_33_dialog_content = "Just keep standing...",
  str_homestory_818201001_34_dialog_content = "My legs hurt, let me take a break. <sprite=emo_tanqi size=60 />",
  str_homestory_818201001_35_dialog_content = "Then we can stop here.",
  str_homestory_818201001_36_dialog_content = "Huh? But the Lin elder said...",
  str_homestory_818201001_37_dialog_content = "The elder couldn't swim, so he probably just made it up.",
  str_homestory_818201001_38_dialog_content = "!!!",
  str_homestory_818201001_39_dialog_content = "I considered it for a minute. I don't think you can resonate with water even if you do stand for 10,000 hours.",
  str_homestory_818201001_40_dialog_content = "Some things you just need to be born with. You can't force them.",
  str_homestory_818201001_41_dialog_content = "You should have said that earlier!",
  str_homestory_818201001_42_dialog_content = "You were so focused, I didn't want to interrupt.",
  str_homestory_818201001_43_dialog_content = "You...",
  str_homestory_818201001_44_dialog_content = "Ah... my legs are cramping...",
  str_homestory_818201001_45_dialog_content = "I'll carry you on my back.",
  str_homestory_818201001_46_dialog_content = "No, it's fine...",
  str_homestory_818201001_47_dialog_content = "See you later, then.",
  str_homestory_818201001_48_dialog_content = "Um, wait, can you please get down?",
  str_homestory_816001001_0_dialog_content = "Michael?",
  str_homestory_816001001_1_dialog_content = "What are you looking at?",
  str_homestory_816001001_2_dialog_content = "(Ah, PlayerName.)",
  str_homestory_816001001_3_dialog_content = "(I'm admiring the candlestick.)",
  str_homestory_816001001_4_dialog_content = "You must really like it. Do you want it?",
  str_homestory_816001001_5_dialog_content = "(No, please allow me to pay. How much is it?)",
  str_homestory_816001001_6_dialog_content = "(Is 1,000 Nightium enough? <sprite=emo_baiyebi size=60 />)",
  str_homestory_816001001_7_dialog_content = "No, you don't need to pay that much.",
  str_homestory_816001001_8_dialog_content = "In fact, I won't sell it to you if you pay.",
  str_homestory_816001001_9_dialog_content = "(How come?)",
  str_homestory_816001001_10_dialog_content = "Why do you look so dejected?",
  str_homestory_816001001_11_dialog_content = "Right, you like to collect trinkets, right?",
  str_homestory_816001001_12_dialog_content = "I remember seeing all kinds of wonderful things in your room.",
  str_homestory_816001001_13_dialog_content = "(Is my hobby weird?)",
  str_homestory_816001001_14_option_content = "(Confirm)",
  str_homestory_816001001_15_dialog_content = "A lot of the stuff looked broken, yet you keep them anyway.",
  str_homestory_816001001_16_dialog_content = "I guess it's... eccentric.",
  str_homestory_816001001_17_option_content = "(Deny)",
  str_homestory_816001001_18_dialog_content = "Everyone's got their hobbies, I don't think it's weird.",
  str_homestory_816001001_19_dialog_content = "I think you just happen to like collecting a wide variety of things.",
  str_homestory_816001001_20_dialog_content = "(I just find them interesting, so I want to collect them.)",
  str_homestory_816001001_21_dialog_content = "(But I want to buy the candlestick for other reasons.)",
  str_homestory_816001001_22_dialog_content = "What reason?",
  str_homestory_816001001_23_dialog_content = "(The candle is flammable, and I'm afraid it will start a fire.<sprite=emo_nuhuo size=60 />)",
  str_homestory_816001001_24_dialog_content = "(Many disasters begin as inconsequential, small dangers.)",
  str_homestory_816001001_25_dialog_content = "(Is that hard to understand?)",
  str_homestory_816001001_26_dialog_content = "No, not really.",
  str_homestory_816001001_27_dialog_content = "So you're concerned about my safety?",
  str_homestory_816001001_28_dialog_content = "(It's my duty to protect Lumopolis.)",
  str_homestory_816001001_29_dialog_content = "(You helped me a lot, so protecting you is also important.)",
  str_homestory_816001001_30_dialog_content = "You've helped me a lot, too.",
  str_homestory_816001001_31_dialog_content = "You're not just saying that as an excuse to buy the candlestick, are you?",
  str_homestory_816001001_32_dialog_content = "(Of course not!)",
  str_homestory_816001001_33_dialog_content = "(You should be treated with respect.)",
  str_homestory_816001001_34_dialog_content = "Why are you blushing?",
  str_homestory_816001001_35_dialog_content = "(It's because... of the candlelight.)",
  str_homestory_816001001_36_dialog_content = "(By the way, I saw something shiny in the river.)",
  str_homestory_816001001_37_dialog_content = "(Just like the candlelight.)",
  str_homestory_816001001_38_dialog_content = "You keep changing the topic...",
  str_homestory_818401001_0_dialog_content = "Hey, Jeriah.",
  str_homestory_818401001_1_dialog_content = "...",
  str_homestory_818401001_2_dialog_content = "Jeriah? Hello...?",
  str_homestory_818401001_3_dialog_content = "Hm? Ah, the little Caelestite.",
  str_homestory_818401001_4_dialog_content = "What are you doing? You seem really focused.",
  str_homestory_818401001_5_dialog_content = "Right... I was just daydreaming.",
  str_homestory_818401001_6_dialog_content = "Daydreaming?",
  str_homestory_818401001_7_dialog_content = "Did I tell you that I have been to ruins near here before?",
  str_homestory_818401001_8_dialog_content = "At that time, you had yet to return.",
  str_homestory_818401001_9_dialog_content = "There were only ruins and Eclipsites here <sprite=emo_kulou size=60 />.",
  str_homestory_818401001_10_dialog_content = "Man, I don't even wanna talk about how much time and effort it took to clean up this place!",
  str_homestory_818401001_11_dialog_content = "Right. That couldn't have been easy.",
  str_homestory_818401001_12_dialog_content = "Speaking of which, I wanted to ask you something.",
  str_homestory_818401001_13_dialog_content = "Do you think renovating Cloud Gardens was a meaningful endeavor?",
  str_homestory_818401001_14_dialog_content = "It's beautiful right now, but if it were to come under attack, or a hundred years from now when you're gone...",
  str_homestory_818401001_15_dialog_content = "everything here could revert back into ruins.",
  str_homestory_818401001_16_option_content = "It was meaningful.",
  str_homestory_818401001_17_dialog_content = "At least now, we can have all the fun we want here.",
  str_homestory_818401001_18_dialog_content = "If any enemies come, I'll drive them all away.",
  str_homestory_818401001_19_dialog_content = "If I can't take care of this place, I'll leave it to someone I can trust.",
  str_homestory_818401001_20_dialog_content = "There will always be a way!",
  str_homestory_818401001_21_dialog_content = "You certainly are optimistic.",
  str_homestory_818401001_22_option_content = "Probably not.",
  str_homestory_818401001_23_dialog_content = "It may have been meaningless if our purpose was to make Cloud Gardens exist forever.",
  str_homestory_818401001_24_dialog_content = "I'm aware of the limits of my abilities...",
  str_homestory_818401001_25_dialog_content = "But at least we're happy, for now.",
  str_homestory_818401001_26_dialog_content = "That's enough for me!",
  str_homestory_818401001_27_dialog_content = "This idea of living in the present is commendable.",
  str_homestory_818401001_28_dialog_content = "When I first came to Eraveil, I thought it was a very sad place indeed.",
  str_homestory_818401001_29_dialog_content = "Overturned tableware, half-opened doors, messy piles of clothes...",
  str_homestory_818401001_30_dialog_content = "They reminded me that once upon a time, ordinary people had enjoyed a happy life here.",
  str_homestory_818401001_31_dialog_content = "Those days... poof. Like dandelions <sprite=emo_pugongying size=60 />, they were blown away in the wind.",
  str_homestory_818401001_32_dialog_content = "Right...",
  str_homestory_818401001_33_dialog_content = "But dandelions carry seeds of hope to faraway lands.",
  str_homestory_818401001_34_dialog_content = "All this could never be meaningless!",
  str_homestory_818401001_35_dialog_content = "True. You're like a little seed yourself, come back to sprout again.",
  str_homestory_818401001_36_dialog_content = "Talking with you is always a unique experience.",
  str_homestory_818401001_37_dialog_content = "Hehe, I'm flattered.",
  str_homestory_818401001_38_dialog_content = "Hmm... In return, let me tell you something you may be interested in.",
  str_homestory_818401001_39_dialog_content = "When I was at the river earlier, I saw something shining in the water.",
  str_homestory_818401001_40_dialog_content = "Maybe you can go and have a look. Think of it as an adventure!",
  str_homestory_818401001_41_dialog_content = "Sounds interesting... Thank you, Jeriah!",
  str_homestory_818501001_0_dialog_content = "What's the matter?",
  str_homestory_818501001_1_dialog_content = "I just sat in one of those spinning coffee cups, and now I'm feeling a bit dizzy <sprite=emo_xuanyun size=60 />...",
  str_homestory_818501001_2_dialog_content = "Dizzy? Do the machines need adjusting?",
  str_homestory_818501001_3_dialog_content = "I remember the speed was already set to the slowest setting. I'll go check it out later.",
  str_homestory_818501001_4_dialog_content = "Those things are super dangerous! Please be careful!",
  str_homestory_818501001_5_dialog_content = "Dangerous?",
  str_homestory_818501001_6_dialog_content = "Aren't those things meant for children aged four and up?",
  str_homestory_818501001_7_dialog_content = "I doubt they're suitable even for children aged twenty years and up...",
  str_homestory_818501001_8_dialog_content = "Some people just can't get used to the spinning sensation. It's perfectly normal.",
  str_homestory_818501001_9_dialog_content = "A good rest should help.",
  str_homestory_818501001_10_dialog_content = "Okay. I'm gonna go rest. I still have to deliver letters to the north later...",
  str_homestory_818501001_11_dialog_content = "Wait. North... South...",
  str_homestory_818501001_12_dialog_content = "Oh, no! I can't tell my directions apart anymore!",
  str_homestory_818501001_13_dialog_content = "I used to be so proud of my sense of direction! How can this be!?",
  str_homestory_818501001_14_dialog_content = "*sobbing* <sprite=emo_daku size=60 />If I can't even deliver letters, what would become of my career?",
  str_homestory_818501001_15_dialog_content = "Uh, that's a little dramatic...",
  str_homestory_818501001_16_dialog_content = "PlayerName, can you tell me which way is north?",
  str_homestory_818501001_17_option_content = "Go left",
  str_homestory_818501001_18_dialog_content = "Is it? I can't tell at all...",
  str_homestory_818501001_19_option_content = "I have no idea either",
  str_homestory_818501001_20_dialog_content = "E-Even you...",
  str_homestory_818501001_21_dialog_content = "Are we gonna end up trapped here?",
  str_homestory_818501001_22_dialog_content = "???",
  str_homestory_818501001_23_dialog_content = "Does it count as being trapped when you're still in your own home?",
  str_homestory_818501001_24_dialog_content = "Now even I'm not really sure where I am...",
  str_homestory_818501001_25_dialog_content = "The Courier Union code says we must always maintain a sense of direction.",
  str_homestory_818501001_26_dialog_content = "Many couriers end up in dangerous situations with nowhere to run just because they got lost.",
  str_homestory_818501001_27_dialog_content = "I think that kind of thing only happens when you're out in the wilderness, like a huge forest.",
  str_homestory_818501001_28_dialog_content = "We're in Cloud Gardens! You see the door?",
  str_homestory_818501001_29_dialog_content = "It's right over there. Just take a few steps and you'll be out of here.",
  str_homestory_818501001_30_dialog_content = "But what if I go out there into the wilderness and wind up as dizzy as I am right now?",
  str_homestory_818501001_31_dialog_content = "Are there coffee cups in the wilderness?",
  str_homestory_818501001_32_dialog_content = "Oh, right...",
  str_homestory_818501001_33_dialog_content = "And even if there are, just don't ride in them.",
  str_homestory_818501001_34_dialog_content = "Yeah! You're so smart!",
  str_homestory_818501001_35_dialog_content = "Hah, sure...",
  str_homestory_818501001_36_dialog_content = "When I go back, I'm going to add a new rule to the Courier Union code—",
  str_homestory_818501001_37_dialog_content = "\"If you encounter spinning coffee cups in the wilderness, don't sit in them!\"",
  str_homestory_818501001_38_dialog_content = "The chances of encountering spinning coffee cups in the wilderness should be quite low...",
  str_homestory_818501001_39_dialog_content = "\"—Wisdom courtesy of the Caelestite.\"",
  str_homestory_818501001_40_dialog_content = "!!!",
  str_homestory_818501001_41_dialog_content = "How much do you want me to pay you to keep my name out of this!?",
  str_homestory_818501001_42_dialog_content = "What? This is really useful advice! Anyway, I'm off...",
  str_homestory_818501001_43_dialog_content = "Oh, great... I'm going to be the laughingstock of the Courier Union...<sprite=emo_tanqi size=60 />",
  str_homestory_802901001_0_dialog_content = "Gabriel?",
  str_homestory_802901001_1_dialog_content = "What do you think you're doing?",
  str_homestory_802901001_2_dialog_content = "I'm currently taking a nap under the tree, <sprite=emo_kun size=60 />, just casually taking in the tree's breath.",
  str_homestory_802901001_3_dialog_content = "The tree's breath?",
  str_homestory_802901001_4_dialog_content = "That's right... Trees are living things too.",
  str_homestory_802901001_5_dialog_content = "I can sense the pattern of its steady breathing. Can you feel it, PlayerName?",
  str_homestory_802901001_6_option_content = "Admit",
  str_homestory_802901001_7_dialog_content = "When its leaves shake, it feels like it's breathing faster.",
  str_homestory_802901001_8_dialog_content = "I think that's just the wind...",
  str_homestory_802901001_9_option_content = "Deny",
  str_homestory_802901001_10_dialog_content = "Oh, I can't sense anything...",
  str_homestory_802901001_11_dialog_content = "It looks like you're the only one with this special ability to sense plants, Gabriel...",
  str_homestory_802901001_12_dialog_content = "Every tree is different, just like every person.",
  str_homestory_802901001_13_dialog_content = "As long as you feel with your heart... you can know their inner world.",
  str_homestory_802901001_14_dialog_content = "For example, this tree's breathing is rather labored... It appears to be a little sick...",
  str_homestory_802901001_15_dialog_content = "I guess that must be why its leaves are a little yellow compared to the other trees.",
  str_homestory_802901001_16_dialog_content = "It does look a little lifeless.",
  str_homestory_802901001_17_dialog_content = "The trees around here are really flourishing. They're blocking out the sunlight... <sprite=emo_taiyang size=60 />",
  str_homestory_802901001_18_dialog_content = "It seems this little one is having trouble carrying out photosynthesis!",
  str_homestory_802901001_19_dialog_content = "So, do you think we need to move this tree somewhere else?",
  str_homestory_802901001_20_dialog_content = "No, plants have their own ways of doing things.",
  str_homestory_802901001_21_dialog_content = "This tree didn't work hard enough to grow tall, so the other trees stole its sunshine...",
  str_homestory_802901001_22_dialog_content = "It needs to rely on itself to grow bigger and stronger... We shouldn't spoil it too much!",
  str_homestory_802901001_23_dialog_content = "I see... That makes a lot of sense, Gabriel!",
  str_homestory_802901001_24_dialog_content = "Heh, I was worried that it might be too difficult for you to understand, PlayerName...",
  str_homestory_802901001_25_dialog_content = "I understand! But, what I'm actually a little surprised about is—",
  str_homestory_802901001_26_dialog_content = "You usually look like you're always walking around in a daze, Gabriel, but today you seem so serious.",
  str_homestory_802901001_27_dialog_content = "I think it's more accurate to say that I always act in accordance with my surroundings...",
  str_homestory_802901001_28_dialog_content = "Plants also have their destinies...",
  str_homestory_802901001_29_dialog_content = "Destinies...?",
  str_homestory_802901001_30_dialog_content = "Right. Meeting you under this tree—is part of the tree's destiny.",
  str_homestory_802901001_31_dialog_content = "Speaking of which, when I was walking along the river just now, I saw something shining...",
  str_homestory_802901001_32_dialog_content = "Could you see what it was?",
  str_homestory_802901001_33_dialog_content = "Well, I was just planning on stopping by the woods to take a little nap!",
  str_homestory_802901001_34_dialog_content = "The fact that I didn't check what it was in the river was also part of destiny's plan!",
  str_homestory_802901001_35_dialog_content = "I think I understand what you mean about destiny...",
  str_homestory_818901001_0_dialog_content = "What are you doing, Leyn?",
  str_homestory_818901001_1_dialog_content = "Hey! Leyn!",
  str_homestory_818901001_2_dialog_content = "Chocolate liqueurs, fruity centers <sprite=emo_sikao size=60 />... Huh?",
  str_homestory_818901001_3_dialog_content = "Oh, hello.",
  str_homestory_818901001_4_dialog_content = "What are you looking at, Leyn? You seem so focused.",
  str_homestory_818901001_5_dialog_content = "Nothing really, I just saw this box of chocolates.",
  str_homestory_818901001_6_dialog_content = "Those are from Mooncrown Day.",
  str_homestory_818901001_7_dialog_content = "If you want to eat them, Leyn, help yourself!",
  str_homestory_818901001_8_dialog_content = "No, I don't want to eat them. I'm just interested in the production process.",
  str_homestory_818901001_9_dialog_content = "I often make chocolate desserts at home too.",
  str_homestory_818901001_10_dialog_content = "But I usually just use melted chocolate for decoration.",
  str_homestory_818901001_11_dialog_content = "I hadn't realized that desserts had come so far in terms of artistry.",
  str_homestory_818901001_12_dialog_content = "I say, do you like chocolate?",
  str_homestory_818901001_13_option_content = "I like it!",
  str_homestory_818901001_14_dialog_content = "In that case, as soon as I learn some new techniques, I'll let you have a try.",
  str_homestory_818901001_15_dialog_content = "It's a little early for you to be drinking chocolate liqueurs...",
  str_homestory_818901001_16_dialog_content = "I'll bring you some fruity ones, then.",
  str_homestory_818901001_17_option_content = "Not a fan...",
  str_homestory_818901001_18_dialog_content = "Oh... What a pity.",
  str_homestory_818901001_19_dialog_content = "Next time, let me bring you some other treats.",
  str_homestory_818901001_20_dialog_content = "If there's anything you'd like to eat, please let me know. Any time you wish.",
  str_homestory_818901001_21_dialog_content = "Sweet! Thank you, Leyn!",
  str_homestory_818901001_22_dialog_content = "Hmm...",
  str_homestory_818901001_23_dialog_content = "What's the matter? Why are you still staring at those chocolates?",
  str_homestory_818901001_24_dialog_content = "Do you... actually want to eat some?",
  str_homestory_818901001_25_dialog_content = "I-I'm just a little curious about what they might taste like! <sprite=emo_hanshui size=60 />",
  str_homestory_818901001_26_dialog_content = "I think I'll buy myself a box to carry out further research!",
  str_homestory_818901001_27_dialog_content = "Hey, why are you still being so polite?",
  str_homestory_818901001_28_dialog_content = "If you want to eat them, just eat them!",
  str_homestory_818901001_29_dialog_content = "Everyone needs to indulge themselves once in a while.",
  str_homestory_818901001_30_dialog_content = "I... erm...",
  str_homestory_818901001_31_dialog_content = "Thank you for your kindness. In that case, I'll just help myself...",
  str_homestory_818601001_0_dialog_content = "Tina?",
  str_homestory_818601001_1_dialog_content = "Why are you here?",
  str_homestory_818601001_2_dialog_content = "Hello there, PlayerName!",
  str_homestory_818601001_3_dialog_content = "This chair is extremely curious.",
  str_homestory_818601001_4_dialog_content = "You mean that beach chair?",
  str_homestory_818601001_5_dialog_content = "Right... So, this is a beach chair...",
  str_homestory_818601001_6_dialog_content = "To tell the truth, I don't know anything about the seaside. I spend most of my time in the Lumopolis Hall of Justice.",
  str_homestory_818601001_7_dialog_content = "Do you often go to the seaside, PlayerName?",
  str_homestory_818601001_8_option_content = "I go all the time.",
  str_homestory_818601001_9_dialog_content = "I often go to the seaside.",
  str_homestory_818601001_10_dialog_content = "The seaside is the best!",
  str_homestory_818601001_11_option_content = "Not really.",
  str_homestory_818601001_12_dialog_content = "Actually, no, I don't go often.",
  str_homestory_818601001_13_dialog_content = "But the seaside is pretty fun. I have some good memories of my time on the beach.",
  str_homestory_818601001_14_dialog_content = "I see!",
  str_homestory_818601001_15_dialog_content = "If I could go to the seaside with you, PlayerName, that would be swell!",
  str_homestory_818601001_16_dialog_content = "But I still have a lot of cases to deal with in the Hall of Justice. I'm terribly busy!",
  str_homestory_818601001_17_dialog_content = "Maybe we'll have a chance to go together in the future.",
  str_homestory_818601001_18_dialog_content = "But the swimsuits everyone wears at the beach... Are you sure you're okay with them?",
  str_homestory_818601001_19_dialog_content = "Swimsuits... I read about those in a book. They're quite skimpy<sprite=emo_qunzi size=60 />, aren't they?",
  str_homestory_818601001_20_dialog_content = "Right... The noble attire of Lumopolis might be a little too stuffy for the seaside...",
  str_homestory_818601001_21_dialog_content = "I fully understand that different clothes should be worn on different occasions, but I don't mind that at all.",
  str_homestory_818601001_22_dialog_content = "However, the elders may accuse me of abandoning their code of etiquette. The mere thought of their sneers gives me chills...",
  str_homestory_818601001_23_dialog_content = "*cough* You don't need to think that far into the future, Tina...",
  str_homestory_818601001_24_dialog_content = "After all, we don't even know when we'll get to go to the seaside...",
  str_homestory_818601001_25_dialog_content = "You're right!",
  str_homestory_818601001_26_dialog_content = "So... Do you want to try out that beach chair, or what?",
  str_homestory_818601001_27_dialog_content = "Yes! I want to give it a try!",
  str_homestory_818601001_28_dialog_content = "It's not as soft as my special recliner, but it's still very comfortable!",
  str_homestory_818601001_29_dialog_content = "This material makes it even more practical for the beach.",
  str_homestory_818601001_30_dialog_content = "Hey, Tina! Are you listening to me?",
  str_homestory_818601001_31_dialog_content = "She's fast asleep...",
  str_homestory_819001001_0_dialog_content = "Matthieu?",
  str_homestory_819001001_1_dialog_content = "You are just in time.",
  str_homestory_819001001_2_dialog_content = "This old restored pavilion is not too shabby, not too shabby at all... It's the perfect place to have a cup of tea and get stuck into a good book.",
  str_homestory_819001001_3_dialog_content = "But it still needs a certain something to make it even more perfect—",
  str_homestory_819001001_4_dialog_content = "What is it?",
  str_homestory_819001001_5_dialog_content = "It's a little drab at the moment, wouldn't you say?",
  str_homestory_819001001_6_option_content = "I don't think so.",
  str_homestory_819001001_7_option_content = "I could do with a bit more decoration.",
  str_homestory_819001001_8_dialog_content = "I'll bring a couple of cushions over. That should be enough, right?",
  str_homestory_819001001_9_dialog_content = "I plan to decorate it with rare flowers and plants, and gold and silver tea sets, for the use of the nobles on board.",
  str_homestory_819001001_10_dialog_content = "Rare flowers and plants, gold and silver tea sets... Won't that be a little too extravagant?",
  str_homestory_819001001_11_dialog_content = "Are you worried about the cost? <sprite=emo_baiyebi size=60 /> You really are quite the frugal Caelestite, aren't you?",
  str_homestory_819001001_12_dialog_content = "You don't have to worry about the money. I'll take care of that.",
  str_homestory_819001001_13_dialog_content = "It's not just the money. Of course, the fact that it'll cost a lot of money is a problem in itself, though.",
  str_homestory_819001001_14_dialog_content = "But since you can take care of it, it's not a problem. However...",
  str_homestory_819001001_15_dialog_content = "Just what are you trying to say?",
  str_homestory_819001001_16_dialog_content = "This is Cloud Gardens, a place where everyone tries their best to live together.",
  str_homestory_819001001_17_dialog_content = "Not everyone is interested in things like bouquets of flowers and gold and silver crockery..",
  str_homestory_819001001_18_dialog_content = "I don't want to make it too fancy, nor do I want to make certain Aurorians feel uncomfortable.",
  str_homestory_819001001_19_dialog_content = "Are you thinking about those who haven't enjoyed everyday life?",
  str_homestory_819001001_20_dialog_content = "Being surrounded by flowers and gold and silver doesn't exactly constitute everyday life...",
  str_homestory_819001001_21_dialog_content = "Anyway, I'll send someone to commence the decoration work right away.",
  str_homestory_819001001_22_dialog_content = "Wait a minute... I'm in charge here—I get the final say in all decisions.",
  str_homestory_819001001_23_dialog_content = "If you want to continue living here with us, you need to learn how to live with different people.",
  str_homestory_819001001_24_dialog_content = "Hmm? Why such serious words all of a sudden?",
  str_homestory_819001001_25_dialog_content = "Wait... Are you just... <size=45>imitating Schwab</size>!?",
  str_homestory_819001001_26_dialog_content = "Hmm? What are you talking about?",
  str_homestory_819001001_27_dialog_content = "I've heard that Schwab also likes to read in pavilions full of flowers, and always has huge crowds of young girls flocking to him when he does.",
  str_homestory_819001001_28_dialog_content = "So, you're trying to get girls to go crazy over you too?",
  str_homestory_819001001_29_dialog_content = "You want to be as popular as Schwab, so you're copying him.",
  str_homestory_819001001_30_dialog_content = "I see...",
  str_homestory_819001001_31_dialog_content = "What!? Don't look at me like that—like you've just cracked a big case! <sprite=emo_shengqi size=60 />",
  str_homestory_819001001_32_dialog_content = "That's not the case at all! Why would I want to be anything like that fool?",
  str_homestory_819001001_33_dialog_content = "The word \"fool\" sounds like an insult at first.",
  str_homestory_819001001_34_dialog_content = "But some people use it to disguise their fondness for others.",
  str_homestory_819001001_35_dialog_content = "I'm starting to feel ill all of a sudden...",
  str_homestory_819001001_36_dialog_content = "I am a preeminent scholar of the Dawn Academy!",
  str_homestory_819001001_37_dialog_content = "Why would I imitate a fool who only cares about maintaining his image in front of a gaggle of fickle women!?",
  str_homestory_819001001_38_dialog_content = "Then, why do you need to decorate the old pavilion with flowers and fancy tea sets?",
  str_homestory_819001001_39_dialog_content = "It's just a matter of my preferences as a noble, of course!",
  str_homestory_819001001_40_dialog_content = "Forget it. Decorate it however you want.",
  str_homestory_819001001_41_dialog_content = "I don't care.",
  str_homestory_819001001_42_dialog_content = "(Overprotest much? Looking at how flustered he became, he clearly can't have suggested all this just because he wanted somewhere to read, can he?)",
  str_homestory_819101001_0_dialog_content = "Hati?",
  str_homestory_819101001_1_dialog_content = "What are you up to?",
  str_homestory_819101001_2_dialog_content = "Oh, just talking to a book on the bookshelf.",
  str_homestory_819101001_3_dialog_content = "Uh... How exactly do you talk to a book?<sprite=emo_yihuo size=60 />",
  str_homestory_819101001_4_dialog_content = "Easy! You just ask a question, and the answer will appear on its pages! Sometimes the answer is too true that I get goosebumps.",
  str_homestory_819101001_5_dialog_content = "So what did you ask it?",
  str_homestory_819101001_6_dialog_content = "I wanted to hear a story, so I asked it to tell me one.",
  str_homestory_819101001_7_dialog_content = "What kind of story? Was it a scary one?",
  str_homestory_819101001_8_dialog_content = "You're not afraid?",
  str_homestory_819101001_9_option_content = "Maybe a little...",
  str_homestory_819101001_10_dialog_content = "But still, I'm curious.",
  str_homestory_819101001_11_option_content = "No way!",
  str_homestory_819101001_12_dialog_content = "Are you kidding? How could a tough guy like me be afraid of a book?",
  str_homestory_819101001_13_dialog_content = "The story it told me just now went something like this...",
  str_homestory_819101001_14_dialog_content = "\"On a cold winter night, you were standing in front of a bookshelf, reading the All-knowing Book...\"",
  str_homestory_819101001_15_dialog_content = "\"When suddenly, you noticed something moving behind you. That's when words slowly began to appear on the pages...\"",
  str_homestory_819101001_16_dialog_content = "\"Do not turn around. <size=45>Someone</size> is behind you.\"",
  str_homestory_819101001_17_dialog_content = "\"In spite of your fear, you couldn't help but turn around and look.\"",
  str_homestory_819101001_18_dialog_content = "That was as far as I got in the story. When I turned around to look, that's when you walked into the room.",
  str_homestory_819101001_19_dialog_content = "Hahaha! Sounds like a typical suspense novel, but with a real-life twist. What happens next?",
  str_homestory_819101001_20_dialog_content = "\"The person behind you is none other than your landlord.\"",
  str_homestory_819101001_21_dialog_content = "\"But there's no need to be afraid. Your landlord is weak, and you could send him flying with a single punch.\"",
  str_homestory_819101001_22_dialog_content = "Wait, what?! Now you're just making things up!",
  str_homestory_819101001_23_dialog_content = "But still, it's almost scary how fitting the story is! That's why I can't put this story down!",
  str_homestory_819101001_24_dialog_content = "\"To get even with your landlord for startling you, you decide to give him a quick jab.\"",
  str_homestory_819101001_25_dialog_content = "\"Unfortunately, your light punch knocks him to the ground. In retaliation, he kicks you out of your home and into the freezing streets, where you catch a cold and die.\"",
  str_homestory_819101001_26_dialog_content = "It's creepy, huh? Oh, don't worry, Mr. Landlord; I would never dream of hitting you.",
  str_homestory_819101001_27_dialog_content = "And I wouldn't kick you out either! No, wait a second—there's no way you could knock me out with a single punch!",
  str_homestory_819101001_28_dialog_content = "Wanna give it a try?",
  str_homestory_819101001_29_dialog_content = "Let's do it!<sprite=emo_dianzan size=60 />",
  str_homestory_819101001_30_dialog_content = "Alright, but you asked for it! Let me just loosen up my wrist.",
  str_homestory_819101001_31_dialog_content = "I-I was talking about that All-knowing Book!",
  str_homestory_819101001_32_dialog_content = "Oh? So what do you want to ask it?",
  str_homestory_819101001_33_dialog_content = "Can it really answer any question?",
  str_homestory_819101001_34_dialog_content = "You see, I'm in a bit of a bind right now. Vice asked me to sort out the Colossus' finances for the month...",
  str_homestory_819101001_35_dialog_content = "I heard you mentioning something about that in the cafeteria, yeah.",
  str_homestory_819101001_36_dialog_content = "So it was the first thing I asked, and it replied—",
  str_homestory_819101001_37_dialog_content = "\"I'm just a book. I have no assets, so I have no way of helping you balance your finances.\"",
  str_homestory_819101001_38_dialog_content = "Tch... And here I thought it could answer any question!",
  str_homestory_819101001_39_dialog_content = "There's no need to ask the All-knowing Book. I could answer your question, no problem.",
  str_homestory_819101001_40_dialog_content = "Oh really? Let's hear it then.",
  str_homestory_819101001_41_dialog_content = "The Colossus' expenditures are completely out of control, and you're on the verge of bankruptcy. Eventually, you're going to end up out on the freezing streets, where you catch a cold and die.",
  str_homestory_819101001_42_dialog_content = "Don't just steal from the All-knowing Book!",
  str_homestory_819101001_43_dialog_content = "Well, it's a pretty fitting answer, don't you think?",
  str_homestory_819101001_44_dialog_content = "Not what you... expected? Boo-hoo...",
  str_homestory_817702001_0_dialog_content = "Hey, I think I hear Goldie singing!",
  str_homestory_817702001_1_dialog_content = "♪ La-la-laaa! ♪",
  str_homestory_817702001_2_dialog_content = "Oh, PlayerName! Hello, there.",
  str_homestory_817702001_3_dialog_content = "Hi, Goldie!",
  str_homestory_817702001_4_dialog_content = "Sorry, I'm not interrupting you, am I?",
  str_homestory_817702001_5_dialog_content = "Not at all, not at all!",
  str_homestory_817702001_6_dialog_content = "I just couldn't help but start singing when I saw the violin here!",
  str_homestory_817702001_7_dialog_content = "To be honest, I was really surprised to find out you had one, PlayerName.",
  str_homestory_817702001_8_dialog_content = "Could it be that... You're interested in instruments?",
  str_homestory_817702001_9_option_content = "I am!",
  str_homestory_817702001_10_dialog_content = "Of course! I love instruments!",
  str_homestory_817702001_11_dialog_content = "But I can't play any of them, so it's really not much of a hobby, heheh...",
  str_homestory_817702001_12_dialog_content = "But that's still a wonderful thing!",
  str_homestory_817702001_13_dialog_content = "It looks like we have yet another thing in common, PlayerName!",
  str_homestory_817702001_14_option_content = "Not really.",
  str_homestory_817702001_15_dialog_content = "Well, I wouldn't call it an interest, really...",
  str_homestory_817702001_16_dialog_content = "But if I ever learn to play an instrument, you'll be the first to hear it!",
  str_homestory_817702001_17_dialog_content = "Really? Heehee... I'm so honored! Thank you!",
  str_homestory_817702001_18_dialog_content = "I should mention something, though...",
  str_homestory_817702001_19_dialog_content = "This isn't just any ordinary violin.",
  str_homestory_817702001_20_dialog_content = "It was actually part of a famous detective's collection!",
  str_homestory_817702001_21_dialog_content = "A detective?",
  str_homestory_817702001_22_dialog_content = "That's right! Apparently, this detective was really fond of playing it whenever they weren't investigating cases.",
  str_homestory_817702001_23_dialog_content = "I don't really know much else about them...",
  str_homestory_817702001_24_dialog_content = "But a detective with a passion for the arts—it just sounds romantic <sprite=emo_aixin size=60 />!",
  str_homestory_817702001_25_dialog_content = "I agree!",
  str_homestory_817702001_26_dialog_content = "A calm and rational detective who spends their nights all alone, with nothing but a violin to keep them company...",
  str_homestory_817702001_27_dialog_content = "Wait a minute... That's it! That's the inspiration I needed!",
  str_homestory_817702001_28_dialog_content = "What inspiration?",
  str_homestory_817702001_29_dialog_content = "The inspiration for my <sprite=emo_yinfu size=60 /> new song!",
  str_homestory_817702001_30_dialog_content = "I'll have to order new costumes and come up with a new choreography too!",
  str_homestory_817702001_31_dialog_content = "I'm getting so pumped up just thinking about it!",
  str_homestory_817702001_32_dialog_content = "A detective-themed idol concert, huh?",
  str_homestory_817702001_33_dialog_content = "I bet it'll be a big hit!",
  str_homestory_817702001_34_dialog_content = "If anyone can pull it off, it's you Goldie!",
  str_homestory_817702001_35_dialog_content = "Heehee! Hope to see you in the audience when the day comes!",
  str_homestory_811602001_0_dialog_content = "What's Fleur doing there?",
  str_homestory_811602001_1_dialog_content = "Hey, Fleur! What are you doing?",
  str_homestory_811602001_2_dialog_content = "Hey, Navigator!",
  str_homestory_811602001_3_dialog_content = "I'm adjusting the ornament.",
  str_homestory_811602001_4_dialog_content = "I picked it up to play with it just now...",
  str_homestory_811602001_5_dialog_content = "And it was making a strange noise.",
  str_homestory_811602001_6_dialog_content = "A strange noise?",
  str_homestory_811602001_7_dialog_content = "That's right. Maybe one of the screws is too tight, or maybe it just needs some oil...",
  str_homestory_811602001_8_dialog_content = "This wheel keeps making an awful squeaking sound.",
  str_homestory_811602001_9_option_content = "I see!",
  str_homestory_811602001_10_dialog_content = "Now that you mention it, this ornament does seem a little off...",
  str_homestory_811602001_11_dialog_content = "If it's making that kind of sound, doesn't it mean that one of its parts is in bad shape?",
  str_homestory_811602001_12_dialog_content = "That's right!",
  str_homestory_811602001_13_dialog_content = "Most people have a hard time understanding that much, but it looks like you might have a knack for fixing machines.",
  str_homestory_811602001_14_dialog_content = "Y-You think so? Hehehe...",
  str_homestory_811602001_15_option_content = "I'm clueless...",
  str_homestory_811602001_16_dialog_content = "You think so...?",
  str_homestory_811602001_17_dialog_content = "Leave it to an expert like you to figure that out, Fleur. I'm hopeless when it comes to this kind of stuff.",
  str_homestory_811602001_18_dialog_content = "I see... I was hoping to talk to you about machines, but I guess that's out of the question.",
  str_homestory_811602001_19_dialog_content = "Don't worry, I can still fix this thing myself.",
  str_homestory_811602001_20_dialog_content = "Hmm... Looks like I was right. This screw is way too tight...",
  str_homestory_811602001_21_dialog_content = "Too bad I don't have the tools to loosen it right now.",
  str_homestory_811602001_22_dialog_content = "I'll come back and fix it once I find the right tool, okay?",
  str_homestory_811602001_23_dialog_content = "Sure thing, Fleur. Thanks again!",
  str_homestory_811602001_24_dialog_content = "Don't mention it. It's just a little screw after all.",
  str_homestory_811602001_25_dialog_content = "Still, one little screw can mean a world of difference when it comes to machines, you know?",
  str_homestory_811602001_26_dialog_content = "Thank goodness it's just a toy, if it was an actual cart...",
  str_homestory_811602001_27_dialog_content = "The wheel would have been busted by now! Hahaha!",
  str_homestory_811602001_28_dialog_content = "No kidding. Normal folks like us only know that something needs fixing when it finally breaks...",
  str_homestory_811602001_29_dialog_content = "If only all machines could point out their problems to us like Soroz...",
  str_homestory_811602001_30_dialog_content = "Is that right?",
  str_homestory_811602001_31_dialog_content = "If you ask me, people are much harder to understand <sprite=emo_sikao size=60 />...",
  str_homestory_811602001_32_dialog_content = "Don't get me wrong, granting every machine a personality would be an enormous achievement...",
  str_homestory_811602001_33_dialog_content = "But the last thing I need is for machines to lie to me while I'm working on them!",
  str_homestory_811602001_34_dialog_content = "Heheh, that's true.",
  str_homestory_811602001_35_dialog_content = "If that day ever comes, I'm sure you'll be up to your ears in problems.",
  str_homestory_808401001_0_dialog_content = "You like riddles too, Istvan?",
  str_homestory_808401001_1_dialog_content = "You're just in time, my young friend.",
  str_homestory_808401001_2_dialog_content = "Tell me, what do you make of this image?",
  str_homestory_808401001_3_dialog_content = "What do I make of it? Let me see...",
  str_homestory_808401001_4_option_content = "Looks a little challenging.",
  str_homestory_808401001_5_dialog_content = "I think some of these clues look a little suspicious <sprite=emo_sikao size=60 />.",
  str_homestory_808401001_6_dialog_content = "I bet I could figure it out with a little more time!",
  str_homestory_808401001_7_option_content = "I don't get it.",
  str_homestory_808401001_8_dialog_content = "Er... I'm not exactly the best at solving riddles <sprite=emo_tanqi size=60 />.",
  str_homestory_808401001_9_dialog_content = "I can't wrap my head around this one at all...",
  str_homestory_808401001_10_dialog_content = "I see.",
  str_homestory_808401001_11_dialog_content = "My apologies. You asked me a question first, and I answered it with another question.",
  str_homestory_808401001_12_dialog_content = "I suppose I should have given you a real answer...",
  str_homestory_808401001_13_dialog_content = "No, my friend. I'm not fond of riddles at all.",
  str_homestory_808401001_14_dialog_content = "Huh? Then why are you still trying to figure it out?!",
  str_homestory_808401001_15_dialog_content = "Rest assured, my young friend, there's a perfectly reasonable explanation for this.",
  str_homestory_808401001_16_dialog_content = "Judging from your own words just now, you assumed that this image was a clue to a riddle.",
  str_homestory_808401001_17_dialog_content = "Which means that you inadvertently viewed it from the perspective of a detective.",
  str_homestory_808401001_18_dialog_content = "Er... That's right, I guess?",
  str_homestory_808401001_19_dialog_content = "However, there are many other characters involved in this case.",
  str_homestory_808401001_20_dialog_content = "The detective, the perpetrator, the victim...",
  str_homestory_808401001_21_dialog_content = "And, of course, the instigator.",
  str_homestory_808401001_22_dialog_content = "The instigator?",
  str_homestory_808401001_23_dialog_content = "Indeed. Like a shepherd, the instigator is responsible for everything, and benefits from it more than anyone else.",
  str_homestory_808401001_24_dialog_content = "Raising sheep carefully by hand, herding them with loyal dogs, protecting them from hungry wolves...",
  str_homestory_808401001_25_dialog_content = "A good shepherd never surrenders his flock to the whims of fate.",
  str_homestory_808401001_26_dialog_content = "Which is why, rather than solve the riddle, the instigator instead chooses the answer that benefits him the most.",
  str_homestory_808401001_27_dialog_content = "Th-That's awfully complicated!",
  str_homestory_808401001_28_dialog_content = "But I think I understand what you're trying to say, Istvan...",
  str_homestory_808401001_29_dialog_content = "For a leader like you, sometimes the truth isn't as important as the end result, right?",
  str_homestory_808401001_30_dialog_content = "Your skills of deduction are as sharp as ever.",
  str_homestory_808401001_31_dialog_content = "Though you're still young, and your future possibilities are almost limitless.",
  str_homestory_808401001_32_dialog_content = "I only hope that a Navigator such as yourself learns how to move other pieces to your own advantage.",
  str_homestory_808401001_33_dialog_content = "To indulge in the pleasures of mediocrity is a lot of sheep, not shepherds.",
  str_homestory_808401001_34_dialog_content = "Heheheh... Thanks, but I think it's a little too early for me to think about stuff like that...",
  str_homestory_808401001_35_dialog_content = "... Perhaps you're right. Rushing these things could prove detrimental in some instances.",
  str_homestory_808401001_36_dialog_content = "In that case, why don't I offer you a more age-appropriate task?",
  str_homestory_808401001_37_dialog_content = "While I was standing by the river, I noticed a sparkling coin in the water <sprite=emo_baiyebi size=60 />.",
  str_homestory_808401001_38_dialog_content = "I couldn't be sure at the time, but there's a chance it was quite the rare trinket.",
  str_homestory_808401001_39_dialog_content = "Why don't you go have a look?",
  str_homestory_808401001_40_dialog_content = "Sure! Thanks, Istvan!",
  str_homestory_819301001_0_dialog_content = "Kristen?",
  str_homestory_819301001_1_dialog_content = "What's up, Kristen?",
  str_homestory_819301001_2_dialog_content = "Hmm-hmm-hmm! <sprite=emo_yinfu size=60 />",
  str_homestory_819301001_3_dialog_content = "Oh nothing, just listening to music!",
  str_homestory_819301001_4_dialog_content = "Your record player is so pretty, so I had to try it out!",
  str_homestory_819301001_5_dialog_content = "So what do you think?",
  str_homestory_819301001_6_dialog_content = "It's awesome! The sound quality is amazing... You really picked a good one!",
  str_homestory_819301001_7_dialog_content = "How long have you been a music-lover, PlayerName?",
  str_homestory_819301001_8_dialog_content = "I've always been pretty fond of music, but I just tend to pick up interesting stuff during my travels... Like this record player!",
  str_homestory_819301001_9_dialog_content = "Though I'm sure it's nothing compared to your own collection.",
  str_homestory_819301001_10_dialog_content = "Well, my family's home does have a pretty extensive collection of music players... One of them is really big too!",
  str_homestory_819301001_11_dialog_content = "I'd wager...",
  str_homestory_819301001_12_dialog_content = "It's probably as tall as the entrance to the Hall of Justice.",
  str_homestory_819301001_13_dialog_content = "Wh-What?!",
  str_homestory_819301001_14_dialog_content = "The entrance to the Hall of Justice... That's enormous!",
  str_homestory_819301001_15_dialog_content = "You could probably hold a concert on something that big!",
  str_homestory_819301001_16_dialog_content = "My father's one of those collector-type nobles, you know? Sometimes it just gets a little out of hand!",
  str_homestory_819301001_17_dialog_content = "But you're a noble too, Kristen...",
  str_homestory_819301001_18_dialog_content = "Yeah, but my father and I are different!",
  str_homestory_819301001_19_dialog_content = "Or do you really think I'm like one of those stuffy, old nobles?",
  str_homestory_819301001_20_option_content = "You're not!",
  str_homestory_819301001_21_dialog_content = "You're always on the lookout for new and popular stuff.",
  str_homestory_819301001_22_dialog_content = "Like music, for example!",
  str_homestory_819301001_23_option_content = "Maybe a little...",
  str_homestory_819301001_24_dialog_content = "I mean, you're really well-educated, just like every noble I've met.",
  str_homestory_819301001_25_dialog_content = "Heehee! You really think so, PlayerName?",
  str_homestory_819301001_26_dialog_content = "Can't say I disagree.",
  str_homestory_819301001_27_dialog_content = "Yes, my birth makes me part of the nobility and all...",
  str_homestory_819301001_28_dialog_content = "But in my heart of hearts, I want to live my own life, on my own terms!",
  str_homestory_819301001_29_dialog_content = "And this new music has given me the inspiration I need to keep going!",
  str_homestory_819301001_30_dialog_content = "Wait a second!",
  str_homestory_819301001_31_dialog_content = "Y-You're gonna perform right here, Kristen? Right now?!",
  str_homestory_819301001_32_dialog_content = "That's right! This song is perfect for hitting some really high notes, too! Laaaa— <sprite=emo_yinfu size=60 />",
  str_homestory_819301001_33_dialog_content = "H-Hang on!",
  str_homestory_819301001_34_dialog_content = "Oh, would you look at the time? I totally forgot I had something important to do! See ya!",
  str_homestory_819301001_35_dialog_content = "R-Right now?",
  str_homestory_819301001_36_dialog_content = "Yep! But go ahead and have fun with the record player! Byeeee!",
  str_homestory_819201001_0_dialog_content = "Leo?",
  str_homestory_819201001_1_dialog_content = "I was just looking for a magnifying glass, and here it is.",
  str_homestory_819201001_2_dialog_content = "What are you gonna use it for?",
  str_homestory_819201001_3_dialog_content = "To look at this map.",
  str_homestory_819201001_4_dialog_content = "My subordinates explored the positions of various military fortresses along the border recently.",
  str_homestory_819201001_5_dialog_content = "They just finished drawing this map today and sent it over.",
  str_homestory_819201001_6_dialog_content = "But the handwriting on this map is so scruffy and ridiculously small. It's making my headache. <sprite=emo_xuanyun size=60 />",
  str_homestory_819201001_7_dialog_content = "Are there many words written on the map?",
  str_homestory_819201001_8_dialog_content = "See it for yourself.",
  str_homestory_819201001_9_dialog_content = "\"Exploration Display and Analysis of Military Fortresses Within 80 Kilometers of Twilight...\"",
  str_homestory_819201001_10_dialog_content = "There's also a second line.",
  str_homestory_819201001_11_dialog_content = "\"... and Detailing Information Such as Spatial Distribution, Quantity, and Qualitative Characteristics and Interrelationships\"",
  str_homestory_819201001_12_dialog_content = "Huff... huff... <sprite=emo_kun size=60 />",
  str_homestory_819201001_13_dialog_content = "D-Do the names of all maps... are so complicated?",
  str_homestory_819201001_14_dialog_content = "I can barely catch my breath after reading it in one go.",
  str_homestory_819201001_15_dialog_content = "Of course it doesn't need to be this complicated, but this time the cartographer was very thorough, so he wrote as much as he could...",
  str_homestory_819201001_16_dialog_content = "It really isn't necessary.",
  str_homestory_819201001_17_dialog_content = "No wonder so many strategists carry a magnifying glass around with them.",
  str_homestory_819201001_18_dialog_content = "If they ever have to rely on a cartographer as thorough as this guy, a magnifying glass is their only hope of being able to read their maps clearly.",
  str_homestory_819201001_19_dialog_content = "(But even after being able to read this ridiculous name, you'd probably end up even more frustrated.)",
  str_homestory_819201001_20_dialog_content = "There are indeed many leaders who are fond of using magnifying glasses.",
  str_homestory_819201001_21_dialog_content = "Not only can they enlarge text and images and assist with observation, but they can also help with making fires when the sun is shining.",
  str_homestory_819201001_22_dialog_content = "One can say they are versatile tools, essential for troops on the march.",
  str_homestory_819201001_23_dialog_content = "However, I have my reservations about magnifying glasses.",
  str_homestory_819201001_24_dialog_content = "Why?",
  str_homestory_819201001_25_dialog_content = "You too, are a commander in battle. Perhaps you can guess the reason?",
  str_homestory_819201001_26_option_content = "They depend on light.",
  str_homestory_819201001_27_dialog_content = "They're difficult to use at night or in the dark.",
  str_homestory_819201001_28_dialog_content = "This is indeed a problem, but as long as a light source is available, this problem can be avoided.",
  str_homestory_819201001_29_option_content = "They can limit your field of vision.",
  str_homestory_819201001_30_dialog_content = "Indeed.",
  str_homestory_819201001_31_dialog_content = "A magnifying glass magnifies an area, allowing the observer to see details more accurately.",
  str_homestory_819201001_32_dialog_content = "But at the same time, the observer's field of vision is limited to the scope of the magnifying glass.",
  str_homestory_819201001_33_dialog_content = "This renders one unable to observe the wider environment surrounding them.",
  str_homestory_819201001_34_dialog_content = "But warfare often requires the deployment of troops from a broader perspective.",
  str_homestory_819201001_35_dialog_content = "I sometimes deliberately avoid using a magnifying glass to prevent my vision field from becoming too focused.",
  str_homestory_819201001_36_dialog_content = "You truly are an inspirational strategist.",
  str_homestory_819201001_37_dialog_content = "It's just a personal habit. For example, I have no choice but to ask for a magnifying glass in our current situation.",
  str_homestory_819201001_38_dialog_content = "You can use the magnifying glass here whenever you want.",
  str_homestory_819201001_39_dialog_content = "But please make sure you put it back in its box after you finish using it.",
  str_homestory_819201001_40_dialog_content = "If it's exposed to direct sunlight, it may cause a fire. <sprite=emo_nuhuo size=60 />",
  str_homestory_819201001_41_dialog_content = "Haha, it's good that you have a strong sense of fire safety awareness.",
  str_homestory_819201001_42_dialog_content = "After all, I've worked so hard to make this a place I can call home.",
  str_homestory_819201001_43_dialog_content = "If all my money goes up in flames... well, my hard work will all have been in vain.",
  str_homestory_819901001_0_dialog_content = "Yingel?",
  str_homestory_819901001_1_dialog_content = "Oh, PlayerName. I'm just about to try out this coffee.",
  str_homestory_819901001_2_dialog_content = "Did you brew it yourself?",
  str_homestory_819901001_3_dialog_content = "That's right.",
  str_homestory_819901001_4_dialog_content = "I saw this beautiful coffee mug just now, so I thought I'd try brewing a cup myself.",
  str_homestory_819901001_5_dialog_content = "It smells amazing! <sprite=emo_dianzan size=60 />",
  str_homestory_819901001_6_dialog_content = "See the pattern on the surface? This is what they call latte art.",
  str_homestory_819901001_7_dialog_content = "Yeah, I see it! It's beautiful!",
  str_homestory_819901001_8_dialog_content = "This shape looks like... Aoha?",
  str_homestory_819901001_9_dialog_content = "You can tell it's Aoha? Well, I suppose I can't call this attempt a failure then.",
  str_homestory_819901001_10_dialog_content = "Of course it's not a failure! It's incredible!",
  str_homestory_819901001_11_dialog_content = "How did you do it, Yingel?",
  str_homestory_819901001_12_dialog_content = "Making a latte isn't difficult at all, and the ingredients are also very basic.",
  str_homestory_819901001_13_dialog_content = "Firstly, you need to pour a small cup of espresso into a coffee cup...",
  str_homestory_819901001_14_dialog_content = "Then foam up some fresh milk and add it to the espresso.",
  str_homestory_819901001_15_dialog_content = "When adding the foam, adjust the shape by moving the milk cup.",
  str_homestory_819901001_16_dialog_content = "And just like that, you should have a latte with a beautiful pattern.",
  str_homestory_819901001_17_dialog_content = "You make it sound easy, but I'm sure it's not as simple as it sounds...",
  str_homestory_819901001_18_dialog_content = "Practice makes perfect. Just try it a few times and you'll be fine.",
  str_homestory_819901001_19_dialog_content = "Whenever I feel tired at work, I make myself a latte.",
  str_homestory_819901001_20_dialog_content = "Smooth milk and mellow coffee are a perfect match.",
  str_homestory_819901001_21_dialog_content = "PlayerName, would you like to give it a try?<sprite=emo_yaosu size=60 />",
  str_homestory_819901001_22_option_content = "Yes",
  str_homestory_819901001_23_dialog_content = "After all, you made this coffee yourself.",
  str_homestory_819901001_24_option_content = "No",
  str_homestory_819901001_25_dialog_content = "If I drink coffee right now, I'm afraid I won't be able to sleep.",
  str_homestory_819901001_26_dialog_content = "It's over two-thirds milk, so it won't keep you up.",
  str_homestory_819901001_27_dialog_content = "Really? In that case, I'd love to give it a try.",
  str_homestory_819901001_28_dialog_content = "How is it?",
  str_homestory_819901001_29_dialog_content = "I give it ten out of ten for flavor!",
  str_homestory_819901001_30_dialog_content = "If only I could make a latte as delicious as this.",
  str_homestory_819901001_31_dialog_content = "You should try making one—I know you can do it.",
  str_homestory_819901001_32_dialog_content = "However, it seems I've run out of milk...",
  str_homestory_819901001_33_dialog_content = "What, it's all gone already?",
  str_homestory_819901001_34_dialog_content = "I was really thirsty just now, so I drank it all.",
  str_homestory_819901001_35_dialog_content = "Erm, Yingel... you can't just guzzle milk down like it's water...",
  str_homestory_820001001_0_dialog_content = "Is Anatoli staring at that outdoor lamp?",
  str_homestory_820001001_1_dialog_content = "What are you doing, Anatoli?",
  str_homestory_820001001_2_dialog_content = "I'm observing this lamp.",
  str_homestory_820001001_3_option_content = "Observing a lamp?",
  str_homestory_820001001_4_dialog_content = "I've found that it remains on, even during the day.",
  str_homestory_820001001_5_dialog_content = "Although the light it emits is far less radiant than sunlight, it never goes out.",
  str_homestory_820001001_6_dialog_content = "Is someone constantly adding lamp oil to it?",
  str_homestory_820001001_7_dialog_content = "Uh, I don't know the answer to that either...",
  str_homestory_820001001_8_option_content = "Why?",
  str_homestory_820001001_9_dialog_content = "Because it's always on, day and night.",
  str_homestory_820001001_10_dialog_content = "Though inconspicuous during the day, it illuminates the darkness at night. <sprite=emo_taiyang size=60 />",
  str_homestory_820001001_11_dialog_content = "Of course!",
  str_homestory_820001001_12_dialog_content = "It's great having a light illuminating the road at night!",
  str_homestory_820001001_13_dialog_content = "However... leaving the light on during the day feels a bit wasteful.",
  str_homestory_820001001_14_dialog_content = "Yes... it certainly does.",
  str_homestory_820001001_15_dialog_content = "After all, this isn't the Eternal Night... There's really no need to keep the lights on all the time.",
  str_homestory_820001001_16_dialog_content = "Then I'll put it out for now and light it up later in the evening.",
  str_homestory_820001001_17_dialog_content = "It'd be better if you kept it on.",
  str_homestory_820001001_18_dialog_content = "Huh? Why?",
  str_homestory_820001001_19_dialog_content = "We might not know who's been adding oil to this lamp, but they must have their reasons.",
  str_homestory_820001001_20_dialog_content = "It'd be better if we didn't disrupt their routine.",
  str_homestory_820001001_21_dialog_content = "You have a point.",
  str_homestory_820001001_22_dialog_content = "I really want to know who this mystery person is!",
  str_homestory_820001001_23_dialog_content = "Well, try observing more and maybe one day you'll meet them.",
  str_homestory_820001001_24_dialog_content = "I remember you being a real genius when it comes to reasoning and analysis...",
  str_homestory_820001001_25_dialog_content = "Do you have any ideas as to who the mystery lamp lighter might be?",
  str_homestory_820001001_26_dialog_content = "I do have my speculations.",
  str_homestory_820001001_27_dialog_content = "Like what?",
  str_homestory_820001001_28_dialog_content = "It must be someone very patient, able to persist in doing something for a long time.",
  str_homestory_820001001_29_dialog_content = "And they should have a good memory, as they never seem to forget such a trivial task.",
  str_homestory_820001001_30_dialog_content = "Last of all, they seem very fond of objects emitting a modest light.",
  str_homestory_820001001_31_dialog_content = "Yeah, that makes sense...",
  str_homestory_820001001_32_dialog_content = "It actually reminds me of a few people.",
  str_homestory_820001001_33_dialog_content = "Wait, I've got it!",
  str_homestory_820001001_34_dialog_content = "Aren't you just talking about yourself?!",
  str_homestory_820001001_35_dialog_content = "Excellent deduction.",
  str_homestory_820001001_36_dialog_content = "So, why do you keep this lamp burning?",
  str_homestory_820001001_37_dialog_content = "It's clearly daytime, so there's obviously no need to use a lamp...",
  str_homestory_820001001_38_dialog_content = "Though the faintest flicker of flame may seem barely visible in the sunlight, there's still something that only it can do.",
  str_homestory_820001001_39_dialog_content = "This is what I believe.",
  str_homestory_802801001_0_dialog_content = "I know that voice...",
  str_homestory_802801001_1_dialog_content = "It's Raphael!",
  str_homestory_802801001_2_dialog_content = "Whoosh! Whoosh! Whoosh!",
  str_homestory_802801001_3_dialog_content = "PlayerName! It's great to see you!",
  str_homestory_802801001_4_dialog_content = "Hey! Try my new Brain Booster pills!",
  str_homestory_802801001_5_dialog_content = "These little things can instantly fill you with energy! They may even allow you to sense the presence of mystical treasure!",
  str_homestory_802801001_6_dialog_content = "Limited-edition! Don't miss this once-in-a-lifetime chance!",
  str_homestory_802801001_7_option_content = "I-I don't think I need it, thanks...",
  str_homestory_802801001_8_dialog_content = "I've been searching high and low for a while now, and I've finally found you!",
  str_homestory_802801001_9_dialog_content = "You don't want my little experiment to fail, do you?",
  str_homestory_802801001_10_dialog_content = "To be honest, I wasn't thinking about that...",
  str_homestory_802801001_11_option_content = "Let me give them a try!",
  str_homestory_802801001_12_dialog_content = "Hehe! You're in an unexpectedly cheery mood today, PlayerName!",
  str_homestory_802801001_13_dialog_content = "I'll bring you some more tomorrow!",
  str_homestory_802801001_14_dialog_content = "Erm... Do you really have nothing else to do these days?",
  str_homestory_802801001_15_dialog_content = "Open your mouth and say, \"ah\"!",
  str_homestory_802801001_16_dialog_content = "W-Wait a minute!",
  str_homestory_802801001_17_dialog_content = "That smell... Isn't that Vice's dishes?",
  str_homestory_802801001_18_dialog_content = "(Uh, those burned ones... <sprite=emo_hanshui size=60 />)",
  str_homestory_802801001_19_dialog_content = "Huh?! You don't trust me?",
  str_homestory_802801001_20_dialog_content = "Erm... What I mean is... you see...",
  str_homestory_802801001_21_dialog_content = "I understand, I understand! You like trusty companions you can rely on, don't you, PlayerName?",
  str_homestory_802801001_22_dialog_content = "I'm doing my best to become an incomparably reliable companion!",
  str_homestory_802801001_23_dialog_content = "One who can make Brain Booster pills—",
  str_homestory_802801001_24_dialog_content = "Hehe, but I really shouldn't brag.",
  str_homestory_802801001_25_dialog_content = "(She's surprisingly optimistic...)",
  str_homestory_802801001_26_dialog_content = "How about this, Raphael—you can go ahead and make some more, and then let Carleen try them out some other day!",
  str_homestory_802801001_27_dialog_content = "She's always working so hard... She might actually appreciate some Brain Boosters.",
  str_homestory_802801001_28_dialog_content = "Huh? Carleen?",
  str_homestory_802801001_29_dialog_content = "I don't think so!",
  str_homestory_802801001_30_dialog_content = "What do you mean by that?",
  str_homestory_802801001_31_dialog_content = "Because if I take them to Carleen, I know she'd say—",
  str_homestory_802801001_32_dialog_content = "\"Raphael! Don't you dare try giving me any more of your strange candy—and don't ask why.\"",
  str_homestory_802801001_33_dialog_content = "Why?",
  str_homestory_802801001_34_dialog_content = "I wish I knew! <sprite=emo_sikao size=60 /> But Carleen doesn't even let me ask.",
  str_homestory_802801001_35_dialog_content = "Oh yeah, and...",
  str_homestory_802801001_36_dialog_content = "These pills were specifically crafted for you and your psychic abilities, PlayerName!",
  str_homestory_802801001_37_dialog_content = "Alright, I understand... Just give it to me then!",
  str_homestory_802801001_38_dialog_content = "(Well, if it's just candy...)",
  str_homestory_802801001_39_dialog_content = "Hehe! I knew they were perfect for you, PlayerName!",
  str_homestory_802801001_40_dialog_content = "So, how was it...? How was it?! Have you noticed any changes?",
  str_homestory_802801001_41_dialog_content = "Have you seen anything shiny? Like treasure?",
  str_homestory_802801001_42_dialog_content = "My vision seems clearer, and I can see further away—",
  str_homestory_802801001_43_dialog_content = "In the river! There's really something shiny in the river!",
  str_homestory_802801001_44_dialog_content = "Yeah! In the river! I knew it!",
  str_homestory_802801001_45_dialog_content = "My Brain Booster experiment was a success! <sprite=emo_aixin size=60 />",
  str_homestory_820201001_0_dialog_content = "What are you doing here?",
  str_homestory_820201001_1_dialog_content = "Here you are.",
  str_homestory_820201001_2_dialog_content = "Was this throne set up specifically for me?",
  str_homestory_820201001_3_dialog_content = "Yeah...",
  str_homestory_820201001_4_dialog_content = "I approve of the thought.",
  str_homestory_820201001_5_dialog_content = "Although it is not on the level of the genuine throne in Lumopolis Gardens...",
  str_homestory_820201001_6_dialog_content = "Nevertheless, it is sufficiently fitting for my status.",
  str_homestory_820201001_7_dialog_content = "Glad you like it!",
  str_homestory_820201001_8_dialog_content = "Is there anything else you need?",
  str_homestory_820201001_9_dialog_content = "How about building a new Lumopolis palace here? <sprite=emo_sikao size=60 />",
  str_homestory_820201001_10_dialog_content = "Since we already have a throne, might as well build a palace to go with it.",
  str_homestory_820201001_11_dialog_content = "You want to build a palace here?",
  str_homestory_820201001_12_dialog_content = "I don't think there's enough space...",
  str_homestory_820201001_13_dialog_content = "Hmm, that is true. On top of being crude, it is not big enough.",
  str_homestory_820201001_14_dialog_content = "How about a renovation funded by me?",
  str_homestory_820201001_15_option_content = "That's okay",
  str_homestory_820201001_16_dialog_content = "I appreciate the thought.",
  str_homestory_820201001_17_option_content = "Will you?",
  str_homestory_820201001_18_dialog_content = "Other than materials, a lot of labor is also needed for the expansion.",
  str_homestory_820201001_19_dialog_content = "I don't think the project's warranted if you're just dropping by once in a while.",
  str_homestory_820201001_20_dialog_content = "It's trivial to me.",
  str_homestory_820201001_21_dialog_content = "But we can forget it if you don't want it.",
  str_homestory_820201001_22_dialog_content = "Hold on, I think I smell something... <sprite=emo_wuzui size=60 />",
  str_homestory_820201001_23_dialog_content = "What is it? A weird odor?",
  str_homestory_820201001_24_dialog_content = "I don't smell anything.",
  str_homestory_820201001_25_dialog_content = "That's exactly what's missing.",
  str_homestory_820201001_26_dialog_content = "You should add some nice scents to make the air smell cleaner and tidier.",
  str_homestory_820201001_27_dialog_content = "I'm not really interested in scents...",
  str_homestory_820201001_28_dialog_content = "If visitors do not sense an air of elegance when they get here...",
  str_homestory_820201001_29_dialog_content = "That is a serious breach of etiquette!",
  str_homestory_820201001_30_dialog_content = "In that case, I'll get somebody on it.",
  str_homestory_820201001_31_dialog_content = "I hope to see a change when I visit again.",
  str_homestory_820201001_32_dialog_content = "Sure...",
  str_homestory_820301001_0_dialog_content = "Jakine?",
  str_homestory_820301001_1_dialog_content = "I see...",
  str_homestory_820301001_2_dialog_content = "What are you doing?",
  str_homestory_820301001_3_dialog_content = "What... How long you've been here?",
  str_homestory_820301001_4_dialog_content = "Did you see the reading I just did?",
  str_homestory_820301001_5_dialog_content = "I just got here and didn't see anything.",
  str_homestory_820301001_6_dialog_content = "Were you doing a reading for something very private?",
  str_homestory_820301001_7_dialog_content = "I'm sorry, I'll leave right now.",
  str_homestory_820301001_8_dialog_content = "It is for something very private, however...",
  str_homestory_820301001_9_dialog_content = "It has to do with you.",
  str_homestory_820301001_10_dialog_content = "With me?",
  str_homestory_820301001_11_dialog_content = "Yeah. I heard the conversation you had with Vice.",
  str_homestory_820301001_12_dialog_content = "You're having financial problems lately?",
  str_homestory_820301001_13_dialog_content = "Well, it's a bit tight.",
  str_homestory_820301001_14_dialog_content = "I was worried, so I did a reading for you.",
  str_homestory_820301001_15_dialog_content = "If you don't want to know, I'll keep the result a secret.",
  str_homestory_820301001_16_dialog_content = "I don't mind. So what is the outcome?",
  str_homestory_820301001_17_dialog_content = "Well, about your finances in the future...",
  str_homestory_820301001_18_dialog_content = "Wait, I'm not quite ready mentally for a bad turnout yet...",
  str_homestory_820301001_19_dialog_content = "It says you'll be super rich! Living a stress-free, happy life every day! <sprite=emo_yaosu size=60 />",
  str_homestory_820301001_20_dialog_content = "Really? It's truly going to be that amazing?",
  str_homestory_820301001_21_dialog_content = "Do you believe that?",
  str_homestory_820301001_22_dialog_content = "Huh? So you were lying to me?",
  str_homestory_820301001_23_dialog_content = "Just answer me, do you believe that?",
  str_homestory_820301001_24_option_content = "I do",
  str_homestory_820301001_25_dialog_content = "Right on! That's the best attitude to have!",
  str_homestory_820301001_26_option_content = "I don't",
  str_homestory_820301001_27_dialog_content = "Why not? You're making me angry now!",
  str_homestory_820301001_28_dialog_content = "The power of believe is critical!",
  str_homestory_820301001_29_dialog_content = "When you believe in something, that's the direction everything moves in.",
  str_homestory_820301001_30_dialog_content = "But what's that got to do with fortune-telling?",
  str_homestory_820301001_31_dialog_content = "Because the purpose of reading is...",
  str_homestory_820301001_32_dialog_content = "To seize the present!",
  str_homestory_820301001_33_dialog_content = "Hmm, it sounds like fortune-telling is really double-talk...",
  str_homestory_820301001_34_dialog_content = "That's because life is a long road, after all.",
  str_homestory_820301001_35_dialog_content = "And on this road, there are many forks.",
  str_homestory_820301001_36_dialog_content = "Which means your decision will impact the path you embark on in the future.",
  str_homestory_820301001_37_dialog_content = "But regardless, I saw a bright future for you <sprite=emo_taiyang size=60 />.",
  str_homestory_820301001_38_dialog_content = "Got it.",
  str_homestory_820301001_39_dialog_content = "The future is full of variables, but it all hinges on the here and now.",
  str_homestory_820301001_40_dialog_content = "Wow, nicely put... I must write it down in my journal.",
  str_homestory_820301001_41_dialog_content = "Haha, anyway, this talk has made me feel a lot better.",
  str_homestory_809801001_0_dialog_content = "Cuscuta?",
  str_homestory_809801001_1_dialog_content = "What are you looking at, Cuscuta?",
  str_homestory_809801001_2_dialog_content = "Flowers <sprite=emo_huaduo size=60 />.",
  str_homestory_809801001_3_dialog_content = "Some of the flowers in the bush welcome the sun, and some refuse to be looked upon.",
  str_homestory_809801001_4_dialog_content = "I know one of the latter type called Black Tail. Have you heard of it?",
  str_homestory_809801001_5_option_content = "Yes",
  str_homestory_809801001_6_dialog_content = "But what do you mean by \"refused to be looked upon\"?",
  str_homestory_809801001_7_option_content = "No",
  str_homestory_809801001_8_dialog_content = "What kind of flower is it?",
  str_homestory_809801001_9_dialog_content = "The Black Tail is very rare.",
  str_homestory_809801001_10_dialog_content = "Its petals are fragile, deep-hued, and absorb sunlight easily<sprite=emo_taiyang size=60 />.",
  str_homestory_809801001_11_dialog_content = "So to prevent burns, it usually hides under the leaves.",
  str_homestory_809801001_12_dialog_content = "Hence, it refused to be looked upon.",
  str_homestory_809801001_13_dialog_content = "I see what you mean...",
  str_homestory_809801001_14_dialog_content = "You like Black Tails very much, don't you, Cuscuta?",
  str_homestory_809801001_15_dialog_content = "How do I determine whether I do or not?",
  str_homestory_809801001_16_dialog_content = "Well, having unique insight into it and understanding how it grows...",
  str_homestory_809801001_17_dialog_content = "I think that's only someone interested in it like you would find out, right?",
  str_homestory_809801001_18_dialog_content = "You think so...?",
  str_homestory_809801001_19_dialog_content = "Actually, Black Tails normally grow on dead bodies.",
  str_homestory_809801001_20_dialog_content = "Dead bodies?!",
  str_homestory_809801001_21_dialog_content = "Yes. I believe...",
  str_homestory_809801001_22_dialog_content = "Right here, soon, you'll see Black Tails.",
  str_homestory_809801001_23_dialog_content = "Y-You mean... there's a dead body... buried underneath here?!",
  str_homestory_809801001_24_dialog_content = "Don't worry, I checked it out already.",
  str_homestory_809801001_25_dialog_content = "I'm referring to this soon-to-wither body of mine.",
  str_homestory_809801001_26_dialog_content = "Oh, I shall slumber soon, meaning Black Tails will appear.",
  str_homestory_809801001_27_dialog_content = "N-No, Cuscuta!",
  str_homestory_809801001_28_dialog_content = "Chubbs told me the soil in Cloud Gardens has special minerals.",
  str_homestory_809801001_29_dialog_content = "S-So it's not unusual for Black Tails to grow.",
  str_homestory_809801001_30_dialog_content = "Perhaps even colorful flowers are possible!",
  str_homestory_809801001_31_dialog_content = "Colorful...",
  str_homestory_809801001_32_dialog_content = "Is that true? <sprite=emo_yundao size=60 />",
  str_homestory_809801001_33_dialog_content = "Yes. So how about we plant colorful flowers together?",
  str_homestory_809801001_34_dialog_content = "Plant together... Is that... work?",
  str_homestory_809801001_35_dialog_content = "Well, not quite...",
  str_homestory_809801001_36_dialog_content = "You like flowers too, PlayerName?",
  str_homestory_809801001_37_dialog_content = "You could say that.",
  str_homestory_809801001_38_dialog_content = "I always felt there wasn't enough color in Cloud Gardens.",
  str_homestory_809801001_39_dialog_content = "You just reminded me that we could plant more flowers to add colors!",
  str_homestory_809801001_40_dialog_content = "So you're saying adding colors will make people happier?",
  str_homestory_809801001_41_dialog_content = "Of course! Why don't we look around for colorful flowers?",
  str_homestory_809801001_42_dialog_content = "Sure, we can do that.",
  str_homestory_809801001_43_dialog_content = "But does the colorful you mentioned include gold?",
  str_homestory_809801001_44_dialog_content = "See that thing glowing in gold in the lake? Is that a flower?",
  str_homestory_820101001_0_dialog_content = "What are you starting at?",
  str_homestory_820101001_1_dialog_content = "If...",
  str_homestory_820101001_2_dialog_content = "Did I disturb you, Mia?",
  str_homestory_820101001_3_dialog_content = "N-No. I'm just pondering on some hard issues.",
  str_homestory_820101001_4_dialog_content = "Anything I can help you with?",
  str_homestory_820101001_5_dialog_content = "Yeah. Can I ask you a question?",
  str_homestory_820101001_6_dialog_content = "Sure.",
  str_homestory_820101001_7_dialog_content = "If you could remember one day forever, which day would you choose?",
  str_homestory_820101001_8_dialog_content = "Forever, huh... I really can't think of one.",
  str_homestory_820101001_9_dialog_content = "So that's what's bothering you.",
  str_homestory_820101001_10_dialog_content = "It's because I saw the question, so...",
  str_homestory_820101001_11_dialog_content = "Okay, let me think.",
  str_homestory_820101001_12_option_content = "The Colossus rebooting...",
  str_homestory_820101001_13_dialog_content = "I'd choose to remember the day when the Colossus was successfully rebooted.",
  str_homestory_820101001_14_dialog_content = "That was my first time seeing what Astra looks like.",
  str_homestory_820101001_15_dialog_content = "Perhaps you can even call it the beginning of my life.",
  str_homestory_820101001_16_option_content = "The rise of the Obelisk of Return...",
  str_homestory_820101001_17_dialog_content = "I'd choose to remember the day when the Obelisk of Return rose...",
  str_homestory_820101001_18_dialog_content = "My mental powers were augmented to where I felt I could see every corner of Astra.",
  str_homestory_820101001_19_dialog_content = "That feeling was incredible.",
  str_homestory_820101001_20_dialog_content = "That does sound like an amazing day.",
  str_homestory_820101001_21_dialog_content = "You thought of it quick enough, PlayerName",
  str_homestory_820101001_22_dialog_content = "Actually, before the Colossus rebooted, every day was a replay of the day prior to me.",
  str_homestory_820101001_23_dialog_content = "My life only became lively until I met everyone.",
  str_homestory_820101001_24_dialog_content = "So I now cherish it to make sure I have a clear memory of their faces.",
  str_homestory_820101001_25_dialog_content = "And I'll strive to remember it all and preserve it forever.",
  str_homestory_820101001_26_dialog_content = "Ah... <sprite=emo_sikao size=60 />",
  str_homestory_820101001_27_dialog_content = "How about sharing your thoughts, Mia?",
  str_homestory_820101001_28_dialog_content = "My thoughts...",
  str_homestory_820101001_29_dialog_content = "Since I forgot some important memories until recently...",
  str_homestory_820101001_30_dialog_content = "I worry a lot about losing them again, so I want to retain them all...",
  str_homestory_820101001_31_dialog_content = "But it's hard to choose between keeping the memories of my mother, sister...",
  str_homestory_820101001_32_dialog_content = "Mia...",
  str_homestory_820101001_33_dialog_content = "Sorry for bringing you down with me...",
  str_homestory_820101001_34_dialog_content = "No, I should be apologizing. I shouldn't have said all that.",
  str_homestory_820101001_35_dialog_content = "It's okay, PlayerName.",
  str_homestory_820101001_36_dialog_content = "I'm actually relieved by what you said.",
  str_homestory_820101001_37_dialog_content = "Really?",
  str_homestory_820101001_38_dialog_content = "Yeah, rather than worrying about forgetting the past, it's more important to cherish the present <sprite=emo_yaosu size=60 />.",
  str_homestory_820401001_0_dialog_content = "Lady Joshua?",
  str_homestory_820401001_1_dialog_content = "What are you doing?",
  str_homestory_820401001_2_dialog_content = "Look, PlayerName.",
  str_homestory_820401001_3_dialog_content = "This potted plant is growing very nicely!",
  str_homestory_820401001_4_dialog_content = "I'm trying to figure out what variety it is.",
  str_homestory_820401001_5_dialog_content = "I see. Have you identified it yet?",
  str_homestory_820401001_6_dialog_content = "Unfortunately, I haven't been able to, thus far...",
  str_homestory_820401001_7_dialog_content = "Do you know what plant this is?",
  str_homestory_820401001_8_option_content = "Nod",
  str_homestory_820401001_9_dialog_content = "I bought it in Umbraton not too long ago.",
  str_homestory_820401001_10_dialog_content = "I just randomly picked out what was available.",
  str_homestory_820401001_11_dialog_content = "I believe the seller called it... manor plant?",
  str_homestory_820401001_12_dialog_content = "Yeah, that's the name.",
  str_homestory_820401001_13_dialog_content = "The name is rather plain, but you've kept it in great shape!",
  str_homestory_820401001_14_dialog_content = "Well, the seller did say it could grow very lush if cared for.",
  str_homestory_820401001_15_option_content = "Shake the head",
  str_homestory_820401001_16_dialog_content = "Well, I'm not sure either.",
  str_homestory_820401001_17_dialog_content = "I only remember the seller said it's a perennial.",
  str_homestory_820401001_18_dialog_content = "You can raise it indoors too.",
  str_homestory_820401001_19_dialog_content = "It seems to be a variety that's easy to care for.",
  str_homestory_820401001_20_dialog_content = "You have many green plants here, PlayerName.",
  str_homestory_820401001_21_dialog_content = "Ever considered having flowers in the mix<sprite=emo_huaduo size=60 />?",
  str_homestory_820401001_22_dialog_content = "Then the environment won't be monotonous.",
  str_homestory_820401001_23_dialog_content = "Hey, that's a great suggestion!",
  str_homestory_820401001_24_dialog_content = "But I'm not really good with flowers...",
  str_homestory_820401001_25_dialog_content = "It's easier for me to just stick to green plants.",
  str_homestory_820401001_26_dialog_content = "I'd plant different flowers in the garden when I'm in Lumopolis.",
  str_homestory_820401001_27_dialog_content = "Watering and trimming them in my spare time...",
  str_homestory_820401001_28_dialog_content = "That makes me feel very serene inside.",
  str_homestory_820401001_29_dialog_content = "I didn't know you were into that!",
  str_homestory_820401001_30_dialog_content = "So, will you teach me how to grow flowers, Lady Joshua?",
  str_homestory_820401001_31_dialog_content = "Of course!",
  str_homestory_820401001_32_dialog_content = "Growing flowers isn't difficult, but it does require patience.",
  str_homestory_820401001_33_dialog_content = "Flowers are very delicate in their early stage of growth.",
  str_homestory_820401001_34_dialog_content = "You can use the pot for this plant for exactly that.",
  str_homestory_820401001_35_dialog_content = "Once you plant the seeds, make sure you water regularly<sprite=emo_hanshui size=60 /> and wait for them to burgeon.",
  str_homestory_820401001_36_dialog_content = "But remember not to overwater.",
  str_homestory_820401001_37_dialog_content = "Okay, got it. And then?",
  str_homestory_820401001_38_dialog_content = "After the seeds sprout, care for them for a month.",
  str_homestory_820401001_39_dialog_content = "Nourish the seedlings with more nutrients in the interim!",
  str_homestory_820401001_40_dialog_content = "When you see saplings, transplant them to a bigger space.",
  str_homestory_820401001_41_dialog_content = "So I need to move them, I see...",
  str_homestory_820401001_42_dialog_content = "Yes. When you develop from a child to a courageous youth, PlayerName...",
  str_homestory_820401001_43_dialog_content = "Didn't you also venture out and broaden your horizons elsewhere?",
  str_homestory_820401001_44_dialog_content = "That's part of the growth cycle.",
  str_homestory_820401001_45_dialog_content = "W-Well, that's precisely what happened...",
  str_homestory_820401001_46_dialog_content = "But you're actually making me blush.",
  str_homestory_820401001_47_dialog_content = "You're a nice kid, PlayerName.",
  str_homestory_820501001_0_dialog_content = "Miss Blanc?",
  str_homestory_820501001_1_dialog_content = "I saw you had your eyes closed. Were you asleep<sprite=emo_kun size=60 />?",
  str_homestory_820501001_2_dialog_content = "No, I was meditating.",
  str_homestory_820501001_3_dialog_content = "Meditating?",
  str_homestory_820501001_4_dialog_content = "Yes. Do you know what meditation is?",
  str_homestory_820501001_5_option_content = "A bit",
  str_homestory_820501001_6_dialog_content = "I heard meditation can calm your mind and heal traumas.",
  str_homestory_820501001_7_dialog_content = "That's correct, it can indeed do that.",
  str_homestory_820501001_8_option_content = "Nope",
  str_homestory_820501001_9_dialog_content = "Meditation is a mental practice that can calm your mind and heal traumas.",
  str_homestory_820501001_10_dialog_content = "Are you having some sort of problem? Feeling restless?",
  str_homestory_820501001_11_dialog_content = "Other than meditating alone, you can also talk to a friend, such as me.",
  str_homestory_820501001_12_dialog_content = "I thought you looked rather lonesome.",
  str_homestory_820501001_13_dialog_content = "I appreciate the thought.",
  str_homestory_820501001_14_dialog_content = "I enjoy your company, of course, but I cannot tell you the reason for my meditation.",
  str_homestory_820501001_15_dialog_content = "Rather, it wouldn't do any good if I told you, anyway.",
  str_homestory_820501001_16_dialog_content = "Is it something serious? I can try to help...",
  str_homestory_820501001_17_dialog_content = "Heheh, having a friend like you just might be of help.",
  str_homestory_820501001_18_dialog_content = "Since my mood perks up whenever I see you.",
  str_homestory_820501001_19_dialog_content = "Meditation is also a secret to looking youthful.",
  str_homestory_820501001_20_dialog_content = "Look youthful?",
  str_homestory_820501001_21_dialog_content = "Yes. I was meditating on slowing down aging and maintaining my physical appearance.",
  str_homestory_820501001_22_dialog_content = "You could do that just by meditating?",
  str_homestory_820501001_23_dialog_content = "Do not underestimate the power of thoughts.",
  str_homestory_820501001_24_dialog_content = "So, would you like to try it?",
  str_homestory_820501001_25_dialog_content = "Can it make me a strong and mighty fighter?",
  str_homestory_820501001_26_dialog_content = "Is that what you want?",
  str_homestory_820501001_27_dialog_content = "Yeah, then I can better protect the people and things I want to protect.",
  str_homestory_820501001_28_dialog_content = "I greatly approve of that thinking since I have also been fighting to protect.",
  str_homestory_820501001_29_dialog_content = "But allow me to remind you that protection takes many forms.",
  str_homestory_820501001_30_dialog_content = "Take me, for example. Even as a guide, I'm defending Lumopolis in different ways.",
  str_homestory_820501001_31_dialog_content = "Why the reminder? Is it because I can't manifest what I want through meditation?",
  str_homestory_820501001_32_dialog_content = "I truly do not know if meditation will improve and increase muscle mass.",
  str_homestory_820501001_33_dialog_content = "You can still try it, though.",
  str_homestory_820501001_34_dialog_content = "Well, I don't think it will either...",
  str_homestory_807501001_0_dialog_content = "Odi?",
  str_homestory_807501001_1_dialog_content = "I can't believe there's something this nice here!",
  str_homestory_807501001_2_dialog_content = "Where's my wrench? I'm gonna start taking things apart!",
  str_homestory_807501001_3_dialog_content = "Wait, what are you dismantling now?",
  str_homestory_807501001_4_dialog_content = "The street light. Why?",
  str_homestory_807501001_5_option_content = "You can't do that.",
  str_homestory_807501001_6_option_content = "Is the street light broken?",
  str_homestory_807501001_7_dialog_content = "No, I just want to take it apart.",
  str_homestory_807501001_8_dialog_content = "Can't do that, then.<sprite=emo_shengqi size=60 />",
  str_homestory_807501001_9_dialog_content = "Why you! Why can't I? It's just a plain old street light!",
  str_homestory_807501001_10_dialog_content = "It's not broken, so why would you take it down?",
  str_homestory_807501001_11_dialog_content = "To study it, of course.",
  str_homestory_807501001_12_dialog_content = "See, this light is completely different from the rest.",
  str_homestory_807501001_13_dialog_content = "Uh, I don't see much difference at all.",
  str_homestory_807501001_14_dialog_content = "I can tell it has intricate internal gears and wiring by the exterior.",
  str_homestory_807501001_15_dialog_content = "I don't think that's how street lights in Lumopolis work...",
  str_homestory_807501001_16_dialog_content = "I told you, you wouldn't understand.",
  str_homestory_807501001_17_dialog_content = "No, you didn't tell me that.",
  str_homestory_807501001_18_dialog_content = "I see you got better at sassing.",
  str_homestory_807501001_19_dialog_content = "Okay, you made up your mind to keep this light, right?",
  str_homestory_807501001_20_dialog_content = "Well then, let's go at it.",
  str_homestory_807501001_21_dialog_content = "And we'll see if I can whack you into malfunctioning!",
  str_homestory_807501001_22_dialog_content = "I'm not a machine, I can't malfunction!",
  str_homestory_807501001_23_dialog_content = "Your cable's the only thing that's going to malfunction.",
  str_homestory_807501001_24_dialog_content = "Are you threatening me?",
  str_homestory_807501001_25_dialog_content = "I'm only stating the facts...",
  str_homestory_807501001_26_dialog_content = "Don't you look down on us techs. You might be a Caelestite, but I'll still...",
  str_homestory_807501001_27_dialog_content = "???",
  str_homestory_807501001_28_dialog_content = "Oops, I don't know what to threaten you with.<sprite=emo_sikao size=60 />",
  str_homestory_807501001_29_dialog_content = "Hahaha...",
  str_homestory_807501001_30_dialog_content = "Hey, laugh at me again and I'll call for backups!",
  str_homestory_807501001_31_dialog_content = "Hahahahaha!",
  str_homestory_807501001_32_dialog_content = "Stop laughing, or I'll get Sinsa to come over!",
  str_homestory_807501001_33_dialog_content = "You sure Sinsa will take your side?",
  str_homestory_807501001_34_dialog_content = "Uh... Well, not really...",
  str_homestory_807501001_35_dialog_content = "So, you just want to study this light?",
  str_homestory_807501001_36_dialog_content = "Yeah. It seems interesting enough to break down and see.",
  str_homestory_807501001_37_dialog_content = "But it's working very well right now, so the inside should be fine too.",
  str_homestory_807501001_38_dialog_content = "Why don't you wait till it doesn't work? Then I'll ask you to repair it.",
  str_homestory_807501001_39_dialog_content = "That's not a bad idea. Fixing things is what I do!",
  str_homestory_807501001_40_dialog_content = "Fine, I won't take it apart now.",
  str_homestory_807501001_41_dialog_content = "Allow me to thank you in the light's behalf.",
  str_homestory_807501001_42_dialog_content = "Speaking of that, I just caught a gleam in the water. It could be some sort of mechanical thing!",
  str_homestory_807501001_43_dialog_content = "I should scoop it out and take it apart!",
  str_homestory_807501001_44_dialog_content = "Uh, perhaps I should go save whatever is in the water...",
  str_homestory_820601001_0_dialog_content = "What's she doing?",
  str_homestory_820601001_1_dialog_content = "What are you looking at?<sprite=emo_yihuo size=60 />",
  str_homestory_820601001_2_dialog_content = "The view up here is amazing!",
  str_homestory_820601001_3_dialog_content = "You've been looking for a while. Are you sure it's just the view?",
  str_homestory_820601001_4_dialog_content = "Don't worry about that. Are you interested in working with me?",
  str_homestory_820601001_5_dialog_content = "Your keen Caelestite perception will definitely help me in future business competitions!",
  str_homestory_820601001_6_dialog_content = "Help you? Competition?",
  str_homestory_820601001_7_dialog_content = "They say \"Business is war\" and a talent like you is exactly what I need!",
  str_homestory_820601001_8_dialog_content = "I'm offering project bonuses plus stock options. So, you in?",
  str_homestory_820601001_9_dialog_content = "That depends on the projects and how much stock—",
  str_homestory_820601001_10_dialog_content = "Wait, I haven't said yes yet!",
  str_homestory_820601001_11_dialog_content = "What's the business competition about? And what's that got to do with the view up here?",
  str_homestory_820601001_12_dialog_content = "I actually just thought of a wonderful business idea... Don't tell anyone.",
  str_homestory_820601001_13_dialog_content = "I-I won't.",
  str_homestory_820601001_14_dialog_content = "It's a foray into the blue sea!",
  str_homestory_820601001_15_option_content = "Blue sea?",
  str_homestory_820601001_16_dialog_content = "Ocean, like it says!",
  str_homestory_820601001_17_dialog_content = "So, you want to get into shipping?",
  str_homestory_820601001_18_option_content = "Shipping industry?",
  str_homestory_820601001_19_dialog_content = "No!",
  str_homestory_820601001_20_dialog_content = "Blue sea is a metaphor, a simile!",
  str_homestory_820601001_21_dialog_content = "What's it a metaphor for?",
  str_homestory_820601001_22_dialog_content = "In business, that means uncharted territory rife with opportunities!",
  str_homestory_820601001_23_dialog_content = "But what's that got to do with you watching from the watchtower?",
  str_homestory_820601001_24_dialog_content = "I realized the islands in the sea haven't really been developed yet!",
  str_homestory_820601001_25_dialog_content = "Whether it's literally or figuratively, it's both blue sea!",
  str_homestory_820601001_26_dialog_content = "If I can discover islands in the ocean and turn them into resorts...",
  str_homestory_820601001_27_dialog_content = "Summer vacation, adventure, treasure hunt, sports, swimming, children's playpark...",
  str_homestory_820601001_28_dialog_content = "I could go on and on just on themes alone!",
  str_homestory_820601001_29_dialog_content = "So you want to develop islands? Anything specific right now?",
  str_homestory_820601001_30_dialog_content = "No suitable prospects yet. That's why I want to get a ship and look for one.",
  str_homestory_820601001_31_dialog_content = "As big as the ocean is, there's bound to be an uninhabited island somewhere!",
  str_homestory_820601001_32_dialog_content = "We just have to beat everyone to it and claim the island, then we can build it however we want!",
  str_homestory_820601001_33_dialog_content = "We? I'm going too?",
  str_homestory_820601001_34_dialog_content = "Of course! That uncanny eyesight and hearing of yours will come in very handy.",
  str_homestory_820601001_35_dialog_content = "I sound pretty amazing in that description.",
  str_homestory_820601001_36_dialog_content = "So, the first step is to find a suitable island?",
  str_homestory_820601001_37_dialog_content = "That's right. I was wondering if I could see farther if we moved the watchtower onto a ship.",
  str_homestory_820601001_38_dialog_content = "And since you're here, let's negotiate the price.",
  str_homestory_820601001_39_dialog_content = "I have no intention of selling it...<sprite=emo_tanqi size=60 />",
  str_homestory_820601001_40_dialog_content = "We'll call it your share of seed money then? You're pretty interested in this venture, I see.",
  str_homestory_820601001_41_dialog_content = "That's not what I meant.",
  str_homestory_820601001_42_dialog_content = "Need more time to think it over? No problem. No contract has been drafted yet, so everything's negotiable before signing the dotted line.",
  str_homestory_820601001_43_dialog_content = "I'll put the plans together as quickly as I can. You just try to make up your mind fast!",
  str_homestory_820601001_44_dialog_content = "...A-Alright. See you then.",
  str_homestory_820701001_0_dialog_content = "Is he riding it?",
  str_homestory_820701001_1_dialog_content = "It seems you're having a great time.",
  str_homestory_820701001_2_dialog_content = "That's very trendy of you to get the new ride into Cloud Gardens! Very cool!",
  str_homestory_820701001_3_dialog_content = "But I heard it's better with two people.",
  str_homestory_820701001_4_dialog_content = "I've heard that playing as a duo can serve as a sort of test, particularly for couples...<sprite=emo_sikao size=60 />",
  str_homestory_820701001_5_dialog_content = "A test?",
  str_homestory_820701001_6_dialog_content = "Two people who are together get on it and ride for a few rounds...",
  str_homestory_820701001_7_dialog_content = "And if they can still manage to ask how the other is doing right after they step off...",
  str_homestory_820701001_8_dialog_content = "That means the relationship is solid. Otherwise, tsk...",
  str_homestory_820701001_9_dialog_content = "Then why are you riding this alone? Are you preparing for a future test?",
  str_homestory_820701001_10_dialog_content = "Wrong, mate!",
  str_homestory_820701001_11_dialog_content = "It's a dizzy, nauseous ride, but also very exciting.",
  str_homestory_820701001_12_dialog_content = "Exciting enough for me to remember back in those days...",
  str_homestory_820701001_13_dialog_content = "I don't think I want to know what you've been through, but I guess it's story time, nevertheless.",
  str_homestory_820701001_14_dialog_content = "I used to be a hunter, specializing in going after certain bad guys.",
  str_homestory_820701001_15_dialog_content = "You mean like a sheriff? But didn't you come from Rediesel Desert?",
  str_homestory_820701001_16_dialog_content = "There couldn't be anything like that. Only gangs like Rediesel Wrench wander around the place.",
  str_homestory_820701001_17_dialog_content = "I did it on my own, which is why I said hunter and not sheriff.",
  str_homestory_820701001_18_dialog_content = "So what kind of bad guys did you go after? Did it have anything to do with your past?",
  str_homestory_820701001_19_dialog_content = "I heard a village in Denuo Valley was sacked once upon a time. Are they related?",
  str_homestory_820701001_20_dialog_content = "Where should I begin... Let's start with a story.",
  str_homestory_820701001_21_dialog_content = "Go ahead.",
  str_homestory_820701001_22_dialog_content = "Once upon a time, there was a great fisherman with unparalleled fishing skills.",
  str_homestory_820701001_23_dialog_content = "The point is, the nets he made were very sturdy and tight, that no fish could escape.",
  str_homestory_820701001_24_dialog_content = "He got big hauls every time he went out to sea, thus becoming wealthy.",
  str_homestory_820701001_25_dialog_content = "But then he started catching fewer and fewer fish...",
  str_homestory_820701001_26_dialog_content = "Ran out of fish?",
  str_homestory_820701001_27_dialog_content = "That's right! The nets were so tight, even the young ones weren't left out.",
  str_homestory_820701001_28_dialog_content = "So the fish population dwindled down to nothing, until one day...",
  str_homestory_820701001_29_dialog_content = "I see a plot twist coming.<sprite=emo_yaosu size=60 />",
  str_homestory_820701001_30_dialog_content = "The fisherman's son saw a beautiful fish in a hidden reef!",
  str_homestory_820701001_31_dialog_content = "Its size indicated it was young, but truly beautiful.",
  str_homestory_820701001_32_dialog_content = "The son couldn't help but tell his father, the fisherman, when he got home.",
  str_homestory_820701001_33_dialog_content = "I bet the fisherman went after it immediately.",
  str_homestory_820701001_34_dialog_content = "This time, he brought the sturdiest, tightest net he had, vowing to catch the fish.",
  str_homestory_820701001_35_dialog_content = "For he knew it was a precious aquarium fish that could fetch very good money.",
  str_homestory_820701001_36_dialog_content = "Guided by his son, he reached the secluded reef...",
  str_homestory_820701001_37_dialog_content = "I bet this is when the trouble began.",
  str_homestory_820701001_38_dialog_content = "Correct! They did see the fish again, except it was even bigger and prettier!",
  str_homestory_820701001_39_dialog_content = "Was it a parent of the fish that the son saw?",
  str_homestory_820701001_40_dialog_content = "Probably.",
  str_homestory_820701001_41_dialog_content = "When the big beautiful fish saw the boat, it began ducking and dodging in the reef.",
  str_homestory_820701001_42_dialog_content = "The fisherman chased it in a hot pursuit...",
  str_homestory_820701001_43_dialog_content = "Only to crash the boat into the reef.",
  str_homestory_820701001_44_dialog_content = "The boat sank. Both the fisherman and the son died.",
  str_homestory_820701001_45_dialog_content = "Oh...",
  str_homestory_820701001_46_dialog_content = "So who's the bad guy you talked about since the fisherman and his son died in the story?",
  str_homestory_820701001_47_dialog_content = "That's why it's just a story. Don't read too much into it.",
  str_homestory_820801001_0_dialog_content = "She's been fixated for a long time...",
  str_homestory_820801001_1_dialog_content = "What are you doing?",
  str_homestory_820801001_2_dialog_content = "What? Oh, it's you! You noticed me?!<sprite=emo_wuzui size=60 />",
  str_homestory_820801001_3_dialog_content = "That's because you've been staring at the monument for a long while now. Aren't your eyes tired?",
  str_homestory_820801001_4_dialog_content = "I do feel it now that you mentioned it...",
  str_homestory_820801001_5_dialog_content = "Wait a second, the point is that you noticed me!",
  str_homestory_820801001_6_dialog_content = "Can this be the monument's power, making others notice those who are insignificant?",
  str_homestory_820801001_7_dialog_content = "No, it's really because you've been standing here for way too long.",
  str_homestory_820801001_8_dialog_content = "Check out the images on it! Can you figure out what they mean, PlayerName?",
  str_homestory_820801001_9_dialog_content = "Not really... It seems to be ancient.",
  str_homestory_820801001_10_dialog_content = "It's so old, I don't think anyone can tell what it's supposed to convey.",
  str_homestory_820801001_11_dialog_content = "Is that so... Sigh...",
  str_homestory_820801001_12_dialog_content = "Why the long face now? You look rather down...",
  str_homestory_820801001_13_dialog_content = "That's because I'm pondering the Rediesel Wrench's future.",
  str_homestory_820801001_14_option_content = "What do you mean, future?",
  str_homestory_820801001_15_dialog_content = "I haven't made up my mind yet, but I know it has to be a long-term goal, not the horsing around that we do now.",
  str_homestory_820801001_16_dialog_content = "But that's the Rediesel style! A lot of people joined because of that.",
  str_homestory_820801001_17_dialog_content = "True, but having plans is always nice! I can't think of any yet, but we must have one!",
  str_homestory_820801001_18_option_content = "Aren't you overthinking it?",
  str_homestory_820801001_19_dialog_content = "...",
  str_homestory_820801001_20_dialog_content = "Bopper?",
  str_homestory_820801001_21_dialog_content = "I don't know why, but I feel somebody has to do it!",
  str_homestory_820801001_22_dialog_content = "Hanging out and loitering every day with random objectives in mind... That's just undisciplined.",
  str_homestory_820801001_23_dialog_content = "It seems you've been giving it serious thought...",
  str_homestory_820801001_24_dialog_content = "I don't think it's even on Sinsa's agenda.",
  str_homestory_820801001_25_dialog_content = "I understand that as the boss, he only has to be the cool leader.",
  str_homestory_820801001_26_dialog_content = "Whereas it's up to me to work plans out as the strategist.",
  str_homestory_820801001_27_dialog_content = "But what's that got to do with the monuments?",
  str_homestory_820801001_28_dialog_content = "Chuck it up to spontaneity!",
  str_homestory_820801001_29_dialog_content = "I heard there are monuments like this in Lumopolis, Illumina Federation, and even Northland.",
  str_homestory_820801001_30_dialog_content = "Built to memorialize famous people, merits, or feats!",
  str_homestory_820801001_31_dialog_content = "But we Rediesel Wrench don't have anything like it...",
  str_homestory_820801001_32_dialog_content = "Plus, we don't own our own turf like them...",
  str_homestory_820801001_33_dialog_content = "So what's going to happen if the future goes awry or everybody gets in a big squabble and goes their separate ways?",
  str_homestory_820801001_34_dialog_content = "That does sound like a legit concern.",
  str_homestory_820801001_35_dialog_content = "See!",
  str_homestory_820801001_36_dialog_content = "But have you thought about how the monument should take shape?",
  str_homestory_820801001_37_dialog_content = "Shape?",
  str_homestory_820801001_38_dialog_content = "It doesn't necessarily have to be a monument, just something representative of the Rediesel Wrench.",
  str_homestory_820801001_39_dialog_content = "You mean like...",
  str_homestory_820801001_40_dialog_content = "Graffiti on cars?",
  str_homestory_820801001_41_dialog_content = "If it's your style, you can always tell it's Rediesel Wrench wherever you are.",
  str_homestory_820801001_42_dialog_content = "Or like if we killed a sandworm, we can draw one with an X over it.",
  str_homestory_820801001_43_dialog_content = "Yes, that's a great idea!",
  str_homestory_820801001_44_dialog_content = "Not to mention Rediesel Wrench is full of awesome graffiti artists!",
  str_homestory_820801001_45_dialog_content = "I gotta go figure out the plan for the Great Rediesel Wrench Car Graffiti Contest!<sprite=emo_yaosu size=60 />",
  str_homestory_820901001_0_dialog_content = "What's she looking at?",
  str_homestory_820901001_1_dialog_content = "Commander Wrath... What're you doing here?",
  str_homestory_820901001_2_dialog_content = "I'm not doing anything. Just saw something really interesting.",
  str_homestory_820901001_3_dialog_content = "So this is how Illumina goes about recruiting these days...",
  str_homestory_820901001_4_dialog_content = "Aren't you the Grand Marshal? Why does it feel like you're only just realizing this now...?",
  str_homestory_820901001_5_dialog_content = "Because the Grand Marshal isn't responsible for overseeing external conscription...",
  str_homestory_820901001_6_dialog_content = "That's what I'm guessing... What do you say?",
  str_homestory_820901001_7_option_content = "Indeed.",
  str_homestory_820901001_8_dialog_content = "I don't think the Grand Marshal really has time for things like that.",
  str_homestory_820901001_9_option_content = "Why are you asking me?!",
  str_homestory_820901001_10_dialog_content = "You're the Grand Marshal! Yet you're still guessing what your responsibilities are supposed to be?",
  str_homestory_820901001_11_dialog_content = "The first thing I did after becoming Grand Marshal was lead an expedition.",
  str_homestory_820901001_12_dialog_content = "But now... It's about time to look into other matters.",
  str_homestory_820901001_13_dialog_content = "For instance—where did you guys find this thing?",
  str_homestory_820901001_14_dialog_content = "It was in Umbraton... We were shooting a movie at the time.",
  str_homestory_820901001_15_dialog_content = "A movie? I see... <sprite=emo_sikao size=60 />",
  str_homestory_820901001_16_dialog_content = "What comes to your mind?",
  str_homestory_820901001_17_dialog_content = "These conscription advertisements... How do they expect to get the nation's best and bravest to enlist in the army with that pathetic board?",
  str_homestory_820901001_18_dialog_content = "While I'm at the helm, I wanna make Illumina stronger than it's ever been before.",
  str_homestory_820901001_19_dialog_content = "So?",
  str_homestory_820901001_20_dialog_content = "So how about we make a movie all about Illumina soldiers? A propaganda piece to help recruit the next generation of this nation's heroes...",
  str_homestory_820901001_21_option_content = "Are you being serious right now?",
  str_homestory_820901001_22_dialog_content = "Even when you put it that way... Shooting a movie still doesn't sound like an Illumina thing.",
  str_homestory_820901001_23_dialog_content = "It's true that Illumina's approach to education leans more toward technology and the art of war than the actual arts themselves...",
  str_homestory_820901001_24_dialog_content = "I'll be the first to admit that.",
  str_homestory_820901001_25_dialog_content = "That's why I want you to shoot this thing.",
  str_homestory_820901001_26_option_content = "Let's do it!",
  str_homestory_820901001_27_dialog_content = "Rousing and inspirational as all those slogans might be, they could never compare to a movie.",
  str_homestory_820901001_28_dialog_content = "If we could show the world the bravery of a true Illumina hero on the big screen, we'd send shock waves across the entire continent.",
  str_homestory_820901001_29_dialog_content = "I can't wait to make this happen!",
  str_homestory_820901001_30_dialog_content = "Well, that settles it! This movie thing is all in your hands now. I'll go raise the funds and prepare for your salaries.",
  str_homestory_820901001_31_dialog_content = "But... I don't know the first thing about making a movie!",
  str_homestory_820901001_32_dialog_content = "I thought you were the creative type, no? I remember you even wrote some poetry back then.",
  str_homestory_820901001_33_dialog_content = "Writing poetry and making a movie are two very different things! Besides, my poetry's not even that good...",
  str_homestory_820901001_34_dialog_content = "To my understanding, the arts are all pretty much interconnected, aren't they?",
  str_homestory_820901001_35_dialog_content = "That's not the problem here!",
  str_homestory_820901001_36_dialog_content = "Besides, there isn't even a single movie theater in all Illumina!",
  str_homestory_820901001_37_dialog_content = "Well, we have screening halls, but they're only open on rest days.",
  str_homestory_820901001_38_dialog_content = "So people won't even get the chance to watch movies...",
  str_homestory_820901001_39_dialog_content = "Illumina enlists all its own citizens anyway. A recruitment campaign like this is obviously for potential recruits outside the federation.",
  str_homestory_820901001_40_dialog_content = "But now that you mention it, letting Illuminans see the federation through the director's lens might boost their morale, perhaps.",
  str_homestory_820901001_41_dialog_content = "And if that's the case... it'll be a rare opportunity indeed. Then—I'm gonna have to star in this thing.",
  str_homestory_820901001_42_dialog_content = "How about we get Reinhardt down here and see who has the most screen presence, eh?",
  str_homestory_820901001_43_dialog_content = "Hey, if we get a few commanders on screen, it might even ignite a little competition among the legions.",
  str_homestory_820901001_44_dialog_content = "You're really getting carried away here...",
  str_homestory_820901001_45_dialog_content = "Oh yeah, and you can also act and direct this thing at the same time.",
  str_homestory_820901001_46_dialog_content = "As the sole Caelestite and the director, you surely should have a starring role.",
  str_homestory_820901001_47_dialog_content = "You're not listening to me at all, are you? Maybe I should just give in... <sprite=emo_yundao size=60 />",
  str_homestory_820901001_48_dialog_content = "Oh, right. I've just come up with a perfect name for this movie.",
  str_homestory_820901001_49_dialog_content = "\"Saving Caelestite PlayerName\"... What do you say?",
  str_homestory_821001001_0_dialog_content = "Joselyne is praying in front of the flag...",
  str_homestory_821001001_1_dialog_content = "Joselyne?",
  str_homestory_821001001_2_dialog_content = "No need to stand there waiting all that time. You could've just called out to me.",
  str_homestory_821001001_3_dialog_content = "I was afraid I might disturb you.",
  str_homestory_821001001_4_dialog_content = "The God of Light questions not our faith merely because our prayers are interrupted.",
  str_homestory_821001001_5_dialog_content = "And I'd never get angry over such a trifling matter. Do you need my help with something?",
  str_homestory_821001001_6_dialog_content = "No, I just saw you standing in front of this flag and thought I'd come over.",
  str_homestory_821001001_7_dialog_content = "Were you praying to this flag just now?",
  str_homestory_821001001_8_dialog_content = "Praying? Well, it's true that if one prays through a specific medium, their prayers will be heard more clearly.",
  str_homestory_821001001_9_option_content = "A medium like this flag?",
  str_homestory_821001001_10_dialog_content = "Umm. Believing in the God of Light has always been part and parcel of conventional Lumopolis life...",
  str_homestory_821001001_11_dialog_content = "So I guess it makes sense that you'd use the flag of Lumopolis as a medium for prayer.",
  str_homestory_821001001_12_option_content = "You mean like a holy relic?",
  str_homestory_821001001_13_dialog_content = "From what I understand, people seeking communion with their god often attempt to do so by using holy relics, right?",
  str_homestory_821001001_14_dialog_content = "In this way, they can presumably communicate with the divine face-to-face. Sounds super effective!",
  str_homestory_821001001_15_dialog_content = "Actually, any object can be used as a medium to achieve the same effect.",
  str_homestory_821001001_16_dialog_content = "Light's<sprite=emo_taiyang size=60 /> grace spreads throughout the land. Everything that exists under the sun is connected to the light of god.",
  str_homestory_821001001_17_dialog_content = "I often pray to the tomato flowers when tending to the vegetable garden.",
  str_homestory_821001001_18_dialog_content = "For real?",
  str_homestory_821001001_19_dialog_content = "However, it's important to select suitable subjects when performing specific prayers.",
  str_homestory_821001001_20_dialog_content = "Then what did you pray for when you were staring at the Lumopolis flag?",
  str_homestory_821001001_21_dialog_content = "...",
  str_homestory_821001001_22_dialog_content = "Sorry, I'm just curious.",
  str_homestory_821001001_23_dialog_content = "If I spoke anything out of turn, please just ignore me, Joselyne.",
  str_homestory_821001001_24_dialog_content = "No, no... After all, it is my duty to spread the God of Light's grace to all.",
  str_homestory_821001001_25_dialog_content = "When it comes to faith, I'll share whatever I know.",
  str_homestory_821001001_26_dialog_content = "But just now, I...",
  str_homestory_821001001_27_dialog_content = "You what...?",
  str_homestory_821001001_28_dialog_content = "I just wanted to take a closer look at the stitchwork on the flag.",
  str_homestory_821001001_29_dialog_content = "Lumopolis truly shines in the field of crafting items related to religion.",
  str_homestory_821001001_30_dialog_content = "Especially flags like this. They are beacons guiding all who behold them. Needless to say, they must be adequately resilient.",
  str_homestory_821001001_31_dialog_content = "If I can find a way to improve my sewing skills, I can do more to help the people in need there.",
  str_homestory_821001001_32_dialog_content = "Hah, and now I can't seem to get this image of you raising a flag heroically into the air out of my head...",
  str_homestory_821001001_33_dialog_content = "You won't find me raising any flags. It's not as easy as it looks, you know?",
  str_homestory_821001001_34_dialog_content = "Although the locals have labeled me a \"Saintess,\" I am far from being the spiritual leader they need.",
  str_homestory_821001001_35_dialog_content = "As for now, I need to start by sewing up the banner of the Ironthorn Knights.",
  str_homestory_821001001_36_dialog_content = "Right. Making a decent flag that leads the battle charge is just as important as waving it. I'll help out too, if you want.",
  str_homestory_821001001_37_dialog_content = "Do you also know how to sew?",
  str_homestory_821001001_38_dialog_content = "Well, I learned a few small tricks from Soroz as a kid...",
  str_homestory_821001001_39_dialog_content = "I'll teach you everything I've learned. This should reinforce and improve my skills too.",
  str_homestory_821001001_40_dialog_content = "First things first—bring all of your clothes over to me.",
  str_homestory_821001001_41_dialog_content = "A-All of them?",
  str_homestory_821001001_42_dialog_content = "The only way to master the fundamentals is through extensive practice.",
  str_homestory_821001001_43_dialog_content = "All talk and no action will only lead us further into the darkness, from which even the God of Light can't deliver us.",
  str_homestory_821001001_44_dialog_content = "I believe you're not that kind of Caelestite, are you?",
  str_homestory_821001001_45_dialog_content = "Of course I'm not! I'll go get those clothes right away!",
  str_homestory_821201001_0_dialog_content = "Antony?",
  str_homestory_821201001_1_dialog_content = "Antony, you've been standing by the Jagged Corridor for half an hour.",
  str_homestory_821201001_2_dialog_content = "Are you interested in this thing?",
  str_homestory_821201001_3_dialog_content = "Oh... Hello, PlayerName.",
  str_homestory_821201001_4_dialog_content = "Truth be told, I really am quite interested in it.",
  str_homestory_821201001_5_dialog_content = "The first time I laid eyes on it, I was certain of one thing—",
  str_homestory_821201001_6_dialog_content = "There's no denying its research value!",
  str_homestory_821201001_7_dialog_content = "May I ask, what kind of creature are these bones actually from?",
  str_homestory_821201001_8_dialog_content = "Now that's a question that's got even me stumped...",
  str_homestory_821201001_9_dialog_content = "At present, the jury's out on that particular point. There are all sorts of opinions regarding these bones.",
  str_homestory_821201001_10_dialog_content = "In your own personal opinion, what kind of bones would you say they are?",
  str_homestory_821201001_11_dialog_content = "I trust your judgment.",
  str_homestory_821201001_12_dialog_content = "Let me think<sprite=emo_sikao size=60 />... Perhaps they're...",
  str_homestory_821201001_13_option_content = "The bones of a certain animal.",
  str_homestory_821201001_14_dialog_content = "Animal bones?",
  str_homestory_821201001_15_dialog_content = "I've traveled to many places and never seen bones like these.",
  str_homestory_821201001_16_dialog_content = "In that case, these could be the remains of some extinct creature!",
  str_homestory_821201001_17_dialog_content = "Really...?",
  str_homestory_821201001_18_option_content = "It's the ribcage of a Colossus.",
  str_homestory_821201001_19_dialog_content = "What?!",
  str_homestory_821201001_20_dialog_content = "Are you serious?",
  str_homestory_821201001_21_dialog_content = "C-Could these really be the bones once used to make a Colossus?!",
  str_homestory_821201001_22_dialog_content = "It's just a guess, that's all.",
  str_homestory_821201001_23_dialog_content = "No, no, you're a Caelestite! You can't be wrong!",
  str_homestory_821201001_24_dialog_content = "Anyway, I need to study this Jagged Corridor carefully!",
  str_homestory_821201001_25_dialog_content = "Can I move a part of it to my room to aid me in my research?!",
  str_homestory_821201001_26_dialog_content = "Hey, you're not moving anything to your room, okay?!",
  str_homestory_821201001_27_dialog_content = "After all, this is public property...",
  str_homestory_821201001_28_dialog_content = "Having said that, I'm a little curious as to what the truth actually is.",
  str_homestory_821201001_29_dialog_content = "Alright, you can conduct your research here, and if you need a hand, I'm sure you'll be able to find someone willing to help you.",
  str_homestory_821201001_30_dialog_content = "Don't worry!",
  str_homestory_821201001_31_dialog_content = "I know I'll get to the bottom of this!<sprite=emo_dianzan size=60 />",
  str_homestory_821101001_0_dialog_content = "Zarya, what are you doing?",
  str_homestory_821101001_1_dialog_content = "Oh, PlayerName, do you have any idea what's this?",
  str_homestory_821101001_2_dialog_content = "It's got \"Detective's Car\" written on it.",
  str_homestory_821101001_3_dialog_content = "What's a... car?",
  str_homestory_821101001_4_dialog_content = "Well, basically, it's a convenient mode of transportation.",
  str_homestory_821101001_5_dialog_content = "This is a mode of transportation?",
  str_homestory_821101001_6_dialog_content = "People don't use carriages anymore...?",
  str_homestory_821101001_7_dialog_content = "They still use carriages in some places, but you'll find that rich people in most areas, generally drive cars.",
  str_homestory_821101001_8_dialog_content = "Oh...",
  str_homestory_821101001_9_dialog_content = "You're interested in carriages, Zarya?",
  str_homestory_821101001_10_dialog_content = "I'm interested in seeing how it's something I've never seen before.",
  str_homestory_821101001_11_dialog_content = "Can you take me to see the real deal later on?",
  str_homestory_821101001_12_option_content = "Sure.",
  str_homestory_821101001_13_dialog_content = "But you have to promise you'll sit in the back seat and behave yourself.",
  str_homestory_821101001_14_dialog_content = "Under no circumstances are you allowed to drive.",
  str_homestory_821101001_15_option_content = "I don't think so.",
  str_homestory_821101001_16_dialog_content = "Huh? Why not...?<sprite=emo_yihuo size=60 />",
  str_homestory_821101001_17_dialog_content = "I feel like you're always just moments away from doing something incredibly dangerous.",
  str_homestory_821101001_18_dialog_content = "Like commandeering a carriage, for example.",
  str_homestory_821101001_19_dialog_content = "Impressive, PlayerName.",
  str_homestory_821101001_20_dialog_content = "How did you know I wanted to ride it?",
  str_homestory_821101001_21_dialog_content = "Ride?",
  str_homestory_821101001_22_dialog_content = "Didn't you say it was a mode of transportation... like any other carriage?",
  str_homestory_821101001_23_dialog_content = "So it should be the same principle, right?",
  str_homestory_821101001_24_dialog_content = "All you need to do is give it a little whip and it'll take you to where you wanna go.",
  str_homestory_821101001_25_dialog_content = "Or do you have to give it a command?",
  str_homestory_821101001_26_dialog_content = "I'm not the best at controlling my Luminatics, but I know my way around a horse!",
  str_homestory_821101001_27_dialog_content = "...",
  str_homestory_821101001_28_dialog_content = "Huh? Cat got your tongue?",
  str_homestory_821101001_29_dialog_content = "I get the feeling you really need to brush up on your knowledge of the modern world...",
  str_homestory_821101001_30_dialog_content = "Huh?",
  str_homestory_821301001_0_dialog_content = "No. 33?",
  str_homestory_821301001_1_dialog_content = "Are you planning to go on a picnic?",
  str_homestory_821301001_2_dialog_content = "Yes, as you can see.",
  str_homestory_821301001_3_dialog_content = "It is for this reason that I am making the necessary preparations.",
  str_homestory_821301001_4_dialog_content = "Don't tell me you're planning on going alone?",
  str_homestory_821301001_5_dialog_content = "You seem to misunderstand me.",
  str_homestory_821301001_6_dialog_content = "Naturally, I will invite my other Aurorian friends to join me.",
  str_homestory_821301001_7_dialog_content = "That includes you, of course.",
  str_homestory_821301001_8_dialog_content = "It'd be my honor.",
  str_homestory_821301001_9_dialog_content = "...",
  str_homestory_821301001_10_dialog_content = "Speaking of which, why don't you invite Vice and the others?",
  str_homestory_821301001_11_dialog_content = "I am conducting important analysis work.",
  str_homestory_821301001_12_dialog_content = "By asking those around me, I have learned of the food standards at your previous picnics.",
  str_homestory_821301001_13_dialog_content = "Based on the picnic food thus far received from my Aurorian friends, I have come to a shocking conclusion:",
  str_homestory_821301001_14_dialog_content = "An excess of calories can have a catastrophic effect on one's health.",
  str_homestory_821301001_15_dialog_content = "Huh?",
  str_homestory_821301001_16_dialog_content = "What do you think, PlayerName?",
  str_homestory_821301001_17_option_content = "You're absolutely right.",
  str_homestory_821301001_18_dialog_content = "If you're looking at this from a purely nutritional perspective, sure, this kind of food has way too many calories.",
  str_homestory_821301001_19_dialog_content = "It's not often that you agree with my point of view so wholeheartedly.",
  str_homestory_821301001_20_dialog_content = "But...",
  str_homestory_821301001_21_option_content = "That's not true.",
  str_homestory_821301001_22_dialog_content = "Regarding your statement \"that's not true,\" what analytical approach did you employ to reach such a conclusion?",
  str_homestory_821301001_23_dialog_content = "I consider the judgment I shared with you to be completely sound.",
  str_homestory_821301001_24_dialog_content = "When we go for a picnic, our goal is naturally just to blow off steam.",
  str_homestory_821301001_25_dialog_content = "You won't achieve that goal if you spend time sweating the small stuff.",
  str_homestory_821301001_26_dialog_content = "Sweating the small stuff? Blow off some steam?",
  str_homestory_821301001_27_dialog_content = "I know your intentions are good, No. 33, but sometimes you need to let loose.",
  str_homestory_821301001_28_dialog_content = "You can be strict when it's time to be strict, and try relaxing when it's time to relax. That way, people are gonna like you more.",
  str_homestory_821301001_29_dialog_content = "Information received. Analyzing information...",
  str_homestory_821301001_30_dialog_content = "I understand.",
  str_homestory_821301001_31_dialog_content = "Then I will readjust my picnic recipes.",
  str_homestory_821301001_32_dialog_content = "Please wait for my invitation.",
  str_homestory_821401001_0_dialog_content = "Rebecca?",
  str_homestory_821401001_1_dialog_content = "Navigator...",
  str_homestory_821401001_2_dialog_content = "Do you want to sit on the hanging chair?",
  str_homestory_821401001_3_dialog_content = "No... I just feel a little nostalgic...",
  str_homestory_821401001_4_dialog_content = "In the past... there used to be a similar hanging chair in the courtyard of my home.",
  str_homestory_821401001_5_dialog_content = "Back then, my older sister, Eleanor, and I would often play together on the hanging chair.",
  str_homestory_821401001_6_dialog_content = "But only two people could play on it because the hanging chair was too small and had limited space...",
  str_homestory_821401001_7_dialog_content = "Which meant that one of us would always miss out...",
  str_homestory_821401001_8_dialog_content = "Really? So how did you decide who would miss out?",
  str_homestory_821401001_9_dialog_content = "We played rock-paper-scissors.",
  str_homestory_821401001_10_dialog_content = "It's strange now that I think about it. I never lost back then. Not even once.",
  str_homestory_821401001_11_dialog_content = "Maybe they had already discussed this between them?",
  str_homestory_821401001_12_dialog_content = "That's possible. To be honest, the relationship between my older sister and Eleanor... was never that great...",
  str_homestory_821401001_13_dialog_content = "I remember there was a time when I got off the hanging chair to rock it...",
  str_homestory_821401001_14_dialog_content = "In the end, my older sister and Eleanor almost had a fight on the hanging chair.",
  str_homestory_821401001_15_dialog_content = "They almost broke it too that time...",
  str_homestory_821401001_16_dialog_content = "It seems like you really miss those times <sprite=emo_sikao size=60 />.",
  str_homestory_821401001_17_dialog_content = "Would you like to sit on it?",
  str_homestory_821401001_18_dialog_content = "Huh? Me? Well...",
  str_homestory_821401001_19_dialog_content = "I think I'll pass.",
  str_homestory_821401001_20_option_content = "Why?",
  str_homestory_821401001_21_option_content = "Give it a try.",
  str_homestory_821401001_22_dialog_content = "Actually... my venom has been a little restless recently...",
  str_homestory_821401001_23_dialog_content = "If I accidentally doze off while I'm sitting on it, I'm afraid the venom will spill out and destroy the hanging chair.",
  str_homestory_821401001_24_dialog_content = "So I'll just look at it.",
  str_homestory_821401001_25_dialog_content = "If I stand near it and close my eyes, it feels like everything has returned to how it was in the past...",
  str_homestory_821401001_26_dialog_content = "Don't worry about it. I'm here.",
  str_homestory_821401001_27_dialog_content = "I'll wake you up immediately if you fall asleep.",
  str_homestory_821401001_28_dialog_content = "Would it cause you too much trouble...?",
  str_homestory_821401001_29_dialog_content = "It'll be fine.",
  str_homestory_821401001_30_dialog_content = "Um... Can you wait a little longer for me?",
  str_homestory_821401001_31_dialog_content = "There are some errands I need to complete at the clinic. I'll come over immediately after I'm done.",
  str_homestory_821401001_32_dialog_content = "Thank you, Navigator.",
  str_homestory_821501001_0_dialog_content = "Isa?",
  str_homestory_821501001_1_dialog_content = "Oh, it's you.",
  str_homestory_821501001_2_dialog_content = "Is something wrong with this car? You keep staring at it.",
  str_homestory_821501001_3_dialog_content = "Aha! Good question.",
  str_homestory_821501001_4_dialog_content = "Don't you think this car... is super cool?",
  str_homestory_821501001_5_option_content = "Not really.",
  str_homestory_821501001_6_dialog_content = "I think you can say that it's beautiful.",
  str_homestory_821501001_7_option_content = "Yes, indeed.",
  str_homestory_821501001_8_dialog_content = "In a sense, it can be considered to be cool.",
  str_homestory_821501001_9_dialog_content = "Anyway, this car is exactly my style!",
  str_homestory_821501001_10_dialog_content = "If I drive this car to pick up Rebecca...",
  str_homestory_821501001_11_dialog_content = "She'll definitely be very excited!",
  str_homestory_821501001_12_dialog_content = "Are you thinking of picking Rebecca up in this car?",
  str_homestory_821501001_13_dialog_content = "Yes, Rebecca isn't well.",
  str_homestory_821501001_14_dialog_content = "But she still needs to walk to work every day. Don't you think she's being too hard on herself?",
  str_homestory_821501001_15_dialog_content = "It does sound tough.",
  str_homestory_821501001_16_dialog_content = "Right? This is what I came up with after careful consideration.",
  str_homestory_821501001_17_dialog_content = "Rebecca always says that I don't know what she wants. Hehe, she definitely needs this transportation tool this time.",
  str_homestory_821501001_18_dialog_content = "But... this car is too flashy. Rebecca won't like it.",
  str_homestory_821501001_19_dialog_content = "Don't you worry. I understand her well. I'm sure I know what she likes.",
  str_homestory_821501001_20_dialog_content = "Rebecca loves flowers. Look at the flowers all over the car. There's no way she would hate it.",
  str_homestory_821501001_21_dialog_content = "... Uh, give it a try then?",
  str_homestory_821501001_22_dialog_content = "Okay, I'll tell Rebecca now.",
  str_homestory_821501001_23_dialog_content = "She would be delighted.",
  str_homestory_821501001_24_dialog_content = "Best of luck.",
  str_homestory_821601001_0_dialog_content = "What's wrong with this machine, Xuan Ji?",
  str_homestory_821601001_1_dialog_content = "It was used by Caelestites in the past. Interested?",
  str_homestory_821601001_2_dialog_content = "It's a mechanical loom, right?",
  str_homestory_821601001_3_dialog_content = "Yes. There are records about it on Soroz.",
  str_homestory_821601001_4_dialog_content = "Eraveil once used such machines to produce textiles, achieving a self-sufficient lifestyle.",
  str_homestory_821601001_5_dialog_content = "It probably requires regular upkeep but hasn't been in use for a long time...",
  str_homestory_821601001_6_dialog_content = "You want to use it, Xuan Ji?",
  str_homestory_821601001_7_dialog_content = "Not really.",
  str_homestory_821601001_8_dialog_content = "It just looks nostalgic to me.",
  str_homestory_821601001_9_dialog_content = "Nostalgic?",
  str_homestory_821601001_10_dialog_content = "It reminds me of the machines for instructional purposes that I used when I was little.",
  str_homestory_821601001_11_dialog_content = "The masters would start us young pupils off on prototype models.",
  str_homestory_821601001_12_dialog_content = "Looms like this are common. You can even call it my second teacher.",
  str_homestory_821601001_13_dialog_content = "No wonder you'd find it interesting.",
  str_homestory_821601001_14_dialog_content = "Also, prototypes are usually very fragile.",
  str_homestory_821601001_15_dialog_content = "That's the case with the one given to me, with certain identical structures too...",
  str_homestory_821601001_16_dialog_content = "They would also do that to make us cherish the craftsmanship.",
  str_homestory_821601001_17_dialog_content = "I'd love to cherish it too, but it broke down more often than not!",
  str_homestory_821601001_18_option_content = "Because you tried to tweak it?",
  str_homestory_821601001_19_dialog_content = "Bingo.",
  str_homestory_821601001_20_option_content = "It's so fragile",
  str_homestory_821601001_21_dialog_content = "No, it's because I tweaked it a lot...",
  str_homestory_821601001_22_dialog_content = "So it didn't last until my graduation.",
  str_homestory_821601001_23_dialog_content = "When I was finally competent enough, it was beyond repair.",
  str_homestory_821601001_24_dialog_content = "I see.",
  str_homestory_821601001_25_dialog_content = "So, want me to fix this loom?",
  str_homestory_821601001_26_dialog_content = "For this current version of me, it should be very easy.",
  str_homestory_821601001_27_dialog_content = "I can even improve the design for it to work and maintain itself the best it can.",
  str_homestory_821601001_28_dialog_content = "Uh<sprite=emo_sikao size=60 />, that won't be necessary, though.",
  str_homestory_821601001_29_dialog_content = "Even if it were fixed, it would be hard to find the materials for it to process.",
  str_homestory_821601001_30_dialog_content = "Not to mention that we can now easily get inexpensive yet pretty fabrics from stores.",
  str_homestory_821601001_31_dialog_content = "True, same in Longzhou.",
  str_homestory_821601001_32_dialog_content = "To normal people, guilds are more vital than artisans now.",
  str_homestory_821601001_33_dialog_content = "That's progress, right?",
  str_homestory_821601001_34_dialog_content = "Umm, can't refute that. This machine has outlived its purpose.",
  str_homestory_821601001_35_dialog_content = "So, better let it rest in peace.",
  str_homestory_818702001_0_dialog_content = "Tianxian? Master Li?",
  str_homestory_818702001_1_dialog_content = "How come you fell asleep on your feet?",
  str_homestory_818702001_2_dialog_content = "Wake up and go back to your room.",
  str_homestory_818702001_3_dialog_content = "Hey!",
  str_homestory_818702001_4_dialog_content = "I was just up in the heavens chatting with the angels a moment ago.",
  str_homestory_818702001_5_dialog_content = "How soon did I fall back to earth...",
  str_homestory_818702001_6_dialog_content = "Guess I still have a long way to go.",
  str_homestory_818702001_7_dialog_content = "I give up. Didn't you notice?",
  str_homestory_818702001_8_dialog_content = "The thing you fell asleep next to and almost leaned on...",
  str_homestory_818702001_9_dialog_content = "Is a clock.",
  str_homestory_818702001_10_dialog_content = "Unbelievable! How could you be sleeping so soundly next to such a big clock...",
  str_homestory_818702001_11_dialog_content = "Au contraire, mon frere.",
  str_homestory_818702001_12_dialog_content = "As far as I know, many people in Astra kept an alarm clock by their pillows.",
  str_homestory_818702001_13_dialog_content = "However, I preferred the sky as my blanket, the land as my bed, and a sundial as my alarm.",
  str_homestory_818702001_14_dialog_content = "So in this case, I am adapting to what the locals do.",
  str_homestory_818702001_15_dialog_content = "But they did it to get up in time, and you were just trying to get a nap<sprite=emo_kun size=60 />!",
  str_homestory_818702001_16_dialog_content = "Do you not sense the time fleeting at all?",
  str_homestory_818702001_17_dialog_content = "It is because time fleets and life is short that one must turn in when the opportunity presents itself.",
  str_homestory_818702001_18_dialog_content = "You should sleep whenever you feel sleepy, not waiting until you yawn.",
  str_homestory_818702001_19_dialog_content = "Why don't you lean up and take a nap? Then you will understand.",
  str_homestory_818702001_20_option_content = "No.",
  str_homestory_818702001_21_dialog_content = "Still young and inexperienced, I see.",
  str_homestory_818702001_22_dialog_content = "I have seen my share of the world and will never give up any chance to get some shuteye.",
  str_homestory_818702001_23_option_content = "I'll try it.",
  str_homestory_818702001_24_dialog_content = "You are finally enlightened!",
  str_homestory_818702001_25_dialog_content = "But even if I'm to crash here, I have to get ready.",
  str_homestory_818702001_26_dialog_content = "I have to bring my sleeping bag, picnic blanket, and the whole nine yards.",
  str_homestory_818702001_27_dialog_content = "You sure know how to enjoy life. I barely have anything for comfort.",
  str_homestory_818702001_28_dialog_content = "Sigh, I think the sundial is probably the most fortunate of all.",
  str_homestory_818702001_29_dialog_content = "It serves the same purpose whether in Longzhou or Astra.",
  str_homestory_818702001_30_dialog_content = "It has time off as long as the sun is not out.",
  str_homestory_818702001_31_dialog_content = "Have you gone so far as to envy a rock?",
  str_homestory_818702001_32_dialog_content = "Do not underestimate rocks. There are even legendary heroes borne out of rocks!",
  str_homestory_818702001_33_dialog_content = "Unfortunately, I could turn into a rock only in my dreams.",
  str_homestory_818702001_34_dialog_content = "Speaking of which, I feel another nap coming.",
  str_homestory_818702001_35_dialog_content = "Still no sense of urgency, I see...",
  str_homestory_818702001_36_dialog_content = "Do not take everything so seriously, PlayerName.",
  str_homestory_818702001_37_dialog_content = "What is wrong with throttling back at work and stopping to smell the roses?<sprite=emo_qingsong size=60 />",
  str_homestory_818702001_38_dialog_content = "True... That's the Li Tianxian I know.",
  str_homestory_818802001_0_dialog_content = "Dantang?",
  str_homestory_818802001_1_dialog_content = "The craftsmanship on this kite is rather unique.",
  str_homestory_818802001_2_dialog_content = "The angular pattern and simple color scheme...",
  str_homestory_818802001_3_dialog_content = "It's very much like the most common variety seen in Longzhou.",
  str_homestory_818802001_4_dialog_content = "Do Caelestites prefer a similar elegance as well? That is quite rare.",
  str_homestory_818802001_5_option_content = "People in Longzhou like to fly kites?",
  str_homestory_818802001_6_dialog_content = "Sure it does.",
  str_homestory_818802001_7_option_content = "Have you kited before, Dantang?",
  str_homestory_818802001_8_dialog_content = "Yes, I love kites very much.",
  str_homestory_818802001_9_dialog_content = "In Longzhou, kiting is one of the favorite activities for children.",
  str_homestory_818802001_10_dialog_content = "When I was young, it was a rare pleasure to fly kites with my sisters.",
  str_homestory_818802001_11_dialog_content = "Back then, our kites would become tangled.",
  str_homestory_818802001_12_dialog_content = "Sometimes, it would even cause quarrels.",
  str_homestory_818802001_13_dialog_content = "Although we would always reconcile in the end,",
  str_homestory_818802001_14_dialog_content = "What kind of kites did you fly, Dantang?",
  str_homestory_818802001_15_dialog_content = "My kites? Oh, I have flown many a kite.",
  str_homestory_818802001_16_dialog_content = "My sisters preferred kites of avian forms, but it was flowers for me.",
  str_homestory_818802001_17_dialog_content = "I haven't seen any kites like that.",
  str_homestory_818802001_18_dialog_content = "Well, the kites in Longzhou varied greatly in style.",
  str_homestory_818802001_19_dialog_content = "Take the Ye Kingdom, for example. They like to attach gadgets to kites.",
  str_homestory_818802001_20_dialog_content = "Which would make every part move and dance.",
  str_homestory_818802001_21_dialog_content = "All of the kites I flew at the time were crafted by the palace artisans.",
  str_homestory_818802001_22_dialog_content = "Lavishly decorated with regal elegance.",
  str_homestory_818802001_23_dialog_content = "I really miss it... I'd love to go kiting again.",
  str_homestory_818802001_24_dialog_content = "This kite here can't measure up to what you had, I'm afraid.",
  str_homestory_818802001_25_dialog_content = "It's all right. What I'm missing are the carefree moments of the past.",
  str_homestory_818802001_26_dialog_content = "Kiting is actually incidental.",
  str_homestory_818802001_27_dialog_content = "Hmm, I'm out of tasks and errands to be done.",
  str_homestory_818802001_28_dialog_content = "I can afford a respite, and it would be the perfect time to fly this kite.",
  str_homestory_818802001_29_dialog_content = "So, would you like to go kiting with me?",
  str_homestory_818802001_30_dialog_content = "It is not fun to fly it alone.",
  str_homestory_818802001_31_dialog_content = "Too bad we only got one here...",
  str_homestory_818802001_32_dialog_content = "That is not an issue. We can take turns, or I can make one myself.",
  str_homestory_822001001_0_dialog_content = "Vergil?",
  str_homestory_822001001_1_dialog_content = "Why do you keep staring at the scarecrow, Vergil?",
  str_homestory_822001001_2_dialog_content = "This scarecrow...<sprite=emo_sikao size=60 />",
  str_homestory_822001001_3_dialog_content = "What about it? Don't tell me this scarecrow is an antique!",
  str_homestory_822001001_4_dialog_content = "At first glance, it does seem to be...",
  str_homestory_822001001_5_dialog_content = "Really? What's special about the scarecrow?",
  str_homestory_822001001_6_dialog_content = "The accessories on it... They might be antiques.",
  str_homestory_822001001_7_dialog_content = "Antiques? Really?",
  str_homestory_822001001_8_dialog_content = "Yes. This vest should be a limited release from an Umbraton brand.",
  str_homestory_822001001_9_dialog_content = "It was in vogue fifty years ago.",
  str_homestory_822001001_10_dialog_content = "The biggest feature of this limited offering is...",
  str_homestory_822001001_11_dialog_content = "Its white-on-black pattern was white stripes dyed on black fabric.",
  str_homestory_822001001_12_dialog_content = "Rather than the conventional one, with black stripes printed on white fabric.",
  str_homestory_822001001_13_dialog_content = "And there's a number sewn behind the collar with gold thread.",
  str_homestory_822001001_14_dialog_content = "I do see it...<sprite=emo_wuzui size=60 />",
  str_homestory_822001001_15_dialog_content = "Also, if you look closely, the scarecrow's eyes are made of obsidian.",
  str_homestory_822001001_16_dialog_content = "The polish and color are both gemstone quality.",
  str_homestory_822001001_17_dialog_content = "The nobles in Lumopolis often made such gemstones into buttons decades ago.",
  str_homestory_822001001_18_dialog_content = "These two aren't far off from that.",
  str_homestory_822001001_19_dialog_content = "I didn't even notice until you mentioned it.",
  str_homestory_822001001_20_dialog_content = "Lastly, the log propping up the scarecrow...",
  str_homestory_822001001_21_dialog_content = "It appears to be agarwood.",
  str_homestory_822001001_22_dialog_content = "Despite it being thinner, you can still sniff a faint aroma when you get up to it.",
  str_homestory_822001001_23_dialog_content = "Agarwood canes are worth quite a lot.",
  str_homestory_822001001_24_dialog_content = "Wow, does that mean this scarecrow is priceless?",
  str_homestory_822001001_25_dialog_content = "Well, antiques are judged by their whole.",
  str_homestory_822001001_26_dialog_content = "A complete set would be priceless, but much less when even one component is missing.",
  str_homestory_822001001_27_dialog_content = "And vice versa, just like this scarecrow, a compilation of completely unrelated objects.",
  str_homestory_822001001_28_dialog_content = "Even from the perspective of a work of art...",
  str_homestory_822001001_29_dialog_content = "It's third-rate at best, worth nothing now.",
  str_homestory_822001001_30_dialog_content = "That's a shame...<sprite=emo_tanqi size=60 />",
  str_homestory_822001001_31_dialog_content = "Unless...",
  str_homestory_822001001_32_dialog_content = "Unless what?",
  str_homestory_822001001_33_dialog_content = "Unless you take it apart. Do you wish to do that?",
  str_homestory_822001001_34_dialog_content = "Well, no.",
  str_homestory_822001001_35_dialog_content = "I prefer how it's here for us to enjoy as is.",
  str_homestory_822001001_36_dialog_content = "I knew you would say that, PlayerName.",
  str_homestory_821901001_0_dialog_content = "What's the matter?",
  str_homestory_821901001_1_dialog_content = "The way you look... Could it be...",
  str_homestory_821901001_2_dialog_content = "You must like this clock very much, don't you?",
  str_homestory_821901001_3_dialog_content = "It's a style I've never seen before.",
  str_homestory_821901001_4_dialog_content = "Is it a Caelestite clock?",
  str_homestory_821901001_5_dialog_content = "I believe so.",
  str_homestory_821901001_6_dialog_content = "Everything on Soroz is Caelestite.",
  str_homestory_821901001_7_dialog_content = "It's not a machine but uses the reflection of sunlight.",
  str_homestory_821901001_8_dialog_content = "Such a wonderful concept...",
  str_homestory_821901001_9_dialog_content = "Could be called Shadow Art.",
  str_homestory_821901001_10_dialog_content = "You really like the clock, I see.",
  str_homestory_821901001_11_dialog_content = "I'm in awe of the fleeting time.",
  str_homestory_821901001_12_dialog_content = "Therefore, I also love to collect clocks of different makes.",
  str_homestory_821901001_13_dialog_content = "What? You mean there are many types of clocks in the world outside?",
  str_homestory_821901001_14_dialog_content = "Clocks in Lumopolis are classical and elegant.",
  str_homestory_821901001_15_dialog_content = "Northland clocks are simple and practical.",
  str_homestory_821901001_16_dialog_content = "Rediesel Desert clocks are full of gimmicks and gadgets.",
  str_homestory_821901001_17_dialog_content = "And Umbraton clocks are low-key yet gorgeous.",
  str_homestory_821901001_18_dialog_content = "I get it. You sure are a collection aficionado.",
  str_homestory_821901001_19_dialog_content = "I never thought there could be so much to a common item.",
  str_homestory_821901001_20_dialog_content = "You've opened my eyes.",
  str_homestory_821901001_21_dialog_content = "The clocks I mentioned are all products of modern times.",
  str_homestory_821901001_22_dialog_content = "Whereas the Caelestite clock made me realize the gravity of the past.",
  str_homestory_821901001_23_dialog_content = "That feeling is special and unique.",
  str_homestory_821901001_24_dialog_content = "If that's how you feel...<sprite=emo_sikao size=60 />",
  str_homestory_821901001_25_dialog_content = "I'd like to give it to you.",
  str_homestory_821901001_26_dialog_content = "Why would you do that?",
  str_homestory_821901001_27_option_content = "Because we're friends.",
  str_homestory_821901001_28_dialog_content = "Out of friendship, is it?",
  str_homestory_821901001_29_dialog_content = "That's a statement of sincerity.",
  str_homestory_821901001_30_option_content = "Seems you like it a lot.",
  str_homestory_821901001_31_dialog_content = "Even so, I don't want to just take it.",
  str_homestory_821901001_32_dialog_content = "I appreciate the thought very much, though.",
  str_homestory_821901001_33_dialog_content = "But why don't we just let it stay \"home\"?",
  str_homestory_821901001_34_dialog_content = "I don't understand it. Don't you like it?",
  str_homestory_821901001_35_dialog_content = "I have other clocks here, so...",
  str_homestory_821901001_36_dialog_content = "I'm very glad to know you would share anything with a friend.",
  str_homestory_821901001_37_dialog_content = "However, I think it's meant to be nowhere else but here.",
  str_homestory_821901001_38_dialog_content = "The past represents memories, and memories consist of history.",
  str_homestory_821901001_39_dialog_content = "Everything Caelestite is here, PlayerName.",
  str_homestory_821901001_40_dialog_content = "All of this means something to you.",
  str_homestory_821901001_41_dialog_content = "I don't want to take any of it away.",
  str_homestory_821901001_42_dialog_content = "Istvan...",
  str_homestory_821901001_43_dialog_content = "Farewell, may the shadow watch over you.",
  str_homestory_821801001_0_dialog_content = "Lady Sheol?",
  str_homestory_821801001_1_dialog_content = "Fancy meeting you here! It's a sign that something good will happen today.",
  str_homestory_821801001_2_dialog_content = "Wouldn't you agree, PlayerName?",
  str_homestory_821801001_3_dialog_content = "It's not unexpected, Lady Sheol. You do know we're in Cloud Gardens, right...",
  str_homestory_821801001_4_dialog_content = "Of course I do.",
  str_homestory_821801001_5_dialog_content = "But you need those occasional coincidences, either in business or in life.",
  str_homestory_821801001_6_dialog_content = "Sorry, I still don't get it.",
  str_homestory_821801001_7_dialog_content = "It's okay. Let me explain.",
  str_homestory_821801001_8_dialog_content = "For instance, you needed to renovate Cloud Gardens and the Cloudrover Guild...",
  str_homestory_821801001_9_dialog_content = "Just happened to have a plan for that.",
  str_homestory_821801001_10_dialog_content = "Wouldn't that be a coincidence?",
  str_homestory_821801001_11_dialog_content = "And by that, you're saying...?",
  str_homestory_821801001_12_dialog_content = "Cloud Gardens is special indeed, but don't you think the dorms are too drab?",
  str_homestory_821801001_13_option_content = "Are they?",
  str_homestory_821801001_14_dialog_content = "Of course, why else would I mention that?",
  str_homestory_821801001_15_dialog_content = "You're probably used to it so you don't feel that way.",
  str_homestory_821801001_16_dialog_content = "But I think plain dorms just aren't a match for Cloud Gardens.",
  str_homestory_821801001_17_option_content = "I feel the same too",
  str_homestory_821801001_18_dialog_content = "I knew it!",
  str_homestory_821801001_19_dialog_content = "In that case, don't you think something should be done about it?",
  str_homestory_821801001_20_dialog_content = "Such as renovating them?",
  str_homestory_821801001_21_dialog_content = "What I mean is, we can make the dorms fancier.",
  str_homestory_821801001_22_dialog_content = "Fancier?",
  str_homestory_821801001_23_dialog_content = "Not a bad idea, but the budget<sprite=emo_baiyebi size=60 /> is tight...",
  str_homestory_821801001_24_dialog_content = "Worry not! You can trust the project to my Cloudrover Guild!",
  str_homestory_821801001_25_dialog_content = "I'll remodel the dorms to match the grandeur of Cloud Gardens for free!",
  str_homestory_821801001_26_dialog_content = "Free? All of it?!",
  str_homestory_821801001_27_dialog_content = "I'm not sure about that...",
  str_homestory_821801001_28_dialog_content = "I know we are friends, but this is taking too much advantage of you, Lady Sheol.",
  str_homestory_821801001_29_dialog_content = "As you know, I don't make unprofitable deals.",
  str_homestory_821801001_30_dialog_content = "When the dorms are finished, we'll rebrand Cloud Gardens into a hotel resort.",
  str_homestory_821801001_31_dialog_content = "Hotel resort?!",
  str_homestory_821801001_32_dialog_content = "Just sit back and leave everything to me.",
  str_homestory_821801001_33_dialog_content = "Or let me put it this way, I guarantee you will be counting money until you're sick of it!",
  str_homestory_821801001_34_dialog_content = "Counting money until I'm sick of it?!",
  str_homestory_821801001_35_dialog_content = "Is this the project you mentioned earlier?",
  str_homestory_821801001_36_dialog_content = "This is truly a proposal I can't refuse<sprite=emo_aixin size=60 />!",
  str_homestory_821801001_37_dialog_content = "Perfect, it's settled then...",
  str_homestory_821801001_38_dialog_content = "Wait, Lady Sheol!",
  str_homestory_821801001_39_dialog_content = "I'm sorry, but I just want to keep the Cloud Gardens the way it is for now.",
  str_homestory_821801001_40_dialog_content = "I'm not sure how the inhabitants of Cloud Gardens will take the news...",
  str_homestory_821801001_41_dialog_content = "So if we just rush into the project right away...",
  str_homestory_821801001_42_dialog_content = "I see. I get it.",
  str_homestory_821801001_43_dialog_content = "That means we have an opportunity to make tourism a thing in the future, right?",
  str_homestory_821801001_44_dialog_content = "Tourism?",
  str_homestory_821801001_45_dialog_content = "Then, I look forward to hearing from you!",
  str_homestory_822101001_0_dialog_content = "Intrigued?",
  str_homestory_822101001_1_dialog_content = "I saw you look at it the whole time, very excited seemingly.",
  str_homestory_822101001_2_dialog_content = "Is this<sprite=emo_sikao size=60 />...",
  str_homestory_822101001_3_dialog_content = "A garbage bin capable of auto-sorting the recycled trash?",
  str_homestory_822101001_4_dialog_content = "Wow! How do you know that?!",
  str_homestory_822101001_5_dialog_content = "It's a Caelestite-style garbage bin, different from your usual variety.",
  str_homestory_822101001_6_dialog_content = "But I still thought it wouldn't be so readily recognizable.",
  str_homestory_822101001_7_dialog_content = "Heh, underestimating me again, are you?",
  str_homestory_822101001_8_dialog_content = "I shall elaborate on my analysis then.",
  str_homestory_822101001_9_dialog_content = "First of all, I hacked into its controlling program and took a glance...",
  str_homestory_822101001_10_dialog_content = "What? Why would you do that to other people's furniture?!",
  str_homestory_822101001_11_dialog_content = "It was in another programming language that's advanced and succinct. Definitely a masterpiece of Caelestite high tech!",
  str_homestory_822101001_12_dialog_content = "But in terms of functions, I could discern its similarities to those of the auto-sorting system in Illumina Cafeteria.",
  str_homestory_822101001_13_dialog_content = "Which means this thing also has the same categorization feature.",
  str_homestory_822101001_14_dialog_content = "By the way, I wrote the program for Illumina Cafeteria.",
  str_homestory_822101001_15_dialog_content = "It could sort and dispense foods based on their nutritional levels!",
  str_homestory_822101001_16_dialog_content = "Nice.",
  str_homestory_822101001_17_dialog_content = "I wonder if there's a nutritious ingredient that could cut down the desire to mess with a friend's furniture.",
  str_homestory_822101001_18_dialog_content = ".... Anyway, not bad for you to associate \"sorting\" with a garbage bin.",
  str_homestory_822101001_19_dialog_content = "Well, there's a more conclusive reason for that.",
  str_homestory_822101001_20_dialog_content = "Oh?",
  str_homestory_822101001_21_dialog_content = "There's a big image of garbage on it.",
  str_homestory_822101001_22_dialog_content = "...",
  str_homestory_822101001_23_dialog_content = "Simply marvelous!",
  str_homestory_822101001_24_dialog_content = "Auto-sorting is not really the best thing since sliced bread.",
  str_homestory_822101001_25_dialog_content = "But to pack a system into such a compact volume...",
  str_homestory_822101001_26_dialog_content = "With such detailed sorting features on top... That's something the current Illumina tech can only dream of.",
  str_homestory_822101001_27_dialog_content = "The Caelestites are truly great people!",
  str_homestory_822101001_28_dialog_content = "Um...",
  str_homestory_822101001_29_option_content = "You really think so?",
  str_homestory_822101001_30_dialog_content = "It's just a garbage bin.",
  str_homestory_822101001_31_dialog_content = "\"Just a garbage bin\" is what made it awesome.",
  str_homestory_822101001_32_option_content = "I didn't think you'd be into an \"automatic recycling bin\" this much.",
  str_homestory_822101001_33_dialog_content = "That even got me all pumped up!",
  str_homestory_822101001_34_dialog_content = "You should be!",
  str_homestory_822101001_35_dialog_content = "Cutting-edge technologies are always applied to military uses first.",
  str_homestory_822101001_36_dialog_content = "Only when they become more prevalent than dirt can they be accessed by the normal people.",
  str_homestory_822101001_37_dialog_content = "In this case, it's only because this auto recycling bin is a garbage bin...",
  str_homestory_822101001_38_dialog_content = "That shows the greatness of the Caelestite culture!",
  str_homestory_822101001_39_dialog_content = "Ah! That does make sense, now that I think about it!",
  str_homestory_822101001_40_dialog_content = "Even though it still bugs me that you hacked into the program...",
  str_homestory_822101001_41_dialog_content = "But I always learn something from talking with you. I mean that.",
  str_homestory_822101001_42_dialog_content = "Thank you, Algol.",
  str_homestory_822101001_43_dialog_content = "Don't mention it! Though I'd rather you give me permission to take the bin apart for thorough study...",
  str_homestory_822101001_44_dialog_content = "Forget about that!",
  str_homestory_822301001_0_dialog_content = "This stone statue...",
  str_homestory_822301001_1_dialog_content = "I hardly see things like this in your cave, PlayerName.",
  str_homestory_822301001_2_dialog_content = "Does this statue hold some kind of special meaning for you?",
  str_homestory_822301001_3_dialog_content = "You guessed it... It's a statue of a Caelestite girl.",
  str_homestory_822301001_4_dialog_content = "A Caelestite... One of your people from a long time ago, yes?",
  str_homestory_822301001_5_dialog_content = "I can sense the breath of time coming from every crack and scratch on this statue.",
  str_homestory_822301001_6_dialog_content = "The tales say that she was a traveler, one who visited every famous landmark of our continent.",
  str_homestory_822301001_7_dialog_content = "And you're right, Chen'ni. This statue is from a very long time ago...",
  str_homestory_822301001_8_dialog_content = "It would be dangerous for a Caelestite to travel our Eclipsite-infested world <sprite=emo_kulou size=60 /> all on their own now...",
  str_homestory_822301001_9_dialog_content = "With me at your side, what's there to fear?",
  str_homestory_822301001_10_dialog_content = "Perhaps one day, a statue'll be erected in your memory as well?",
  str_homestory_822301001_11_dialog_content = "Huh? M-Me?! No way, I'm nothing special at all...",
  str_homestory_822301001_12_dialog_content = "Why not? For instance, what if there was a severe drought in the world, and I summoned heavy rain to bring salvation to everyone...",
  str_homestory_822301001_13_dialog_content = "And then afterward, you took me to buy some sugar melons...",
  str_homestory_822301001_14_dialog_content = "Then everyone would see you with me, and make statues out of both of us!",
  str_homestory_822301001_15_dialog_content = "That's an oddly-specific example, almost as though it really happened at some point...",
  str_homestory_822301001_16_dialog_content = "Or maybe one winter, I rescue thirty-eight people from a shipwreck at sea in one fell swoop!",
  str_homestory_822301001_17_dialog_content = "And once they come ashore, you light fires and provide blankets for them to survive the harsh cold...",
  str_homestory_822301001_18_dialog_content = "They'll put a statue of you right next to mine, and people will light incense in our honor for generations!",
  str_homestory_822301001_19_dialog_content = "...",
  str_homestory_822301001_20_dialog_content = "What's the matter? Don't these stories sound interesting to you?",
  str_homestory_822301001_21_option_content = "They do.",
  str_homestory_822301001_22_dialog_content = "But they also sound really sad.",
  str_homestory_822301001_23_option_content = "It's hard to say...",
  str_homestory_822301001_24_dialog_content = "I feel like that's not a good way to consider them.",
  str_homestory_822301001_25_dialog_content = "Mostly because they're not just stories, are they?",
  str_homestory_822301001_26_dialog_content = "When I was in Longzhou, I saw so many statues of you in different places.",
  str_homestory_822301001_27_dialog_content = "I imagine you've helped out countless people all throughout Longzhou, leaving behind legends and stories like the ones you just mentioned.",
  str_homestory_822301001_28_dialog_content = "As for the people in your stories, like the one who bought you sugar melons or the one who helped you save those people...",
  str_homestory_822301001_29_dialog_content = "They're probably not a part of this world anymore... You're the only one still left.",
  str_homestory_822301001_30_dialog_content = "Do you pity me, PlayerName?",
  str_homestory_822301001_31_dialog_content = "I'm just sorry that you have to keep saying goodbye to people around you...",
  str_homestory_822301001_32_dialog_content = "Is it wrong of me to feel that way for a dragon goddess?",
  str_homestory_822301001_33_dialog_content = "As a being of flesh and blood, it's perfectly natural for you to feel this way.",
  str_homestory_822301001_34_dialog_content = "I feel the same way about you as well.",
  str_homestory_822301001_35_dialog_content = "Time is unfathomably long, and leads everything to its end.",
  str_homestory_822301001_36_dialog_content = "Despite my longevity, even my own existence is but a blink of an eye in comparison to the world.",
  str_homestory_822301001_37_dialog_content = "But our ephemeral nature is precisely what makes our meeting precious. To be able to walk alongside one another is to entwine our destinies.",
  str_homestory_822301001_38_dialog_content = "It would be arrogant of me to pity mortals for their short lifespans.",
  str_homestory_822301001_39_dialog_content = "That does make sense... For some reason, my mood feels much better now.",
  str_homestory_822301001_40_dialog_content = "\"Friendship fears not the passage of time.\" Isn't that what they say in Longzhou?",
  str_homestory_822301001_41_dialog_content = "That's exactly right! You really have learned a lot lately.",
  str_homestory_822301001_42_dialog_content = "Time can be cruel, but it also has a good side to it.",
  str_homestory_822301001_43_dialog_content = "<sprite=emo_qingsong size=60 /> Heehee... Guess I can't afford to squander my time by sitting around in one place!",
  str_homestory_822301001_44_dialog_content = "Besides, if it wasn't for the passage of time, we never would have met...",
  str_homestory_822301001_45_dialog_content = "And I never would have gotten to spend so many happy days here with everyone.",
  str_homestory_822401001_0_dialog_content = "Luo Song?",
  str_homestory_822401001_1_dialog_content = "Do you want to use this?",
  str_homestory_822401001_2_dialog_content = "Of course I do! It's so finely made, after all!",
  str_homestory_822401001_3_dialog_content = "Finely... Made?",
  str_homestory_822401001_4_dialog_content = "Yes! Just look at how its expression inspires an urge for confrontation!",
  str_homestory_822401001_5_dialog_content = "And its frame isn't too hard or too soft either!",
  str_homestory_822401001_6_dialog_content = "No matter how hard you hit it, it always returns to its original position...",
  str_homestory_822401001_7_dialog_content = "It's the perfect training tool for my fists!",
  str_homestory_822401001_8_option_content = "I understand.",
  str_homestory_822401001_9_dialog_content = "I knew<sprite=emo_guilian size=60 /> you would understand, PlayerName.",
  str_homestory_822401001_10_option_content = "I don't really get it...",
  str_homestory_822401001_11_dialog_content = "I can't really explain it either <sprite=emo_sikao size=60 />. I suppose you could call it a warrior's intuition?",
  str_homestory_822401001_12_dialog_content = "During my travels in Longzhou, I put myself through bitter training every single day.",
  str_homestory_822401001_13_dialog_content = "Strength-building, meditation, shadow-boxing, you name it.",
  str_homestory_822401001_14_dialog_content = "Even a single day without training can make a person rusty.",
  str_homestory_822401001_15_dialog_content = "But the point of training like this is to strengthen one's body.",
  str_homestory_822401001_16_dialog_content = "Some people get carried away with the \"bitter\" part of it, and end up hurting themselves as a result.",
  str_homestory_822401001_17_dialog_content = "And that defeats the purpose entirely.",
  str_homestory_822401001_18_dialog_content = "That's right!",
  str_homestory_822401001_19_dialog_content = "It's like how some people slam into trees repeatedly when practicing the \"Iron Mountain Lean\" technique.",
  str_homestory_822401001_20_dialog_content = "Because of the high risk of personal injury, it's an extremely unwise way to practice that move.",
  str_homestory_822401001_21_dialog_content = "I see. The more you know, huh...",
  str_homestory_822401001_22_dialog_content = "During my travels, I also had to use trees to train since I couldn't find a better way.",
  str_homestory_822401001_23_dialog_content = "Maybe it's because I was young, but I hardly felt any pain or discomfort.",
  str_homestory_822401001_24_dialog_content = "But later, I started training Ah Ding and the others.",
  str_homestory_822401001_25_dialog_content = "And I quickly realized that following my routine was an easy way for them to get hurt.",
  str_homestory_822401001_26_dialog_content = "I also realized that the training methods and equipment I used in the past were way too crude.",
  str_homestory_822401001_27_dialog_content = "That's why I've started paying more attention to safety during training, and including things like protective gear.",
  str_homestory_822401001_28_dialog_content = "I've even made custom training equipment just for Ah Ding and the other fiendlings...",
  str_homestory_822401001_29_dialog_content = "It cost me a lot of time and effort to design gear with their needs in mind.",
  str_homestory_822401001_30_dialog_content = "Especially those plum blossom pillars. It took so many tries to make something that works with their stubby, little legs!",
  str_homestory_822401001_31_dialog_content = "You're a pretty considerate guy.",
  str_homestory_822401001_32_dialog_content = "Of course. Besides, I don't really have any hobbies outside of training.",
  str_homestory_822401001_33_dialog_content = "So naturally I'm going to do what's best for my friends' training too.",
  str_homestory_822401001_34_dialog_content = "When I have some time, I'll be sure to design some stuff for you too!",
  str_homestory_822501001_0_dialog_content = "That lantern over there...",
  str_homestory_822501001_1_dialog_content = "You like that court lantern, Tiare?",
  str_homestory_822501001_2_dialog_content = "Feel free to get a closer look, if you want.",
  str_homestory_822501001_3_dialog_content = "This is the perfect distance, actually.",
  str_homestory_822501001_4_dialog_content = "It reminds me of the beacon in Northland from here.",
  str_homestory_822501001_5_dialog_content = "I see what you're saying, now that you mentioned it.",
  str_homestory_822501001_6_dialog_content = "A shame it's just a plain lantern and doesn't watch over the creatures in Northland like a beacon.",
  str_homestory_822501001_7_dialog_content = "...",
  str_homestory_822501001_8_dialog_content = "I used to sit on the top of cedar trees and watch the beacon when I was little.",
  str_homestory_822501001_9_dialog_content = "It was amazingly bright...",
  str_homestory_822501001_10_dialog_content = "Its glow could reach anywhere, no matter how dark it was and how much fog.",
  str_homestory_822501001_11_dialog_content = "The light kept the Snowpine Forest quiet and still.",
  str_homestory_822501001_12_dialog_content = "No shrieking Eclipsites, no screaming Aurorians... The serenity was priceless.",
  str_homestory_822501001_13_dialog_content = "Only we Northlanders have that special beacon.",
  str_homestory_822501001_14_dialog_content = "I can tell how much you people appreciate and revere it.",
  str_homestory_822501001_15_dialog_content = "Actually, what we appreciate and revere is not the beacon...",
  str_homestory_822501001_16_dialog_content = "One time, I was too busy chasing a wily prey to realize how far out I had gone.",
  str_homestory_822501001_17_dialog_content = "Until the cries of Eclipsites startled me! By then, I was too far from home.",
  str_homestory_822501001_18_dialog_content = "That was when I saw the lights from a beacon.",
  str_homestory_822501001_19_dialog_content = "You could still see it that far from home?",
  str_homestory_822501001_20_dialog_content = "No, what I saw wasn't the beacon that protected us.",
  str_homestory_822501001_21_dialog_content = "But a normal lighthouse by the sea.",
  str_homestory_822501001_22_dialog_content = "It would turn into an Eclipsite hideout after nightfall.",
  str_homestory_822501001_23_dialog_content = "Good heavens!",
  str_homestory_822501001_24_dialog_content = "I hid in the woods, not daring to move.",
  str_homestory_822501001_25_dialog_content = "The light kept sweeping past me.",
  str_homestory_822501001_26_dialog_content = "I looked at it while Eclipsites moved underneath.",
  str_homestory_822501001_27_dialog_content = "Do you know what I realized then?",
  str_homestory_822501001_28_dialog_content = "What?",
  str_homestory_822501001_29_dialog_content = "That lighthouse was exactly the same as the beacon I appreciated and revered.",
  str_homestory_822501001_30_dialog_content = "...",
  str_homestory_822501001_31_dialog_content = "It had the same glow that could penetrate the darkest night and the densest fog...",
  str_homestory_822501001_32_dialog_content = "But it couldn't protect me. For the whole night, if I had even so much as twitched...",
  str_homestory_822501001_33_dialog_content = "The Eclipsites would have torn me into pieces.",
  str_homestory_822501001_34_dialog_content = "Tiare...",
  str_homestory_822501001_35_dialog_content = "I finally understood that night.",
  str_homestory_822501001_36_dialog_content = "The beacon itself was nothing special.",
  str_homestory_822501001_37_dialog_content = "Like this common lantern we see, it was just an ordinary building.",
  str_homestory_822501001_38_dialog_content = "It would have been nothing if no one had lit it, maintained it, and put resolve behind it.",
  str_homestory_822501001_39_dialog_content = "What had been protecting the Northlanders was never the beacon...",
  str_homestory_822501001_40_dialog_content = "But Queen Bethlehem.",
  str_homestory_822501001_41_dialog_content = "...",
  str_homestory_822501001_42_option_content = "Her Majesty's resolve is simply unbreakable.",
  str_homestory_822501001_43_dialog_content = "Even without the beacon, she'd do everything she could to defend her people.",
  str_homestory_822501001_44_option_content = "That must have been an important night in your life.",
  str_homestory_822501001_45_dialog_content = "That night was when you forged your own resolve.",
  str_homestory_822501001_46_dialog_content = "That's right.",
  str_homestory_822501001_47_dialog_content = "Even if I can't hold a candle to Her Majesty, I will follow her to the bitter end.",
  str_homestory_822501001_48_dialog_content = "I've dedicated my life to defending and protecting my people, like her.",
  str_homestory_822501001_49_dialog_content = "That's how I feel too.",
  str_homestory_822501001_50_dialog_content = "Especially the part about \"can't hold a candle to Her Majesty.\"",
  str_homestory_822501001_51_dialog_content = "Haha, who could hold a candle to her anyway?",
  str_homestory_822501001_52_dialog_content = "But as long as she is there, I'll never be lost.",
  str_homestory_822601001_0_dialog_content = "Hey...",
  str_homestory_822601001_1_dialog_content = "Don't you think this rocking horse is pretty interesting, Rachel?",
  str_homestory_822601001_2_dialog_content = "I know it's a little childish, but it's surprisingly fun to ride.",
  str_homestory_822601001_3_dialog_content = "Wanna give it a try? Go on!",
  str_homestory_822601001_4_dialog_content = "I'd rather not...",
  str_homestory_822601001_5_dialog_content = "No matter what you say, I'm too old for this sort of thing.",
  str_homestory_822601001_6_dialog_content = "As for you, I didn't know you were such a huge fan of rocking horses.",
  str_homestory_822601001_7_dialog_content = "I-I wouldn't call myself a \"fan\" of them or anything...",
  str_homestory_822601001_8_dialog_content = "(I thought she was just too embarrassed to ride it, but now my secret is out!)",
  str_homestory_822601001_9_dialog_content = "Still, it is a pretty well-made toy.",
  str_homestory_822601001_10_dialog_content = "When you look past its simple appearance, the design and craftsmanship are both excellent.",
  str_homestory_822601001_11_dialog_content = "A powerful combination of ergonomics and structural mechanics.",
  str_homestory_822601001_12_dialog_content = "Even I'm somewhat captivated by it.",
  str_homestory_822601001_13_dialog_content = "Wow... I never noticed any of that for myself.",
  str_homestory_822601001_14_dialog_content = "You mean you can discern all of those things just by looking at something?",
  str_homestory_822601001_15_dialog_content = "Yes. It's a basic skill for any engineer.",
  str_homestory_822601001_16_dialog_content = "The ability to draw a three-dimensional rendering of any object from a single glance is very important.",
  str_homestory_822601001_17_dialog_content = "In fact, I have a good idea of how to replicate this rocking horse now.",
  str_homestory_822601001_18_dialog_content = "That sounds like a superpower to me...",
  str_homestory_822601001_19_dialog_content = "Alright, then I'll let you have it!",
  str_homestory_822601001_20_dialog_content = "Huh?",
  str_homestory_822601001_21_option_content = "You can take it home for research purposes.",
  str_homestory_822601001_22_dialog_content = "I understand. You want me to leave, so I can stop bothering you, right?",
  str_homestory_822601001_23_dialog_content = "Not at all!",
  str_homestory_822601001_24_option_content = "You seem to like it a lot.",
  str_homestory_822601001_25_dialog_content = "Yes, but I like your Colossus more than anything else.",
  str_homestory_822601001_26_dialog_content = "Soroz isn't on the table!",
  str_homestory_822601001_27_dialog_content = "Heh... Only kidding.",
  str_homestory_822601001_28_dialog_content = "Thanks for the offer, but...",
  str_homestory_822601001_29_dialog_content = "I want to make my sister's gift with my own two hands.",
  str_homestory_822601001_30_dialog_content = "... Sister?",
  str_homestory_822601001_31_dialog_content = "Yes. The moment I saw this rocking horse, I decided to make one just like it for my little sister.",
  str_homestory_822601001_32_dialog_content = "I never had the opportunity to play with toys like this as a child, but at least my sister will...",
  str_homestory_822601001_33_dialog_content = "Though maybe it's just my way of making up for my own past.",
  str_homestory_822601001_34_dialog_content = "Rachel...",
  str_homestory_822601001_35_dialog_content = "I was being serious just now.",
  str_homestory_822601001_36_dialog_content = "This rocking horse... It's way more fun than you think!",
  str_homestory_822601001_37_dialog_content = "H-Huh?",
  str_homestory_822601001_38_dialog_content = "So give it a whirl! You can't make the perfect replicate for your sister unless you've tried out the original one for yourself, right?",
  str_homestory_822601001_39_dialog_content = "Come on, don't be shy!",
  str_homestory_822601001_40_dialog_content = "Uh... Alright then... But just this once.",
  str_homestory_822601001_41_dialog_content = "I bet you'll get hooked on it too!",
  str_homestory_822701001_0_dialog_content = "Zeta?",
  str_homestory_822701001_1_dialog_content = "What in the world is this thing?",
  str_homestory_822701001_2_dialog_content = "These adorable wings, this expert craftsmanship...",
  str_homestory_822701001_3_dialog_content = "If you ask me, this must be some sort of priceless treasure from the distant past.",
  str_homestory_822701001_4_dialog_content = "It's a Windelion Doll.",
  str_homestory_822701001_5_dialog_content = "Well, if it isn't the Last Caelestite! You came at just the right time.",
  str_homestory_822701001_6_dialog_content = "Since you know its name, you must be very familiar with this marvelous creation.",
  str_homestory_822701001_7_dialog_content = "It's just a decoration for Windelion.",
  str_homestory_822701001_8_dialog_content = "Windelion?",
  str_homestory_822701001_9_dialog_content = "It's a Caelestite holiday. Someone once told me that it's similar to how Aurorians commemorate their saints and the God of Light.",
  str_homestory_822701001_10_dialog_content = "Saints? The God of Light? That sounds awesome!",
  str_homestory_822701001_11_dialog_content = "I had no idea this world had such a cool holiday!",
  str_homestory_822701001_12_dialog_content = "A friend of mine learned about Windelion from books as well.",
  str_homestory_822701001_13_dialog_content = "For us Caelestites, it's an incredibly important holiday.",
  str_homestory_822701001_14_dialog_content = "Every year on Windelion, we give thanks to nature by hosting a huge feast.",
  str_homestory_822701001_15_dialog_content = "Oh... That doesn't sound much different than any other holiday.",
  str_homestory_822701001_16_dialog_content = "Ahem... In any case, this doll is just another decoration used to celebrate Windelion.",
  str_homestory_822701001_17_dialog_content = "We fill the doll's belly with candy and wishes.",
  str_homestory_822701001_18_dialog_content = "Did you say... candy and wishes?",
  str_homestory_822701001_19_dialog_content = "Let's do it then! I want to celebrate Windelion right now!",
  str_homestory_822701001_20_dialog_content = "Why are you so excited all of a sudden?",
  str_homestory_822701001_21_dialog_content = "I want to make a Windelion Doll too!",
  str_homestory_822701001_22_option_content = "You can make them outside of the holiday too, you know.",
  str_homestory_822701001_23_dialog_content = "Is that so? Then show me how to make one.",
  str_homestory_822701001_24_option_content = "Sure, I don't see why not.",
  str_homestory_822701001_25_dialog_content = "Really? You're the best!",
  str_homestory_822701001_26_dialog_content = "Heehee, and once I'm done, I'll fill its belly with my latest masterpieces...",
  str_homestory_822701001_27_dialog_content = "When everyone starts to wonder what's inside...",
  str_homestory_822701001_28_dialog_content = "Boom! Pop! Whoosh! A bunch of smoke and candy will come flying out!",
  str_homestory_822701001_29_dialog_content = "Huh? You're not gonna put bombs in it, are you?",
  str_homestory_822701001_30_dialog_content = "Yes, I am, but don't worry! I'll only use enough to send candy flying in every direction!",
  str_homestory_822801001_0_dialog_content = "Batia",
  str_homestory_822801001_1_dialog_content = "You finally came outside!",
  str_homestory_822801001_2_dialog_content = "Oh, hi...",
  str_homestory_822801001_3_dialog_content = "Can I help you?",
  str_homestory_822801001_4_dialog_content = "No, it's just that you keep spending all day in your tent playing games.",
  str_homestory_822801001_5_dialog_content = "I was about to tell you to come out and get some fresh air.",
  str_homestory_822801001_6_dialog_content = "Ah... Phew...",
  str_homestory_822801001_7_dialog_content = "There, done. See you.",
  str_homestory_822801001_8_dialog_content = "W-Wait! You should at least take a walk before you go back inside, don't you think?",
  str_homestory_822801001_9_dialog_content = "Ugh, the outdoors...",
  str_homestory_822801001_10_dialog_content = "Why do you hate going outside so much, Batia?",
  str_homestory_822801001_11_dialog_content = "Do you... not like it around here?",
  str_homestory_822801001_12_dialog_content = "Not at all! It's not that I dislike this place or anything...",
  str_homestory_822801001_13_dialog_content = "I-In fact, I like it way more than the streets of Umbraton!",
  str_homestory_822801001_14_dialog_content = "Oh... So you've been comparing this place to Umbraton all along...",
  str_homestory_822801001_15_dialog_content = "S-Sorry, I didn't mean it like that!",
  str_homestory_822801001_16_dialog_content = "I-I'm really only familiar with Umbraton's streets...",
  str_homestory_822801001_17_dialog_content = "Which is all the more reason to visit different places!",
  str_homestory_822801001_18_option_content = "So where should we go?",
  str_homestory_822801001_19_dialog_content = "By the river.",
  str_homestory_822801001_20_dialog_content = "We could go fishing in one of the nearby rivers?",
  str_homestory_822801001_21_dialog_content = "Oh, so like an IRL version of Fishing Master!",
  str_homestory_822801001_22_dialog_content = "I'm not sure I can catch a real fish, though...",
  str_homestory_822801001_23_dialog_content = "Hahaha, well, the rules are a little different from those in your games.",
  str_homestory_822801001_24_option_content = "The forest.",
  str_homestory_822801001_25_dialog_content = "Let's go camping in the forest. We can light a campfire, forage for wild fruit, and cook in the great outdoors!",
  str_homestory_822801001_26_dialog_content = "Oh, that sounds just like a management-style game.",
  str_homestory_822801001_27_dialog_content = "Plotting out our camp's development and following different crafting processes to ensure maximum efficiency...",
  str_homestory_822801001_28_dialog_content = "Camping doesn't have points or achievements, you know.",
  str_homestory_822801001_29_dialog_content = "Oh, okay. I guess I can give it a shot.",
  str_homestory_822801001_30_dialog_content = "But can I at least bring my tent if we're going out?",
  str_homestory_822801001_31_dialog_content = "If we get tired, we can always go inside and play games.",
  str_homestory_822801001_32_dialog_content = "Well, I guess that wouldn't hurt.",
  str_homestory_822901001_0_dialog_content = "Lady Victoria, why do you keep staring at the hanging chair?",
  str_homestory_822901001_1_dialog_content = "Is there something wrong with it?",
  str_homestory_822901001_2_dialog_content = "It just reminds me of a similar hanging chair in the True Order.",
  str_homestory_822901001_3_dialog_content = "It's their favorite chair.",
  str_homestory_822901001_4_dialog_content = "They what?",
  str_homestory_822901001_5_dialog_content = "Eight out of ten times I passed it by, I would see Beryl curled up reading in it.",
  str_homestory_822901001_6_dialog_content = "As for the other two, she fell asleep on one of her books.",
  str_homestory_822901001_7_dialog_content = "Then she's taken it for herself!",
  str_homestory_822901001_8_dialog_content = "Sometimes, I see Eicy going around it in circles.",
  str_homestory_822901001_9_dialog_content = "And she's always mumbling things that most people would never understand, like...",
  str_homestory_822901001_10_dialog_content = "It would make a perfect torture device with some iron spikes added to the seat and backrest!",
  str_homestory_822901001_11_dialog_content = "You must protect that hanging chair well before she gets her hands on it... And Beryl too!",
  str_homestory_822901001_12_dialog_content = "You can't blame Eicy for thinking that way.",
  str_homestory_822901001_13_dialog_content = "It did look rather similar to an instrument of torture when it was covered in Nails' blood.",
  str_homestory_822901001_14_dialog_content = "Even Nails?!",
  str_homestory_822901001_15_dialog_content = "You can't blame Nails for that. It's a really comfy chair.",
  str_homestory_822901001_16_dialog_content = "Even our devout ascetic would like to sit there sometimes.",
  str_homestory_822901001_17_dialog_content = "...",
  str_homestory_822901001_18_dialog_content = "Then... Are you the only one who hasn't sat on it?",
  str_homestory_822901001_19_dialog_content = "Now that I think about it, you're right.",
  str_homestory_822901001_20_dialog_content = "Maybe I'm avoiding it.",
  str_homestory_822901001_21_dialog_content = "Avoiding... a chair?",
  str_homestory_822901001_22_dialog_content = "It's from the old Varaki house and once belonged to my father.",
  str_homestory_822901001_23_dialog_content = "I don't know what Faust was thinking when he brought it back to me.",
  str_homestory_822901001_24_dialog_content = "Seeing it reminds me of my parents, my childhood, and the Varaki's helpless fate.",
  str_homestory_822901001_25_dialog_content = "I... don't want to keep remembering all of that.",
  str_homestory_822901001_26_dialog_content = "Faust should learn how to keep his hands to himself.",
  str_homestory_822901001_27_dialog_content = "Maybe he was trying to remind me that facing destiny is a part of the Truth.",
  str_homestory_822901001_28_dialog_content = "The hanging chair is a memento from your childhood.",
  str_homestory_822901001_29_dialog_content = "Those memories may be painful, but there's joy in them too, right?",
  str_homestory_822901001_30_dialog_content = "Heh, I guess. Father once held me in his arms while reading on the hanging chair. That's a beautiful memory.",
  str_homestory_822901001_31_dialog_content = "However, after experiencing recent events, I finally understand now.",
  str_homestory_822901001_32_dialog_content = "The pain of the past only exists in my heart.",
  str_homestory_822901001_33_dialog_content = "If I can overcome it, then the hanging chair will be nothing more than a hanging chair.",
  str_homestory_822901001_34_dialog_content = "Just as your natural wisdom pointed out.",
  str_homestory_822901001_35_dialog_content = "I shouldn't stare at it, I should sit comfortably on it.",
  str_homestory_822901001_36_dialog_content = "Y-Yeah! That's what I was trying to tell you!",
  str_homestory_822901001_37_dialog_content = "Please have a seat. You're always welcome to sit on my hanging chair.",
  str_homestory_822901001_38_dialog_content = "Thank you for the hospitality, PlayerName.",
  str_homestory_823001001_0_dialog_content = "This house looks weird, doesn't it?",
  str_homestory_823001001_1_dialog_content = "But its looks deceive because it's very comfy inside!",
  str_homestory_823001001_2_dialog_content = "Weird? Not at all...",
  str_homestory_823001001_3_dialog_content = "Its tower-like structure and the placement of windows make it resemble a tiny castle.",
  str_homestory_823001001_4_dialog_content = "If you allow it, I would like to train here occasionally.",
  str_homestory_823001001_5_dialog_content = "No problem!",
  str_homestory_823001001_6_dialog_content = "Use the place whenever you want.",
  str_homestory_823001001_7_dialog_content = "None at all...",
  str_homestory_823001001_8_dialog_content = "If you can guarantee no blood will be spilled here...",
  str_homestory_823001001_9_dialog_content = "I'm eternally grateful for your generosity.",
  str_homestory_823001001_10_dialog_content = "By the way, Mr. Wilhelm is training in seclusion at a castle, right?",
  str_homestory_823001001_11_dialog_content = "Oh! Y-Yes... Why did you suddenly bring up my mentor?",
  str_homestory_823001001_12_dialog_content = "I was just thinking... Do you want to train in a castle-like house...",
  str_homestory_823001001_13_dialog_content = "Due to Mr. Wilhelm's influence?",
  str_homestory_823001001_14_dialog_content = "...",
  str_homestory_823001001_15_dialog_content = "Lying is a sin. Since you're seen through my intentions, I can only admit it.",
  str_homestory_823001001_16_dialog_content = "I do have a tiny desire to... imitate my mentor.",
  str_homestory_823001001_17_dialog_content = "Though I promised him I wouldn't do it.",
  str_homestory_823001001_18_dialog_content = "A being so insignificant as I attempting to become like my mentor is a terrible sin! I...",
  str_homestory_823001001_19_dialog_content = "That's not true! Isn't it very normal to have the desire to imitate someone you respect?",
  str_homestory_823001001_20_dialog_content = "What have you tried to imitate?",
  str_homestory_823001001_21_dialog_content = "I...",
  str_homestory_823001001_22_dialog_content = "I tried to... grow out my hair.",
  str_homestory_823001001_23_dialog_content = "...",
  str_homestory_823001001_24_dialog_content = "But my hair doesn't seem to be suited for that. A pair of sparrows thought my head was their nest...",
  str_homestory_823001001_25_dialog_content = "By the time I finished repenting, a chick had already hatched on my head.",
  str_homestory_823001001_26_dialog_content = "You really repented for a long time...",
  str_homestory_823001001_27_dialog_content = "After cutting my hair, I tried to stay awake and read through the night like my mentor.",
  str_homestory_823001001_28_dialog_content = "But I fell asleep while walking and rolled down the stairs...",
  str_homestory_823001001_29_dialog_content = "Hey, hey!",
  str_homestory_823001001_30_dialog_content = "My mentor's sword, Crimson Tide, is really cool.",
  str_homestory_823001001_31_dialog_content = "But my mentor stopped me when I tried to imitate Crimson Tide with my own blood.",
  str_homestory_823001001_32_dialog_content = "Oh! He must have told you to just be yourself, right?",
  str_homestory_823001001_33_dialog_content = "My mentor asked me tenderly, \"Nails, look up and tell me what you see.\"",
  str_homestory_823001001_34_dialog_content = "I replied, \"The sky, Mentor. The Lord of Truth is watching us from there.\"",
  str_homestory_823001001_35_dialog_content = "My mentor asked, \"Do you know why we can see the sky?\"",
  str_homestory_823001001_36_dialog_content = "I replied, \"Because the Lord created it.\"",
  str_homestory_823001001_37_dialog_content = "My mentor said, \"It's because your Crimson Tide just sliced off our roof.\"",
  str_homestory_823001001_38_dialog_content = "...",
  str_homestory_823001001_39_dialog_content = "I deeply repented for my sins.",
  str_homestory_823001001_40_dialog_content = "Then I realized that I hadn't learned the most valuable thing from my mentor.",
  str_homestory_823001001_41_dialog_content = "My mentor never strayed from his beliefs.",
  str_homestory_823001001_42_dialog_content = "And I should do the same. I should live as I was born.",
  str_homestory_823001001_43_dialog_content = "If you were able to reach that conclusion from that string of disasters... I mean incidents...",
  str_homestory_823001001_44_dialog_content = "You must be very perceptive.",
  str_homestory_823001001_45_dialog_content = "Thank you for the kind words, PlayerName.",
  str_homestory_823001001_46_dialog_content = "In return, I'm always happy to listen to your confessions in this tiny castle.",
  str_homestory_823001001_47_dialog_content = "Ahem, let's do it once I figure it out!",
  str_homestory_823101001_0_dialog_content = "Mr. Wilhelm, why are you staring at that pavilion? There's nothing there.",
  str_homestory_823101001_1_dialog_content = "I'm wondering if this pavilion of yours has a puzzle buried beneath it.",
  str_homestory_823101001_2_dialog_content = "A puzzle? S-Seriously...? What makes you think that?",
  str_homestory_823101001_3_dialog_content = "A lone pavilion in the wilderness has a natural affinity with adventure and puzzles.",
  str_homestory_823101001_4_dialog_content = "Similar things have occurred in many legends.",
  str_homestory_823101001_5_dialog_content = "Inspired by this, I once proposed a question to Victoria.",
  str_homestory_823101001_6_dialog_content = "I-In the pavilion?",
  str_homestory_823101001_7_dialog_content = "I started off by irritating her...",
  str_homestory_823101001_8_dialog_content = "Why would you do that?!",
  str_homestory_823101001_9_dialog_content = "It was an easy task as she always had a sense of hostility toward me.",
  str_homestory_823101001_10_dialog_content = "But from how she screamed \"Go to hell! Demon!\" and ran off with bloodshot eyes...",
  str_homestory_823101001_11_dialog_content = "I may have gone too far.",
  str_homestory_823101001_12_dialog_content = "Lady Victoria was very... lively back then, huh?",
  str_homestory_823101001_13_dialog_content = "After that, I deliberately left all sorts of clues to make her think the Varaki had an ancestral treasure.",
  str_homestory_823101001_14_dialog_content = "And if she found it, she could overthrow me and retake the position of family head.",
  str_homestory_823101001_15_dialog_content = "You have such a twisted relationship...",
  str_homestory_823101001_16_dialog_content = "She didn't disappoint. She successfully deciphered the clues and came to the correct conclusion.",
  str_homestory_823101001_17_dialog_content = "The location of the ancestral treasure was inscribed on the pavilion deep within the garden.",
  str_homestory_823101001_18_dialog_content = "What happened next?",
  str_homestory_823101001_19_dialog_content = "Of course, locating the pavilion wasn't the end of it.",
  str_homestory_823101001_20_dialog_content = "She had to solve the riddles carved into the stone slabs of the pavilion and uncover the true location of the treasure.",
  str_homestory_823101001_21_dialog_content = "I should mention that my artificial aging of the stone slabs was impeccable.",
  str_homestory_823101001_22_dialog_content = "...",
  str_homestory_823101001_23_dialog_content = "So... Did you come up with those riddles? What were they?",
  str_homestory_823101001_24_dialog_content = "They were nothing. Just some general knowledge questions about history, myths and fables, and a few math problems.",
  str_homestory_823101001_25_dialog_content = "She would only have to study for a week to breeze through it all.",
  str_homestory_823101001_26_dialog_content = "I have a feeling it didn't end well...",
  str_homestory_823101001_27_dialog_content = "It depends on the way you look at it. She succeeded, just as I thought she would.",
  str_homestory_823101001_28_dialog_content = "But I really couldn't figure out why she got so mad after finding the treasure...",
  str_homestory_823101001_29_dialog_content = "Let me just ask you now. What did you bury as the treasure?",
  str_homestory_823101001_30_dialog_content = "Victoria's favorite honey. An entire jar that was freshly harvested that year.",
  str_homestory_823101001_31_dialog_content = "That's it?!",
  str_homestory_823101001_32_dialog_content = "Is that not enough? It was clearly written in \"How to Deal with Rebellious Teen Girls\"—",
  str_homestory_823101001_33_dialog_content = "\"Prepare something she likes. You can never go wrong with sweet things.\"",
  str_homestory_823101001_34_dialog_content = "I really don't understand what the problem is.",
  str_homestory_823101001_35_dialog_content = "Why didn't you just give her the honey?!",
  str_homestory_823101001_36_dialog_content = "Remember how she's hostile toward me?",
  str_homestory_823101001_37_dialog_content = "Provoking each other isn't too boring, but it's truly tiring.",
  str_homestory_823101001_38_dialog_content = "So, I didn't mind distracting her with something else.",
  str_homestory_823101001_39_dialog_content = "She spent a week straining her mind and studying history, fables, and math while burning with anticipation...",
  str_homestory_823101001_40_dialog_content = "Yet in the end, all she found was a new jar of honey. It was no different than you mocking her for being fooled...",
  str_homestory_823101001_41_dialog_content = "Do you still not understand why she was angry?",
  str_homestory_823101001_42_dialog_content = "You have a point.",
  str_homestory_823101001_43_dialog_content = "But that is no reason to pour honey over my seat before the meeting of family heads...",
  str_homestory_823101001_44_dialog_content = "I had no choice but to sit on the honey and act like nothing was wrong for the entire duration of the meeting!",
  str_homestory_823101001_45_dialog_content = "What do you think?",
  str_homestory_823101001_46_dialog_content = "You deserved it.",
  str_homestory_823101001_47_dialog_content = "You got what you deserved.",
  str_homestory_823101001_48_dialog_content = "Tch..."
}
return config
